using System.Collections.Generic;

namespace BandItPlus.Cultures
{
    public enum ServiceKind
    {
        TrophyRoom, PoisonBrewer, InfoBroker, SlaveMarket, VeteranHall,
        Falconer, HorseMaster, Oracle, BeggarEar, Hunter, TollMaster,
        SteppeTrader, CoastalSmuggler, SandScout,
    }

    // Wave 5 (Chief Recruitment): which mechanical event-hook pattern the
    // chief's Chapter 1 "Prove Yourself" task uses. All 14 chiefs map to
    // exactly one of these four patterns; no new Harmony patches required.
    // See spec Section 6.5 for the pattern table and Phase 3 task list for
    // the per-pattern objective implementations.
    public enum AllianceCh1Pattern
    {
        KillNamedLord = 1,          // Pattern A: HeroKilled filtered to a specific named lord (validate-and-reroll on lord unavailability)
        DestroyPartiesOfType = 2,   // Pattern B: MobilePartyDestroyed with a party-type / clan / culture filter
        RaidVillagesOfClan = 3,     // Pattern C: VillageBeingRaided counter against villages of a specific clan
        EscortToSettlement = 4,     // Pattern D: SettlementEntered (escort arrival at a quest-resolved destination)
    }

    public class CultureSubService
    {
        public string Label;
        public string Flavor;
        public ServiceKind Kind;
        public int GoldCost; // for RevealHideouts/CostlyMorale; 0 for free
        public int MoraleGain; // for CostlyMorale dispatch
    }

    // Wave 4.6: bring-items errand the chief gives the player to earn trust.
    // ItemIds and Counts are parallel arrays. For "bring me X denars" quests, set
    // IsGoldQuest = true and use GoldAmount instead — ItemIds/Counts are ignored.
    public class TrustQuest
    {
        public string[] ItemIds;       // vanilla item StringIds, e.g. ["fur"] or ["wine", "iron"]
        public int[] Counts;            // per-item quantities, length matches ItemIds
        public bool IsGoldQuest;        // true for "bring me X denars" quests
        public int GoldAmount;          // used only when IsGoldQuest is true
        public string IntroText;        // chief's offer line, per-culture flavor
        public string ThanksText;       // chief's acceptance line after turn-in
        public string ShortLabel;       // short noun phrase for menu/log, e.g. "30 fur"
    }

    // Wave 4.11-fix v43 (2026-05-08): per-vendor identity + voice. Each culture has two
    // distinct vendors (food + gear), each with their own name, title, short backstory,
    // and voice-specific gate speech. Replaces the Wave 4.6 generic shared vendor text.
    public class VendorProfile
    {
        public string Name;          // e.g. "Tess of the Smokehouse"
        public string Title;         // e.g. "Smoke-Master" — shown beside name when relevant
        public string Backstory;     // 1–2 sentence character history
        public string GateSpeech;    // first-meet "chief trusts you, I don't" line, voice-specific

        // Wave 4.12-fix v60 (2026-05-11): per-vendor tier-deepening content.
        // T2 craft secret (visible at vendor_trust >= 2) — food: a recipe or
        // curing technique; gear: a forging/smithing detail or weapon-provenance.
        public string T2CraftDetail;

        // Wave 4.14.4 (2026-06-07): long-form T2 body prose (3-4 paragraphs each,
        // authored per-vendor per-culture). T2CraftDetail above is the legacy 1-2
        // sentence version preserved as fallback; T2CraftSecretBody is the new
        // chunker-rendered version used by "Tell me a secret of your craft." dialog.
        // T2RoadGossipBody is similarly long-form for "What's the gossip from the road?"
        public string T2RoadGossipBody;
        public string T2CraftSecretBody;

        // T2 custom-order tease (visible at vendor_trust >= 2, one-shot per
        // (culture, vendorKind)) — vendor narratively promises a bespoke item
        // and gifts a small denar token of goodwill. Consumed via
        // BanditDialogManager.SetVendorCustomOrderPlaced.
        public string T2CustomOrderTease;

        // T3 family beat (visible at vendor_trust >= 3) — a personal monologue
        // about kin, loss, or kept ties. Re-askable (no state).
        public string T3FamilyBeat;

        // T3 contact introduction (visible at vendor_trust >= 3, one-shot per
        // (culture, vendorKind)) — vendor name-drops a counterpart in another
        // camp/city. Currently flavor + small denar goodwill.
        public string T3ContactName;

        // Wave 4.14 (2026-06-06): chat sub-menu story dialog. Two long-form prose
        // blocks surfaced through the vendor chat sub-menu — backstory ("what pays
        // a man into this trade") + road-news ("what's the word on the road").
        // Bodies may embed <span style="BandItPlus.X"> color markup rendered by the
        // conversation brush override. Mirrors SlaverProfile.SelfStoryBody pattern.
        public string SelfStoryTitle;     // popup title for backstory
        public string SelfStoryBody;      // 4-5 paragraph backstory monologue (\n\n-separated)
        public string NewsRumorsTitle;    // popup title for road-news
        public string NewsRumorsBody;     // 4-5 paragraph news/rumors monologue (\n\n-separated)
    }

