    // How a signature-quest confrontation choice is gated.
    public enum SignatureRequirement
    {
        None = 0,
        StrengthRatio = 1,   // RequirementValue = percent of target strength (120 = 1.2x)
        Renown = 2,          // RequirementValue = minimum player clan renown
        GoldCost = 3,        // RequirementValue = denars the player pays on pick
    }

    // What picking a confrontation choice resolves to.
    public enum SignatureOutcome
    {
        ComplyFull = 0,      // target yields the full objective, despawns peacefully
        ComplyHalf = 1,      // target yields half, despawns peacefully
        Battle = 2,          // conversation closes to the encounter menu — steel
        Betray = 3,          // player sells the chief out; quest concludes betrayed
    }

    // One player choice line in the confrontation (or the post-battle beat).
    public class SignatureChoice
    {
        public string Label;                  // the player's spoken line
        public SignatureRequirement Requirement = SignatureRequirement.None;
        public int RequirementValue;
        public SignatureOutcome Outcome = SignatureOutcome.Battle;
        public string ResultProse;            // the captain's (or chief's) reply
        public int GoldToPlayer;              // denars into the player purse when this resolves
        public int BonusRenown;               // extra renown on this path (Khalid's freed-stock)
    }

    // Full authored definition of a chief's signature quest. All prose fields are
    // spoken words only; journal fields are quest-log register.
    public class SignatureQuestSpec
    {
        public string Title;
        public string HeraldLine;             // rank-and-file bandit pointing at the chief
        public string OfferProse;
        public string AcceptProse;
        public string DeclineNudge;
        public string BusyLine;               // "finish the work you carry first"
        public string TargetPartyName;
        public string CaptainName;            // conversation nameplate for the column's speaker (via ConversationNamePatch)
        public string JournalObjectiveText;
        public string JournalReturnText;
        public string ConfrontIntro;          // target captain's opening
        public SignatureChoice[] Choices;     // up to 3 confrontation choices
        public string DemandFailProse;        // captain laughs off a failed strength/renown demand
        public string PostBattleChoiceIntro;  // chief's question at return (Khalid's stock) — null = none
        public SignatureChoice[] PostBattleChoices;
        public string ClosingProse;           // chief payoff, honored path
        public string ClosingProseAlt;        // colder variant (half toll / freed stock) — null = ClosingProse
        public string ClosingProseOtherCause; // third party destroyed the target; half rewards
        public string BetrayedProse;          // permanent greeting after betrayal — null = n/a
        public int RewardGold = 2000;
        public int RewardRelation = 8;
        public int BattleLootGold;            // recovered from the wreck on the battle path (Skarvac's toll)
        public bool RewardFoodVendorTrustBump; // Hod: feeds people
        public string[] RewardItemIds;        // Borchu: horses
        public int[] RewardItemCounts;
    }

    public static class CultureProfileRegistry
    {
        private static readonly string[] EmptyOracle = new string[0];

        // Wave 5 / Phase 6 / Task 38 — vanilla-culture root used by
        // BanditAllianceBehavior.OnWarDeclared / OnClanChangedKingdom for break #2.
        // Vanilla-extended bandit cultures map to the kingdom culture whose region
        // they geographically infest; BP-authored cultures map per Section 6 affinity
        // table (mirrors BanditAllianceQuest._bpCultureAffinity). `looters` returns
        // null — looters span every region and have no major-faction alignment, so
        // they are exempt from KingdomWar breaks per spec R4 fallback ("acceptable
        // to drop break #2 entirely for a given culture if mapping unclear").
        public static string GetVanillaCultureRoot(string cultureId)
        {
            if (string.IsNullOrEmpty(cultureId)) return null;
            switch (cultureId)
            {
                // Vanilla-extended bandit cultures.
                case "sea_raiders":              return "sturgia";
                case "forest_bandits":           return "battania";
                case "mountain_bandits":         return "vlandia";
                case "steppe_bandits":           return "khuzait";
                case "desert_bandits":           return "aserai";
                case "looters":                  return null; // no kingdom alignment

                // BP-authored cultures — affinity table from Section 6.5.
                case "bp_frost_reavers":         return "sturgia";
                case "bp_marsh_stalkers":        return "battania";
                case "bp_highwaymen":            return "vlandia";
                case "bp_slaver_caravans":       return "aserai";
                case "bp_fallen_legionaries":    return "empire";
                case "bp_sky_raiders":           return "battania";
                case "bp_steppe_wolves":         return "khuzait";
                case "bp_pagan_cult":            return "battania";

                default:                         return null;
            }
        }

        // Wave 4.28.x — shared bandit-agent test (single source of truth). A character is a
        // bandit when it carries the Bandit occupation OR belongs to one of this registry's
        // cultures (the 6 vanilla bandit cultures + 8 bp_* customs). Some vanilla bandit
        // parties (e.g. desert_bandits, hero-led variants) spawn troops WITHOUT
        // Occupation.Bandit, so the old occupation-only checks in the WARBAND dossier and the
        // battle-tactics gate silently missed them. Both callers use this so it can't drift.
        public static bool IsBanditCharacter(TaleWorlds.CampaignSystem.CharacterObject co)
        {
            if (co == null) return false;
            if (co.Occupation == TaleWorlds.CampaignSystem.Occupation.Bandit) return true;
            var cul = co.Culture;
            return cul != null && cul.StringId != null && ByCultureId.ContainsKey(cul.StringId);
        }

        // Wave 4.29.0 — party-level companion to IsBanditCharacter. A party is bandit when
        // it's a vanilla bandit party (IsBandit / bandit faction) OR its culture is one of
        // this registry's cultures (covers bp_* customs, whose clans have IsBanditFaction=false).
        public static bool IsBanditParty(TaleWorlds.CampaignSystem.Party.MobileParty p)
        {
            if (p == null) return false;
            if (p.IsBandit) return true;
            var f = p.MapFaction;
            if (f != null && f.IsBanditFaction) return true;
            if (p.ActualClan != null && p.ActualClan.IsBanditFaction) return true;
            var cul = p.ActualClan?.Culture ?? p.LeaderHero?.Culture;
            return cul != null && cul.StringId != null && ByCultureId.ContainsKey(cul.StringId);
        }

        public static readonly Dictionary<string, CultureProfile> ByCultureId =
            new Dictionary<string, CultureProfile>
        {
            { "bp_frost_reavers", new CultureProfile {
                ChiefName = BandItPlus.Localization.Get("bp_cultureprofileregistry_001", "Vargolf the Iron-eyed"),
                Signature = new SignatureQuestSpec
                {
                    Title = BandItPlus.Localization.Get("bp_cultureprofileregistry_002", "The Iron Price"),
                    HeraldLine = BandItPlus.Localization.Get("bp_cultureprofileregistry_003", "Chief wants you at the fire. There's a lord's iron rolling south on the Pravend road and he means to have every bar. Go quick — the cold puts an edge on him."),
                    OfferProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_004", "A convoy climbs the Pravend road — iron ingots, wagon after wagon, bound for a coastal lord's smithies. He will beat it into garrison steel for the men who ride my passes. I want it beaten into axe-heads for my Reavers and hinges for my longhouse doors. Winter is close, traveler. You can smell it in the wagon-ruts. The convoy master is hired iron himself — hard men on the boards, a harder man at the head. Take the wagons. All of them. Grain rots and silver spends. Iron carries a people through the cold. Bring it to this fire and the fire pays. Ride before the first deep snow shuts the road."),
                    AcceptProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_005", "Good. Hard hands for hard cargo. The wagons roll slow and the guards watch the road behind them, not the treeline. When the iron sits at this fire, your pay sits beside it. Ride."),
                    DeclineNudge = BandItPlus.Localization.Get("bp_cultureprofileregistry_006", "Then winter finds my Reavers with dull axes while a lord's garrison wears their steel. Think on it, traveler. The convoy rolls whether you do or not, and the snow does not wait."),
                    BusyLine = BandItPlus.Localization.Get("bp_cultureprofileregistry_007", "You carry my work already, traveler. Finish it. Vargolf does not stack iron on a sled that has not moved."),
                    TargetPartyName = BandItPlus.Localization.Get("bp_cultureprofileregistry_008", "Iron Ingot Convoy"),
                    CaptainName = BandItPlus.Localization.Get("bp_cultureprofileregistry_009", "Convoy Master Torvald"),
                    JournalObjectiveText = BandItPlus.Localization.Get("bp_cultureprofileregistry_010", "Intercept the iron ingot convoy bound for the coastal lord's smithies and seize the wagons for Vargolf the Iron-eyed before winter closes the roads."),
                    JournalReturnText = BandItPlus.Localization.Get("bp_cultureprofileregistry_011", "The iron has been taken from the convoy. Return to Vargolf the Iron-eyed at the Frost Reaver camp to deliver the ingots and collect payment."),
                    ConfrontIntro = BandItPlus.Localization.Get("bp_cultureprofileregistry_012", "Off the road. This iron is bought, paid, and promised to a lord's smiths, and I've hauled it through worse country than yours. Say what you came to say and be quick about it."),
                    Choices = new[]
                    {
                        new SignatureChoice { Label = BandItPlus.Localization.Get("bp_cultureprofileregistry_013", "Count my riders, convoy master. Then unhitch the wagons."), Requirement = SignatureRequirement.StrengthRatio, RequirementValue = 120, Outcome = SignatureOutcome.ComplyFull, ResultProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_014", "I count them. I've buried better men than these guards for worse cargo, and I won't spend them here. Take the wagons. But mark me — I'll haul this road again, and next time the count may run the other way.") },
                        new SignatureChoice { Label = BandItPlus.Localization.Get("bp_cultureprofileregistry_015", "The iron changes hands the hard way. Draw."), Outcome = SignatureOutcome.Battle, ResultProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_016", "So be it. Shields up, lads. The cargo stays.") },
                    },
                    DemandFailProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_017", "That's your strength? I've hauled through fen-raiders and two Sturgian winters, and none of it looked as thin as your band. No. The wagons roll. Step aside or stop them yourself."),
                    ClosingProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_018", "Stack it by the forge-tent. Every bar. My smith beats axe-heads from it before the first deep snow, and my Reavers winter armed instead of hungry for steel. The coastal lord can guard his empty smithies. You did the work, traveler, and the work is what Vargolf pays. Here — your silver, counted twice. The fire remembers who fed it. Winter comes. Now it comes to a camp with iron."),
                    ClosingProseOtherCause = BandItPlus.Localization.Get("bp_cultureprofileregistry_019", "Word ran ahead of you, traveler. Some other band hit the convoy first — hill-scum, no code — and the ingots went into the snow like spilled grain. You gathered what the drifts gave back. Half the iron, then, and half the pay. My smith works with what the road sends. But hear it plain: a full sled buys a full welcome. Next time, ride faster than the other wolves."),
                    RewardGold = 1800,
                    RewardRelation = 8,
                },
                ChiefTitle = BandItPlus.Localization.Get("bp_cultureprofileregistry_020", "Reaver-Chief"),
                ChiefBackstory = BandItPlus.Localization.Get("bp_cultureprofileregistry_021", "Vargolf was born to the Yulskaya boyar-line of northern Sturgia, a clan that held the Pravend trade routes for three generations before the year he came of age — when the routes were lost to a southern rival and the Yulskaya hearth-roll was halved. He took his iron from his father at sixteen, his grandfather's name a year later, and walked the snow-trails alone through every winter of his apprenticeship. The feud that broke him was a stolen wife — not stolen by him but stolen FROM his clan, and the boyar-council refused to ride for her recovery. Vargolf rode alone, took her back from a Vlandian outrider's tent in the high passes, and returned to find his name struck from the longhouse rolls and his hearth-cousins reassigned to a rival branch. He took twenty cousins past the tree-line and named the band the Frost Reavers, after the wolf-pack that reaves the Sturgian coast each spring. Forty winters later he speaks fewer words than his hounds, drinks only on naming-days, and pays his men in silver coined from imperial caravans his Reavers stop on the snow-roads. The Sturgian crown still lists him as a runaway boyar; he has not contested the title."),
                ClanHistory = BandItPlus.Localization.Get("bp_cultureprofileregistry_022", "The Frost Reavers were founded forty winters ago by twenty Yulskaya hearth-cousins struck from the same longhouse-rolls Vargolf was struck from. They wintered the first year in a thaw-hollow that lost six men to frostbite before spring. Each generation since has recruited the same way — Sturgian sons disinherited by southward-shifting trade routes, Vlandian deserters who walked the wrong pass, broken huscarls whose lords would not pay their oath-silver. The Reaver-code Vargolf wrote at the founding-fire forbids village-raiding; they take only imperial tax-wagons, foreign caravans, and the occasional noble outrider party. Pravend's counting-house has lost eleven wagons to them this winter alone. The Sturgian crown has put no bounty on the band — only on Vargolf personally — because the boyars who rule the snow-roads quietly use the Reavers to ruin rivals. Among the snow-clans the Reavers are not feared so much as respected: they are the wolves the cold north feeds in place of the kings it never got."),
                ChiefGreeting = BandItPlus.Localization.Get("bp_cultureprofileregistry_023", "The reaver-chief stands knee-deep in churned snow, axe balanced across his shoulders. He doesn't speak as you approach — only watches, breath fogging the cold air, while his men close the circle behind you. When he finally moves, it is to look you over once, like a butcher reading a carcass. \"You walk warm clothes. The dead ones we strip leave their warmth on the wolves. Speak quick, traveler — Vargolf's patience freezes the same as everything else up here.\""),
                ChiefGreetingTolerated = BandItPlus.Localization.Get("bp_cultureprofileregistry_024", "The reaver-chief glances up from sharpening his axe as you approach. He doesn't put the stone down. The men around the fire shift, then settle, then ignore you — the surest mark of acceptance the snows allow. \"You've come back. The cold didn't take you. That's twice now you've earned a portion of Vargolf's fire. Speak — slow words travel better in the cold.\""),
                ChiefLoyaltySpeech = BandItPlus.Localization.Get("bp_cultureprofileregistry_025", "Names are wind in the cold, traveler. Wind dies. What lasts is what a man carries — and the only proof Vargolf takes is in deeds. There's a task for hands like yours. Bring the wages of it back to this fire, and we'll speak again as something other than stranger and chief."),
                CampIntro = BandItPlus.Localization.Get("bp_cultureprofileregistry_026", "The Frost Reavers' camp is hollowed out of a drift, ice walls braced with logs. Smoke curls thick from cookpots. A skinned stag turns on a spit. Fur-cloaked sentries watch the ridges with bows drawn loose."),
                HideoutDirections = BandItPlus.Localization.Get("bp_cultureprofileregistry_027", "Ride three days north of Pravend, traveler, past the last farmstead the imperial tax-rolls remember. When the snow-pines close black over the road and your horses' breath comes white as bone-meal, you are near enough. Look for a wind-cut ravine that the sun never reaches before noon - there is a fox-skull nailed to the second pine, and below it the spring runs frozen even in the thaw months. Our hold lies at {HIDEOUT_NAME}, deeper in than the ravine-mouth looks.\n\nFrom the skull you walk in, not ride. The trail is single-file and my watchers above the ridge see your shoulders before they see your face. Bows held loose, arrows not yet nocked - that is their patience, not their welcome. Ride in with your party-banner low and one rider out front with empty hands, or send a name ahead with the drovers who know the road. My scouts have ears for a name they owe a debt to.\n\nCome up the ravine without that name and the first arrow is a warning. The second is not. We do not feed strangers here - we feed the wolves we owe. Bring me a name worth knowing and the gate-log opens, the fire is yours, and we share what the south has not yet taken from us. Otherwise the snow keeps the matter quiet till the spring thaw walks your bones out."),
                ScoutsLordsProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_028", "The boyars of Pravend keep sending their tax-riders into my passes. Two captains this season already - one I sent back without his horse, one I sent back without his head. The crown has a new governor in the southern keep who calls himself Lord Mikhail Yulskaya. The name is mine. He stole it the year I was struck from the longhouse-rolls. So we have a quarrel that runs deeper than ice and longer than the road between us.\n\nThe Vlandian outriders cross the high passes in summer chasing imperial coin - my Reavers chased a column of them off the snow-roads last moon. Battanian raid-bands slip up the western treelines too, but they keep to their own grudges and we keep to ours. The Khuzait send no one this far north. Their horses do not love the deep snow.\n\nThe southern boyars send the levies, the Vlandians send the outriders, the Empire sends its tax-wagons. We send them all home lighter than they came. If you ride south with a banner of your own, traveler, the boyars will read it before they read your face. Carry that knowledge with you. The crown has a memory, and the snow keeps every footprint until the thaw."),
                ScoutsClanProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_029", "The Marsh Stalkers in the southern fens owe my Reavers a debt - a winter five years back, their matriarch Mireborn put a token in my hand for a Vlandian outrider I rode down for her. She has not repaid. I have not asked. The Stalkers move slow and pay slow, but they pay. The Highwaymen of the downs are men I do not deal with - their Reeve counts coin where I count cousins. We do not share a fire.\n\nThe sea-raiders to the east have been moving inland this season, hunting where they should not. My scouts marked three of Bjornulf's longboats beach near the Pravend road, and the Salt-Tongue knows my mark. If they cross again I will ride the long way to his cove and we will settle in the old way. Granny Hod's forest band sent a runner two weeks back - smoke-talk, a token of birch, no words. She watches. That is her way.\n\nAs for the steppe, the Wolf-Khan Borchu and I have an understanding. We do not ride into each other's grass. So far we both keep our word. The pass-lords under Skarvac have gone quiet in the high snows. Quiet is never good. When a mountain man stops boasting, he is sharpening something."),
                ScoutsCaravanProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_030", "Sturgian fur-trains move south from Revyl to Pravend every second week. Eight axemen, two wagons, a captain who drinks at the Pravend gate before the road - I have watched him three winters. He sets out heavy and slow. The pelts are good. The men are slower.\n\nBut the column you want is Vlandian. A grain-and-iron caravan climbs the pass under the Pravend road six days from now, sixteen guards, four wagons, escorted by a southern knight who thinks snow is a rumour. They camp at the cold-spring because the water does not freeze there. The outriders sleep. The knight drinks. My boys have counted their watches twice and the second watch never wakes the third. That is the hour.\n\nTake the iron, traveler. Leave the grain. Grain rots, iron does not, and the Vlandian smiths at Galend will buy back their own bars and ask no questions - a Highwayman friend of mine, Reeve's man, moves steel through Galend every moon and the price is set. Do not ride the Revyl road south of the iron-bridge after - the boyars send tax-riders that way and they remember faces. Ride west. The snow forgets faster than men."),
                PactTeaseProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_031", "You ask the iron question. Good. I do not waste breath on those who come to a fire only to warm their hands. Sit. The snow will hear what we say, and the snow remembers longer than men.\n\nAn oath from a Reaver is not coin. It is the hearth-roll, scratched into the longhouse beam above my own seat, and the names on that beam are few. My Yulskaya cousins, who rode with me when the ice cracked at Pravend. Old Halrek, who took an arrow that was meant for my throat and asked for nothing afterward. The Stalker-matriarch who fed my Reavers a winter we should not have survived. That is the company you ask to join. The axe knows them. The axe does not yet know you.\n\nBring me a deed the snow will not forget. A southern caravan taken in my name. A blood-debt paid before I have called it. A road kept open when the lowland lords swore it shut. Walk back into this longhouse with iron on your boots and a banner the ridge can see, and the beam learns a new mark. Until then - the road between us is begun, but not yet walked. Ask again when you have weight to your name."),
                OathBrotherProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_032", "Then it is spoken, and the longhouse-beam has heard it. Stand. The horn comes to your hand before the mead does - drink, and let the cold of it find the bottom of you. Now the iron knife from my belt. I open my palm where the old brother-scar lies - the one my dead brother Halgrim cut into me before the southern axemen took him at the Pravend ford - and I lay the new cut across the old. Your palm to mine. Press. The snow at the door is watching. The hearth-roll on the beam takes a new notch tonight - your name beside Halgrim's, beside my father's, beside the wolf-marks of the founders. The blood is one blood now.\n\nBrother means this in the Reavers' tongue: my fire is your fire, my mead-bench is your bench, my cousins answer to your call as they answer to mine. The feud I carry against the lowland lords is your feud from this breath forward, and the feud they will one day open against you is mine. We do not bury our kin alone. We do not ride to our blood-debts alone.\n\nHear it then, brother. The hearth-roll above Pravend knows you. The snow-pine ridges know you. The lowland lords who hung my cousin from their gate-tree will read your name beside mine when the thaw comes. From this fire forward you are Vargolf's blood, and the road we walk together no longer has an end."),
                PactAnswerProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_033", "Then I have heard it, and I weigh it the way the smith weighs the bar before the strike - by feel, not by speech. You did not come up the ridge with a fine sentence rehearsed in your teeth. You came with the deed already cooling at your belt, and the word arrived after, like snow falling on a fresh-cut stump. That is the order I trust. My father told me once that an oath spoken before the work is a debt; an oath spoken after the work is a verdict. You have given me the verdict. I accept it.\n\nHear the shape of it, then. This is not the hearth-bond. This is iron. From this moon, when you raise your banner, the Reavers ride - not as paid spears, not as a courtesy I can pull back when the wind shifts. Your feud is my feud. Your hunters are my quarry. You owe me the same in turn: when my axe is up, your steel is up beside it, and you do not ask the reason until the work is done. The longhouse will know your name in the hearth-roll, written next to the men I have already buried.\n\nThe wind off these ridges carries sound a long way, traveler. When steel is drawn, it will be drawn for both of us. Ride hard. The road south is loud, and we are sworn now in the colder kinship - the kinship of the WORK. That bond outlasts blood."),
                TroopLoanProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_034", "Done. Ten axemen for seven days - I cut them from my own hearth-band before sundown. My second is Halgrim Snow-Tooth, who has stood my shield-wall since the river froze twice over. He rides at the head of them and carries my word like he carries his axe. What he says, I have said. Count the days, traveler. Seven. The longhouse counts them with you.\n\nNow hear my terms. If a Reaver of mine falls in your work, you bring his blade back to this hall - the iron, at least, comes home, or you and I will speak again on harder ground. If he lives, you send him back fed and drunker than he left, or you have wasted my gift. My axemen do not break shield for coin or boredom. They break shield for the work I have set them to, and while they ride under your banner your work IS my work. Do not spend them on petty things.\n\nHalgrim will tell me what you did with them. I will be listening."),
                NamedTargetAcceptProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_035", "His name is {TARGET}. He sleeps under his own banner at {HOME}, and that hall stands on ground my brother Halgrim was dragged across twelve winters past - roped behind a Yulskaya horse until the snow was red for half a league. {TARGET}'s father gave the order. {TARGET} ate at the same table the night it was done and laughed when the courier brought the rope back. I swore on Halgrim's axe I would put steel through whichever son of that house outlived the others. The youngest is {TARGET}.\n\nHe rides with six lances and a houseman named Brun who lost a brother to the same campaign and has no love left for his lord. Brun waters his horse at the millstream below {HOME} every third dawn - put a coin in his palm and he will tell you the gate hour. {TARGET} hunts boar on the east ridge when the frost breaks. Take him there, away from his walls. He fights poorly off a horse.\n\n{REWARD} denars when the word reaches me, traveler. The gold is the smaller half of what is owed - the rest is Halgrim's, and the snow keeps that ledger. Ride before the moon turns."),
                NamedTargetReason = BandItPlus.Localization.Get("bp_cultureprofileregistry_036", "{CHIEF} has named {TARGET} of {HOME} as the man whose death he has waited twelve winters for. The grudge is old and specific - a brother dragged on a Yulskaya rope, three days hanging on a frontier tree, an outrider's contract paid in clean Vlandian silver and never answered for in iron. {CHIEF} carries the names of those involved on the longhouse-beam where his hearth-roll is cut, and only {TARGET}'s name remains uncrossed. The Reaver-Chief offers a heavy purse and the weight of a debt finally closed. The road south is loud. The snow remembers. The contract is open."),
                NamedTargetComplete = BandItPlus.Localization.Get("bp_cultureprofileregistry_037", "{TARGET} is dead. {CHIEF} has been told, and {CHIEF} has heard. The longhouse-beam now bears a finished mark - the last uncrossed name from the twelve-winter feud with Yulskaya is crossed at last. {REWARD} denars sit at the Reaver-chief's fire, heavy and counted, and the iron-eyed bond between bandit-king and traveler-killer is stamped a degree deeper. Brother Halvi, dragged on the Yulskaya rope through the white pass of '88, is not back, but his name has been answered for, and the snow keeps the rest. The hearth-roll is whole again, and the axe rests cold against the beam."),
                NamedTargetOtherCauseProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_038", "Word came across the snow-track at dusk: {TARGET} lay stiff in a ditch two valleys south, throat opened by some rival lord's outriders in a quarrel that had nothing to do with Halgrim. {CHIEF} heard it out beside the hearth-roll, his iron eye fixed on the longhouse-beam where his brother's name is still cut, and said nothing for a long span. The grudge for that Yulskaya rope, twelve winters carried, was answered - but answered by another hand, and the silence in the hall went colder for it. He had the steward count out {REDUCED_REWARD} denars, quarter-pay, thin coin for a thin closing. The bond holds, set a smaller notch firmer, no warmer than river-ice."),
                RaidVillageAcceptProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_039", "\"There is a village called {VILLAGE} on the southern slope of the Yulskaya hills, held by Lord {LORD} of that same boyar-clan that burned my Reaver winter-camp ten winters back. Eight of my men froze in the snow when their outriders kicked apart our cookfires and rode out laughing. {LORD} was a green captain that year. He kept the cloak my brother died wearing, and the silver wolf-pin sewn to its collar.\n\nThe granaries are full this season - they tithe to the Pravend keep on the first new moon. Hit them three nights before, when the wagons are loaded and the watch-fires are doubled but the riders are off collecting their winter-pay. Burn the grain. Take the iron, take the salt. The smallfolk - leave them to the road. We did not freeze for thralls.\n\n{REWARD} denars when the smoke is seen from the high passes. The snow keeps the rest. Ride before the moon turns.\""),
                RaidVillageReason = BandItPlus.Localization.Get("bp_cultureprofileregistry_040", "{CHIEF} has named {VILLAGE}, a granary-fief of Lord {LORD} of the Yulskaya tributary clan, as the holding whose burning will close a debt ten winters old. The Yulskaya boyar-riders rode down {CHIEF}'s Reaver winter-camp in the deep ice, and eight of his hearth-band froze in the cookfire-ashes while their cloaks were hauled back to the Yulskaya hall as trophies. The granary feeds the boyar who gave that order, and {CHIEF} has waited ten winters for a banner cold enough to ride it. The Reaver-Chief offers a heavy purse of {REWARD} and the closing of a grudge that has kept its edge in the snow. The road south is loud. The contract is open."),
                RaidVillageComplete = BandItPlus.Localization.Get("bp_cultureprofileregistry_041", "{VILLAGE} is ash, and {CHIEF} has the tally on the cut-stick. The granary-fief of Lord {LORD} of the Yulskaya tributary - the boyar-clan that burned the Reaver winter-camp ten winters past and left eight men under the ice - is broken thatch and cold ovens, the tithe-sleds split for firewood, the bondsmen scattered into the drifts. {REWARD} denars sit weighed at the longhouse-beam where the hearth-roll is notched, and the iron between bandit-king and traveler-raider is stamped one degree firmer. The Reaver-roll is eight names shorter. The snow keeps the rest."),
                RaidVillageOtherCauseProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_042", "Word came north along the frost-track at second watch: {VILLAGE}, that fat little granary of the Yulskaya boyar-line, lay smoking and empty - but the column that put it to the torch had been {LORD}'s outriders settling some quarrel of their own, nothing to do with eight men lost under the ice ten winters back. {CHIEF} heard the runner out beside the hearth-roll, fingered the iron at his throat, and said only that the snow had thawed in the right village by the wrong hand. The grudge stood answered, after a fashion. He had the steward count out {REDUCED_REWARD} denars - quarter-pay, thin coin for a thin closing - and waved the traveler back into the cold, no warmer than river-ice."),
                // 2026-05-25 rewrite: FOUND-OBJECT shape. Opens with the player reading
                // a verse burned into a birch marker before the camp is visible at all;
                // the verse colors the descent. No companion, no negation list, no
                // "you watched" reveal — the player walks past the artifact, not past
                // the people.
                HideoutCinemaIntro = BandItPlus.Localization.Get("bp_cultureprofileregistry_043", @"You find the marker before you find the camp.

It is a length of split birch, planted in the snow at a switchback, hung at eye-height where any rider must see it. Someone has burned letters into the bark with a heated knife. The script is old Sturgian. You read it slowly, because the wind keeps trying to take your eyes from the words:

    Cold sharpened him.
    Cold did not break him.
    Cold made the man.
    Cold is the master here.

There is no sign-name beneath it. No clan-mark. Only the verse, and the small black scorch-rings the knife left around each letter.

You sit your horse and read it twice.

Past the marker the trail dips and the wind takes the other half of itself away, and there, in a hollow scooped from a great drift and walled with ice and black logs, the Reavers have made a place to keep warm. Smoke stands straight up in the dead air. A stag turns on a spit. Along the ridge above the hollow, fur-wrapped figures hold longbows loose at their thighs. They have been watching you since you stopped to read.

You leave the birch where it stands. You will pass back this way if you live, and the words will still be there.

You walk your horse down."),
                ServiceLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_044", "Visit the trophy room."),
                ServiceFlavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_045", "Vargolf pulls aside a hide curtain. Inside: looted gold cups, a Sturgian noble's signet ring, a cloak of black bear, a sword that once belonged to a count."),
                Kind = ServiceKind.TrophyRoom,
                BribeAmount = 250,
                WhyNotKingdom = BandItPlus.Localization.Get("bp_cultureprofileregistry_046", "\"A king would tax our cookfires. Out here we owe nobody. We freeze sometimes. We never bow.\""),
                Religion = BandItPlus.Localization.Get("bp_cultureprofileregistry_047", "\"Old Sturgian gods. The thunder-one, the fire-one, the cold mother. They take what's given and ask no priest to count it.\""),
                ThreatResponse = BandItPlus.Localization.Get("bp_cultureprofileregistry_048", "\"Cut me down? Boy. The cold has tried for forty winters. You think a sword frightens a man the snow forgot to kill?\""),
                Pleasantry = BandItPlus.Localization.Get("bp_cultureprofileregistry_049", "Vargolf grunts, almost a laugh. \"Camp does its job. Wind's quiet here. Reavers warm. That's enough.\""),
                DrinkFlavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_050", "The Reavers pour a black mead, thick as syrup. The chief raises a horn. \"To the wolves who eat our enemies and the wolves we are.\""),
                RestFlavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_051", "You bunk in a fur-piled tent. The chief's hounds sleep at the foot. Your party wakes warmer than they've been in months."),
                ExtraServices = new[] {
                    new CultureSubService { Label = BandItPlus.Localization.Get("bp_cultureprofileregistry_052", "Visit the skin trader."), Flavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_053", "An old man with hands like leather lays out furs. Bear, wolf, ermine. \"Better prices than any town. Towns sell to fur-merchants. Fur-merchants sell to me. I cut the middle.\""), Kind = ServiceKind.Hunter },
                    new CultureSubService { Label = BandItPlus.Localization.Get("bp_cultureprofileregistry_054", "Hear wolfhunt tales by the fire."), Flavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_055", "An old reaver with one eye spits in the fire. \"Listen. Story is true or it isn't, but the listening costs nothing.\""), Kind = ServiceKind.Oracle, GoldCost = 0 },
                    new CultureSubService { Label = BandItPlus.Localization.Get("bp_cultureprofileregistry_056", "Drink with the skald. (50 denars)"), Flavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_057", "A man with a small harp begins a winter-song. The Reavers join in low. Your party joins in louder. The night gets stronger."), Kind = ServiceKind.VeteranHall, GoldCost = 50, MoraleGain = 5 },
                },
                Rumors = new[] {
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_058", "\"Sturgian count Sigurd is sending a tax-wagon down the spine road in four days. We'll be there.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_059", "\"The lord at Revyl drinks more than he prays. His guard rotates at midnight — we know.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_060", "\"There's an old Sturgian armory frozen in a glacier west of here.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_061", "\"A boyar's daughter went missing on the high pass last month. 5000 denars reward.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_062", "\"The Sturgian winter levy is starving. Half their militia would join us for hot food.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_063", "\"We saw imperial scouts on the ridge two days ago. Three of them. They didn't see us.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_064", "\"A merchant from Pravend offered us silver to torch a rival's caravan. We did.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_065", "\"The empire's pulled their northern garrison south. The roads belong to us until they remember.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_066", "\"There's a wolf-pack tracking a Vlandian noble across the tundra. He doesn't know yet.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_067", "\"Sturgians from the eastern clans want vengeance against Boyar Tora. Pay's good if we help.\""),
                },
                // Wave 4.7e: random pools per tier. Tier 3 added for steeper progression.
                TrustQuestTier1Pool = new[] {
                    new TrustQuest {
                        ItemIds = new[] { "fur" }, Counts = new[] { 30 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_068", "\"You want to trade with us, traveler? Bring me thirty pelts. Wolves, bears, whatever. The Reavers don't deal with men who can't survive a winter walk.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_069", "Vargolf inspects each pelt. \"Heavy. You did the work or paid someone honest. Either way — trade with my men.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_070", "30 fur"),
                    },
                    new TrustQuest {
                        ItemIds = new[] { "hardwood" }, Counts = new[] { 25 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_071", "\"Twenty-five hardwood. Pine cracks under our snow weight. We need oak from the southern slopes. Bring it.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_072", "Vargolf weighs a beam. \"Hard wood. Won't split when the men set lodge-poles. Trade with my traders.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_073", "25 hardwood"),
                    },
                    new TrustQuest {
                        ItemIds = new[] { "hides" }, Counts = new[] { 30 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_074", "\"Thirty hides. The smoke-tent burns through tanning hides faster than the wolves provide them. Hunt or buy — either way, bring them.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_075", "Vargolf prods the stack. \"Clean cuts. The tanner won't curse your name when he works these. Trade.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_076", "30 hides"),
                    },
                },
                TrustQuestTier2Pool = new[] {
                    new TrustQuest {
                        ItemIds = new[] { "hardwood", "fur" }, Counts = new[] { 20, 20 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_077", "\"You proved yourself. Now I'd see you build a Reaver's lodge. Twenty hardwood and twenty more fur. The men who do this ride with us in raids.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_078", "Vargolf laughs once, deep. \"You build with these hands like one of us. The trophy room is open to you.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_079", "20 hardwood + 20 fur"),
                    },
                    new TrustQuest {
                        ItemIds = new[] { "fur", "mule" }, Counts = new[] { 40, 5 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_080", "\"Forty pelts and five pack-mules. We re-supply the deep camp before the snows close the pass. Heavy load — Reaver work.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_081", "Vargolf claps the lead mule. \"Now the camp survives the winter. Take what the armory holds.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_082", "40 fur + 5 mules"),
                    },
                    new TrustQuest {
                        ItemIds = new[] { "hardwood", "hides" }, Counts = new[] { 30, 20 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_083", "\"Thirty hardwood and twenty hides. New bow-staves and tannage for the spring raids. Bring both and the trophy room is yours to walk.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_084", "Vargolf bends a stave to test it. \"Solid grain. The Reavers will draw farther this spring because of your work.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_085", "30 hardwood + 20 hides"),
                    },
                },
                TrustQuestTier3Pool = new[] {
                    new TrustQuest {
                        ItemIds = new[] { "fur", "hardwood", "ironIngot2" }, Counts = new[] { 50, 50, 10 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_086", "\"Fifty fur, fifty hardwood, ten wrought-iron ingots. The whole high-camp re-equips. Only blood-kin haul this. Take your time, brother — but bring it all.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_087", "Vargolf stands silent a long moment. \"You've outfitted my Reavers. The cold north remembers your name forever.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_088", "50 fur + 50 hardwood + 10 wrought iron"),
                    },
                    new TrustQuest {
                        ItemIds = new[] { "fur", "ironIngot3" }, Counts = new[] { 100, 20 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_089", "\"A hundred fur and twenty refined-iron ingots. The Reavers ride the empire's borderlands this spring. Outfit us, and you sit at my right when we ride.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_090", "Vargolf grips your shoulder. \"You bought us a winter and a war. There is no man closer to me now.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_091", "100 fur + 20 refined iron"),
                    },
                },
                // Wave 5 (Chief Recruitment) alliance content
                AllianceCh1TaskBrief = BandItPlus.Localization.Get("bp_cultureprofileregistry_092", "Sink Jarl Asmund's caravan-marked party at the northern strait, where the Reavers cannot reach without crossing the open ice."),
                AllianceCh1Pattern = AllianceCh1Pattern.DestroyPartiesOfType,
                AllianceCh1TargetSeedHint = "asmund_caravan_party",
                AllianceCh3RitualText = BandItPlus.Localization.Get("bp_cultureprofileregistry_093", "The Vargolf the Iron-eyed accepts your oath; the rite is sealed in salt-blood at the longboat prow on the low tide."),
                AllianceCh3GiftItemId = "two_handed_battle_axe_t3",
                AllianceBrokenText = BandItPlus.Localization.Get("bp_cultureprofileregistry_094", "Vargolf does not raise his voice. He sets the axe across his knees and stares at the cold horizon. \"The snow forgets nothing. Ride.\""),
            }},
            { "bp_marsh_stalkers", new CultureProfile {
                ChiefName = BandItPlus.Localization.Get("bp_cultureprofileregistry_095", "Mireborn"),
                Signature = new SignatureQuestSpec
                {
                    Title = BandItPlus.Localization.Get("bp_cultureprofileregistry_096", "The Drowned Road"),
                    HeraldLine = BandItPlus.Localization.Get("bp_cultureprofileregistry_097", "You. Chief wants you at the fire. There's lowlanders in the reeds with stakes and string — measuring, they are. Measuring us. Go quick. She's gone all quiet, and that's never good for somebody."),
                    OfferProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_098", "There are men in my reeds with stakes and string, traveler. A surveyor — a fussy little man under a lord's seal — walking the fen with charts, marking where the causeway will go. A road. You understand what a road is, in a marsh? First the stakes, then the stone, then the ditches, and in ten years there is no fen. Dry ground. Counted ground. My grandmothers drowned kings' men to keep this water dark, and I will not be the chief who let it be measured. Go to the column. Break it. Kill who stands. And bring me his charts — every page, every marker. The marsh keeps its own maps."),
                    AcceptProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_099", "Good. Take the charts before you take the men, if the fight lets you — paper drowns faster than surveyors, and I want it whole enough to rot slow. Walk soft, traveler. The reeds will watch you there."),
                    DeclineNudge = BandItPlus.Localization.Get("bp_cultureprofileregistry_100", "Then go. But the stakes are still in my fen, and every dusk they stand is a yard of water the lowlands think they own. The marsh is patient, traveler. I am less."),
                    BusyLine = BandItPlus.Localization.Get("bp_cultureprofileregistry_101", "The stakes still stand, walker. My watchers count the column every dusk — twelve spears and a man with paper. Go finish it. We will speak when the charts are wet."),
                    TargetPartyName = BandItPlus.Localization.Get("bp_cultureprofileregistry_102", "Royal Survey Column"),
                    CaptainName = BandItPlus.Localization.Get("bp_cultureprofileregistry_103", "Royal Surveyor Ferand"),
                    JournalObjectiveText = BandItPlus.Localization.Get("bp_cultureprofileregistry_104", "Mireborn wants the royal survey column staking a causeway through the marsh destroyed. Defeat the surveyor's escort and recover the causeway charts."),
                    JournalReturnText = BandItPlus.Localization.Get("bp_cultureprofileregistry_105", "The survey column is broken and the causeway charts are in your possession. Return them to Mireborn at the Marsh Stalkers' camp."),
                    ConfrontIntro = BandItPlus.Localization.Get("bp_cultureprofileregistry_106", "Halt — halt! You are inside a marked survey line. This ground is measured under royal commission, every stake numbered and logged. State your business at once, and mind the string. Do NOT touch the string."),
                    Choices = new[]
                    {
                        new SignatureChoice { Label = BandItPlus.Localization.Get("bp_cultureprofileregistry_107", "The marsh keeps its own maps. Leave the stakes — bleed or run."), Outcome = SignatureOutcome.Battle, ResultProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_108", "Leave the — this survey carries the crown's own seal, you dripping savage! Eleven weeks of triangulation! Sergeant, form your line — I want this ruffian's name for the record before you kill him!") },
                    },
                    ClosingProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_109", "Give them here. Measured twice — drowned once. Watch: page by page to the black water, held under until the ink lifts and their causeway blurs to nothing. The fen stays trackless, traveler. Your pay is in the wicker, counted out by reed-light. Listen — the heron settles. The marsh is pleased, and the marsh is not often pleased."),
                    ClosingProseOtherCause = BandItPlus.Localization.Get("bp_cultureprofileregistry_110", "The marsh did not wait to be hired, traveler. The surveyor died fevered in his own tent, the quick-mud took his sergeant and two mules, and arrows out of empty reeds finished the count — none of them yours. A fen-girl brought me the charts already drowned, the ink run to green shadows. Half the coin. Be quicker than the fen next time. Few are."),
                    RewardGold = 1500,
                    RewardRelation = 8,
                },
                ChiefTitle = BandItPlus.Localization.Get("bp_cultureprofileregistry_111", "Stalker-Matriarch"),
                ChiefBackstory = BandItPlus.Localization.Get("bp_cultureprofileregistry_112", "Mireborn was born in the deep fenlands of what was once a Battanian marshland, in a reed-house her grandmother built on stilts that have not yet rotted. She has never set foot inside a town's walls, never tasted bread that was not made of fen-millet, and has known no roof but reed and hide. The Stalkers passed to her from her grandmother, who took them from hers, and the band has belonged to the marsh-women for seven generations — a matrilineal succession the lowland scribes refuse to record because they refuse to record any chief who is a woman. Her first kill was a Vlandian tax-collector at eleven, drowned in three feet of standing water without ever knowing where the sound came from. Her second was the boyar's son who came looking for the tax-collector. By twenty she had drowned twelve men and never raised her voice, and the marsh-women elected her chief without a word spoken — a vote conducted in shared glances over a fire. She moves through reeds without sound, remembers every drowned thing, and tells the stalker-children to remember too."),
                ClanHistory = BandItPlus.Localization.Get("bp_cultureprofileregistry_113", "The Marsh Stalkers are seven generations old, founded by a marsh-grandmother whose name has been forgotten on purpose — the Stalker-women say her name only once, on the night a new chief is elected, and never write it down. Every chief since has been a woman; every successor has been chosen by the silent vote of the elder-circle around a smoke-fire. Mireborn is the seventh. Stalker-children come from fen-villages so deep in the standing water that no scribe, surveyor, or priest has charted them — settlements the lowland lords have declined to tax for two centuries, less from generosity than from an inability to locate them. They learn to drown men before they learn to read, and most never learn to read. The band's signature is silence: a tax-collector is never warned, never charged, never seen — only found face-down in three feet of black water with no wound and no witness. Vlandian and Battanian lords have organized eleven sweeps of the fen in living memory; eight returned with no Stalker captured and no Stalker dead, and three did not return at all. The marsh-women say the fen kills its own enemies and they are only its hands."),
                ChiefGreeting = BandItPlus.Localization.Get("bp_cultureprofileregistry_114", "For a long moment you see only reeds. Then a lean figure unfolds from the green like a heron rising — silent, mud-streaked, eyes pale as marsh-water. He tilts his head, studying you the way a hunter studies prints in soft ground. \"You found us. Few do. Either you're clever, traveler, or someone whispered the path to you. Mireborn would like to know which — before we speak of trade.\""),
                ChiefGreetingTolerated = BandItPlus.Localization.Get("bp_cultureprofileregistry_115", "The reeds part for you now without protest — the stalkers know your tread. Mireborn rises slower this time, eyes the same pale marsh-water but no longer measuring. He gestures you toward the dry-stone where he sits. \"Twice you've found the path. The marsh remembers. Speak, traveler — Mireborn listens to walking-friends with the patience the reeds taught him.\""),
                ChiefLoyaltySpeech = BandItPlus.Localization.Get("bp_cultureprofileregistry_116", "The marsh hears all names and forgets most. Mireborn doesn't keep what the marsh discards. You want trade with the stalkers, traveler — there's a thing my men need, and the reeds will not yield it without effort. Bring it back, and the marsh will start remembering you."),
                CampIntro = BandItPlus.Localization.Get("bp_cultureprofileregistry_117", "The Marsh Stalkers' camp floats. Reed huts on stilts, plank walks lashed between trees. Frogs and birds. Somewhere, a child cries — then is hushed. Stalkers move slow and deliberate, never breaking the surface."),
                HideoutDirections = BandItPlus.Localization.Get("bp_cultureprofileregistry_118", "Ride south from Marunath until the road forgets itself in the reeds. The horses will refuse the wet ground before you do - leave them with a fen-boy at the last solid alder, and walk. Look for the plank walks lashed between the drowned trees; they are silver-grey and the bog has half-swallowed them, but they hold a thin man. Follow the black-water channel where the heron-rookery quarrels at dusk, and watch for peat-fires that give off no smoke. That is our breath you are seeing. Our hold lies at {HIDEOUT_NAME}, deeper in than any tax-man has ever cared to wade.\n\nMy watchers are in the reeds before you see the reeds. They will count your party from the rookery before your second step on the planks, and a girl with a bone-whistle will tell the camp your number and your weight. Walk slow. Keep your hands where the water can see them. If you carry a token I have given you, hold it open in your left palm; if you carry only your name, speak it once to the air and keep walking.\n\nCome quiet and the camp opens to you - dry reeds, fen-cake, a place by the smokeless fire. Come loud, and the bog keeps you. We do not bury the loud ones. The bog does that itself, in its own slow time."),
                ScoutsLordsProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_119", "The Battanian lords of Marunath send their fian-bands south into my fenland each spring, and each spring the bog drinks a few of them quiet. They come hunting heads, they come hunting the bounty their high king set on my women. They do not come back the same number they rode in. Lord Caladog's vassals are the worst of them - a clan that calls itself the Wolfskin, led by a thane named Brennus mac Tarn. He lost a brother to my reeds two winters past and he has not forgotten the debt. Nor have I.\n\nThe Vlandian outriders push east from Galend now, chasing Battanian cattle and Battanian scalps both. Their sergeants do not know the fen the way the high-king's men know it - they ride heavy, they ride in mail, and the soft ground takes them down to the chest before they understand what country they are in. My watchers count them in and count fewer out. That is the only arithmetic the fen knows.\n\nThe southern Empire sends tax-riders up the old road sometimes, looking for tribute the Battanians forgot to pay. They do not find it. If you carry a banner of any of these three south of the stilt-paths, traveler, the reeds will know your colors before I do. The fen has older eyes than mine. Walk gentle."),
                ScoutsClanProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_120", "The Frost Reavers' Vargolf carries a token I gave him five winters past. He rode down a Vlandian outrider for me when my own kin could not cross the snow. I have not repaid. He has not asked. The fens teach patience, and Vargolf is a patient man for one who lives by the axe. When the reeds bend, I will send him what is owed. Not before.\n\nThe Highwaymen on the downs - their Reeve and I do not speak. He measures men by the weight of their purse. I measure them by what they leave in the water when they pass. We have different scales. Granny Hod's forest band to our north shares the wet country with us, and she has been kind. Her people bring us pelts. We send back salt and silence. That is enough.\n\nThe Sky Raiders worry me. Aerlin's people have come down from the high crags three times this moon, hunting in fens that are not theirs. Birds do not belong in the mud. My scouts found their feathers near the old causeway, and one of my daughters did not come home from that walk. I do not name a debt yet. The water remembers. When the reeds tell me her name, I will go where Aerlin sleeps and we will speak of it quietly."),
                ScoutsCaravanProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_121", "A Battanian salt-train comes up from the coast every third week, traveler. Six wagons, eighteen spears, a captain named Cadoc who drinks the marsh-pear wine my girls leave at the milestones. He thinks it a gift from a grateful village. It is not. By the time his column reaches the causeway south of Marunath his hands are slow and his eyes are softer than reed-water. That is where the road narrows to one wagon's width between two stilt-pools, and a man who steps wrong drowns in mud that does not give him back.\n\nThe salt is the lure. The fourth wagon carries Vlandian glass and southern dye-pots bound for the Battanian thanes - small crates, heavy purses, the kind of cargo that does not spoil if it sits a season in a fen. The escort tightens around the salt because they think that is what we want. They are wrong. We take the fourth wagon while the spears guard the first.\n\nGo three nights from now, an hour before the moon clears the alders. Bring fifteen riders, no more - horses sink past the fetlock off the causeway and a crowd only feeds the bog. Leave Cadoc breathing. A captain who keeps losing the same wagon is worth more to me than a dead one, and the Highwaymen east of here would charge you for that lesson. The fen takes what it takes. We only carry the rest away."),
                PactTeaseProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_122", "You speak the slow-water question. Most who sit at my reed-fire chatter of silver and seasons; you have asked the thing the bog hears. Sit. Let the smoke take its time. A knot tied in haste slips when the tide turns, and what you ask of me is a knot the fen will be asked to remember.\n\nWhen the time comes, I bleed for the names the water already knows. My grandmother, who walked into the mire so her daughters would not be sold south. Aelwyn of the third stilt-house, who hid my wounded under her floorboards while the Imperials probed the reeds with spears. A Vlandian deserter named Coros who fed my scouts for a winter and asked nothing. Three names. The fen keeps them. It does not yet keep yours.\n\nBring me a deed the marsh can drink. A southern tax-boat sunk where no one will dredge it. A village warned before the legion's torches reach the thatch. A debt of mine, paid quietly, before I have spoken it aloud. Do that, and the reeds will whisper your name when I am not there to say it. Until then, my knife is mine, my stalkers are mine, and the slow water between us has only begun to rise. Ask me again when the tide has turned."),
                OathBrotherProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_123", "Then the reeds have heard you, and the reeds are slow to forget. Kneel at the water's edge with me. I cut my thumb on the bone-hook I wore the year my mother drowned holding the stilt-rope for the children, and I press that old scar to yours - see, the blood goes into the black water the same, your red and my red curling like two eels finding one current. Drink from the cup of fen-water and crushed bog-myrtle. Spit. The marsh has tasted you. It will not give you up to any lowlander's hound or any Marunath rider's torch. You are reed-bound now, and the reed bends but does not break, and neither do we.\n\nBrother, in the fenland, means hearth-share under one stilt-roof when the floods come. It means my daughters call you uncle and bring you the first ladle. It means when I dream a warning of horses in the mist, I dream it for you also. My silence is your shelter. My knife is your knife. The path through the bog that only I know - the safe boards under the black water from the heron-stone to the old wicker shrine - that path is yours now. You will never wade blind again where I have walked.\n\nStilt-brother. The longhouse on the south island learns your name before dawn. The drowned-king under Marunath learns it when the tide turns. And the Battanian lords who burned my aunt's holdfast in the year of low water - they will read your name in the reeds and know my feud rides with two heads now. Walk soft. Walk with me."),
                PactAnswerProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_124", "Then the answer is heard, and the reeds heard it before I did. You did not bring me a speech, traveler. You brought me a deed still wet, and you laid it at the edge of my fire the way a heron lays a fish at the foot of her chick - without ceremony, because the work itself was the ceremony. A lesser walker would have spoken first and bled later. You bled first. That is the order the bog trusts. Sit. Let the water settle around what you have done.\n\nFrom this tide forward, my Stalkers wade where you wade. Not as guides you have hired. Not as a debt I can drain dry. As blood-allies, bound the way two reeds knot beneath the surface where the current cannot see them - one cannot be pulled without the other tearing free of the silt. Your feud is now ours. The hunters who track you through the lowlands will find Stalker-spears rising out of water they thought was empty. In turn, when my fen is burned at, you raise your banner south of Marunath and you come.\n\nThe wind carries oaths better than mouths do, and the fen-wind has long memory. It already knows your name beside mine. When the steel sings, walker, the marsh will hear it and answer. We are kin in the cold work now. That kinship does not thaw."),
                TroopLoanProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_125", "Done, walker. Ten of my fen-walkers, hand-picked, for seven turnings of the moon - I will whisper their names to the reeds before they go. My second is Yslen Reed-Tongue, who reads water the way you read maps. She walks at your shoulder. The spear-girls follow her quiet, and she answers to me.\n\nHear my terms. If a stalker of mine sinks in your work, you bring her spear back to me unwashed - the marsh knows its own blood and will want it. If she walks home, she walks home fed. My fen-walkers do not bend reed for coin or for cruel sport. While they wade under your banner, your road is my road - so do not spend them on shallow water. Seven days. Count each dusk.\n\nThe reeds will be told who rode out. The reeds will count who comes back."),
                NamedTargetAcceptProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_126", "His name is {TARGET}. His banner stands over {HOME}, on dry stone, on land that drinks no water and remembers no debts. The bog remembers. Nine summers back his huntsmen rode my sister Aelwyn into the reed-flats below the old causeway - drove her horse until it foundered, then left her to the leeches and the slow cold. They called it a hunt that strayed. {TARGET} signed the writ that paid them. The reeds have held her name in green knots ever since, and tonight the knots came loose in my hand when you walked through the door.\n\nHe travels with a dozen retainers and a Battanian tracker who owes him no love - a man named Ceol, scarred down the jaw. Ceol fishes the slow channels east of {HOME} at every new moon, alone, and a quiet word and a coin will pull him onto your side. {TARGET} keeps to the high road, sleeps in stone halls, fears the wet ground. Take him where the path turns soft. He will not know the footing.\n\n{REWARD} denars when the water carries his name back to me, traveler. The reeds want him more than the gold does, but the gold is the shape the debt has taken. The bog remembers the rest. Ride."),
                NamedTargetReason = BandItPlus.Localization.Get("bp_cultureprofileregistry_127", "{CHIEF} has named {TARGET} of {HOME} as the debt the marsh has held in its black water for nine flood-seasons. The grudge is patient and exact - a sister-by-water named Vethra, drowned in the reed-cuts above Old Pelm fen on a tax-rider's order, her body weighted with iron and her name unspoken at any pyre. {CHIEF} keeps a knot of bog-rope for each wrong, hung from the willow-post above his pallet, and only one knot remains untied. The Mireborn offers a heavy purse of {REWARD} and the closing of a debt the still water will not forget. The reeds part southward. The bog remembers. The contract is open."),
                NamedTargetComplete = BandItPlus.Localization.Get("bp_cultureprofileregistry_128", "{TARGET} is drowned-still, and {CHIEF} has been told, and {CHIEF} has heard. The reed-knot for the sister Aelynn - the one cut down at the Greyfen sluice in the wet-spring three floods past, her body left in the eel-weir for the bog to keep - that knot is at last untied from the alder-post and laid on the slow water. {REWARD} denars rest in the stalker's wicker, counted twice by reed-light. The fen does not forgive, but it does remember, and tonight it remembers a thing finished. The bog has drunk its answer, and the water is quiet again."),
                NamedTargetOtherCauseProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_129", "The rumour drifted into the reed-camp on a peat-merchant's tongue: {TARGET} had been ridden down by a rival lord's outriders on a winter road, throat opened before any bog-knot could be tied around it. {CHIEF} listened without lifting his eyes from the bowl of murky water he was scrying, then set it aside and murmured Vethra's name once - the sister who drowned in reed-cuts on a tax-rider's order, whose bog-rope memorial still hung at the camp's edge. The grudge was answered. The hand that answered it was not the one promised. {CHIEF} counted out {REDUCED_REWARD} denars in thin coin, quarter-pay for a kill borrowed from another man's blade, and the bond between them settled a small notch firmer - cooler than a knot pulled tight by earned hands."),
                RaidVillageAcceptProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_130", "\"There is a village called {VILLAGE} crouched on the dry hummock above my reed-cuts, held by thane {LORD} of the Battanian huntsman-clan that drove three of my fen-walker girls into the deep cuts six summers past. {LORD}'s grandsire dug the first diversion ditch that year. His huntsmen laughed when they heard the girls calling under the water. The ditches still drink my fen. I have not forgotten which spades cut them.\n\n{LORD}'s outriders ride west on the dark of the moon to hunt the Battanian boar-runs - four nights, sometimes five. The village holds drained-field grain and the iron spades they use to widen the ditches every spring. Burn the spade-stores first. Throw the grain in the cuts. The smallfolk dug the ditches with those same hands - leave none of the diggers walking.\n\n{REWARD} denars when the diversion ditches run black with ash. The bog drinks the rest. Go quiet, and go before the dark moon thins.\""),
                RaidVillageReason = BandItPlus.Localization.Get("bp_cultureprofileregistry_131", "{CHIEF} has named {VILLAGE}, the thane-fief of Lord {LORD}, as the settlement whose drowning will answer a debt six summers deep. The Battanian huntsmen of that hall once ran three of the chief's fen-walker girls into the reed-cuts and left them to the suckmud, and the diversion ditches their thane has since cut through the upper marsh have drained the fenland a yard further every spring. The water that fed the chief's pools now feeds their barley. {CHIEF} offers a quiet purse of {REWARD} and asks only that the ditches be choked, the thatch put to torch, and the reeds given back what was taken. The contract is open. The fen is listening."),
                RaidVillageComplete = BandItPlus.Localization.Get("bp_cultureprofileregistry_132", "{VILLAGE} lies drowned in its own smoke, and {CHIEF} has been told. The thane-hold of Lord {LORD} - the same Battanian blood whose huntsmen drove three fen-walker girls into the reed-cuts six summers past - is ash and sodden timber, the diversion ditches already choking on cinder and silt as the fen drinks back what was stolen. {REWARD} denars lie counted on the bog-oak plank where {CHIEF} reckons her debts, and the reed-bond between marsh-king and traveler is knotted tighter by one wet knot. The water keeps the rest. Three names are washed a shade cleaner."),
                RaidVillageOtherCauseProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_133", "Word slid through the reed-stems on a fen-runner's tongue: {VILLAGE} lay black and silent, its diversion-ditches choked with ash, but the burning had been some other lord's quarrel, a feud with no thought for the three fen-walker girls drowned in the reed-cuts six summers past. {CHIEF} heard it standing knee-deep in the still water and only nodded once, slow as a heron settling. The thane-clan's huntsmen had paid, but not to him, and not by his hand. He bid the marsh-steward count {REDUCED_REWARD} denars onto the peat-bench - thin water-coin for a debt closed by stranger's flame - and the bond between Fen-Speaker and traveler held, quiet as standing water before frost."),
                // 2026-05-25 rewrite: SOUND-FIRST / BLIND-RECEPTION shape. The marsh is
                // received through audio cues alone — frog-chorus stopping, paddle-click,
                // hushed child, heron lifting — until a hand the player cannot see
                // finds the bridle. Visual is withheld. No companion-quote pivot, no
                // negation list, no "you watched" reveal. Ends in dialogue from an
                // unseen speaker.
                HideoutCinemaIntro = BandItPlus.Localization.Get("bp_cultureprofileregistry_134", @"You hear them before you see them.

Or you do not hear them — you hear what they have made the marsh stop saying. The frog-chorus that had filled the dark a hundred yards back is gone. The night-birds that called overhead have gone with it. There is the soft drip of water off a hanging leaf, and there is the long whining drone of insects, and there is nothing else.

That is the first sound of the camp.

The second sound is the small wet click of a paddle-pole, somewhere off to your left, where you cannot see it. You stop your horse. You wait. The click does not come again.

Third: a child's voice, beginning to rise, and a woman's hand cutting it short. You know the second sound by its quality — you have heard mothers quiet children all your life. You did not know one could do it so fast.

Fourth: a heron, lifting. A long slow heavy lift of wings. Somewhere in the green. The reeds bow and resettle in three places at once, which is wrong, because a heron is one bird.

You sit your horse in the standing water and you understand by your skin and your ears alone that you have been inside the camp for some time now and not seen it.

Then a voice from the reeds, very close, not loud:

""Walk the horse left. The bog past your right knee will take it.""

You walk the horse left.

A hand finds your bridle out of the green. The fingers are cold. The wrist is mud to the elbow. You do not see the body.

""Mireborn was wondering when you'd come. Step down. Slow.""

You step down. Slow."),
                ServiceLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_135", "Bargain with the poison brewer."),
                ServiceFlavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_136", "An old man with shaking hands stirs a pot of green liquid. \"Arrows? Throwing knives? I coat what you bring. Not free.\""),
                Kind = ServiceKind.PoisonBrewer,
                BribeAmount = 200,
                WhyNotKingdom = BandItPlus.Localization.Get("bp_cultureprofileregistry_137", "\"A king's flag would sink in our marsh. Our great-grandmothers fled a king. We remember.\""),
                Religion = BandItPlus.Localization.Get("bp_cultureprofileregistry_138", "\"The marsh has its own. The fen-mother who eats unbaptised children. The reed-spirit who hides our dead.\""),
                ThreatResponse = BandItPlus.Localization.Get("bp_cultureprofileregistry_139", "Mireborn smiles, slow. \"You shout in a marsh and the marsh laughs. Cut me down — try. The mud takes its share before the blade does.\""),
                Pleasantry = BandItPlus.Localization.Get("bp_cultureprofileregistry_140", "She tilts her head. \"You like our reeds? Most don't. Most see only the smell.\""),
                DrinkFlavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_141", "Stalkers brew a marsh-mead from fen-flowers. It tastes of rain and honey. Mireborn raises her cup without speaking. The toast is silent."),
                RestFlavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_142", "You sleep on a reed-platform, the marsh whispering below. Strange dreams come, full of green light. Your party wakes oddly rested."),
                ExtraServices = new[] {
                    new CultureSubService { Label = BandItPlus.Localization.Get("bp_cultureprofileregistry_143", "Rent a marsh-skiff for the day. (100 denars)"), Flavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_144", "A young Stalker punts a flat-bottom skiff over from the reeds. \"Take it. Bring it back. Or don't. We'll find another. The marsh is full of lost boats.\" Your party feels well-rested from the diversion."), Kind = ServiceKind.TollMaster, GoldCost = 100, MoraleGain = 3 },
                    new CultureSubService { Label = BandItPlus.Localization.Get("bp_cultureprofileregistry_145", "Trade with the bone-collector."), Flavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_146", "A child no older than ten tends a stall of dried frog-bones, river-pearls, snake-skin. \"For the druid who buys these, mostly. But you can have what you want, if you trade fair.\""), Kind = ServiceKind.Hunter },
                    new CultureSubService { Label = BandItPlus.Localization.Get("bp_cultureprofileregistry_147", "Consult the Seer of Mires."), Flavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_148", "A blind woman is led from a hut. Mud streaks her arms. She sniffs the air around you. \"Something walks beside this one. Not a friend. Listen.\""), Kind = ServiceKind.Oracle },
                },
                Rumors = new[] {
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_149", "\"There's a sunken merchant boat in the eastern fen. Hasn't been picked clean.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_150", "\"Battanian druid lives three islands east. He buys frog-bones, nothing else.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_151", "\"The Vlandian baron's been sending hunting parties into our marshes. Six have come back.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_152", "\"A nobleman's daughter is hidden in our reeds. Her father has offered triple if we hand her over.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_153", "\"Old Battanian tomb in a marsh-island, unopened. The wards have weakened.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_154", "\"A wandering monk asks too many questions. We let him keep wandering.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_155", "\"There's a cure for marsh-fever growing only in our fens. We don't tell the towns where.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_156", "\"Imperial mapmaker tried to chart our marsh last spring. We sold him bad maps.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_157", "\"A boatman at Kefraje smuggles into and out of the marsh. Tell him Mireborn sent you.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_158", "\"A heretic priest hides among us. The temple wants him alive.\""),
                },
                TrustQuestTier1Pool = new[] {
                    new TrustQuest {
                        ItemIds = new[] { "hardwood" }, Counts = new[] { 20 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_159", "\"Trade? Bring me twenty bundles of hardwood — the marsh eats our walkways faster than we can lay them.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_160", "The chief runs a hand along the planks. \"Dry. Heavy. The Stalkers know your face now.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_161", "20 hardwood"),
                    },
                    new TrustQuest {
                        ItemIds = new[] { "fish" }, Counts = new[] { 25 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_162", "\"Twenty-five fish. The reed-children eat first; the warriors eat after. Bring it.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_163", "Mireborn nods. \"The marsh feeds tonight. Trade with my people.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_164", "25 fish"),
                    },
                    new TrustQuest {
                        ItemIds = new[] { "leather" }, Counts = new[] { 20 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_165", "\"Twenty leather. Reed and rope rot fast in the wet — we bind everything in skin. Bring it.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_166", "She tests a strip between her teeth. \"Properly cured. The marsh-walks will hold another season.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_167", "20 leather"),
                    },
                },
                TrustQuestTier2Pool = new[] {
                    new TrustQuest {
                        ItemIds = new[] { "hardwood", "mule" }, Counts = new[] { 40, 5 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_168", "\"Forty hardwood and five mules to haul it. The marsh eats footing — we need new hide-walks across the deeper pools.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_169", "She claps the lead mule. \"Good beasts, good wood. The deep camp is open to you.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_170", "40 hardwood + 5 mules"),
                    },
                    new TrustQuest {
                        ItemIds = new[] { "fish", "leather" }, Counts = new[] { 30, 20 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_171", "\"Thirty fish and twenty leather. The fish for the deep-camp larder, the leather for our hunting harness. Bring both.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_172", "Mireborn signals her quartermaster. \"Stocks topped, harness mended. The marsh trusts you now.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_173", "30 fish + 20 leather"),
                    },
                    new TrustQuest {
                        ItemIds = new[] { "hardwood", "fish" }, Counts = new[] { 50, 10 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_174", "\"Fifty hardwood and ten fish. We rebuild the eastern walk after the floods. Bring both.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_175", "She watches her builders test the new boards. \"Sound enough for ten seasons. The Stalkers honor your work.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_176", "50 hardwood + 10 fish"),
                    },
                },
                TrustQuestTier3Pool = new[] {
                    new TrustQuest {
                        ItemIds = new[] { "hardwood", "ironIngot2" }, Counts = new[] { 100, 10 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_177", "\"A hundred hardwood and ten wrought-iron ingots. We forge marsh-spikes for the eastern approach — they'll lame the imperial cavalry next spring.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_178", "Mireborn smiles, slow as water. \"The marsh defends itself now. You have done a Stalker-elder's work.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_179", "100 hardwood + 10 wrought iron"),
                    },
                    new TrustQuest {
                        ItemIds = new[] { "leather", "fish", "mule" }, Counts = new[] { 50, 50, 5 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_180", "\"Fifty leather, fifty fish, five pack-mules. The whole deep-camp gets re-supplied for the wet season. Heavy haul — only kin do this.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_181", "She lays a hand briefly on your forehead. \"Marsh-kin now. The reeds won't betray you.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_182", "50 leather + 50 fish + 5 mules"),
                    },
                },
                // Wave 5 (Chief Recruitment) alliance content
                AllianceCh1TaskBrief = BandItPlus.Localization.Get("bp_cultureprofileregistry_183", "Destroy a Vlandian outrider company that has pushed too far into the reeds at Mire's-End."),
                AllianceCh1Pattern = AllianceCh1Pattern.DestroyPartiesOfType,
                AllianceCh1TargetSeedHint = "vlandian_outrider_party",
                AllianceCh3RitualText = BandItPlus.Localization.Get("bp_cultureprofileregistry_184", "The Mireborn accepts your oath; the rite is sealed knee-deep in marsh water over the sunken stone idol."),
                AllianceCh3GiftItemId = "sickle_1h_t3",
                AllianceBrokenText = BandItPlus.Localization.Get("bp_cultureprofileregistry_185", "Mireborn says nothing for a long beat. Then, quietly: \"The reeds do not forget faces. Step careful in the marsh from now on.\""),
            }},
            { "bp_highwaymen", new CultureProfile {
                ChiefName = BandItPlus.Localization.Get("bp_cultureprofileregistry_186", "The Reeve"),
                Signature = new SignatureQuestSpec
                {
                    Title = BandItPlus.Localization.Get("bp_cultureprofileregistry_187", "The Reeve's Arrears"),
                    HeraldLine = BandItPlus.Localization.Get("bp_cultureprofileregistry_188", "You there — the Reeve's asking for you. Some merchant lot ran his roads a whole season and never paid a copper. He's ruled a fresh page and everything. Fresh page means work. Best hurry."),
                    OfferProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_189", "Sit, traveler. The stump is for sitting. Page thirty-two — the Wenshal combine. They ran my roads a full season unpaid. Ninety-one wagons by my count, and not a copper entered. Now their strong-wagon rolls south carrying the season's takings, hired blades around it and a guild factor on the box who signs receipts in a very fine hand. Find that wagon. Collect the arrears — principal plus interest, fourteen percent, compounded quarterly by insult. The factor will offer you talk; he sells it by the yard. Do not buy. Coin or the wagon itself, I am not particular. The ledger only asks that the column close."),
                    AcceptProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_190", "Good. The entry is open — Wenshal, arrears plus interest. Bring me the sum or the wagon that carries it. And traveler — leave the factor able to write. Someone must sign the receipt."),
                    DeclineNudge = BandItPlus.Localization.Get("bp_cultureprofileregistry_191", "As you please. But one unpaid toll teaches every merchant on the road the same arithmetic. The column stays open. Interest accrues. Come back before it compounds into something bloodier."),
                    BusyLine = BandItPlus.Localization.Get("bp_cultureprofileregistry_192", "You carry an open contract already, traveler — I can read an unclosed column off a man's shoulders. Settle your own page first. Then we will talk about Wenshal's."),
                    TargetPartyName = BandItPlus.Localization.Get("bp_cultureprofileregistry_193", "Wenshal Strong-Wagon"),
                    CaptainName = BandItPlus.Localization.Get("bp_cultureprofileregistry_194", "Guild Factor Hamon"),
                    JournalObjectiveText = BandItPlus.Localization.Get("bp_cultureprofileregistry_195", "Find the Wenshal Strong-Wagon on the western roads and collect the Reeve's arrears. The merchant combine ran his tolled roads unpaid for a full season, and the wagon carries the season's takings under hired guard."),
                    JournalReturnText = BandItPlus.Localization.Get("bp_cultureprofileregistry_196", "The Wenshal account is settled. Return to the Reeve at his camp to enter the sum in his ledger and collect your share."),
                    ConfrontIntro = BandItPlus.Localization.Get("bp_cultureprofileregistry_197", "Ah. The Reeve's collector — he does keep punctual staff. Let us not waste the light. I am authorized to discuss figures, and my blades are authorized to discuss everything else. Which conversation are we having?"),
                    Choices = new[]
                    {
                        new SignatureChoice { Label = BandItPlus.Localization.Get("bp_cultureprofileregistry_198", "You know my name. Pay the full arrears, with interest."), Requirement = SignatureRequirement.Renown, RequirementValue = 150, Outcome = SignatureOutcome.ComplyFull, ResultProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_199", "I do know it. Everyone on this road does, more's the pity. Very well — the full sum, and the Reeve's usury on top. Open the box. Note, please, that I was courteous.") },
                        new SignatureChoice { Label = BandItPlus.Localization.Get("bp_cultureprofileregistry_200", "Half the arrears now, and your wagon rolls on."), Outcome = SignatureOutcome.ComplyHalf, ResultProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_201", "Half. Yes. A sensible figure — the figure I was authorized to reach, as it happens. The combine will be pleased. Do give the Reeve my compliments on his flexible arithmetic.") },
                        new SignatureChoice { Label = BandItPlus.Localization.Get("bp_cultureprofileregistry_202", "No figures. The Reeve sent me for everything."), Outcome = SignatureOutcome.Battle, ResultProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_203", "Pity. Blades — earn your wages. Hold the wagon, no quarter, and someone mark the time for my report.") },
                    },
                    DemandFailProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_204", "Forgive me. I keep the combine's correspondence for three kingdoms, and I pride myself on names — yours has never crossed my desk. Not once, in any hand. So we return to figures, and the figure, respectfully, is no."),
                    ClosingProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_205", "Full weight. I have counted it twice and the second count flattered the first. A season of arrears, the interest to the copper, and a receipt signed by their own factor — that last is worth more than the coin. Every combine from Pravend to Galend will read this column by market-day and pay at the milestone like honest men. Your share, weighed fair. The road keeps its law, traveler, and today you were the law's handwriting."),
                    ClosingProseAlt = BandItPlus.Localization.Get("bp_cultureprofileregistry_206", "Half. Mm. Half settles the principal and leaves the insult drawing interest. I will take it — coin refused is coin wasted — but the column does not close. It carries forward to a new page with Wenshal's name at the head, and next season their toll doubles until the balance clears. Your share, counted to the copper. Adequate work earns an adequate entry, traveler. The full-weight column would have earned you a better one."),
                    ClosingProseOtherCause = BandItPlus.Localization.Get("bp_cultureprofileregistry_207", "A war-party out of the south broke the wagon before you reached it — I had the dispatch at second bell. The takings went into the ditches and the pockets of men who keep no books. My riders recovered perhaps half; the rest is scattered arithmetic. The column closes at half-weight, marked as act of lords — the one entry no clerk can prevent. Half fee, counted clean. You rode in good faith, and the ledger records faith even when it cannot record delivery."),
                    RewardGold = 1600,
                    RewardRelation = 8,
                },
                ChiefTitle = BandItPlus.Localization.Get("bp_cultureprofileregistry_208", "Toll-Reeve"),
                ChiefBackstory = BandItPlus.Localization.Get("bp_cultureprofileregistry_209", "Before he was a bandit he was a clerk — third son of an Imperial border-lord's secretary, sent to the road-courts at fourteen to learn the trade his elder brothers were too well-connected to bother with. He rode the south-eastern circuits for twenty years with a strongbox and two armed escorts, collected the road-tolls for a different lord every five seasons, and never once short-changed an account. The trouble began when the lord he served stopped opening the books — the man's wife had taken to gambling and his stewards to drink, and the strongbox was no longer being audited at all. The Reeve discovered, one quiet autumn, that the lord's records were lazier than his own counting; coin could disappear and bandits would be blamed because there were always bandits to blame. He arranged the first false robbery himself, walked away with a year's salary, and reported it stolen with two genuine tears. By spring he had a band of twelve, all former soldiers the lord had cashiered for petty offences. The Reeve has been a bandit for fifteen years now; the books he keeps in his saddlebag still balance to the copper, and he files his year-end accounts with a forger in Praven who passes them up the line as if nothing has changed."),
                ClanHistory = BandItPlus.Localization.Get("bp_cultureprofileregistry_210", "The Highwaymen are the youngest of the great bandit bands and the only one organized like a magistracy. The Reeve founded them eighteen years ago with seven other dismissed Imperial road-clerks — men who knew the toll-tables and patrol-rotations of every road between Pravend and Lageta because they had written them. The pool they draw from is not peasants or veterans but clerks, accountants, and literate sons of small-merchants who lost positions in the imperial reorganization — men whose hands could hold a quill and whose standing could not survive a clerk's dismissal-notice. The band keeps a real ledger: every taken purse entered, every share calculated, every captain audited at the end of each season. They never burn what they take; they negotiate ransoms in writing, on parchment, with imperial seal. Three Imperial circuit-judges have been Highwayman captives — two paid in silver, one in grain — and all three were released on the same road they were taken from with their robes brushed clean. The Empire still has not declared the band outlaw because it does not yet know how to outlaw an institution more orderly than its own road-courts."),
                ChiefGreeting = BandItPlus.Localization.Get("bp_cultureprofileregistry_211", "A clean-shaven man in stolen Vlandian leathers does not look up from his ledger as you approach. He finishes his column, sets the quill down, and only then meets your eyes — calmly, almost professionally. \"Welcome. The stump is for sitting. We do business by the page here, traveler — every coin recorded, every favor inked. So tell me your name, your purpose, and what page of mine you'd like to be written on.\""),
                ChiefGreetingTolerated = BandItPlus.Localization.Get("bp_cultureprofileregistry_212", "The Reeve has your name in his ledger now. He nods you toward the stump without looking up, finishes a notation, and only then sets the quill aside. \"Welcome back. Page seven, line eleven — I keep all repeat business in the same column. What entry are we adding today, traveler?\""),
                ChiefLoyaltySpeech = BandItPlus.Localization.Get("bp_cultureprofileregistry_213", "Names go on page one, traveler. Page two is where I record what's been done for the company — that's the column that matters to me. There's an entry waiting for you there. Earn it, and we'll talk business proper. Until then, you're a heading without a story."),
                CampIntro = BandItPlus.Localization.Get("bp_cultureprofileregistry_214", "The Highwaymen camp is orderly — almost like an army camp. Tents in rows, watch-fires at four corners, a cook-tent with a real pot. The Reeve runs it like a counting-house."),
                HideoutDirections = BandItPlus.Localization.Get("bp_cultureprofileregistry_215", "Take the post-road south from Charas, traveler, and keep the milestones on your right hand until you count the seventh. There you will find a cairn the locals stack higher each summer - my men add a stone for every purse the road owes us. From the cairn, follow the cart-ruts west to the old toll-house, the one the crown burned in the famine year and never rebuilt. Past its broken chimney the stake-fence begins, and each post is numbered in tar like a clerk's ledger. Our hold lies at {HIDEOUT_NAME}, at the end of that counting.\n\nThe watch-tower on the rise sees you long before you see it. My scouts will mark your party, count your spears, weigh your saddlebags by the set of your horse's gait - we keep a running tally the same as any honest house of business. Ride slow, hands open on the reins, and when you reach the third numbered post, halt and let them read you. A man who hurries past the count is a man who means to cheat the count.\n\nCome correct and the gate opens to tents in proper rows, watch-fires at four corners, and a cup of decent wine while we settle accounts. Come crooked and you join the ledger on the wrong side of the page - we balance the books before the moon turns, and the downs are wide enough to bury what does not balance."),
                ScoutsLordsProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_216", "The Reeve: \"Vlandia owns these downs on parchment, traveler, and parchment is what I read. The crown sends its tax-riders down the Charas-Galend road four times a season - I have the dates ruled in my ledger, ink still wet on the last column. Lord Derthert's bannermen pass through in spring chasing tournament purses, the lesser knights in autumn chasing imperial mercenary contracts. Both pay my toll. Neither knows they paid it.\n\nThe house I watch closest is Clan Caraveer. Their seneschal raised my toll by three denars last Praven assize and called it a road-tax. I have raised his caravan-losses by three hundred. We are square now, by my count, but he does not yet know we are keeping the same book. There is also a Vlandian outrider captain - Sir Almund of the southern marches - who has burnt two of my watch-posts this year. His head is worth eighty denars on my ledger and I will pay it to the man who brings it.\n\nThe Battanian raiders cross the western tree-line whenever Marais sleeps, and the imperial cataphracts come north when the Khuzaits press them. Both ride through my country without paying. I do not forget a crossing, traveler. If you carry a kingdom's banner one day, ride the long way around the junction at Galend. The Reeve's ledger has a column for friends and a column for tolls, and I will know which side to write you under.\""),
                ScoutsClanProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_217", "Let me reckon the ledger. The Reavers up north - Vargolf's lot - I do not share fire with, as he no doubt told you. He counts cousins. I count coin. A man who weeps over kin will burn a profitable bridge to prove a point, and I have crossings to keep open. We have an arrangement of distance, which is the cheapest kind of peace. Owes me nothing. I owe him nothing. Long may that column balance.\n\nSkarvac's pass-lords in the mountains owe me four hundred and twenty denars from the spring caravan we routed onto their road for a cut. They have paid one ninety. I am patient. Interest accrues at a denar a week in goodwill, and I will collect in salt or in throats, whichever moves first. Granny Hod's forest band south of Galend is the trouble this season - she has taken to charging her own toll on MY road, the stretch between the two mileposts past the ford. That is a debt of blood and copper both, and I am tallying it.\n\nThe Stalkers in the fens have gone quiet these six weeks. No runners, no token-trade, no smoke from the marsh-fires. That is never good news. Either the Mireborn is dead, or she is moving men somewhere she does not want counted. I have a boy watching the causeway. When he comes back I will know the price."),
                ScoutsCaravanProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_218", "Three columns matter on these downs, and I have them all in the ledger. The Charas-to-Galend wool train rolls every eighth day - four wagons, eight crossbow levies, a Vlandian sergeant who counts heads at every milestone but never looks up the bank. He thinks the road is the danger. The road is never the danger. The bank above the third ford is the danger. We have lifted his rear wagon twice and he still writes the same route in the same hand to the same boyar.\n\nThe second column is the salt-cart out of the Pravend mines - two wagons, six guards, but the captain is a sober man named Otric and I will not waste men on him. Mark him off. The third is the prize: a Vlandian merchant-banker's strongbox-wagon that rides hidden inside a grain convoy on the new-moon week. Twelve outriders, but only four know what they guard. The rest think they are minding oats.\n\nIf you want clean coin, traveler, take the wool train at the third ford on the eighth day. Bring twelve horse, hit from the upper bank, leave the sergeant alive so he writes the same report and the boyar sends the same caravan again. That wagon has paid my winter for three years. I will charge you nothing for the route - I have already taxed it. Just do not break the pattern. A broken pattern is a closed purse."),
                PactTeaseProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_219", "You ask a ledger-question, and you ask it sober, which is more than most. Sit on the bench across from me. I keep two books at this junction - the day-book, where every wagon and every toll is entered fresh, and the red-book, where the debts that outlive coin are signed in a hand that does not smudge. You are asking after the red-book. Few travelers know it exists.\n\nThe red-book is short. There is the smith at Galend who shod my horse the winter the road froze and would not take silver for it - his name is in red. There is the Charas notary who burned a writ of seizure rather than serve it on my mother's house - his name is in red. There is a captain of the southern road, dead now, who rode against four men so I could finish counting a tithe-chest - his name is in red. When their kin come to this junction, the toll is a smile and a cup. When their enemies come, the toll is something else.\n\nYou are entered in the day-book, traveler, in a careful column. Bring me a deed I can write in red - a debt collected that the law would not collect, a wagon turned my way when the south leaned on you, a column closed in MY favor - and the red-book learns your name. The contract is open. It is not yet signed. Come back when the entry is ready."),
                OathBrotherProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_220", "Then the entry is made. Sit. The red book opens between us - here, on the left page where my own mark was cut when old Halbrec the Counter put a knife to my thumb on the Charas road thirty winters back. Press your thumb to the wax. There. The ledger takes the print. Now the quill, now the line beneath: paid in full, no balance, no lien, no further reckoning. I sign as witness. The book signs as oath. Drink the small beer from the clerk's cup - it is sour and it is honest, the way every true entry is. The red wax cools. The seal holds. We are written.\n\nBrother, in my trade, is the one line the ledger cannot strike. Coin can be returned. Tolls can be refunded. A debt of silver settles and the page closes. But a brother-entry runs forever in the margin, carried forward year on year, paid in kind and never in coin. My cousins at the Galend weigh-station become your cousins. My ink is your ink. What is owed to me is owed to you, and what wounds you wounds the book itself - and the book does not forget. From this hour my reeves call you kin.\n\nThe Charas toll-house learns your name tonight. The downs-clerks of Galend learn it by morning rider. Count Derthert's tax-men will read it next time they audit our road - and they will know the second name on the seal is no longer alone. Brother. The ledger is one."),
                PactAnswerProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_221", "So. The ledger answers itself. I asked you a question on the Charas road - whether you would bleed for me when the column came - and you have not answered it in words. You have answered it in a margin entry, paid in full, dated before I knew to ask. That is the order I keep. Deed first, word after, signature optional. A lesser hand would have ridden in with a speech and a thin purse. You rode in with the purse heavy and the speech almost forgotten. Sit. The ink of what you have done is still wet, and I am the man who reads it.\n\nFrom this audit forward, the Reeve's books carry your name in the red column - not as debtor, not as patron, but as co-signatory. When you raise your banner against a house, my toll-riders ride against that house, no fee, no question, no separate reckoning. The downs between Charas and Galend are your passage now, road-tax waived, gate-coin returned. In exchange, when my collectors are run down by some baron's hounds, your sword answers the summons. This is not the hearth-bond. This is the war-bond. Costlier. Plainer. Older.\n\nMy old reeve was killed for a ledger he would not surrender. I have kept it since, and now your name is in it, in the same red ink, on the same page. The wind off the downs carries the sound of drawn steel a long way. Let it carry ours together. We are bound in the WORK now - and the work has never released a man yet."),
                TroopLoanProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_222", "Marked in the red book. Ten collectors, seven days - I have already drawn the tally line beside their names. My under-reeve goes with them: Vellic of the Short Quill, who keeps the count when I cannot. He carries my seal. What he says on the road is what I would say. The collectors answer to him, and he answers to me.\n\nNow the terms, traveler, and I will speak them plain so the ledger is clean. If a road-man of mine falls in your work, you bring me his tally-stick and the coin he was carrying - both, not one. If he lives, you return him on the seventh day with his boots still on his feet. My reeves do not break shield for petty road-work. They break shield for tolls owed and debts collected. While they ride your road, your road is on my ledger - so do not spend them on errands a farmboy could run.\n\nSeven days. I will mark the date their tally reopens. The red book remembers what men forget."),
                NamedTargetAcceptProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_223", "The name is {TARGET}. Banner over {HOME}, signet in red wax, and a debt in my ledger eleven years old. Page forty-one, third column - one hundred and twenty wagons of southern grain, paid for in good Vlandian silver, signed for by his factor at the Helmsford crossing, and never delivered. His men took the silver, burned the wagons, and called it a road tax. My uncle Aldric kept that ledger. They hanged him for the loss when the merchants came for their bond.\n\nHe travels with six riders and a notary who carries his seal. The notary lodges at the Greysend tollhouse on market-eves and drinks with the weighmaster - put a denar in the right cup and you will have his master's road, his bedchamber, his morning ride. {TARGET} is fat at the table and thin in the saddle. Take him at first light, before the column counts itself.\n\n{REWARD} denars on delivery of his seal-ring, weighed and tallied against the page. The debt is older than the gold, but the gold settles the line. The red book waits. Ride."),
                NamedTargetReason = BandItPlus.Localization.Get("bp_cultureprofileregistry_224", "{CHIEF} has entered {TARGET} of {HOME} into the red book under the heading of unpaid debts, and the column has been open for nine years. The entry runs to three lines: one strongbox of tithe-silver lifted from the Bramblegate toll-house on the eve of Saint Arwa's feast, one factor named Olen of Pellic strangled in the counting-room and left across his own ledger, and one writ of immunity signed by {TARGET}'s seneschal that closed the matter before the assizes could open it. The Reeve carries a purse and the figure {REWARD} written in clean hand. The contract is logged. The column waits to be ruled across."),
                NamedTargetComplete = BandItPlus.Localization.Get("bp_cultureprofileregistry_225", "{TARGET} is dead. {CHIEF} has been told, and the red ledger is opened to the page where the Westbridge column has stood unbalanced for nine years. The eighty-four wagons of taxed Battanian wool, the burned tally-house at Coppersmoor, the strangled clerk Aelwin found face-down in his own ink - all of it draws a single ruled line across the foot of the column. {REWARD} denars are counted in, recounted, and entered on the credit side in {CHIEF}'s own small precise hand. The Westbridge account is closed. The book is shut and the wax pressed warm."),
                NamedTargetOtherCauseProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_226", "Word reached {CHIEF} by a wool-carter out of the eastern passes: {TARGET} had been cut down in a roadside ambush by a rival lord's outriders, the body stripped and left for the crows before any hand of ours could close the account. {CHIEF} heard it out, opened the red book, and inked the line against uncle Aldric's name and the forty-one wagons of grain with the same patient stroke he gave any closed column - though the nib lingered a breath longer than it ought. The grudge stood answered on the page; it did not stand answered in the room. He counted out {REDUCED_REWARD} denars in thin coin, slid them across the trestle, and ruled the ledger shut. The bond held, set a smaller notch firmer, but the warmth of an earned kill was not in it."),
                RaidVillageAcceptProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_227", "\"Open the red book to the page marked {VILLAGE}. It is a hamlet on the cart-road south of the Vlandian marches, entered under the seal of Lord {LORD} - the same house whose seneschal struck my collector Adelaine across the face at the last assize and whose villages have refused my road-tax for two ledgers running. Two years of dust on that column. The ink remembers what the lash forgot.\n\nThe outriders ride to the assize on the fifteenth to swear loyalty over wine; the village will be three swords and a sleeping reeve. The tithe-barn is stacked with the grain they would not weigh for my men, and the chapel-loft holds the silver candlesticks Adelaine was sent to count. Burn the barn. Take the silver. The smallfolk pay no tax to me - leave them their hands and their doors.\n\n{REWARD} denars on delivery, struck against the column and the column closed. The ledger waits. Ride.\""),
                RaidVillageReason = BandItPlus.Localization.Get("bp_cultureprofileregistry_228", "{CHIEF} has entered {VILLAGE} into the red book as the chattel of Lord {LORD}, a Vlandian house whose holdings have refused the road-tax for two ledgers running. The arrears are itemised: caravan tolls unpaid, bridge-pence withheld, the wintering-fee struck through with a seneschal's mark. At the last assize the same seneschal laid an open hand across the face of the collector Adelaine, and the matter was carried back to {CHIEF} in three lines of small script. The Reeve has assessed the principal, the interest, and the dishonour, and posts the burning of {VILLAGE} as the settlement. A purse of {REWARD} is held in escrow against delivery. The account stands open."),
                RaidVillageComplete = BandItPlus.Localization.Get("bp_cultureprofileregistry_229", "{VILLAGE} burns, and {CHIEF} has been told. The tithe-village of Lord {LORD} - of the same Vlandian house whose seneschal struck Adelaine across the face at the last assize, the same villages that withheld two ledgers of road-tax - is ash and broken thatch, the tax-rolls scattered in the trampled rye. The red book is opened on the trestle, the column ruled, the entry inked in {CHIEF}'s own hand. {REWARD} denars are weighed against the standing arrears and the balance noted as part-settled, no more. The collector's bruise is paid in coin and cinder. Two ledgers stand. The third will be called in turn."),
                RaidVillageOtherCauseProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_230", "Word reached the toll-house at second bell: {VILLAGE} had been put to torch and the ledgers of that Vlandian house were burning with it, but the hand that struck was {LORD}'s war-column, not a collector of ours. The Reeve received the dispatch standing, read it twice, and set it aside without remark. Two ledgers of refused road-tax stood closed. The mark across Adelaine's face stood unanswered by the right hand. The red book would note the entry settled at half-measure, the column \"satisfaction\" left blank. He had the steward count out {REDUCED_REWARD} denars - a clerk's quarter-fee for intelligence delivered, not collection performed - and signed the chit with the smaller seal."),
                // 2026-05-25 rewrite: ORAL-TRADITION / ROAD-FOLKLORE shape. The road
                // tells the Reeve's story before the player arrives — incantatory
                // "they say" repetition establishes reputation; player only enters
                // in the second-to-last paragraph ("And then you came up it.").
                // Ends on the Reeve's ledger-metaphor (a "page" the player chooses
                // to be on), echoing his greeting line.
                HideoutCinemaIntro = BandItPlus.Localization.Get("bp_cultureprofileregistry_231", @"Of this stretch of road they tell this.

A wool-merchant from Pravend rides it once a season, with two armed boys and a strongbox he never lets out of his sight. Twice in seven years he has been stopped on it. Twice he has been received with the courtesy due his trade. Twice he has continued, lightened only by the standard toll — which is, as everyone south of Lageta knows, fourteen percent of the cargo's declared value, payable in coin or in kind, with a receipt issued under a forged Imperial seal that is, the merchant has more than once observed, a better seal than the one his last legitimate factor used.

They say a circuit-judge passed this way three winters back and did not return for ninety-one days. They say his robes came back to Lageta brushed clean. They say the family paid the ransom in grain, not silver, and that the Reeve credited them for the grain at market rate, not at the discount usually applied to such captives, and that the judge himself was not displeased with the transaction once he had recovered the use of his hands.

They say no body has been left on this road in eight years. They say this is policy.

They say the Reeve was once a clerk himself. They say his ledger balances. They say a clerk in Praven still files his year-end accounts.

They say a great deal about this road. Some of it is true.

And then you came up it.

The night is orderly. Too orderly — the verges swept, the milestones standing straight, the silence behaving as though it had been issued instructions. Past the rise where the beeches crowd the road, the small dry sound of someone keeping a tally by lamplight: coin counted, names counted, the road's takings reckoned out.

You sit your horse at the top of the rise and decide what page of theirs you would like to be written on."),
                ServiceLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_232", "Buy information from the Reeve. (200 denars)"),
                ServiceFlavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_233", "The Reeve flips through his ledger. \"Two camps of our cousins. I'll mark them on your map.\""),
                Kind = ServiceKind.InfoBroker,
                BribeAmount = 220,
                WhyNotKingdom = BandItPlus.Localization.Get("bp_cultureprofileregistry_234", "\"A kingdom's a business with worse margins. We tax the same caravans, but we keep the profit.\""),
                Religion = BandItPlus.Localization.Get("bp_cultureprofileregistry_235", "\"Gods of the road. The Quiet Saint who watches caravans. The Ledger-Keeper who tallies what's owed. Practical faiths.\""),
                ThreatResponse = BandItPlus.Localization.Get("bp_cultureprofileregistry_236", "The Reeve sets his pen down carefully. \"That kind of talk gets transcribed in my ledger, friend. Under the column 'unfortunate accidents.'\""),
                Pleasantry = BandItPlus.Localization.Get("bp_cultureprofileregistry_237", "He inclines his head. \"Disciplined men are productive men. Tell that to the next merchant who calls us savages.\""),
                DrinkFlavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_238", "The Reeve produces a flask of imported wine — Vlandian, by the seal. \"The merchant who carried it never reached his customer. We toast his memory.\""),
                RestFlavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_239", "Your party gets a real cot, in a real tent, with a real cookfire. The Reeve runs the camp like a captain runs a barracks."),
                ExtraServices = new[] {
                    new CultureSubService { Label = BandItPlus.Localization.Get("bp_cultureprofileregistry_240", "Browse the highwayman's ledger. (100 denars)"), Flavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_241", "The Reeve flips a few pages. \"One nearby cousin we'd missed. Pleasure doing business.\""), Kind = ServiceKind.InfoBroker, GoldCost = 100 },
                    new CultureSubService { Label = BandItPlus.Localization.Get("bp_cultureprofileregistry_242", "Hire a sword arm. (200 denars)"), Flavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_243", "A scarred veteran nods at you. \"Two weeks of bodyguarding. I drink, but I don't drink before fighting. Take it or leave it.\" Your party's morale rises."), Kind = ServiceKind.VeteranHall, GoldCost = 200, MoraleGain = 3 },
                    new CultureSubService { Label = BandItPlus.Localization.Get("bp_cultureprofileregistry_244", "Visit the document forger. (300 denars)"), Flavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_245", "An old scribe hunches over parchment. \"What you need? A passport, a writ, a letter from a noble? I do them all. I do them well. Twice this town's price, half the wait.\" Your morale rises a touch."), Kind = ServiceKind.VeteranHall, GoldCost = 300, MoraleGain = 2 },
                },
                Rumors = new[] {
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_246", "\"Caravan from Pravend, six wagons, escorted by mercenaries. Departs in three days.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_247", "\"Vlandian baron's tax-collector takes the south road on the first of every month.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_248", "\"There's a secret cache of imperial dispatches buried under a roadside shrine.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_249", "\"The merchant Eustace pays bandits to attack his rivals' caravans.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_250", "\"A guard captain at Charas takes bribes. Half the smuggled goods in town pass under his nose.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_251", "\"The Empress is sending a private courier westward — ungentlemanly business, no escort.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_252", "\"A priest at Marunath has been embezzling temple gold.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_253", "\"Sturgian mead caravan rolls through the pass tomorrow night.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_254", "\"There's a bounty on a Battanian rebel — 800 denars, dead or alive.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_255", "\"The arena fighter Hokkar throws fights for coin.\""),
                },
                TrustQuestTier1Pool = new[] {
                    new TrustQuest {
                        IsGoldQuest = true, GoldAmount = 500,
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_256", "\"Five hundred denars. Up front. Call it your toll, call it what you like. No coin, no business.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_257", "He counts the coin twice, smirks. \"You learn fast. The roads are ours now, and so are you — within reason.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_258", "500 denars"),
                    },
                    new TrustQuest {
                        ItemIds = new[] { "leather" }, Counts = new[] { 50 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_259", "\"Fifty leather. Saddle-bags, harness, gear-straps. The road eats our kit faster than we can pay for it. Bring leather, save us the trip.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_260", "He weighs the stack, slings a bundle over his shoulder. \"Honest hide. The road is friendly to you now.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_261", "50 leather"),
                    },
                    new TrustQuest {
                        ItemIds = new[] { "wine" }, Counts = new[] { 30 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_262", "\"Thirty amphorae of wine. Imperial vintage if you can find it. The boys ride harder when the night warms.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_263", "He pulls a cork. \"Imperial. You've got connections we'd want. Trade with us.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_264", "30 wine"),
                    },
                },
                TrustQuestTier2Pool = new[] {
                    new TrustQuest {
                        IsGoldQuest = true, GoldAmount = 2000,
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_265", "\"Two thousand denars. That's a real toll. Hand me that, and you're not a customer of the road — you're a partner.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_266", "He weighs the bag. \"Heavy enough. The road is yours when you ride it. Take what you need.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_267", "2000 denars"),
                    },
                    new TrustQuest {
                        ItemIds = new[] { "leather", "wine" }, Counts = new[] { 80, 30 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_268", "\"Eighty leather and thirty wine. We're outfitting two new gangs for the southern road. Bring both.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_269", "He nods once. \"Two more gangs ride this week thanks to you. The boys salute.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_270", "80 leather + 30 wine"),
                    },
                    new TrustQuest {
                        IsGoldQuest = true, GoldAmount = 1500,
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_271", "\"Fifteen hundred denars and we forget the last three caravans you didn't pay tax on. Coin solves problems faster than anything.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_272", "He pockets the coin without counting. \"Books are clean. The boys have your back on the road.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_273", "1500 denars"),
                    },
                },
                TrustQuestTier3Pool = new[] {
                    new TrustQuest {
                        IsGoldQuest = true, GoldAmount = 5000,
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_274", "\"Five thousand denars. The road-network is opening to you — every gang from here to the southern marches takes orders from a man who walked in with this kind of money.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_275", "He weighs the chest, then locks it without counting. \"You don't pay this kind of money to be a customer. You pay it to be a king of roads. Welcome.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_276", "5000 denars"),
                    },
                    new TrustQuest {
                        ItemIds = new[] { "velvet", "leather" }, Counts = new[] { 50, 100 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_277", "\"Fifty velvet and a hundred leather. We're fitting out a noble-looking caravan to ambush a real noble-caravan. Bring the disguise.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_278", "He laughs at the velvet bolt. \"This is the kind of audacity that makes legends. The southern road is ours together now.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_279", "50 velvet + 100 leather"),
                    },
                },
                // Wave 5 (Chief Recruitment) alliance content
                AllianceCh1TaskBrief = BandItPlus.Localization.Get("bp_cultureprofileregistry_280", "Escort a stolen-goods caravan from the Reeve's hideout to a fence town within three days, no losses."),
                AllianceCh1Pattern = AllianceCh1Pattern.EscortToSettlement,
                AllianceCh1TargetSeedHint = "fence_town_local",
                AllianceCh3RitualText = BandItPlus.Localization.Get("bp_cultureprofileregistry_281", "The The Reeve accepts your oath; the rite is sealed in wax-stamped ledger ink, signed by candlelight at the wayhouse table."),
                AllianceCh3GiftItemId = "highwayman_mask",
                AllianceBrokenText = BandItPlus.Localization.Get("bp_cultureprofileregistry_282", "The Reeve closes the ledger and slides it under the stump. \"Your account is settled. Don't come up this road again expecting credit.\""),
            }},
            { "bp_slaver_caravans", new CultureProfile {
                ChiefName = BandItPlus.Localization.Get("bp_cultureprofileregistry_283", "Khalid the Chain"),
                Signature = new SignatureQuestSpec
                {
                    Title = BandItPlus.Localization.Get("bp_cultureprofileregistry_284", "Break the Rival's Chain"),
                    HeraldLine = BandItPlus.Localization.Get("bp_cultureprofileregistry_285", "Oi — the master wants you at the receiving-stump. Somebody's been selling on our roads. Cheap. Khalid don't shout when he's angry, and he ain't shouted in three days. Go quick."),
                    OfferProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_286", "Sit, traveler. Drink. This is a small matter of bookkeeping. Faruk drove for me six years — knew my wells, knew my buyers. Now he runs his own string on my roads and sells at seven denars a head against my nine. Understand me: I do not begrudge a man ambition. I begrudge him my routes taken without purchase. The ledger calls that theft, however politely it is done. Find his column, break it. His men trained at my fires, so they will fight well — and Faruk will talk before he fights, because talk was always his best-selling item. Do not buy. There is silver in this, weighed fair."),
                    AcceptProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_287", "Good. A clean entry. Break the column, scatter what he drives, and bring me word — or better, bring me his stock. The ledger pays by weight, traveler, and Faruk weighs heavy on it."),
                    DeclineNudge = BandItPlus.Localization.Get("bp_cultureprofileregistry_288", "As you like. But roads that carry cut-rate flesh soon carry cut-rate everything — your contracts included. Think on it over the wine. The entry stays open a while yet."),
                    BusyLine = BandItPlus.Localization.Get("bp_cultureprofileregistry_289", "You carry unfinished business, traveler — I can smell an open contract the way a camel smells water. Close your ledger first. Then we will speak of Faruk."),
                    TargetPartyName = BandItPlus.Localization.Get("bp_cultureprofileregistry_290", "Faruk's Cut-Rate Column"),
                    CaptainName = BandItPlus.Localization.Get("bp_cultureprofileregistry_291", "Faruk"),
                    JournalObjectiveText = BandItPlus.Localization.Get("bp_cultureprofileregistry_292", "Find Faruk's Cut-Rate Column on the desert roads and destroy it. A splinter ring of slavers is poaching Khalid the Chain's routes and undercutting his prices."),
                    JournalReturnText = BandItPlus.Localization.Get("bp_cultureprofileregistry_293", "Faruk's ring is broken. Return to Khalid the Chain at his camp to settle the contract."),
                    ConfrontIntro = BandItPlus.Localization.Get("bp_cultureprofileregistry_294", "Khalid's new errand-rider — right on schedule. The old man keeps punctual help. Before anyone draws, hear a number: three thousand denars, yours tonight, and all you tell him is the roads were empty. Empty roads are the cheapest goods I sell. Well?"),
                    Choices = new[]
                    {
                        new SignatureChoice { Label = BandItPlus.Localization.Get("bp_cultureprofileregistry_295", "Three thousand, counted now. The roads were empty."), Outcome = SignatureOutcome.Betray, GoldToPlayer = 3000, ResultProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_296", "Counted and yours. A pleasure doing honest business, friend — Khalid taught us both that lie. Ride slow and tell it plain. The desert's roads have never been emptier.") },
                        new SignatureChoice { Label = BandItPlus.Localization.Get("bp_cultureprofileregistry_297", "Keep your denars. Khalid paid for a breaking."), Outcome = SignatureOutcome.Battle, ResultProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_298", "Shame. You'd have made a fine partner. Instead you'll make nine denars a head — whatever's left of you sells somewhere. Chains up, boys. Close this one's ledger.") },
                    },
                    PostBattleChoiceIntro = BandItPlus.Localization.Get("bp_cultureprofileregistry_299", "So Faruk's chain is off my roads. Good. Sit, drink — and answer the one question the ledger cares about: he was driving stock when you took him. Forty head, by my factors' count. Where do they walk now, traveler?"),
                    PostBattleChoices = new[]
                    {
                        new SignatureChoice { Label = BandItPlus.Localization.Get("bp_cultureprofileregistry_300", "Driven to your pens. Count them yourself."), GoldToPlayer = 3000, ResultProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_301", "Already counted — my tally-boys had them at the gate before you sat down. Sound stock, delivered at fair weight without a single loss. That is how an entry should close, traveler. Full price, weighed while you watch.") },
                        new SignatureChoice { Label = BandItPlus.Localization.Get("bp_cultureprofileregistry_302", "I struck the chains. They scattered into the dunes."), GoldToPlayer = 1500, BonusRenown = 15, ResultProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_303", "Forty head, walking free in my desert. You cost me their price and told me to my face. Most men would have lied. I dock the loss and note the spine — the ledger has a column for both.") },
                    },
                    ClosingProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_304", "The account closes clean, then. Faruk's column broken, his string driven whole to my pens, his buyers already writing to me at the old price — nine denars a head, as the desert intended. Here is your silver, weighed against the full delivery, no skim, no haggling. You do tidy work, traveler. Men who deliver what they contract are rarer on these roads than sweet water. When the ledger next opens a page worth your while, I will send for you."),
                    ClosingProseAlt = BandItPlus.Localization.Get("bp_cultureprofileregistry_305", "Faruk is broken and his prices with him, so the contract stands — half of it. The other half walked into the dunes when you struck their chains, and I do not pay for stock I cannot sell. Here is your silver, lighter than it might have been. And yet — forty head chose the desert over the block, and you stood there and watched them go. Curious economics, traveler. I have known one other man who kept books that way. Drink before you ride."),
                    ClosingProseOtherCause = BandItPlus.Localization.Get("bp_cultureprofileregistry_306", "You come to sell me news I bought yesterday, traveler. A desert emir's lancers caught Faruk's column at a dry well and did my breaking for me — loudly, and free of charge. So the roads are mine again, and your contract died of another man's blade. Still. You rode out in good faith, and a merchant who stiffs honest effort teaches his partners to stiff him back. Half-weight, counted clean. Faster hooves next time."),
                    BetrayedProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_307", "You told me the roads were empty. Faruk sold at seven denars in Quyaz within the week — my factors count better than you lie. What he paid you is entered under your name; that page does not reopen. No wine. No trade. Speak standing."),
                    RewardGold = 2500,
                    RewardRelation = 8,
                },
                ChiefTitle = BandItPlus.Localization.Get("bp_cultureprofileregistry_308", "Caravan-Master"),
                ChiefBackstory = BandItPlus.Localization.Get("bp_cultureprofileregistry_309", "Khalid was born free in a Nahasawi desert village his grandfathers helped found three centuries ago — a small settlement on the rim of the deep dunes, watered by a spring that has never failed. He grew up tending camels, learning the dune-paths from his father, and would have inherited the village's tenuous chieftaincy had the slavers not come the autumn he turned nineteen. They took thirty of his kin in a single dawn raid; Khalid escaped because he was sleeping under a date-palm and the slavers did not check beneath the trees. He spent four years tracking them, learning their routes, and finally — when he could find no other way to learn the inner workings of their network — he sold himself to a slaver-captain on a forged contract, riding chained for nine days through the dunes. He freed the men he was chained to on the seventh night using a bone-pick he had hidden in his cheek; they killed three guards, took the lead-camel, and rode south. The freed slaves became his first crew, and he has been freeing slaves and selling false-papered shipments to corrupt sultans ever since. Khalid the Chain runs the desert routes from the other end now — buying the men he was once chained beside, freeing them, and selling the bills of sale to lords who collect such things."),
                ClanHistory = BandItPlus.Localization.Get("bp_cultureprofileregistry_310", "The Slaver Caravans are not new — they are the surviving fragment of an old Aserai chain-trade the early sultans tolerated and the later sultans forbade. When the trade was outlawed two generations ago, most chain-merchants converted to spice or wool; a small core of Nahasawi families refused, retreated into the deep dunes, and kept moving. Khalid's grandfather was one of them. Desert-villagers whose wells have failed, Aserai sons disinherited by imperial-leaning fathers, and southern men who have learned the trade-tongues of three nations and found no honest employer for the skill — these are the people the Nahasawi families take on. Their caravans never stop in a town; they trade at well-heads, at oasis-edges, at half-stripped sultanate forts the maps have forgotten. The Aserai sultanate has placed a standing bounty on every Slaver chief for forty years and has never collected it. Among the southern lords the band is half-rumor, half-trade-partner — lords who would never speak Khalid's name in court still buy his stock through a cousin's cousin, and Khalid has noted every name in a coded book he keeps under his receiving-stump."),
                ChiefGreeting = BandItPlus.Localization.Get("bp_cultureprofileregistry_311", "The caravan-master does not rise. He sits cushioned and content, a cup of date-wine in one ringed hand, while behind him manacled figures stand in absolute, practiced silence. He watches you a long beat, weighing — the way a merchant weighs a stranger's purse without touching it. \"Coin or chains, traveler. Khalid the Chain finds most who come to his fires bring one or wear the other. Which are you?\""),
                ChiefGreetingTolerated = BandItPlus.Localization.Get("bp_cultureprofileregistry_312", "Khalid does not gesture for you to sit, but he no longer signals his bodyguards either. The date-wine cup is offered without a word — a courtesy he extends only to those he has decided not to chain. \"Back to my fires, traveler. Khalid finds you've a useful habit of arriving without dragging trouble behind you. Drink. Speak. Trade.\""),
                ChiefLoyaltySpeech = BandItPlus.Localization.Get("bp_cultureprofileregistry_313", "Khalid has heard the name. Heard hundreds. Most arrive expecting trade and leave wearing their welcome instead of their armor. The Chain's measure of a man is what he hauls home from the first errand. There is an errand. Complete it, and Khalid will pour you the wine he reserves for partners — not the wine he serves to fools."),
                CampIntro = BandItPlus.Localization.Get("bp_cultureprofileregistry_314", "The Slaver Caravans' camp is a maze of pens and tents, ringed by armed guards. Children in chains haul water. Khalid sits like a magistrate at his receiving-stump."),
                HideoutDirections = BandItPlus.Localization.Get("bp_cultureprofileregistry_315", "Ride east out of Quyaz one full day, until the city's perfume of myrrh and rotting fruit gives way to the clean stink of camels. You will strike a dry wadi running south like a knife-cut in the sand - follow it. When the wadi forks, take the right hand, and you will see slave-pens of mud-brick rising before you like teeth in a broken jaw. Behind them stands a single deep well, the only sweet water for twenty leagues. Our hold lies at {HIDEOUT_NAME}, and the well is the heart of it.\n\nMy drover-boys watch the dune-ridges from before the sun is up. They will mark your party from a league out and count your spears before you count your own waterskins. Ride beneath a banner of honest colors - white and rust like ours, or any merchant's stripe - and keep your hands open on the reins. If you arrive at noon, water your horses at the trough outside the gate; that is the sign of a man who knows the courtesy of the road.\n\nCome correct and I will receive you at the receiving-stump like any other ledger-business: a cup of date-wine, a fair price on flesh or steel, my word on a contract. Come wrong, with hidden weapons or an empty purse and a loud mouth, and my guards will add you to the chains hauling the water. I sell what walks into my camp, traveler. Walk in carefully."),
                ScoutsLordsProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_316", "The Aserai sultan's tax-collectors ride out from Quyaz with twenty spears at their back, and they think the dune-fringe is a column in their ledger. I have taught three of them, this season, to read a different column. One paid in silver. One paid in horseflesh. The third signed his name in the sand with what was left of him. The sultanate keeps sending replacements because the sultanate keeps having sons it does not want at court.\n\nThere is a desert emir - Mubarak of the Banu Hilal, a clan-name you will hear in the south markets - who has sworn to my ruin in three separate audiences. He says I sold his cousin to a Vlandian count. He is correct. The count paid in good northern gold, and the cousin sang on the road, so the bargain was clean on both ledgers but his. Mubarak rides with forty lancers and a grudge older than his beard.\n\nThe Vlandian outriders cross the deep desert in late summer chasing slave-coin and Aserai horseflesh - rich fools, badly watered, easy ledger-work. Khuzait raiders push west when the steppe-grass burns. If you carry an Aserai banner south through my country, traveler, the emir will read your colors before he reads your purpose. The desert remembers debts. So do I."),
                ScoutsClanProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_317", "The desert is a ledger, friend, and every chief upon it owes someone. Hakkun's dune-band runs the southern wells - small men, small contracts, but they sell me captives at fair weight and ask no questions about destination. I respect a man who delivers clean goods on time. Boll's outcasts I would not buy from if they paid me. Diseased stock, broken limbs, half of them dead before Quyaz. The Crone Vael's cult sends emissaries every other moon asking for \"tribute in flesh\" - I send them polite refusals and double my outriders for a week.\n\nThe blood-debt I carry sits with Aurelius and his Fallen Legionaries. Two seasons back his column took a caravan of mine on the Empire road - thirty head of stock, four guards, my second cousin running the manifest. He claims he did not know the mark. I claim the interest compounds. We have not met across a fire since. One day we will, and the account will close.\n\nThe quiet that troubles me is Bjornulf Salt-Tongue. His longboats have not raided the Aserai coast in three months, and silence from a sea-raider means he is counting something he does not want counted aloud. My scouts on the Pravend road brought back tongue-chatter of his men buying horses inland. A sea-raider who buys horses is a sea-raider who means to ride. Mark the name."),
                ScoutsCaravanProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_318", "A spice-train leaves Quyaz every eighth dawn for the Vlandian ports - four wagons, eighteen guards, an Aserai captain named Mufaddal who drinks date-wine from a copper flask he thinks no one sees. He sees nothing past the third cup, and the third cup arrives at the dune-fringe waystone where the well-road bends north. My ledger has him crossing my reach in six days. The lead wagon carries saffron and cardamom for the boyars who pay in silver they minted from Sturgian mines - the second wagon is bolts of southern silk, the third is the only one that matters: bonded servants for the slave-blocks at Sanala. The escort doubles around that wagon and thins everywhere else.\n\nIf you ride with fifteen lances, traveler, take the front two wagons at the bend and let me have the third. That is a clean trade. I will pay you in silver weighed against the saffron, no haggling, no skim. The bonded servants are my ledger entries already - the buyers in Sanala have been promised, and a Slaver who breaks a delivery does not get a second contract.\n\nDo not touch the rear-wagon. It carries a Vlandian factor's son riding back to his father, and the Highwaymen tried that game last spring. Reeve still owes me eighty dinars for the column I rerouted to bury his mistake. The desert remembers who collects, and who pays."),
                PactTeaseProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_319", "You ask the ledger-question, southerner. Most who sit at my fire ask for water, for safe passage, for a cut of the salt-road. You ask to be written into the book of binding. That is not a thing whispered between sips of tea. Sit. Hold your tongue while I read what is already inked under your name.\n\nWhen Khalid the Chain bleeds for a man, it is because that man is sealed in salt and sworn in the ledger of flesh. I have three such names. Tariq, who broke his thumb-bone over my wrist when the Banu Hilal would have sold us both. Old Rashida, who covered my caravan-debt in Quyaz before the qadi knew my face. A bondsman whose chains I struck off in the dunes, who now wears them by choice, around his neck, as my mark. These are my chains. These are my bound.\n\nBring me the deed of a bondsman, not a buyer. A rival caravan turned to my profit. A debt I did not know I was owed, paid. A road east of Quyaz held open while the wells went dry. Do that, and the ledger learns your name in salt. Ask me again when the ink is wet, and not before."),
                OathBrotherProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_320", "Then it is written. Kneel at the ledger - rise as a name within it. I take the salt-jar from the lead camel's pack, the same jar my father pressed to my tongue when I was eight and screaming, and I press a pinch to your tongue now. Taste it. That is the dune east of Quyaz, where I cut my first thumb-bond at twelve over a stolen girl and a stolen mule. I draw the curved knife - the one that opened the Quyaz factor who tried to short the manifest - and I score your palm beside the brand on mine. Press. The salt finds the cut. The cut remembers the salt. The ledger has tasted you now, brother, and the ledger does not forget what it tastes.\n\nYou are kin-of-the-chain from this hour. Not chattel - kinsman. My camels are your camels. My drivers bow to you as they bow to me. The slave-girl who pours my coffee pours yours first now, because the elder brother drinks last in the caravan-master's tent. My debts are your debts. My salt-stores in Quyaz, in Iqbayl, in the deep-desert caches no factor knows - yours to draw upon as breath.\n\nLet the dune-fringe witness. Let the Quyaz emirs who paid me in clipped dinars witness, for they will learn this name when their warehouses next burn. You are Khalid's brother now - chained to me by the salt and the ledger and the scar. The road from here is long, brother, and we walk it weighing every soul we pass."),
                PactAnswerProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_321", "Then the ledger is read, and the entry stands. You did not come to my tent with a merchant's speech, with terms and clauses and a hand half-extended for the seal. You came with the work already finished and the salt of it still on your boots. I asked once if you would bleed for me when the time came, and you answered not with breath but with iron. That is the only currency I weigh. Sit. Let the chain settle on the post while I name what you have bought.\n\nFrom this hour my caravans are your road, and your enemies are my freight. When you raise your banner against a lord, my outriders sweep his villages before his couriers reach him. When you ride into the deep dunes, my water-stations open to you as they open to no other rider south of Quyaz. In return you owe me this and only this: when I send word that a debtor has run, you bring him back, alive or in pieces, and we split the ledger clean. Not brothers. Not hearth-kin. Blood-allies, the way a man and his chain are allies - one cannot move without the other, and both leave a mark.\n\nThe salt-seal on my tent flap was set in the year my first caravan-master broke his word and I broke his neck. It has held every oath since. It holds yours now. Ride out, ally. When my men hear hooves at the dune-crest, they will not draw steel - they will count your numbers and add them to ours."),
                TroopLoanProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_322", "Done, and the salt-seal closes it. Ten chain-riders for seven days - I count them out myself, by name, by collar, by the brand on their forearm. My second is Qadir Salt-Tongue, who has driven caravans from the desert to the wet coast and knows which of my outriders ride straight and which ride for themselves. He goes with you. The chain leaves my post at dawn.\n\nHear my terms, buyer. A man of mine is not a coin you spend - he is a coin I loaned. If one falls in your work, you bring me his collar and the name of the blade that took him, and I will set the price of that name later. My caravan-guards do not break shield for petty work. They break shield for cargo that pays, for roads that need clearing. While they wear my mark under your banner, do not waste them on errands a stableboy could finish.\n\nSeven days. I have already written it in the ledger. When the moon turns, I expect ten men back at my gate - or nine men and one good story, told by Qadir himself."),
                NamedTargetAcceptProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_323", "His name is {TARGET}. He keeps his banner over {HOME}, and his father bought my sister Aluneh from a Geroia broker nineteen summers past - bought her with my own coin, traveler, coin he owed me for a salt-shipment he never paid. She died scrubbing his floors in {HOME} the winter before last. I have her tally-mark cut into the wood of this counting-desk. {TARGET} signed her death-warrant when he refused to ransom her back to me at three times her weight.\n\nHe rides a tall grey and travels with twelve riders, but four of them are sons of men who owe me chain-money - they will not draw fast. He counts his coffers in {HOME} on the first morning of each moon. Take him on the road home from his accountant, when his purse is heavy and his guard is drunk on the count.\n\n{REWARD} denars when his seal-ring reaches my desk. The ledger of flesh remembers what gold cannot wash clean. The salt-seal waits. Ride."),
                NamedTargetReason = BandItPlus.Localization.Get("bp_cultureprofileregistry_324", "{CHIEF} has set {TARGET} of {HOME} upon the open page of his salt-ledger, and the entry is older than any living factor remembers. Seven seasons past, a slaver-caravan out of Iskon-Drabh was broken on the coast road, its iron struck off and its cargo scattered into the brush; among the lost was a chained woman called Suren who had served the Chain as steward and counter, and who carried in her head the names of every buyer from Quyaz to the Kanikat strait. {TARGET} kept her ransom and burned the manifest. The Chain pays a heavy purse in clean coin. The seal of salt waits. The contract is open."),
                NamedTargetComplete = BandItPlus.Localization.Get("bp_cultureprofileregistry_325", "{TARGET} is dead. {CHIEF} has been told, and the ledger of flesh is opened to the page that has waited eleven seasons for closing. The Razih entry - the salt-caravan of forty-three souls broken on a hill outside Quyaz, the iron neck-ring of his sister Amineh struck off and lost in the dust - is now scored through with the long red mark of debt-paid. {REWARD} denars are weighed on the salt-stone and folded into the chain-master's coffer, heavy as a closed contract. The salt-seal is pressed once, and the name is taken off the chain. The ledger is shut."),
                NamedTargetOtherCauseProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_326", "Word reached {CHIEF} by a salt-runner out of the southern passes: {TARGET} had been cut down in a rival lord's ambush along a coast road, throat opened before the slaver's own blade ever found the mark. The chief took the news at his ledger, the same ledger where Aluneh's name still stood unpaid - the sister he had once seen bought, worked, and buried by the very chain that traded her flesh. He weighed the report against that older debt and judged it answered, though not cleanly. The grudge was closed; the salt-seal pressed; yet the killing had not been earned. Quarter-pay was counted out in thin coin, {REDUCED_REWARD} denars stacked without flourish, and the bond between them set a smaller notch firmer - acknowledged, ledgered, but cooler than a kill delivered by hand."),
                RaidVillageAcceptProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_327", "\"There is a village called {VILLAGE} in the red dunes south of the salt-road, held by Lord {LORD} of the emir-clan that refused my salt-toll nine seasons running. Nine seasons, scribe. I counted each one in a ledger bound with goat-hide. Their elders snapped the iron neck-chain my brother Tariq forged with his own hands - snapped it across a well-stone and laughed while the slaves walked free. Tariq does not laugh anymore. He does not speak.\n\n{LORD} keeps his outriders close to the wells through the dry month, but the grain-fields ripen now and his men sleep through the noon-heat under the date-palms. Burn the threshing floors. Take the brass scale-weights from the headman's house - they are mine by salt-right. The smallfolk you may chain or leave; I have buyers in Quyaz either way, but the chained ones pay better.\n\n{REWARD} denars in struck silver when the smoke rises over the dunes. The ledger waits, and Tariq's hand grows colder. Ride.\""),
                RaidVillageReason = BandItPlus.Localization.Get("bp_cultureprofileregistry_328", "{CHIEF} has named {VILLAGE}, the grain-fief of Lord {LORD} of an Aserai emir-clan, as the ledger to be closed in fire. Nine seasons running, this village refused the salt-toll the caravan-master sets on every loaf of bread that crosses his road, and nine seasons the chain-master has marked them in the iron book his brother Tariq kept before the elders broke the chain Tariq forged with his own hands. Tariq is gone. The chain is broken. The grain-fields ripen now, and {CHIEF} will see them harvested by other hands. A purse of {REWARD} is offered to the rider who will bring the torch. The salt-toll falls due. The contract is open."),
                RaidVillageComplete = BandItPlus.Localization.Get("bp_cultureprofileregistry_329", "{VILLAGE} smolders, and {CHIEF} the Chain has weighed the news. The emir-fief of Lord {LORD} of the Aserai - the salt-debtors of nine seasons, the elders who shattered the chain Tariq forged - lies opened to the wind, its ripened grain trampled into the dust, its wells fouled, its men roped in coffles bound for the southern blocks. {REWARD} denars are counted out on the merchant's scale where Khalid keeps his ledger of unpaid tolls, and a fresh link is hammered shut in Tariq's memory. The salt-toll is collected at last. One debtor-clan answers no more."),
                RaidVillageOtherCauseProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_330", "Word reached the caravan-pavilion at the second muezzin-call: {VILLAGE} lay scorched, the granaries cracked open, the elders scattered - but the torch had been {LORD}'s, carried for some border quarrel that had nothing to do with nine seasons of unpaid salt-toll, nothing to do with the chain my brother Tariq forged that those elders broke across their threshing-stone. {CHIEF} heard the runner out, folded the ledger, and smiled the smile that does not warm the eyes. \"The grain is burned,\" he said, \"but the debt was not collected. A creditor takes no satisfaction from a fire he did not light.\" He counted out {REDUCED_REWARD} denars himself - half-weight, paid clean - and waved the matter closed."),
                // 2026-05-25 rewrite: LEDGER / DOCUMENT shape. Opens with a recovered
                // manifest as an indented block — the horror is the bookkeeping. The
                // prose under the manifest is the player's reaction; the camp enters
                // the story as the live-action of the document. No companion-quote,
                // no negation list, no "you watched" reveal. Player's intent at the
                // end echoes the ledger metaphor: "add a line of your own to the
                // book" — deliberately ambiguous between trade and intervention.
                HideoutCinemaIntro = BandItPlus.Localization.Get("bp_cultureprofileregistry_331", @"Khalid's last manifest, recovered from a clerk's saddle outside Quyaz two months ago, read as follows:

    Cargo, southbound from Razih:
      Adult males, sound, age 16–35:  forty-two head
      Adult males, lamed, age 35–50:  nine head
      Adult females, sound, age 14–30:  thirty-one head
      Children, both sexes, age 6–12:  twenty-two head
      Infants (with mothers): four
      Loss in transit (heat, attempted escape, illness): seven
      Net delivered, payable to Chain of Quyaz: 101 head
      Per head, gross: 12 dinar
      Less feed, water, guard wages, road-tolls: 3 dinar/head
      Net to seller: 9 dinar/head
      Total: 909 dinar
    Signed in good faith,
      K., for the Chain

It was a clean ledger. The hand was educated. There were no marks in the margin for the seven losses, no notes on why they were lost, no entry at all for the four infants except the line that bracketed them in with their mothers as one figure each. The bookkeeping was as good as any imperial counting-house. That was the part that turned the stomach.

You read it twice on the road and could not stop reading it.

Now you sit your horse at the top of the dune-track and you can hear, in the lee of the rocks below, the small even sounds that book becomes when a book is what is happening: iron link against iron link, a cough swallowed, the murmur of a great many people being quiet in a way that has stopped being fear and become a habit.

A heavy man sits on a cut stump at the camp's heart as though it were a magistrate's bench, and a line waits on his judgment.

Khalid is doing his accounts.

You take the manifest out of your saddle-bag and look at it once more in the torchlight. You fold it. You put it back.

You ride down to add a line of your own to the book."),
                ServiceLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_332", "Browse the slave market."),
                ServiceFlavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_333", "Khalid claps. Two figures are dragged forward. \"Strong backs, weak wills. Pick what you can use.\""),
                Kind = ServiceKind.SlaveMarket,
                BribeAmount = 300,
                WhyNotKingdom = BandItPlus.Localization.Get("bp_cultureprofileregistry_334", "\"A king would outlaw our trade in public and buy from us in private. The arrangement we have is more honest.\""),
                Religion = BandItPlus.Localization.Get("bp_cultureprofileregistry_335", "\"We pray to Tariq, who blesses the bargain. Coin doesn't care which god is invoked over it.\""),
                ThreatResponse = BandItPlus.Localization.Get("bp_cultureprofileregistry_336", "Khalid laughs without moving his face. \"Bold for a man my guards outnumber four-to-one. Shall I add your name to my inventory?\""),
                Pleasantry = BandItPlus.Localization.Get("bp_cultureprofileregistry_337", "He shrugs. \"Fine? It's a market. The merchandise complains, the buyers complain. Normal day.\""),
                DrinkFlavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_338", "Khalid pours a clear spirit from the south. The captives watch in silence. \"Drink, friend. Business is better when the partners are loose-tongued.\""),
                RestFlavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_339", "You sleep in a guarded tent. The chains clink all night. Your party rises tense, but better-rested than the road allows."),
                ExtraServices = new[] {
                    new CultureSubService { Label = BandItPlus.Localization.Get("bp_cultureprofileregistry_340", "Visit the auction hall."), Flavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_341", "Khalid leads you to a tent where finery is laid out — looted dresses, jeweled rings, a noble's writing-set. \"What we strip from the merchandise. Premium prices, but prime quality.\""), Kind = ServiceKind.TrophyRoom },
                    new CultureSubService { Label = BandItPlus.Localization.Get("bp_cultureprofileregistry_342", "Tap the whisper network. (200 denars)"), Flavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_343", "Khalid lights a long pipe. \"My chains travel everywhere. So do my eyes. Two camps marked. Tonight you don't even pay full price.\""), Kind = ServiceKind.InfoBroker, GoldCost = 200 },
                    new CultureSubService { Label = BandItPlus.Localization.Get("bp_cultureprofileregistry_344", "Hire a whip-trainer. (500 denars)"), Flavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_345", "A scarred man with a whip walks past you. \"He'll train your soldiers in cruelty. Useful when the world is cruel.\" Your party's morale shifts uneasily, but they march harder."), Kind = ServiceKind.VeteranHall, GoldCost = 500, MoraleGain = 3 },
                },
                Rumors = new[] {
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_346", "\"There's a market for noble captives in the Aserai south. Triple the price.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_347", "\"Imperial law forbids slavery, so the imperial nobles use middlemen. We are middlemen.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_348", "\"The Khanate has a labor camp in the eastern steppe. They've paid us twice for new bodies.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_349", "\"A Vlandian lord's son was captured by us last month. We sold him to a rival house.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_350", "\"Galleys along the southern coast need rowers. They pay in advance, no questions about accent.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_351", "\"There's a tunnel under Husn Fulq used for moving captives.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_352", "\"A noble's daughter ran away to marry a smith. The father's hired us to find her.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_353", "\"The desert sultan buys eunuchs at any price.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_354", "\"A merchant prince in Quyaz is collecting captive scholars. 5000 denars per.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_355", "\"Imperial galleys lost a slave shipment to pirates. They want them back.\""),
                },
                TrustQuestTier1Pool = new[] {
                    new TrustQuest {
                        ItemIds = new[] { "iron" }, Counts = new[] { 10 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_356", "\"Bring me ten loads of iron. We need it for shackles, for chain. The trade we run isn't pretty.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_357", "He weighs the ore in one hand. \"Clean. You don't ask what I do with it. The caravan trades with you now.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_358", "10 iron"),
                    },
                    new TrustQuest {
                        ItemIds = new[] { "mule" }, Counts = new[] { 5 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_359", "\"Five mules. The caravan moves bodies, and bodies need beasts to carry them. Bring sound stock.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_360", "He inspects each animal's teeth. \"Strong-backed. The caravan rolls with you now.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_361", "5 mules"),
                    },
                    new TrustQuest {
                        ItemIds = new[] { "leather" }, Counts = new[] { 15 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_362", "\"Fifteen leather. Restraints, harness, hood-bags. We don't pretend our trade is otherwise.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_363", "He runs a strap between his fingers. \"Properly cured. Trade with us.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_364", "15 leather"),
                    },
                },
                TrustQuestTier2Pool = new[] {
                    new TrustQuest {
                        ItemIds = new[] { "mule", "iron" }, Counts = new[] { 10, 10 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_365", "\"Ten mules and ten iron. Pack animals and shackles. You bring this, you sit at our table.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_366", "He runs a chain through his fingers. \"Iron and beasts. The caravan opens its rolls to you.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_367", "10 mules + 10 iron"),
                    },
                    new TrustQuest {
                        ItemIds = new[] { "iron", "leather" }, Counts = new[] { 20, 20 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_368", "\"Twenty iron and twenty leather. The next caravan moves doubles. We need restraint-kit for forty.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_369", "He nods grimly at the stack. \"Now we move forty. The caravan owes you a share.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_370", "20 iron + 20 leather"),
                    },
                    new TrustQuest {
                        ItemIds = new[] { "mule", "leather" }, Counts = new[] { 8, 30 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_371", "\"Eight mules and thirty leather. We're swapping out our string and re-harnessing the lot. Heavy haul — caravan-rider work.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_372", "He claps the lead mule's flank. \"Fresh stock, fresh harness. The desert's ours together.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_373", "8 mules + 30 leather"),
                    },
                },
                TrustQuestTier3Pool = new[] {
                    new TrustQuest {
                        ItemIds = new[] { "mule", "iron" }, Counts = new[] { 30, 50 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_374", "\"Thirty pack-mules and fifty iron. We're moving the largest single caravan our crew has ever run — three hundred bodies south. Don't ask, just bring.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_375", "He doesn't smile. \"Three hundred souls move because of your work. The caravan owes you a debt of blood. Don't think on it too long.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_376", "30 mules + 50 iron"),
                    },
                    new TrustQuest {
                        ItemIds = new[] { "iron", "ironIngot2" }, Counts = new[] { 100, 20 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_377", "\"A hundred iron and twenty wrought-iron ingots. Heavy chains for a hundred captives. The crew's biggest take of the year hangs on this.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_378", "He locks the chest of finished chain. \"That's a southern fortune in steel. The caravan rides with you on the rest.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_379", "100 iron + 20 wrought iron"),
                    },
                },
                // Wave 5 (Chief Recruitment) alliance content
                AllianceCh1TaskBrief = BandItPlus.Localization.Get("bp_cultureprofileregistry_380", "Intercept a rival slave caravan being escorted to a foreign faction and seize the cargo before it crosses the border."),
                AllianceCh1Pattern = AllianceCh1Pattern.DestroyPartiesOfType,
                AllianceCh1TargetSeedHint = "rival_slaver_escort_party",
                AllianceCh3RitualText = BandItPlus.Localization.Get("bp_cultureprofileregistry_381", "The Khalid the Chain accepts your oath; the rite is sealed with the brief click of a chain linking your wrist to the chief's for one heartbeat."),
                AllianceCh3GiftItemId = "iron_shackles_ceremonial",
                AllianceBrokenText = BandItPlus.Localization.Get("bp_cultureprofileregistry_382", "Khalid pours wine and does not offer the cup. \"You came to my fires under truce. The truce is ended. Walk out before the chains find you.\""),
            }},
            { "bp_fallen_legionaries", new CultureProfile {
                ChiefName = BandItPlus.Localization.Get("bp_cultureprofileregistry_383", "Centurion Aurelius"),
                Signature = new SignatureQuestSpec
                {
                    Title = BandItPlus.Localization.Get("bp_cultureprofileregistry_384", "The Lost Standard"),
                    HeraldLine = BandItPlus.Localization.Get("bp_cultureprofileregistry_385", "You there. The old man's been at the whetstone since the pickets came in — imperial column on the road, carrying something that's ours. He wants you at the standard-stone. Quick-march, he said. He never says quick-march to outsiders."),
                    OfferProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_386", "Stand straight and listen once. My pickets marked an imperial column on the post-road — a wagon under canvas, an escort, and a captain young enough to still believe in the Senate. Under that canvas rides the eagle of the Twelfth. My eagle. The one they stripped from us the afternoon they struck our numerals from the rolls. Some clerk has decided it will decorate a garrison shrine. It will not. Twenty years I have drilled boys under an empty pole. Bring it home. Buy it or take it — the method I leave to the field commander. But it comes back whole, and it comes back to me. Questions? No. Then move."),
                    AcceptProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_387", "Good. That word was given like a soldier gives it. The column halts at the milestones to water — catch them strung out on the road, not camped. Bring my eagle home and the cohort counts you one of ours."),
                    DeclineNudge = BandItPlus.Localization.Get("bp_cultureprofileregistry_388", "As you were, then. But mark this: every dawn count, ninety men salute an empty pole. The offer stands until that column reaches its garrison. After that the eagle goes behind walls, and the ledger stays open another twenty years."),
                    BusyLine = BandItPlus.Localization.Get("bp_cultureprofileregistry_389", "You have standing orders already, soldier. One duty at a time — that is how a cohort stays a cohort. Finish what you carry, then report back. The eagle will keep a little longer. It has kept twenty years."),
                    TargetPartyName = BandItPlus.Localization.Get("bp_cultureprofileregistry_390", "Cassius' Eagle Column"),
                    CaptainName = BandItPlus.Localization.Get("bp_cultureprofileregistry_391", "Captain Cassius"),
                    JournalObjectiveText = BandItPlus.Localization.Get("bp_cultureprofileregistry_392", "Find Cassius' Eagle Column on the imperial roads and recover the eagle standard of the Twelfth Legion for Centurion Aurelius."),
                    JournalReturnText = BandItPlus.Localization.Get("bp_cultureprofileregistry_393", "Return the recovered eagle standard to Centurion Aurelius at the Fallen Legionaries' camp."),
                    ConfrontIntro = BandItPlus.Localization.Get("bp_cultureprofileregistry_394", "Halt there. This column marches under imperial writ — the standard of the disbanded Twelfth, bound for the shrine at Lycaron. I know what you are. State your business and clear the road, or my escort will clear it for you."),
                    Choices = new[]
                    {
                        new SignatureChoice { Label = BandItPlus.Localization.Get("bp_cultureprofileregistry_395", "You know my name. Count my spears, then hand down that eagle."), Requirement = SignatureRequirement.Renown, RequirementValue = 200, Outcome = SignatureOutcome.ComplyFull, ResultProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_396", "I know it. So do my men — I can hear them knowing it behind me. Sergeant, uncrate the standard. Present it properly; we will not be shamed twice in one hour. Take your eagle. The report I write tonight will flatter neither of us.") },
                        new SignatureChoice { Label = BandItPlus.Localization.Get("bp_cultureprofileregistry_397", "Fifteen hundred denars for the eagle. No blood, no report."), Requirement = SignatureRequirement.GoldCost, RequirementValue = 1500, Outcome = SignatureOutcome.ComplyFull, ResultProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_398", "Put it away — no. Give it here, quickly, before I think. The men are owed three months' pay and the Senate is owed nothing by me. Sergeant, the crate. It fell from a wagon at the ford. That is what happened. Go.") },
                        new SignatureChoice { Label = BandItPlus.Localization.Get("bp_cultureprofileregistry_399", "The eagle stays on this road. Draw."), Outcome = SignatureOutcome.Battle, ResultProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_400", "Escort — form line! Shields front, dress on me! You want a legion's eagle, brigand? Then meet a legion's drill. It was carried by better men than either of us. Come and take it.") },
                    },
                    DemandFailProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_401", "Your name. I have read every dispatch out of Lycaron this season and it appears in none of them. No. The eagle rides with me, and if you want it you may try steel — my escort could use the drill."),
                    ClosingProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_402", "Hand it up. Slowly. There. Twenty years since this weight was in my hands, and my hands remember it to the ounce. Look — the crown is nicked where the Dasalir arrow struck. I was standing under it. Sound the muster. The cohort makes the dawn count under a full pole for the first time since our numerals were struck from the rolls. You did this, soldier. Stand at my right for the count. That post has been empty a long time."),
                    ClosingProseOtherCause = BandItPlus.Localization.Get("bp_cultureprofileregistry_403", "So this is how it comes home. Pulled out of a ditch by whoever got there first, mud in the wing-feathers, crown stove in. Give it to me. An eagle is not disgraced by mud, soldier — only by the men under it, and the men under it now are mine. The smith will hammer out the dent. The rest we leave. It should look like what it has been through. Half-honors on the ledger. Full place on the pole. Dismissed."),
                    RewardGold = 2000,
                    RewardRelation = 10,
                },
                ChiefTitle = BandItPlus.Localization.Get("bp_cultureprofileregistry_404", "Disowned Centurion"),
                ChiefBackstory = BandItPlus.Localization.Get("bp_cultureprofileregistry_405", "Aurelius enlisted in the Northern Empire's Twelfth at fifteen, the youngest son of a smallholder family in Praven who had no inheritance to look forward to and no land to farm. He served with distinction in the Khuzait wars of his youth, was promoted to optio at twenty-two, and made centurion at twenty-eight after his predecessor was killed at the Battle of the Dasalir Crossing. The trouble began the year the imperial succession fractured into three claimants — pay-shipments stopped arriving, requisitions went unanswered, and the cohort was left to forage on the imperial highways for three full winters with no word from the capital. Aurelius held the line at Pravend through all three winters, refused to disband his men or surrender the standards to opportunistic lords, and waited for relief that never came. When the cohort's water-stores ran out for the second time he made the decision: he marched the legion off the imperial roster with the eagles and the pay-chests they had captured from a corrupt prefect. Twenty years on, the cohort still drills at dawn, still wears the imperial purple, and still numbers in the hundreds — pension-veterans, deserters, and second-generation children born inside the cohort's marching-camp. The empire has issued three separate edicts demanding the return of the eagles; Aurelius has filed three separate counter-petitions demanding the back-pay he is still owed."),
                ClanHistory = BandItPlus.Localization.Get("bp_cultureprofileregistry_406", "The Fallen Legionaries are exactly what they appear to be — what is left of the Northern Empire's Twelfth, after the cohort was disbanded without back-pay in the second imperial reorganization and twenty years of accrued pay-claims written off the rolls in a single afternoon. Aurelius held the cohort together for the first march east, then the first winter, then the first refusal of an imperial decree. The original survivors numbered ninety-one. Only veterans of imperial service are admitted, and only those who can produce proof of the rolls they were dropped from. The camp is laid as a cohort-camp — palisade, ditch, regular tents, dawn-drill, evening watch-rotation — because that is what it remains, and the inverted eagle in front of Aurelius's tent has not been touched in twelve years. The Empire treats them as an embarrassment more than a threat: the Senate has tried twice to amnesty them in exchange for surrender of arms, and both delegations went home empty-handed. The Legionaries take only imperial wagons, only imperial revenue-trains, only imperial granary-shipments — never private merchants, never peasants, never anyone the cohort would once have been sworn to defend."),
                ChiefGreeting = BandItPlus.Localization.Get("bp_cultureprofileregistry_407", "The grey-haired man straightens as you approach, snapping his hand up in a salute that is older than the empire he no longer serves. His eyes scan you head to foot the way a centurion still does — armor, posture, weapon-hand, the small tells. \"Eyes front, soldier. Aurelius doesn't ask twice. State your business in two sentences and stand straight while you do it — I have buried better men for taking three.\""),
                ChiefGreetingTolerated = BandItPlus.Localization.Get("bp_cultureprofileregistry_408", "Aurelius's salute is curter this time — the kind a centurion gives to a soldier who has earned the omission of formality. His eyes still scan you, but they no longer linger. \"At ease, soldier. The watch reports you've held discipline on every visit since the first. Make your report. Aurelius will hear it through this time.\""),
                ChiefLoyaltySpeech = BandItPlus.Localization.Get("bp_cultureprofileregistry_409", "Name noted, soldier. The roster wants more than a name. Aurelius has command of men who survived three campaigns the Empire forgot they were sent on — they don't take new comrades on names alone. There is a duty waiting for you. Carry it through, and the cohort will know your name like its own."),
                CampIntro = BandItPlus.Localization.Get("bp_cultureprofileregistry_410", "The Fallen Legionaries' camp is laid out like an imperial cohort camp — palisade, ditch, regular tents. Aurelius drills the boys at dawn. The eagle banner hangs upside down."),
                HideoutDirections = BandItPlus.Localization.Get("bp_cultureprofileregistry_411", "Ride the old imperial post-road west out of Lycaron until the paving stones break apart and the weeds take them. You will pass a collapsed milestone leaning in the grass - the numeral is half-gone but the eagle is still cut clean on the upper face. From that stone, turn south into the sentinel-hill country and keep the highest hill on your right shoulder. When you see the inverted eagle on a pole above a proper palisade and ditch - dug to the book, not scratched out by goat-herds - you have found {HIDEOUT_NAME}.\n\nMy pickets hold the ridgelines a full mile out. They are old legionaries and they will mark your column before you mark them. Ride at a walk, banners shown, hands off the hilt. If you have a centurion's vinestaff or a broken eagle of your own, raise it. We were soldiers once and we still answer the old signs. A man who comes in at the trot with weapons bared earns the response his manners deserve.\n\nCome in proper order and you will eat what we eat - black bread, stale wine, iron discipline. Come in like brigands and my line will form on the drilling-yard and you will learn what a cohort still remembers. The Empire disowned us. We did not forget the drill. Keep that in your head before you cross my ditch, traveler."),
                ScoutsLordsProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_412", "The Empire has not forgotten us, traveler. Three cohorts they have rotated through the sentinel-hill country this season - imperial outriders, the kind I once commanded, riding the old frontier road west of Lycaron like they own the milestones. They do not. The milestones were cut by men whose grandsons I drilled. I gut their picket-riders when they stray, and I leave the bodies sitting upright against the ruin-walls so the next column reads the message.\n\nThere is a tribune called Lucius Varro who hunts me by name. He was a junior officer under my command at the Lycaron muster, and now he wears the eagle I was stripped of. He sends his scouts in pairs, never threes - he was always cheap with rations. I have killed four of his pairs this season. Sooner or later he will come himself, and then we will settle the ledger the legion never let me close.\n\nThe Vlandians push their outriders into the western passes when the snow breaks, chasing imperial bounties on my head - a tidy sum, I am told. The Battanians stay clear; they remember the punitive expedition my old cohort ran through their hills, and they have long memories for grudges. If you ride my country under an imperial banner, soldier, my pickets will read the colors before they read your intent. Carry that knowledge. The frontier still belongs to me."),
                ScoutsClanProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_413", "My pickets keep a roster, same as any cohort - know your neighbors, know who holds the next hill. The Sky Raiders nest above the sentinel ridges north of us. Aerlin and I have a treaty signed in nothing but silence: her hawks do not stoop on my picket fires, and my crossbows stay capped when her riders pass the ridgeline. We were both legion-broken in our own ways. That is enough.\n\nThe Highwaymen of the downs are another matter. Their Reeve sold a tally of my supply caches to a Vlandian tax-rider two winters back. Three of my men bled out in a ditch for that ledger. I owe him a debt paid in iron, and one day my second cohort will ride the down-road and collect it in full. Granny Hod's forest band to our west I leave alone - she trades honest, keeps her snares off my ration runs, and her boys have warned my scouts twice when imperial outriders came hunting.\n\nThe quiet one is Khalid's slaver caravan. My scouts have not crossed his column in six weeks. A slaver does not go silent because he is resting. He is moving cargo somewhere he does not want witnessed, and when a man like that vanishes from the road, somebody downwind is about to find chains on their wrists."),
                ScoutsCaravanProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_414", "My pickets have been counting wheels on the Lycaron post-road for six weeks running. There is an Imperial grain-column that moves east on the kalends of each month - eight wagons of milled flour and salted pork bound for the garrison at the old sentinel-hill forts. The escort is sixteen legionary-pattern spears and four crossbows, which sounds like a cohort until you watch them eat. They halt at the third milestone west of the ruined Aurelian bridge, unbuckle their helms, and pass a wine-skin the quartermaster pretends not to see. That hour, traveler, is when the column is a sleeping dog.\n\nThe captain is one Tribune Marcellinus - a sharp man on parade, a drunk man after noon. Bribe his outrider sergeant for twenty denars and the pickets will face the wrong way. We have done it. The third wagon carries the pay-chest disguised under flour-sacks; the lead two are honest grain. Hit the rear, not the front, and the spears in front will keep marching half a furlong before they notice their tail is gone.\n\nThere is also a Vlandian silk-train that cuts north through my hills on the dark of each moon, running pepper and dyed cloth up to the Sturgian boyars. Smaller escort, ten riders, but they march at night and they do not sleep. Leave that one to my cohort. The grain-column is yours if you want it. A soldier should eat well before he fights."),
                PactTeaseProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_415", "You ask the sacramentum, stranger. The oath-question. In the cohort we did not speak it twice, and we did not speak it at all to men who had not earned the standing. Sit. The fire is mine, and so is the silence that follows what you have just asked.\n\nI have sworn the blood-oath twice in this life. Once to the Eagle, before the Senate sold it for grain prices and frontier maps. Once to Decimus, my optio, who took a Khuzait arrow in the throat at the Lycaron crossing because I had broken formation to drag a recruit from the river. I bled for him before he bled for me, and the ledger between us closed only when he stopped breathing in my arms. That is what an oath from a centurion costs. Not coin. Not a season's loyalty. The drill, until the drill ends you.\n\nBring me a frontier held against orders. A column kept in line when the line should have broken. One deed done in the discipline of the old standards, not the mercenary rabble of this age, and I will read your name into the roll where Decimus is written. Speak the question again when you have stood the watch."),
                OathBrotherProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_416", "Then the sacramentum is spoken twice in one life, and the second time the gods of the legion did not flinch. Stand at attention. No - stand easy. I have not given that word to a man in nine years. Draw your gladius. Lay it across mine on the stone where the cohort's eagle used to rest before the Senate struck our numerals from the rolls. Now the cut. Forearm, soldier's cut, the one the drill-master opens on the first day so you learn what your own blood smells like. Press it to mine. There. The iron drinks. The eagle that was taken from us still sees, and tonight it counts one more.\n\nFrom this watch forward you are my brother under the old oath, the one they could not unmake when they unmade us. My cohort is your cohort. My wound at Lycaron - the one the tribune called desertion and the surgeon called bone-deep - is your wound now, and the answer we owe for it is your debt as it is mine. You sleep inside my watch-line. You eat from my mess. When I drill at dawn you drill beside me at my right hand, where the signifer used to stand before they hanged him.\n\nBrother. The frontier west of Lycaron knows your name tonight. The ruined castra knows it. The legate who disowned us will hear it when our shields come over his wall. Fall in."),
                PactAnswerProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_417", "Then it is heard, and it is enough. You did not come back with a speech rehearsed on the road. You came back with the deed already cold on your blade and the word offered after, as a soldier offers his report - flat, factual, finished. That is the order I was taught before they stripped the eagle from our standard. The sacramentum was never the words. The sacramentum was what a man had already done by the time the centurion called the roll.\n\nSo hear the terms as a soldier hears them. When you raise your banner, my cohort forms on your flank. Not as auxiliaries the Senate can recall by edict - that lie I have already outlived once. As sworn shields, bound by the same iron oath we swore to a legion that disowned us. Your enemies inherit my grudge-list. The lords who paid the bounty on my head will find my men in their grain-stores and at their gate-hinges. In return you give me what the Empire withheld: the right to be SPENT for a cause that meant it.\n\nThe drill carries this now. Every dawn count, every cadence-step my legionaries take, your name marches in the line. When steel is drawn, the eagle - mine, broken though it is - rises beside your standard. We are not kin. We are something the legions understood better. We are sworn, and the sworn do not break ranks until the field is ours or we are under it."),
                TroopLoanProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_418", "Granted. Ten line-men, seven days, counted from the next dawn watch. I will draw them from the second file - they still remember the drill, which is more than I can say for the rest of this pit. My optio, Brennus Quintus, rides at their head. He took an oath on my standard the day the eagle fell, and he has not broken it since. He answers to you as he answers to me. No further.\n\nNow my terms, traveler. The sacramentum binds them to the work, not to your purse - so the work had better be worth a legionary's sweat. If one of mine falls in your line, you bring me his gladius and the name of who put him down. I will see to the rest. If he lives, you return him fed, watered, and with his kit intact. I count blades when they march back through this gate.\n\nSeven days. The cohort expects them at the seventh dawn, formed up and accounted for. Do not be late."),
                NamedTargetAcceptProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_419", "His name is {TARGET}. He sleeps under his own banner at {HOME}, fed and warm, and that is the wound. Nine years ago I held the Third Cohort's left flank at the Drava ford under our sacramentum to the old eagle. {TARGET} commanded the relief column. He turned south. Forty-two of my men were ridden down in the shallows while he wintered his horses at a wine-merchant's villa. The legion called it lost dispatches. I called it what it was. He has lived nine years on that lie.\n\nHe rides with twelve in his household guard, but only four are veterans, and the veterans hate him for the same reason I do. His captain is a man called Brennus who lost a brother at the ford - find him at the smithy in {HOME} on market days, stand him a drink, and he will speak. {TARGET} hunts boar in the woods west of the keep every third dawn. He goes with two outriders. Take him on the trail.\n\n{REWARD} denars when the eagle is paid back in full. The cohort keeps the rest. Now move."),
                NamedTargetReason = BandItPlus.Localization.Get("bp_cultureprofileregistry_420", "{CHIEF} has named {TARGET} of {HOME} as the magistrate whose ledger must be closed in blood. Eleven years past, on the Veranda road south of Lycaron, the Tenth Cohort marched on stale bread and forged orders - a quartermaster's contract sold for clean denarii to a man wearing a senator's ring. Forty-two legionaries fell to a Khuzait ambush that was never supposed to happen, the eagle taken, the standard-bearer's hands struck from his wrists before he died. {CHIEF} carries the cohort-roll on a strip of tanned hide beneath his lorica, and {TARGET}'s name is the last unblotted line. The drill demands answer. A heavy purse of {REWARD} denarii is offered, and the sacramentum waits to be honoured in iron."),
                NamedTargetComplete = BandItPlus.Localization.Get("bp_cultureprofileregistry_421", "{TARGET} is dead, and {CHIEF} has been told. The name of the magistrate who signed the disbandment order at Lavium in the ninth year - the man whose seal scattered the Tenth Cohort and left Quintus rotting in a ditch outside the gate - has been struck from the long bronze tally nailed above the cohort's fire. {REWARD} denars sit counted in the strongbox beside the broken eagle, and the relation between centurion and sword-for-hire is set one notch deeper into the wax. Quintus does not march again. But the sacramentum has been honoured. The drill is kept. The ledger of Lavium is shut."),
                NamedTargetOtherCauseProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_422", "Word reached {CHIEF} at second watch: {TARGET} was dead, bled out in a ditch off the post road, cut down by some rival baron's outriders over a tax quarrel that had nothing to do with the eagle, nothing to do with Lavium, nothing to do with Decimus face-down in the Drava silt. The centurion received the news standing, the way he had received the disbandment order years ago, and said little. The grudge was answered on paper. The ledger of the optio's drowning was closed by another man's blade, in another man's quarrel, and that sat in him like cold iron. He counted out {REDUCED_REWARD} denars - quarter-pay, the price of a result without the doing of it - and set the bond a notch firmer, though no warmer. The broken eagle stayed broken."),
                RaidVillageAcceptProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_423", "\"There is a village called {VILLAGE} on the {LORD} clan's eastern revenue list. They sent seventy modii of wheat to the column that betrayed us at Lavium - and the forged marching orders that put my cohort on the wrong road were sealed in {LORD}'s grandfather's hall. Twelve years on, that village still grinds the bread the traitor-column ate while my centuria bled in the river-fords. The debt is grain, and grain it shall be paid in.\n\nTheir militia rides patrol on market-days and returns at dusk drunk on the lord's wine. Strike at the third watch when the bread-ovens are cold and the granary stewards are counting tally-sticks by lamplight. Burn the wheat first, then the tally-house, then the millstones. Spare the field-hands and the bondswomen - they grind for whichever banner stands over them. Kill any man wearing {LORD}'s sash.\n\n{REWARD} denars when the granaries are ash and the modii are settled. Discipline first, then the burning. The legion's ledger does not forget.\""),
                RaidVillageReason = BandItPlus.Localization.Get("bp_cultureprofileregistry_424", "{CHIEF} has named {VILLAGE}, the holding of Lord {LORD}, as the field where the cohort's ledger will be balanced in fire. The granary there fed the column that turned on the Lavium oath, and the orders forged in that village's scriptorium moved the betraying standards into position before dawn. Seventy modii of wheat were drawn from those barns to feed men who would later cut down their own. The Centurion remembers the count, and he remembers the seal. He offers a soldier's purse of {REWARD} and the closing of an account ten years overdue. The debt is wheat. The payment is ash. The contract is sealed in the cohort's roll."),
                RaidVillageComplete = BandItPlus.Localization.Get("bp_cultureprofileregistry_425", "{VILLAGE} smolders, and {CHIEF} has been told. The grain-fief of Lord {LORD}, whose stores fed the betraying column at Lavium and whose scribes forged the orders that walked the cohort onto Imperial spears, lies threshed in its own ash. The seventy modii of wheat are paid, not in grain but in the only currency the Centurion still keeps a ledger for. {REWARD} denars are counted out on the standard-stone where the cohort once mustered, struck across to the player like back-pay to a foederatus. One name is scored from the roll. The wheat-debt has been spilled."),
                RaidVillageOtherCauseProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_426", "Word reached the marching-camp at second watch: {VILLAGE} stood ash and bone, but the column that put it to the torch had ridden under {LORD}'s pennant on a quarrel of borders, not on cohort writ. {CHIEF} read the dispatch by lamp-oil and folded it twice, the way an officer folds orders that no longer require action. The seventy modii of wheat owed the cohort since Lavium had been paid in another man's fire. The grudge stood discharged - on the ledger, not on the standard. He had the quartermaster tally {REDUCED_REWARD} denars from the strongbox, half-rate by old legion custom for a debt collected by foreign hand, and signed the chit without comment. The wheat was burnt. The honor was not."),
                // 2026-05-25 rewrite: COMPANION-MONOLOGUE shape. A member of the
                // player's own party — Vermund, a cashiered ex-legionary — reads
                // the camp for the player in military diction; the player is silent
                // throughout, only obeys at the end. Distinct from forest_bandits
                // (boy-stranger speaks AT the camp) — Vermund is OUR party-veteran
                // and his analysis carries his own history. No "These were not X",
                // no negation list, no "you watched" reveal.
                HideoutCinemaIntro = BandItPlus.Localization.Get("bp_cultureprofileregistry_427", @"""Eagle's upside down,"" Vermund says, beside you on the rise. ""You see it?""

You see it. Vermund used to wear that eagle right-way-up on his shoulder before they cashiered him for taking a Battanian girl out of a burned village instead of leaving her in it. He has not been the same about eagles since. He sits his horse a little stiffer in their presence — the only sentimentality he has ever shown you.

""The ditch is the V-spec,"" he says, ""dug to the marching depth. Three feet at the lip, narrowing to one. Spoil on the inner face. You don't dig that ditch by accident. You dig it because a centurion named Macrius made you redig it twice when you were eighteen. Either the man down there learned from Macrius or he served under him. Either way, he is older than you think.""

He nods toward the gate.

""Challenge given. No countersign returned. That's the giveaway. In the proper years you'd be dead between the syllables. They're going through the motions because they remember the motions, and they remember the motions because the motions are the last unbroken thing they own.""

A long pause.

""See those boots? Unblacked. Centurion would have flogged a man for that. So would I. So would the man inside that gate, ten years ago. Now he watches and lets it pass, because the price of correcting it is the boy's face when the boy realizes nobody's coming to relieve him.""

Vermund spits into the dust, very carefully, away from you.

""I knew an Aurelius once. Tenth Century, Fourth Cohort. He had a way of straightening a guy-rope nobody else would have noticed. That'd be him, then. Or one of his.""

He goes quiet, then, and listens. From inside the rotting palisade comes the slow patient sound of a blade being sharpened — and under it, very faint, an old marching-cadence hummed without words, on no particular pitch, by a man who has nowhere to march to.

Vermund touches his brow with two fingers. The old salute. For himself, not for them.

""Walk the horse down,"" he says. ""He'll want to look at us before he decides anything.""

You walk the horse down."),
                ServiceLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_428", "Train at the legion's drill yard. (1000 denars)"),
                ServiceFlavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_429", "Aurelius examines your party. He shouts orders. Your soldiers drill until they bleed."),
                Kind = ServiceKind.VeteranHall,
                BribeAmount = 250,
                WhyNotKingdom = BandItPlus.Localization.Get("bp_cultureprofileregistry_430", "\"We served the empire. The empire owed us pay and gave us the road. We chose new bosses — ourselves.\""),
                Religion = BandItPlus.Localization.Get("bp_cultureprofileregistry_431", "\"Imperial gods, in the imperial way. Eagle, sword, and emperor — though the emperor we curse, the eagle we still salute.\""),
                ThreatResponse = BandItPlus.Localization.Get("bp_cultureprofileregistry_432", "Aurelius doesn't move. \"Soldier, I have ordered men to their deaths. I have buried half my cohort. A threat from a stranger doesn't reach me.\""),
                Pleasantry = BandItPlus.Localization.Get("bp_cultureprofileregistry_433", "He nods stiffly. \"A camp is built right or it isn't. Mine is. Some habits don't die when the wages stop.\""),
                DrinkFlavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_434", "The Legionaries pass a clay jug of soldier-wine. Aurelius raises it. \"To the brothers we left buried, and the empress who left us to bury them.\""),
                RestFlavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_435", "You bunk in regulation tents, two to a row, on imperial-issue cots. Aurelius wakes you at dawn whether you want it or not."),
                ExtraServices = new[] {
                    new CultureSubService { Label = BandItPlus.Localization.Get("bp_cultureprofileregistry_436", "Stand at the standards."), Flavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_437", "Aurelius leads you to the upended eagle. \"We touch the staff once a day. It reminds us why we hated them. And what we still are.\" Your party's morale ticks up."), Kind = ServiceKind.VeteranHall, GoldCost = 0, MoraleGain = 3 },
                    new CultureSubService { Label = BandItPlus.Localization.Get("bp_cultureprofileregistry_438", "Read the imperial dispatches. (100 denars)"), Flavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_439", "Aurelius opens a captured pouch. \"We intercept these from the post-rider. One reveals a cousin's camp. Take it. The empire pays us in carelessness.\""), Kind = ServiceKind.InfoBroker, GoldCost = 100 },
                    new CultureSubService { Label = BandItPlus.Localization.Get("bp_cultureprofileregistry_440", "Visit the quartermaster."), Flavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_441", "A bald man with a slate gestures you in. \"Imperial gear, slightly used. Some bloodstained. We're honest about the source.\""), Kind = ServiceKind.SlaveMarket },
                },
                Rumors = new[] {
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_442", "\"The Twelfth Legion is being reformed in the south — without us.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_443", "\"There's an imperial pay-chest hidden at the old Lycaron fort. Lost in the war.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_444", "\"Senator Lucon votes against soldier pensions every term.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_445", "\"A Battanian rebel pays for old legion training. We sent two of our boys to him.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_446", "\"The Western Empire is hiring mercenaries again. Twice the wage of last year.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_447", "\"There's a deserters' fort hidden in the southern hills. Other legions, same story.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_448", "\"An imperial dispatch rider goes through here weekly. We let him pass — and read his pouch first.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_449", "\"A relic from the Twelfth's standards is in private hands.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_450", "\"The empire's conscription officer is bringing fresh recruits past here.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_451", "\"Aurelius taught the empress's nephew sword-work years ago.\""),
                },
                TrustQuestTier1Pool = new[] {
                    new TrustQuest {
                        ItemIds = new[] { "wine" }, Counts = new[] { 10 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_452", "\"Ten amphorae of wine. The legion taught us drinking among other things. The empire never paid our back-wages, so the empire's wine will do.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_453", "He pulls a cork with his teeth, drinks long. \"Imperial vintage. You drink with us tonight.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_454", "10 wine"),
                    },
                    new TrustQuest {
                        ItemIds = new[] { "oil" }, Counts = new[] { 15 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_455", "\"Fifteen oil. Lamps for the night-watch, and the boys still oil their kit like proper legionaries. Bring it.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_456", "He tests the oil between thumb and forefinger. \"Pure olive. Not the rancid stuff the quartermaster sold us back in service.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_457", "15 oil"),
                    },
                    new TrustQuest {
                        ItemIds = new[] { "grain" }, Counts = new[] { 20 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_458", "\"Twenty grain. The men march on bread and the cohorts line up for it like old times.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_459", "He surveys the sacks. \"Quartermaster's portion. Tomorrow we eat as we did at Pravend.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_460", "20 grain"),
                    },
                },
                TrustQuestTier2Pool = new[] {
                    new TrustQuest {
                        ItemIds = new[] { "wine", "iron" }, Counts = new[] { 30, 10 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_461", "\"Thirty wine and ten iron. The legion drank, and the legion sharpened steel. Bring both, and we'll count you a comrade.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_462", "He stacks the amphorae like a quartermaster. \"You'd have made a centurion. Take what you need.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_463", "30 wine + 10 iron"),
                    },
                    new TrustQuest {
                        ItemIds = new[] { "oil", "wine" }, Counts = new[] { 25, 15 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_464", "\"Twenty-five oil and fifteen wine. The cohorts maintain kit and morale on these alone. Bring both — full quartermaster's haul.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_465", "He nods like a centurion. \"Properly stocked. The cohort thanks you with steel.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_466", "25 oil + 15 wine"),
                    },
                    new TrustQuest {
                        ItemIds = new[] { "wine", "mule" }, Counts = new[] { 40, 5 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_467", "\"Forty wine and five mules to haul it. The mid-summer drinking-feast for the cohorts. Don't be late.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_468", "He surveys the festival-laden mules. \"Tonight we drink like we did before the empire forgot us. Take what you need.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_469", "40 wine + 5 mules"),
                    },
                },
                TrustQuestTier3Pool = new[] {
                    new TrustQuest {
                        ItemIds = new[] { "wine", "iron", "ironIngot3" }, Counts = new[] { 50, 30, 10 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_470", "\"Fifty wine, thirty iron, ten refined-iron ingots. The cohorts re-equip for the imperial border. We'll show the empire what its forgotten legion can still do.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_471", "He stands at attention as the ingots are laid out. \"You re-equipped a legion. The empire we left will remember why it should have paid us.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_472", "50 wine + 30 iron + 10 refined iron"),
                    },
                    new TrustQuest {
                        ItemIds = new[] { "wine", "oil" }, Counts = new[] { 100, 50 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_473", "\"A hundred wine and fifty oil. The full cohort triumph-feast. We march out at dawn after — you'll see what discipline survives twenty years in the wild.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_474", "He raises a horn. \"Drink with us, brother. Tomorrow we ride, and you've earned the right to ride at the standard.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_475", "100 wine + 50 oil"),
                    },
                },
                // Wave 5 (Chief Recruitment) alliance content
                AllianceCh1TaskBrief = BandItPlus.Localization.Get("bp_cultureprofileregistry_476", "Recover the lost III Legion eagle from the marked patrol ferrying it past the cracked castle."),
                AllianceCh1Pattern = AllianceCh1Pattern.DestroyPartiesOfType,
                AllianceCh1TargetSeedHint = "imperial_eagle_patrol_party",
                AllianceCh3RitualText = BandItPlus.Localization.Get("bp_cultureprofileregistry_477", "The Centurion Aurelius accepts your oath; the rite is sealed at the cracked legion altar with hand pressed to the eagle-stone."),
                AllianceCh3GiftItemId = "lorica_fragmenta_chest",
                AllianceBrokenText = BandItPlus.Localization.Get("bp_cultureprofileregistry_478", "Aurelius salutes you, fist to chest, the old legion salute. \"Dismissed, soldier. There is no place for you under this eagle now.\""),
            }},
            { "bp_sky_raiders", new CultureProfile {
                ChiefName = BandItPlus.Localization.Get("bp_cultureprofileregistry_479", "Aerlin Cliffborn"),
                Signature = new SignatureQuestSpec
                {
                    Title = BandItPlus.Localization.Get("bp_cultureprofileregistry_480", "The Caged Cliffs"),
                    HeraldLine = BandItPlus.Localization.Get("bp_cultureprofileregistry_481", "You. Cliff-Master wants you up top. Some lord's bird-man netted our falcons off the eyries — whole wagonload in cages, rolling south for the lowlands. Aerlin's gone quiet over it. The bad quiet. I'd climb fast."),
                    OfferProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_482", "A lord's man came up my cliffs with nets while the eyries were feeding young. He took nine falcons off the wind, traveler — hatched on my ledges, first-flown over my sea — and now they ride south in wicker cages, hooded in the dark, bound for a lowland mews and a fat wrist at feast-days. A caged cliff-falcon does not tame. She bates against the bars until her wings break or her heart does. Find that caravan. I do not care what the falconer takes for them or what he bleeds — the birds come home to the wind. Bring the cages up whole. The wind will tell me you are coming. It always does."),
                    AcceptProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_483", "Good. Do not open the wicker on the road — a falcon loosed in lowland air rises into strange wind and stranger arrows. She goes back to the sky from the ledge she hatched on, or not at all. Climb careful, traveler."),
                    DeclineNudge = BandItPlus.Localization.Get("bp_cultureprofileregistry_484", "Then walk back down, traveler. But the cages roll south while you think, and a cliff-falcon does not last long behind wicker. The wind keeps the offer. It does not keep it long."),
                    BusyLine = BandItPlus.Localization.Get("bp_cultureprofileregistry_485", "You carry work already, traveler. A falconer flies one bird at a time — throw two at the sky and you lose both. Finish what is on your wrist."),
                    TargetPartyName = BandItPlus.Localization.Get("bp_cultureprofileregistry_486", "Falconer's Caravan"),
                    CaptainName = BandItPlus.Localization.Get("bp_cultureprofileregistry_487", "Master Falconer Gerwin"),
                    JournalObjectiveText = BandItPlus.Localization.Get("bp_cultureprofileregistry_488", "Find the Falconer's Caravan on the roads and recover the caged cliff-falcons netted from the Sky Raiders' eyries."),
                    JournalReturnText = BandItPlus.Localization.Get("bp_cultureprofileregistry_489", "Carry the caged falcons back to Aerlin Cliffborn at the Sky Raiders' camp."),
                    ConfrontIntro = BandItPlus.Localization.Get("bp_cultureprofileregistry_490", "That's close enough. These birds are lawful cargo — netted under license, bound for my lord's mews. I know what you are and which cliff you climbed down from. Name your business and keep your hands off the wicker."),
                    Choices = new[]
                    {
                        new SignatureChoice { Label = BandItPlus.Localization.Get("bp_cultureprofileregistry_491", "Count my riders, falconer. Then open the cages."), Requirement = SignatureRequirement.StrengthRatio, RequirementValue = 120, Outcome = SignatureOutcome.ComplyFull, ResultProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_492", "Take them, then. Gently — gods, gently, they bruise. No. That is a lie I tell my lord. Three years on my glove, every one of them. Go on, take them. Better your cliff than a mews they'd have died in.") },
                        new SignatureChoice { Label = BandItPlus.Localization.Get("bp_cultureprofileregistry_493", "A thousand denars for the cages. All of them."), Requirement = SignatureRequirement.GoldCost, RequirementValue = 1000, Outcome = SignatureOutcome.ComplyFull, ResultProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_494", "...Done. Quietly, then — coin in the hawking bag, cages off the rear wagon, and no names carried either way. Tell whoever flies them the grey tiercel takes the lure high. He earned better than a lord's mews anyway.") },
                        new SignatureChoice { Label = BandItPlus.Localization.Get("bp_cultureprofileregistry_495", "No bargain. The birds fly today — through you if need be."), Outcome = SignatureOutcome.Battle, ResultProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_496", "Guards — to the wagons! Cover the cages, the cages first! Damn you, climber, I'd have sold you half of them if you'd asked twice. Loose at will!") },
                    },
                    DemandFailProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_497", "I count a dozen good crossbows on my wagons and rather fewer blades at your back. No. These birds cost me three years and my lord a small fortune — I'll not hand them to the first climber who talks hard. Move along."),
                    ClosingProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_498", "Set the cages on the flat stone and stand off. There. Watch her — she remembers. Off the ledge, down, down — and the updraft takes her. Look at her climb. Nine birds back on the wind, traveler. A lowland lord sits at his feast-table this winter with an empty gauntlet, and my sky is full again. The wind carries debts both ways. Today it carries mine to you. Take your coin — and the wind's thanks with it. That is worth more."),
                    ClosingProseOtherCause = BandItPlus.Localization.Get("bp_cultureprofileregistry_499", "The gulls brought it in before you did. Someone else hit the falconer's wagons at a ford — no craft in it, just axes. Half the cages broke in the wreck. Four birds found the wind on their own. The rest — a falcon does not die well in wicker, traveler. My rope-runners carried the living ones up last night. So. Half done, by other hands, and paid the same way. Half coin. The wind does not owe what it did not carry."),
                    RewardGold = 1700,
                    RewardRelation = 8,
                },
                ChiefTitle = BandItPlus.Localization.Get("bp_cultureprofileregistry_500", "Cliff-Master"),
                ChiefBackstory = BandItPlus.Localization.Get("bp_cultureprofileregistry_501", "Aerlin was born on a stone ledge above a mountain pass, the bastard of a Vlandian noblewoman who could not present him at court and would not abandon him at a temple. She built a stone hut at the edge of the world — three days' ride from the nearest settlement — and raised him there with two trusted servants and a small library of stolen books. He grew up reading the loot-ledgers of his uncles' raids before he could write his own name; his mother taught him geometry by stacking captured coin and arithmetic by valuing stolen jewelry. When she died — a lung-fever that no physician could reach in time — Aerlin was nineteen and had never spoken to more than four people in his life. He came down off the cliff with his mother's ledgers and a list of every Vlandian noble who had wronged her, and within five years he had robbed the convoys of every name on the list. The Sky Raiders took shape as a company of climbers and scouts, men who could fight on slopes that infantry could not navigate; today they raid the high passes of Vlandia and the western border, holding ledges no army has the patience to siege. Aerlin has never lost a fight on uneven ground, and the only thing he hates more than the Vlandian crown is the prospect of falling."),
                ClanHistory = BandItPlus.Localization.Get("bp_cultureprofileregistry_502", "The Sky Raiders are the smallest of the great bands and the strangest. Their roots are not in any kingdom but in a falconer-tradition older than all four — a high-mountain craft of training peregrines and gyrfalcons for hunt and war that the Vlandian lowland lords no longer practice and the Battanian highland clans only half-remember. Aerlin's mother carried the craft up from the lowlands and built her stone hut at the cliff's edge for the wind, and Aerlin has never lived under any other roof. Cliff-village shepherds, dispossessed Vlandian bastards, falconer-apprentices whose masters could not afford to keep them, and the rare lowland nobleman's son who cannot abide a stone hall find their way up to Aerlin's camp by routes the lowland patrols have never mapped. They rope between cliffs to move and signal with falcon-jesses tied with colored thread, and their raids are precise to a degree no flat-country lord has learned to anticipate — they arrive when no road-patrol expects, vanish into rock-folds no lowland horse can follow. The crown classifies them as a curiosity rather than a threat — it has not yet lost enough men in the high passes to correct that classification."),
                ChiefGreeting = BandItPlus.Localization.Get("bp_cultureprofileregistry_503", "The Cliff-Master does not turn until you've cleared the last rope-pitch. The hawk on his gauntlet sees you first — head tilting in that quick, surgical way — and only then does he. He studies you in that same surgical manner: brief, complete, unimpressed. \"You came up the slow way. The clever ones do. The dead ones tried the fast. Speak, traveler — Aerlin's wind doesn't wait, and neither does his bird.\""),
                ChiefGreetingTolerated = BandItPlus.Localization.Get("bp_cultureprofileregistry_504", "The hawk on Aerlin's gauntlet recognizes you before its handler does — head tilting in that quick raptor's curiosity instead of the surgical study from before. Aerlin himself lowers his gauntlet a fraction. \"You came up the slow way again. The wind likes you, traveler. So does the bird, which is rarer. Speak — Aerlin's perch is open to those his hawk doesn't strike at.\""),
                ChiefLoyaltySpeech = BandItPlus.Localization.Get("bp_cultureprofileregistry_505", "The wind's heard names, traveler. Carries them off the cliffs and forgets them by sundown. Aerlin trusts what the bird trusts — and the bird trusts what proves itself. There's a task within our reach. Earn the bird's calm and you've earned mine; refuse, and the next strong wind takes your name with it."),
                CampIntro = BandItPlus.Localization.Get("bp_cultureprofileregistry_506", "The Sky Raiders' camp clings to a cliff — tents staked into ledges, ropes between, perches for a dozen falcons. The wind never stops. A boy is teaching a young hawk the lure."),
                HideoutDirections = BandItPlus.Localization.Get("bp_cultureprofileregistry_507", "Follow the coast road north of Sanala until the inland trees give up and the wind starts pulling at your cloak in earnest. When the road forks at the white limestone scoured bare by the gales, take the goat-trail switchback that climbs the cliff-face - the one no sane drover uses. Our hold lies at {HIDEOUT_NAME}, on the ledges above the breakers, where the gulls scream louder than a man can shout.\n\nLong before you reach the last switchback, my falcon-cote will see you. The bird on that ledge is no wild thing - she is mine, and her jesses are tied to a bell that rings in my tent. My watchers run the knotted ropes between the high perches faster than you can climb the trail, and they will count your spears before you count your breaths. Ride open-handed. Tie a strip of white cloth to your spear-point so the wind shows it clean against the cliff.\n\nCome the right way and there is salt-fish on the fire and a sheltered ledge for your horses out of the spray. Come the wrong way and the wind takes you first, then the rocks, then the gulls - we do not even need to draw a bow. The cliff has fed itself on bolder men than you, traveler. Carry a name I know, and the ropes drop for you."),
                ScoutsLordsProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_508", "The Battanian lords think these cliffs belong to them because their grandfathers fished the same gulls we eat. They send their fianna up the coast road in twos and threes, sworn-men in green cloaks asking the fisher-villages who feeds the cliff-dwellers. The fishers point south. We watch them ride south. We laugh into the wind. There is a lord out of Marunath called Cuthred who has sworn on his grandfather's torc that he will burn my eyries before midwinter. He has sworn this three midwinters running. The gulls remember his face now.\n\nThe true trouble comes from below. The Empire's southern legate keeps a tax-galley working the Sanala coast - she puts in at every cove with a coin-chest and a centurion who thinks the cliff-paths are myth. We took her tithe-purse twice this season. The third time she came with Aserai mercenaries in the hold and we lost a good rope-man on the rocks. So now there is a debt between me and that legate that only salt water settles.\n\nIf you ride the coast road under any banner that is not Battanian green, traveler, ride it fast. The fianna read banners before they read faces, and the southern empire reads purses before either. The cliffs do not care which side claims you. The gulls eat from every hand that falls."),
                ScoutsClanProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_509", "Bjornulf Salt-Tongue and his longboats put in at my coves twice a year, and we trade the way gulls trade with the tide - he leaves a cask of Sturgian mead, I leave him word of which Battanian thanes have weak watch-fires. We owe each other nothing and that is why the bargain holds. The man who rides the sea and the man who watches from the cliff should never count debts between them, or one of us ends in the surf.\n\nGranny Hod's forest band, south where the highland breaks into oakwood, sent a runner last moon asking after a debt of salt. I sent her two barrels and the head of a Vlandian tax-rider who had wandered too near her trees. She owes me a season of safe passage now, and her boys know not to climb where the gulls nest. Skarvac's pass-lords in the mountains east of here - them I do not trust. They count coin like Reeve's Highwaymen and they have stopped answering smoke-signals from the cliff-watch.\n\nThe Reavers up in the snows - Vargolf - we have never crossed, and the wind says we should keep it so. But the Cult, Crone Vael's lot, have been seen on the cliffs at dusk leaving carved gulls on the rocks. That is old sign, and not for me. When the Cult moves quiet near my coast, I sharpen the watch and I do not sleep facing the sea."),
                ScoutsCaravanProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_510", "The cliff-road from Sanala to Pen Cannoc runs along the sea for three days, traveler, and the merchants who take it think the gulls are their friends. They are not. The gulls are my eyes. A Vlandian cloth-train comes north every dark moon - four wagons, eight crossbowmen, two outriders who hate each other and ride a furlong apart because of a woman in Jaculan. The wagons carry dyed wool bound for Battanian chiefs who pay in amber. They camp at the Cormorant Spring because the captain fears the cliff-wind after dusk, and the wind is loud enough there to swallow a scream.\n\nHit them at the third hour past midnight. The crossbowmen sleep in a ring but the wind blows their fire flat, and a man cannot string a wet bow in the spray. I have taken that train twice - once for the wool, once for the amber the chiefs had already paid in advance. The captain is named Othric. He bribes well if you put a knife to his belly first, but he will lie about a second purse he keeps in the axle of the lead wagon. Cut the axle open.\n\nIf you ride with thirty horse, the train is yours and I will not contest it - my longboats are out hunting Sturgian salt-cogs this moon and my cliffs are thin. Take the amber. Leave the wool on the rocks for the gulls. Wool drowns slow and the tide takes everything by dawn."),
                PactTeaseProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_511", "You ask the cliff-question, traveler, and the wind has already heard you. Sit. Down there, where the gulls turn, the fall is the same whether a man means his oath or only thinks he does - so I will not answer quickly, and you will not pretend you did not ask.\n\nWhen I bleed, I bleed for those whose jesses I have tied to my own wrist. My sister Caelin, who I cut from a Sturgian rope when she was twelve and the tide was rising. Old Mawran, who taught me which ledges hold and which lie. A gull-girl from Pen Cannoc whose name the cliff still keeps though her bones do not. Their knots are at my wrist. Yours is in my hand, untied, waiting.\n\nBring me a deed the wind will carry north - a raid kept silent until the gulls had flown, a southern banner cut down on a ledge no horseman could climb, a debt of mine paid before I knew I owed it - and I will tie your jess to my own. Until then my rope is my rope and my fall is my fall. Come back when the cliff has a reason to remember your name."),
                OathBrotherProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_512", "Then the wind has heard it, and the gulls have heard it, and that is witness enough for me. Stand on the ledge with me - here, where the rope is anchored to the iron ring my father drove when I was a boy. Give me your wrist. I tie the jess around it, the same leather I tie to my hawks before I throw them at the sky, and I tie the other end to my own. There. We are jessed to each other now. Drink from the horn - it is salt-water and barley-spirit mixed, the cliff-drink, the only oath my people swear with their feet over open air. The knot at our wrists is a brother-knot. Rope-knots do not lie.\n\nFrom this gust forward you are my hearth-brother. The scar across my shoulder, the one the lowland archer gave me the day I lost my first hawk to a crossbow bolt, that scar is your scar to avenge if I fall before you do. My sister at Sanala is your sister. My mother's grave on the headland is your grave to tend. When I throw the hawks at dawn, one is yours - the brown one, the quick one, she will learn your whistle. Sky-raider brothers share wind, share rope, share the long fall if the rope fails.\n\nHear it, cliff. Hear it, gull. Hear it, every Battanian lord who has ever sent men up these paths to burn us. Aerlin Cliffborn names this one brother on the high ledge, and the knot is tied, and the wind has carried it inland. Brother - the cliff holds two now."),
                PactAnswerProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_513", "Then I have heard it, and I heard it before you spoke. The wind off the cliffs carries news faster than tongues, and word of your deed reached this ledge two gulls ago. You did not come up that rope to ask my blessing. You came up to report. The deed first, the word almost an afterthought - that is the order a Cliff-Master trusts. A lesser man brings a fine speech and a clean knife. You brought a knife that has been used, and the speech was nearly forgotten in the doing. Sit. The salt will dry on you while we talk terms.\n\nFrom this tide forward, my jesses are cut for your hand. When you raise your banner, the longboats slip the cove and the rope-bridges drop for your riders - not as hire, not as a favor I can reel back, but as a war-bond knotted the way I knot a falcon's leash: one loop the bird cannot break, and one I will not. Your feud is the cliff's feud now. Your enemies will hear oars where they expected only gulls. In return I ask the same - when a southern banner climbs against my eyrie, your steel rides north before the tide turns twice.\n\nThe gull cries this oath out across the headland already. Steel makes its own sound, and the wind carries it - to the lowland lords, to the salt, to every cove that has ever sheltered me. We are bound now in the work of war, you and I, the way a rope is bound to the cliff it hangs from. Cut one, the other falls. Ride hard, ally. The knot holds."),
                TroopLoanProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_514", "Done, traveler. Ten cliff-walkers for seven days - rope-runners I have weighed myself, each one gull-throated and quick on a bad ledge. My second is Maerwen Salt-Eye, who has worked every shelf on this coast and knows when to whistle and when to cut the line. She rides with you. The wind owes you that much.\n\nNow hear my terms. If a rope-runner of mine falls in your work, you bring back his knife and the name of the place he died - I will carve it on the cliff where his mother can find it. If he lives, you feed him well and send him home with salt still in his hair. My men do not break shield for petty grudges or roadside thieves. While they wear your colours, your road IS my road, so do not waste them chasing crows.\n\nSeven days. Count them by the moon, not the sun - the sun lies on water. The gulls will tell me when they ride back through the pass, and I will be listening."),
                NamedTargetAcceptProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_515", "His name is {TARGET}. He keeps his banner over {HOME}, and that cliff was Cliffborn ground before his great-uncle Maerwin came up the rope-ladders one summer dawn with paid swords and a forged charter from a dead king. He took the eyrie. He took my grandfather Aedric off the high ledge by the ankles and let the gulls have what fell. The jesses my father wore on his wrist were cut from my grandfather's belt. {TARGET} sits in that hall now. The cliff knows.\n\nHe flies a tercel he calls Lord's Pride, and the bird hunts the cove below the south stair every third morning. He rides out with it himself, six lances, no scout. The cove path narrows where the gulls nest. A man on the rope-knot above can see his banner before the bird does. Take him there, traveler, where the wind comes off the water and steals the sound of a drawn bow.\n\n{REWARD} denars when his banner comes down off that wall. The grudge is older than the coin and the coin will not close it, but it is what I have to give. The wind will tell me when it is done. Ride."),
                NamedTargetReason = BandItPlus.Localization.Get("bp_cultureprofileregistry_516", "{CHIEF} has named {TARGET} of {HOME} as the man who cut the jesses on a falcon called Sea-Eye nine summers past, and with her the throat of the boy who flew her. The bird was a gift-hawk, hand-fed from the cliff at Gull-Stair, and the boy was {CHIEF}'s sister-son, sent down to the lowland court bearing a peace-token wrapped in oilcloth. Neither came back up the rope. The token was returned by a paid rider, stained, and the falcon's hood was nailed to the chapel door. The Cliffborn keeps the hood on his beam still. {REWARD} is offered, and a knot the wind has waited too long to pull tight. The contract is open."),
                NamedTargetComplete = BandItPlus.Localization.Get("bp_cultureprofileregistry_517", "{TARGET} is dead, and {CHIEF} has heard the wind carry it home. The jess-strap that hung empty above the cliff-perch since the winter Brennec was cast from the Skewer's high ledge now bears a single knot drawn tight - the falconer's brother answered for at last. {REWARD} denars sit weighed beside the rope-coil at the chief's fire, counted twice by gull-light, and the bond between Sky-Reaver and stranger-blade is cut a knot deeper. The hawk that lost her hand is not given back, but her name is spoken even, and the cliff keeps the rest. The rope is finished."),
                NamedTargetOtherCauseProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_518", "Word came in on a salt-stiff gull-runner: {TARGET} had been ridden down by a rival lord's outriders three valleys east, ambushed at a ford while the snow still clung to the reeds. {CHIEF} took the news standing by the beam where the jess-strap of Sea-Eye still hangs empty, and for a long breath he said nothing at all. The Skewer ledge had its answer; Brennec's name could be set down. But the gift-falcon was not recovered by a hand he chose, and the killing was not paid in the coin he had asked. He counts out {REDUCED_REWARD} denars - thin coin, quarter-pay - and nods once. The grudge is closed. The bond is set a smaller notch firmer, cooler than an earned kill, but firm."),
                RaidVillageAcceptProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_519", "\"There is a fisher-village called {VILLAGE} on the headland below Skewer Cliff, held by Lord {LORD} of the coast-clan that lit the wrecker-beacons twelve winters past. They hung false harbor-lanterns on the rocks the night the Saelvarg made for shelter. My longboat broke her keel on their cradle of stones. Twelve oar-mates went down singing. Their gulls still pick clean what the tide leaves, and {LORD}'s smallfolk glean the wreck for nails and beads when the water draws back.\n\nGo when the spring-tide is at its lowest - their men are out on the flats then, gathering my dead-men's iron from the sand. The drying-sheds are heavy with smoked fish bound for the inland markets, and the wreck-gleaners hoard amber and sea-glass in the chapel cellar. Burn the sheds. Take the cellar. The fisher-wives and the children of fishermen - let them run inland. I will not drown what already lives by water.\n\n{REWARD} denars when the smoke goes up from the headland and the gulls fly out to sea. The wind takes the rest. Sail before the tide turns.\""),
                RaidVillageReason = BandItPlus.Localization.Get("bp_cultureprofileregistry_520", "{CHIEF} has named {VILLAGE}, the wrecker-cove held in fief by Lord {LORD} of the Battanian coast-clans, as the shore whose thatch will burn to close the debt of the longboat Saelvarg. It was {VILLAGE} that set the false beacons below Skewer Cliff one black autumn, and it was {VILLAGE} that gleaned the wreck while twelve of {CHIEF}'s oar-mates rolled in the surf, lungs full of cold salt. The fisher-folk still pick brass from the rocks at low tide. The Cliffborn offers a purse of {REWARD} to the keel that returns with smoke at its back. The wind has turned. The Saelvarg's twelve are waiting. The contract is open."),
                RaidVillageComplete = BandItPlus.Localization.Get("bp_cultureprofileregistry_521", "{VILLAGE} smokes on the headland, and {CHIEF} stands at the cliff-edge where the Saelvarg's keel still ribs the rocks below. The fisher-clan of Lord {LORD} - the wrecker-kin who hung the false beacons that drowned twelve oar-mates a tide ago - have no beacons left to light, no nets left to gather salt-stripped boards. {REWARD} denars are counted onto a longboat-thwart hauled up from the wash, every coin tallied against a drowned name. The gleaners gleam no more. The Saelvarg's debt is one shore lighter, and {CHIEF} marks the cliff with a fresh oar-notch for the dead."),
                RaidVillageOtherCauseProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_522", "A gull-runner came up the cliff stair at low tide with the word: {VILLAGE} lay broken on its own shingle, but the keels that broke it had flown a different pennant - {LORD}'s feud, not the Saelvarg's reckoning. {CHIEF} heard it standing at the cliff-rail above the wreck-line, where the twelve oar-mates still slept under green water. He spat once into the wind for the drowned and said the gleaners would steal no more lanterns to set on no more rocks. The beacon-clan was answered, but the torch had been another's. He counted out {REDUCED_REWARD} denars from the salt-stained chest - half-fare for a passage he had not rowed - and turned back to the sea, neither warmed nor cheated."),
                // 2026-05-25 rewrite: IMPERATIVE / SECOND-PERSON-INSTRUCTION shape.
                // A series of "Do not X" commands — the vertigo lives in what the
                // rules forbid. The camp doesn't appear until the wind drops and
                // silence arrives. No "These were not X", no companion-quote pivot,
                // no "you watched" reveal, no "No, not tonight" refusal. Ends with
                // permission to speak — "Slowly."
                HideoutCinemaIntro = BandItPlus.Localization.Get("bp_cultureprofileregistry_523", @"Do not look down.

You will want to. The body, when it finds itself this far from the ground, tries to satisfy itself by measuring the distance. Do not let it. Keep your eyes on the rock to your left, on the narrow strip of stone the path has become, on the rope-anchor driven into the cliff at chest height. There is the strip. There is the anchor. Keep moving.

Do not stop on the windward shelves. They look the safest because they are the widest. They are not. Wind that has crossed forty miles of open air arrives here without warning and arrives with the weight of a hand laid flat against your chest. A man who is standing still on a windward shelf when that wind comes is no longer standing still.

Do not trust the bridges. The Cliffborn weave the ropes and the Cliffborn replace the ropes, but the wind ages the ropes faster than any people, and the bridges they last crossed at noon they will recross at dusk and find changed. Watch where the Sky Raider in front of you sets his weight, and set yours where his was. He will not turn to check on you. That is not unkindness. That is mercy. Looking back kills.

Do not speak. The wind takes voices and the wind does not give them back. If you must speak, lean close, and shape the word against the listener's ear. Calls have killed climbers up here who did not deserve to die for a call.

Do not look at the falcons. Look at the gloves that handle the falcons. Look at the knots in the jesses. The birds will not hurt you. The bird-keepers will not, either, if you watch their hands the way they watch yours.

Do not flinch when the wind drops.

It will. Suddenly. The roar will go and the silence will arrive and the silence will be very large, and in the centre of that silence you will hear voices, women talking low, a child laughing, someone singing a long string of nonsense to a falcon to soothe it. You will hear the camp.

Then look up.

The tents staked along the bare ledges. The figures crossing the ropes. The firelight snapping sideways. A woman with her feet over nothing, mending a glove.

Now you may speak. Slowly. Aerlin Cliffborn is the one with her hood off."),
                ServiceLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_524", "Send a hawk aloft to scout for hideouts."),
                ServiceFlavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_525", "Aerlin lifts her arm. The hawk lifts off and is gone. \"I'll mark every camp she sees on your map.\""),
                Kind = ServiceKind.Falconer,
                BribeAmount = 200,
                WhyNotKingdom = BandItPlus.Localization.Get("bp_cultureprofileregistry_526", "\"Kings live below us. We don't even see their banners from up here. Who would we serve, the wind?\""),
                Religion = BandItPlus.Localization.Get("bp_cultureprofileregistry_527", "\"The sky-mother. The wind-father. The hawk that watches all things. We pray short, in the open.\""),
                ThreatResponse = BandItPlus.Localization.Get("bp_cultureprofileregistry_528", "Aerlin smiles, slowly. The hawk stiffens. \"My bird sees better than you do. Take a step. See where she lands.\""),
                Pleasantry = BandItPlus.Localization.Get("bp_cultureprofileregistry_529", "She looks past you, at the wind. \"It's a good cliff. We had to fight three other clans for it. We won't fight a fourth.\""),
                DrinkFlavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_530", "The Raiders share a liquor distilled from cliff-berries — sharp and cold. \"To the sky and to the strong rope. Either alone is death. Together, freedom.\""),
                RestFlavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_531", "You sleep on a cliff-ledge, lashed to a rope just in case. The wind sings all night. Your party wakes light-footed."),
                ExtraServices = new[] {
                    new CultureSubService { Label = BandItPlus.Localization.Get("bp_cultureprofileregistry_532", "Visit the cliff-forge."), Flavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_533", "An old man hammers iron at a forge bolted to the rock. \"Cliff-iron is harder. The wind tempers it as it cools. Costs more, lasts longer.\""), Kind = ServiceKind.TrophyRoom },
                    new CultureSubService { Label = BandItPlus.Localization.Get("bp_cultureprofileregistry_534", "Speak with the wind-reader. (50 denars)"), Flavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_535", "An old raider sits on a windward perch, eyes closed. \"The wind tells everything. Storm coming. War coming. You — choose the wind, not the wave.\""), Kind = ServiceKind.Oracle, GoldCost = 50 },
                    new CultureSubService { Label = BandItPlus.Localization.Get("bp_cultureprofileregistry_536", "Hire a falcon-trainer. (300 denars)"), Flavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_537", "A young trainer with raw hands shows your soldiers how a hawk lands. \"Discipline of the bird is discipline of the man. Cheap at the price.\" Morale rises."), Kind = ServiceKind.VeteranHall, GoldCost = 300, MoraleGain = 3 },
                },
                Rumors = new[] {
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_538", "\"There's a noble's hunting hawk worth more than a Vlandian war-horse.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_539", "\"A Battanian druid pays for fresh-kill from sky-hunts.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_540", "\"An imperial messenger uses falcons too — flies them down the coast road.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_541", "\"The cliff-passes get a tax-collector twice a year. He climbs slow. We climb faster.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_542", "\"A merchant pays double for sky-raider feathers in Onica.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_543", "\"The kingdom's pigeon-network was disrupted last year. Some of them were us.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_544", "\"There's an abandoned eyrie three valleys west — hawk-eggs unhatched, tools intact.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_545", "\"A rival cliff-clan has been encroaching on our airspace.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_546", "\"The Imperial War College sends scouts up here every spring to recruit falconers.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_547", "\"A young heiress wants to learn falconry in secret.\""),
                },
                TrustQuestTier1Pool = new[] {
                    new TrustQuest {
                        ItemIds = new[] { "velvet" }, Counts = new[] { 15 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_548", "\"Silk. Fifteen bolts. We strip silks from caravans on the high passes, but supply runs short between raids.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_549", "He fingers the silk to the light. \"Real. Not the dyed cotton merchants pass off. The Raiders trade with you.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_550", "15 velvet"),
                    },
                    new TrustQuest {
                        ItemIds = new[] { "leather" }, Counts = new[] { 20 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_551", "\"Twenty leather. Saddle, harness, fall-rope kit. The high passes are unforgiving on tack.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_552", "He weighs a strap, snaps it taut. \"Strong stitch. The Raiders welcome you to the trails.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_553", "20 leather"),
                    },
                    new TrustQuest {
                        ItemIds = new[] { "linen" }, Counts = new[] { 25 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_554", "\"Twenty-five linen. We bandage what the high stones break. Bring it, and the men will heal because of you.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_555", "He hands a roll to the camp's healer. \"Clean cloth. The boys live longer because of this. Trade.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_556", "25 linen"),
                    },
                },
                TrustQuestTier2Pool = new[] {
                    new TrustQuest {
                        ItemIds = new[] { "velvet", "leather" }, Counts = new[] { 30, 20 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_557", "\"Thirty silk and twenty leather. We sleep light and ride lighter — silk for ropes, leather for harness.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_558", "He nods sharp. \"You ride the high country now. Recruit my best, take the armory.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_559", "30 velvet + 20 leather"),
                    },
                    new TrustQuest {
                        ItemIds = new[] { "linen", "hardwood" }, Counts = new[] { 40, 30 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_560", "\"Forty linen and thirty hardwood. New stretcher-frames for the high-fall climbs. Bring both, and the high country is yours.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_561", "He tests a frame's give. \"Steady carries. The Raiders ride safer because of you.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_562", "40 linen + 30 hardwood"),
                    },
                    new TrustQuest {
                        ItemIds = new[] { "velvet", "mule" }, Counts = new[] { 25, 5 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_563", "\"Twenty-five silk and five sure-footed mules. The eastern raid moves silently in silk-padded harness. Bring both.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_564", "He surveys the silent caravan. \"Whisper-quiet now. The eastern lord won't hear us coming.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_565", "25 velvet + 5 mules"),
                    },
                },
                TrustQuestTier3Pool = new[] {
                    new TrustQuest {
                        ItemIds = new[] { "velvet", "hardwood", "ironIngot3" }, Counts = new[] { 60, 30, 10 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_566", "\"Sixty silk, thirty hardwood, ten refined-iron ingots. The grandest raid this generation has run. Outfit us, and you ride at the head.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_567", "He clasps your forearm in the high-rider greeting. \"You lead the eastern raid this autumn. The Raiders ride at your hand.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_568", "60 velvet + 30 hardwood + 10 refined iron"),
                    },
                    new TrustQuest {
                        ItemIds = new[] { "leather", "velvet" }, Counts = new[] { 100, 50 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_569", "\"A hundred leather and fifty silk. We re-arm the entire raid-cohort for the spring high-passes. Heavy haul.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_570", "He surveys his men in fresh kit. \"The high country has never seen Raiders this proud. You walk among us as equal.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_571", "100 leather + 50 velvet"),
                    },
                },
                // Wave 5 (Chief Recruitment) alliance content
                AllianceCh1TaskBrief = BandItPlus.Localization.Get("bp_cultureprofileregistry_572", "Ambush a Battanian highland tribute caravan from the cliff-ambush position above the high road."),
                AllianceCh1Pattern = AllianceCh1Pattern.DestroyPartiesOfType,
                AllianceCh1TargetSeedHint = "battanian_tribute_caravan_party",
                AllianceCh3RitualText = BandItPlus.Localization.Get("bp_cultureprofileregistry_573", "The Aerlin Cliffborn accepts your oath; the rite is sealed at sunset on the cliff edge, a hawk released into the dropping sun."),
                AllianceCh3GiftItemId = "throwing_axe_set_t3",
                AllianceBrokenText = BandItPlus.Localization.Get("bp_cultureprofileregistry_574", "Aerlin watches you over the cliff's edge, hand on the hawk's hood. \"The wind takes some friendships. This one. Go before I loose her at your back.\""),
            }},
            { "bp_steppe_wolves", new CultureProfile {
                ChiefName = BandItPlus.Localization.Get("bp_cultureprofileregistry_575", "Khan Borchu"),
                Signature = new SignatureQuestSpec
                {
                    Title = BandItPlus.Localization.Get("bp_cultureprofileregistry_576", "Forty Hooves"),
                    HeraldLine = BandItPlus.Localization.Get("bp_cultureprofileregistry_577", "You. The Wolf-Khan's been asking for you. Something about a lord's horses walking a road they shouldn't. He's at the camp. I'd not make him ask twice — he doesn't."),
                    OfferProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_578", "A lord is selling horses. Forty of them, steppe-bred, walking to market under drovers' whips like oxen. Steppe horses do not belong to the man who holds the rope, traveler. They belong to the man who can ride them. That lord cannot. His drovers walk. His guard riders sit their saddles like sacks of millet. Find the herd on the road and drive it home to my grass. Forty horses is not plunder — forty horses is a herd, and a herd is a clan's blood walking. Bring me that blood, and Borchu will not forget whose hand drove it home."),
                    AcceptProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_579", "Good. Ride light and carry rope. A herd follows a lead mare, not a whip — take the whips off them and the horses will remember whose grass they were foaled on. The wind rides with you."),
                    DeclineNudge = BandItPlus.Localization.Get("bp_cultureprofileregistry_580", "As you like. The herd walks to market either way — to a fat lord's purse or to my grass. Think on which end of that road you would rather stand. The offer keeps until the horses sell."),
                    BusyLine = BandItPlus.Localization.Get("bp_cultureprofileregistry_581", "One hunt at a time, traveler. Finish the work you carry. A rider who chases two herds catches dust."),
                    TargetPartyName = BandItPlus.Localization.Get("bp_cultureprofileregistry_582", "Lord's Horse-Drove"),
                    CaptainName = BandItPlus.Localization.Get("bp_cultureprofileregistry_583", "Drover Captain"),
                    JournalObjectiveText = BandItPlus.Localization.Get("bp_cultureprofileregistry_584", "Find the Lord's Horse-Drove on the roads and take the herd of forty steppe horses from its drovers and guard riders."),
                    JournalReturnText = BandItPlus.Localization.Get("bp_cultureprofileregistry_585", "Drive the captured herd back to Khan Borchu at the Steppe Wolves' camp."),
                    ConfrontIntro = BandItPlus.Localization.Get("bp_cultureprofileregistry_586", "Close enough, rider. These horses walk under a lord's brand, bought fair at the spring muster. You want a mount, the market is two days on. You want trouble, my riders are paid for that too."),
                    Choices = new[]
                    {
                        new SignatureChoice { Label = BandItPlus.Localization.Get("bp_cultureprofileregistry_587", "Come dark, this herd runs. Try holding it."), Outcome = SignatureOutcome.Battle, ResultProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_588", "Torches! Get torches up — they're in the herd! Hold the line, hold the — gods, they're all running! To me! Guards, to me!") },
                        new SignatureChoice { Label = BandItPlus.Localization.Get("bp_cultureprofileregistry_589", "No dark work. I'll take them here, in the open."), Outcome = SignatureOutcome.Battle, ResultProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_590", "Open ground, then. You picked the one fight my lads know. Wheel about! Lances down — earn your wages, boys.") },
                    },
                    ClosingProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_591", "Forty. I counted them from the rise before you crossed the creek. A herd walks differently when it comes home — you will learn to hear it. Foaled on this grass, sold off it by a man who never slept against a horse's warmth in the snow. Well. The grass has them back. Take the grey and the dun with the black legs — best of the forty. A khan does not let a herd-bringer ride away worse mounted than the herd he brought. Ride hard."),
                    ClosingProseOtherCause = BandItPlus.Localization.Get("bp_cultureprofileregistry_592", "Word came in on the wind before you did. Another band hit the drovers at the ford and the herd went forty ways at once. My riders gathered what the steppe gave back — six, still shaking. The rest run loose out there. Good. A steppe horse loose on steppe grass is not lost, traveler — it is home the older way. Still. Six is not forty. Quarter-pay, and no shame riding with it. The wind does not apologize either."),
                    RewardGold = 1200,
                    RewardRelation = 8,
                    RewardItemIds = new[] { "t2_khuzait_horse" },
                    RewardItemCounts = new[] { 2 },
                },
                ChiefTitle = BandItPlus.Localization.Get("bp_cultureprofileregistry_593", "Wolf-Khan"),
                ChiefBackstory = BandItPlus.Localization.Get("bp_cultureprofileregistry_594", "Borchu is a true Khergit khan by birthright — but only by a sister-line that was never meant to see succession. His mother was the Great Khan's youngest sister, married off to a minor steppe-prince to seal a border alliance; she bore Borchu the year her husband died of a horse-fall, and the boy was raised in his uncle's tents as a fosterling. The Great Khan's sons did not appreciate the existence of a cousin with a legitimate claim, and at twenty-three Borchu was sentenced to exile on a charge of insulting a half-brother. He rode west into the empty grass with seventeen riders who refused to leave him; for three years they lived as outlaws, raided Vlandian merchants, and grew their numbers off bandits and steppe-orphans. When the Great Khan's eldest son died in a mysterious accident, Borchu came back at the head of two hundred horsemen, demanded an audience, and presented his claim. The Khanate's elders did not formally acknowledge him but they did not formally exile him a second time either; he keeps his title because nobody alive remembers stripping it from him. The Steppe Wolves are now the largest non-affiliated band on the steppe, and Borchu rides as a khan in all but recognition."),
                ClanHistory = BandItPlus.Localization.Get("bp_cultureprofileregistry_595", "The Steppe Wolves are a sister-line of the Khergit royal house, and that is the inconvenient fact that has never let the Khanate quite kill them. Borchu is a true khan by birthright — only by a sister-line never meant to see succession, but a true khan, and the Wolves know it. Horsemen with nowhere to go collect around Borchu's standard — steppe-clansmen whose grazing has been re-allocated by the Great Khan's favor, exiles whose feuds the royal court declined to mediate, second sons with no herd of their own. They winter wherever the grass is short enough to suggest a herd has just left and nobody can prove which herd. The raid-pattern is the old steppe pattern: ride hard, take what fits on a horse, vanish, return three months later from a direction no patrol has watched. The Great Khan has refused four imperial requests to suppress them — officially because the steppe polices itself, unofficially because Borchu is family. Among the eastern clans the Wolves are a quiet legitimacy-problem: every herd-feud that comes to a head ends with someone whispering Borchu's name as a possible alternative banner."),
                ChiefGreeting = BandItPlus.Localization.Get("bp_cultureprofileregistry_596", "The Wolf-Khan does not dismount. His pony stands placid, ears back, while Borchu himself looks down at you with the slow assessment of a man who has spent forty winters reading travelers off their saddles. He smiles, eventually — wolfish, joyless. \"You ride a foreigner's horse. The wolves smell that on you, traveler. Trade with old Borchu and you'll ride better. Refuse, and the wolves smell something else entirely.\""),
                ChiefGreetingTolerated = BandItPlus.Localization.Get("bp_cultureprofileregistry_597", "Borchu still does not dismount, but his pony's ears prick at your approach now — the small horse remembers the rider it's been told not to bite. The Wolf-Khan's smile, when it comes, is less wolfish, more amused. \"You ride better now, traveler. Old Borchu told you trade with us would do that. Come — the fire is the wolves', but a place at it is yours.\""),
                ChiefLoyaltySpeech = BandItPlus.Localization.Get("bp_cultureprofileregistry_598", "Borchu has heard names enough to fill a steppe sky, traveler. Names wash off in rain. Deeds — the wolves remember. There is a thing my pack would have. Bring it, and Borchu will tell you which fire is yours; until then you ride a foreigner's horse and carry a foreigner's word."),
                CampIntro = BandItPlus.Localization.Get("bp_cultureprofileregistry_599", "The Steppe Wolves' camp is a half-circle of yurts, horses everywhere. The grass is short here from grazing. Children with bows hunt rabbit at the edge of camp."),
                HideoutDirections = BandItPlus.Localization.Get("bp_cultureprofileregistry_600", "Ride east out of Makeb until the farmland gives up and the grass takes over. When you reach the river-bend - the one that swings south like a drawn bow - turn your horse along the bank and follow the hoof-trampled trace for half a day. You will see a horse-skull on a pole standing taller than a man; that pole is mine, and the wind that turns it knows my name. Our camp lies at {HIDEOUT_NAME}, a half-circle of yurts set where the grass is cropped short by my herds.\n\nMy outriders see you long before you see them. We watch from the low rises, and a hundred horses raise a dust-cloud no scout misses. Come at a walk, not a gallop. Hold your weapon-hand open and your reins loose. The children hunting rabbit at the camp-edge will mark you first - if they do not run, my men will not draw.\n\nRide in soft and you sit at my fire, drink my mare's-milk, and ride out heavier than you came. Ride in hard and my arrows find you before the wolf-tails on the windbreak stop turning. I am Borchu, and the steppe is a wide grave for fools. Bring me a name worth speaking, traveler, and the grass parts for you."),
                ScoutsLordsProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_601", "The Khuzait khans send their riders past Makeb every grazing-moon, and they ride like they own the four horizons. They do not. The horizons belong to the wind, and the wind answers to no khan but the one who outlasts him. A noyan named Urkhun Ghazi has been crossing my river-bend with two hundred horse-archers, calling it a hunt. He hunts my outriders. I hunt his remounts. We have an understanding written in lame horses and empty quivers.\n\nThe Empire still pushes tax-wagons up from the southern garrisons, but they send mercenary captains now, not legati - the eagle has grown shy of the steppe since the last khagan broke its wing. There is a Vlandian sellsword called Sir Aldric the Bone-Pale riding under imperial coin who has burned two of my wintering-grounds. I owe him a wind-burial. He owes me his teeth. One of these debts will be paid before the grass turns.\n\nWatch for Khuzait banners flying the white-tailed horse - that is Clan Urkhudai, and their khan has put a price on my saddle that would buy a small town. If you ride with their colors, traveler, ride elsewhere. The steppe is wide. My wolves are patient. The wind carries word of every banner that crosses my country, and I read the wind like other men read sky."),
                ScoutsClanProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_602", "The grass talks if you listen. Vargolf of the Reavers and I have grass between us - he keeps his snow, I keep my steppe, and neither rides where the other's horses graze. Once, in a winter the elders still name, I sent him three remounts when the freeze took his strings. He has not forgotten. The Iron-eyed pays in silence, but he pays. The Slavers under Khalid are another tale. Their chains pass my four horizons three times a season, and three times a season I take my tithe. He calls it raiding. I call it tax. Khalid and I will settle one day with sabres, not words.\n\nUlan's steppe-band rides the eastern flats and counts himself my cousin. He is not. He is a boy with a borrowed name who eats what my scouts leave. I let him live because the Khuzait boyars hunt him and not me. Useful, that. The Sky Raiders out of the high passes - Aerlin's lot - sent a rider this moon asking for safe ride across the river-bend. I said yes. A favour banked is a horse fed.\n\nWhat troubles me is the Cult. Crone Vael's people have gone quiet south of Makeb. No smoke, no chatter, no bodies on the road. Quiet cultists are cultists at work. Watch the shrines. Wind brings news, and the wind off the Crone's country smells wrong."),
                ScoutsCaravanProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_603", "The wind tells me things, traveler. The wind, and four boys I keep posted on the four horizons. A Khuzait silk-train rides the Makeb road every twelfth dawn - forty camels, eight wagons, twenty-six guards on shaggy ponies. They look strong. They are not. The captain is a fat cousin of some khan in Chagan who drinks fermented mare's milk till the second watch and snores through the third. His outriders cluster like sheep because the steppe frightens them. Steppe frightens everyone who was not born inside it.\n\nHit them at the river-bend two days east of here, where the willows hide a man on a horse. The wagons must slow to ford. The rear pair carries Aserai dye and pressed tea-bricks the southern caravan-masters trade for silver by the fist. Do not touch the lead wagons - those carry the captain's gifts for some boyar in Sturgia, and that boyar will send tax-riders for a year if his pretties go missing. Take the rear. The captain will blame the ford.\n\nTwenty horse will do it. Thirty is greedy and the wind notices greed. Ride light, ride at dusk, and leave the camels - they slow you and the wolves out here, the four-legged kind, will thank you for the meat. That is how my clan has fed itself across three moons. The road forgets. The steppe does not, but the steppe keeps its own counsel."),
                PactTeaseProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_604", "You ask the saddle-question, rider. The one the steppe asks of every wind before it lets the wind pass. Sit. Drink the milk before it sours. A man who asks this without his hand on his sword is either a fool or worth weighing, and I have not yet decided which you are.\n\nThe grass remembers what stone forgets. I have bled for three names the grass still knows. Old Tegus, my milk-brother, whose mare I rode when mine fell at the river-bend. The widow Altani, who hid my wounded under her felt when the Khan's-men came counting heads. And one Sturgian I will not name, who held the ford while my warband crossed and asked nothing of me but to remember. These are my saddle-brothers. The roll is closed against the easy and open to the proven.\n\nYou are not yet milk-shared. You are not yet wind. Ride one of my raids without flinching, take a caravan in MY name across the four horizons, or hold a road when the Imperials try to close it - and the grass will learn your hoofbeat. Until then, my horse is mine and my riders are mine. Ask again when you have a banner the snow will not forget."),
                OathBrotherProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_605", "Then it is spoken from the saddle and the wind has heard it. Down. Off the horse. We do this on the grass where my mother foaled me and where my father's bones are pressed. Take the bowl - the white mare's milk, drawn this dawn, mixed now with a red drop from my wrist and a red drop from yours. Drink half. I drink half. The mare watches. She knows the smell of her milk gone to brother-blood. Now the knife - thin cut across the inside of the bridle-hand, the rein-hand, so every time you lift the reins from this day the scar pulls and remembers me. Mine pulls already. It has pulled since the steppe winter when old Kheter cut me and called me son.\n\nFrom this dawn you are saddle-brother to me. Milk-shared. That word is not loose on the steppe. It means my tent is the roof you sleep under when the snow rides sideways, my herd is the herd your hungry horse drinks from, my children call you uncle, and my mother - dead these nine winters - hears your name tonight in the wind and counts another son.\n\nRide. The river-bend by Makeb learns your name. The Wolves learn it. The Khuzait khans who scorned us learn it the next time their banner crosses our four horizons. Brother - the steppe is wide, and from here to its edge there is no horseman who rides alone."),
                PactAnswerProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_606", "The deed rode in before the word did. I heard the hoofbeats at dawn and knew the answer before you swung down from the saddle. A man who speaks first and rides later is a man whose mare is always too tired when the work begins. You came the other way around - the work first, the word almost a courtesy. Good. That is the order Borchu trusts. Sit. Let the horse blow. The milk-bowl is yours.\n\nHear the terms, then, the way the steppe hears them. From this moon, when you raise your banner inside four horizons of Makeb, my riders answer. Not as hirelings paid in silver, not as a favor I tally and call back. As blood-allies, the way two saddle-brothers are bound when one has pulled the other from a river - the debt does not close, it only changes shape. Your feud is my feud. The lords who hunt you will find Wolf riders at their backs before their horns finish blowing. In return, when I send a rider with a knot of black hair, you mount. No question. No delay. That is the bond.\n\nThe wind carries it now. The wind, and the sound of steel when it leaves the sheath - that sound rides farther than any messenger. We are kin in the work, traveler. Ride hard."),
                TroopLoanProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_607", "Done, saddle-brother. Ten of my horse-archers for seven days - I cut them from the herd myself before the fires bank. My second is Tugai Short-Stirrup, a rider who has shared my milk-bowl since we were boys and knows the Wolf-Khan's standards in his bones. He rides at your right hand. If a Wolf of mine falls in your work, you bring his bow and his braid back to me - I will see them burned proper on the steppe. If he lives, you bring him back with more horses than he left with.\n\nMark this, traveler: my riders do not draw bow for coin. They draw for the hunt I have set them to. While they ride under your banner, your hunt IS my hunt - so do not waste them chasing goats. Seven days. Count the suns. The yurts expect them.\n\nI will tell the women whose sons rode out. They will count the suns harder than you."),
                NamedTargetAcceptProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_608", "His name is {TARGET}, and his banner rides over {HOME} where the four horizons bend toward Khuzait grass. Nine summers past his hawks took my sister Altani at a watering ford near the Bukhari bend - cut her mare's hamstrings, dragged her to his hold, sent her bones back in a saddlebag with a Sturgian merchant who would not meet my eye. The grass remembers her. My horses remember her. {TARGET} has not yet learned that the steppe is patient and I am not.\n\nHe rides with twelve lancers and a tracker out of Tyal who reads hoofprints like a priest reads bones. The tracker drinks fermented mare's milk at the Ozolts well every third dusk - sit beside him, share your skin, and he will sell you the route his master takes to summer pasture. {TARGET} sleeps in a felt tent on the high ground. He posts no guard on the north wind. Come from the north.\n\n{REWARD} denars when his horse comes home riderless, saddle-brother. The debt is older than the coin, but the coin is what the living can carry. The grass remembers the rest. Ride hard."),
                NamedTargetReason = BandItPlus.Localization.Get("bp_cultureprofileregistry_609", "Khan Borchu has named {TARGET} of {HOME} as the rider whose blood the four horizons have been waiting to drink. The grudge is cut in horsehide and remembered by the grass — a younger brother, Tergei, run down on the open steppe near the Bitter Wells in a summer of poor rain, hamstrung from the saddle and left for the crows because a southern lord wanted the herd that crossed his hunting grounds. The Khan rode three days behind the trail and found only bones and a broken bridle-bit, and that bit hangs from his belt still. The Khan offers {REWARD} and the closing of a circle nine winters long. The grass remembers. The contract is open."),
                NamedTargetComplete = BandItPlus.Localization.Get("bp_cultureprofileregistry_610", "{TARGET} is dead. {CHIEF} has been told, and the Khan has heard the news between two sips of fermented mare's milk. The dun mare's bridle - the one cut from his uncle Tarbagan's saddle in the Year of the Black Snow, when six riders rode out of Kerkhech and only the boy Borchu rode back - hangs now above the ger's smoke-hole, its brass cheekpiece catching firelight at last. {REWARD} denars are counted twice and tied into a horsehair pouch. The four horizons are quieter by one rider. The grass remembers, and now the grass is fed."),
                NamedTargetOtherCauseProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_611", "A rider came in at dusk with frost still on his beard and word that {TARGET} was already cold - cut down on a back road by some rival lord's outriders, the kill claimed by another saddle. {CHIEF} heard it out without rising, one thumb resting on the dun mare's bridle-bit worn at his belt, the bit he had carried since uncle Tarbagan went down in the Year of the Black Snow. The grudge was answered, after a fashion. The steppe did not care which hand held the knife, only that the wolf no longer ran. Still, the khan's mouth set thin: a kill owed was a kill owed, and a borrowed blow tasted of old milk. He counted out {REDUCED_REWARD} denars in quarter-pay, slid them across the felt, and let the bond sit one notch firmer - cooler than a finished hunt, warmer than a stranger's nod."),
                RaidVillageAcceptProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_612", "\"There is a village called {VILLAGE} on the long grass under Lord {LORD}'s tally-stones. Three grazing-seasons his hide-tax has bled my pastures white. Last moon his tax-rider came to my yurt with my cousin Tugai's ear nailed to a wooden token and a number cut beside it. The number was what this village owes him. So this village will pay it - to me, in fire.\n\n{LORD}'s outriders ride east on the new moon to escort the khan-clan's tribute-wagons. Strike the third night after they leave. The herds graze loose past the willow-creek and the felt-tents hold the season's tanned hides, the wool, the smoked horse-flesh meant for his table. The smallfolk - cut the men who lift a blade, let the rest run. They are nothing to me. The hides are everything.\n\n{REWARD} denars when the smoke crosses the steppe. Tugai's ear I keep. Ride hard, leave nothing standing, and the wind carries the rest.\""),
                RaidVillageReason = BandItPlus.Localization.Get("bp_cultureprofileregistry_613", "{CHIEF} has named {VILLAGE}, the hide-tax fief of Lord {LORD} of the khan-clan, as the pasture that will pay for three grazing-seasons of bled herds. The khan-rider came to the Wolf-camp last spring with cousin Tugai's ear nailed to a wooden tax-token, and rode home with a tally the Wolves could not pay in horses. The village pays that tax. The village feeds the rider who carried the ear. The Khan of the Steppe Wolves offers a purse of {REWARD} and the right to burn the grain that fattens the hand that nailed Tugai. The grass is long. The hooves are shod. The contract waits for a saddle."),
                RaidVillageComplete = BandItPlus.Localization.Get("bp_cultureprofileregistry_614", "{VILLAGE} smokes black against the steppe-rim, and {CHIEF} has heard the gallop. The hide-tax pastures of Lord {LORD}'s khan-clan - the same clan that nailed Tugai's ear to a tax-token three grazing-seasons running - lie trampled, the tithe-yurts split, the herders scattered without their counting-rods. {REWARD} denars are weighed out at the khan's stirrup, cold silver pressed into the rider's palm without ceremony. The horse-proud bond is set firm. Tugai's ear is answered by an empty pasture, and the hide-tax wagon will ride no road through Borchu's grass this season."),
                RaidVillageOtherCauseProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_615", "A rider came in off the grass at second-watch, horse blown, with word that {VILLAGE} lay burnt to the wattle - but it was {LORD}'s own war that had ridden through, not the khan-clan's hide-tax and not the token of Tugai's ear. {CHIEF} heard it standing by his picket-line and spat once into the dust. Three grazing-seasons of bled pastures still ran in him; the village that paid the tax had paid for the last time, only another hand had struck the flint. The grudge stood without honor. He told the steward to count {REDUCED_REWARD} denars - thin coin, a quarter-saddle - and turned back to his mares without another word."),
                // 2026-05-25 rewrite: HORSE-POV-OPENS shape. The player's mount
                // senses the camp first — ears, nostrils, withers — and the rider's
                // awareness catches up only afterward. Ends with Khan Borchu
                // appraising the player THROUGH the horse — the steppe-cultural
                // gesture of reading a man via his mount. No companion-quote, no
                // negation list, no "you watched", no "No, not tonight" refusal.
                HideoutCinemaIntro = BandItPlus.Localization.Get("bp_cultureprofileregistry_616", @"Your horse smells them before you do.

It is a thing horses know — the smell of fifty other horses corralled close, lipped milk, the salt of grass-fed sweat, the faint sweet rot of well-mucked hide tents — and the body under you understands it as a question that wants an answer. The ears come up. The withers lift a little. The nostrils flare wide and stay wide. A muscle along the shoulder twitches you cannot feel through your hand on the rein and you only notice it because the saddle moves. The horse has heard before you have, smelled before you have, decided before you have.

You let your hand sit easy. The horse knows what kind of question it is. You will only spoil the answer by interrupting.

Three paces on, the body shifts under you again. There. Wind off the steppe carries it now to you too — banked smoke, the hot animal smell of a great picketed herd, the faint sour note of fermented milk. The horse turns its head a quarter-degree toward the smell, hesitates, then turns its head back, because the rider has not chosen and the horse will not choose for the rider.

You ride.

The trail bends into a fold of the grassland — a long shallow crease the eye misses from any distance, and inside the crease the Wolves have gone to ground. Yurts in a patient half-circle, their felt walls warm with the fires inside them. Horses everywhere: picketed, grazing, asleep on their feet. The grass for a long bowshot in any direction has been cropped to dust by their teeth. Two children stalk a rabbit at the camp's edge with small bows and enormous seriousness.

Your horse exhales a long slow breath you feel through the saddle. It has been holding it. You did not notice. The breath says the place is safe. The horse decided this some time ago. You only just caught up.

Khan Borchu walks out from the nearest yurt without hurrying. He looks at your face for one heartbeat and then at your horse for three, the way a horseman appraises a man through his mount. Whatever he reads there, his shoulders ease.

He raises a hand.

You ride down."),
                ServiceLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_617", "Ride to the horse master."),
                ServiceFlavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_618", "Borchu leads you to a string of horses. \"Bred from the great khanate's stock. Stolen, but raised by us.\""),
                Kind = ServiceKind.HorseMaster,
                BribeAmount = 150,
                WhyNotKingdom = BandItPlus.Localization.Get("bp_cultureprofileregistry_619", "\"A khan sold our pastures to a Vlandian count. That was the last time we trusted a khan.\""),
                Religion = BandItPlus.Localization.Get("bp_cultureprofileregistry_620", "\"Wolf-spirit. Sky-father. Long-Mother of the herds. They are everywhere on the steppe.\""),
                ThreatResponse = BandItPlus.Localization.Get("bp_cultureprofileregistry_621", "Borchu doesn't smile. \"My riders are watching. You have not seen them. Choose your next words.\""),
                Pleasantry = BandItPlus.Localization.Get("bp_cultureprofileregistry_622", "He nods. \"The horses are good. The grass is short but the horses are good. That is enough.\""),
                DrinkFlavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_623", "The Wolves share fermented mare's milk — sour and strong. Borchu offers a cup. \"To the horse, the wolf, and the open sky. Land of three things only.\""),
                RestFlavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_624", "You sleep in a yurt with felt walls. The wind doesn't cut through. Your party rises strong."),
                ExtraServices = new[] {
                    new CultureSubService { Label = BandItPlus.Localization.Get("bp_cultureprofileregistry_625", "Trade with the felt-maker."), Flavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_626", "A woman lays out felt blankets, leather goods, fur trim. \"Steppe goods. Wear felt and you stay warm in any wind.\""), Kind = ServiceKind.Hunter },
                    new CultureSubService { Label = BandItPlus.Localization.Get("bp_cultureprofileregistry_627", "Consult the wolf-shaman."), Flavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_628", "An old man in wolf-skin enters the yurt. He chews dried herbs slowly. \"The wolf walks beside you. You have not noticed. Listen.\""), Kind = ServiceKind.Oracle },
                    new CultureSubService { Label = BandItPlus.Localization.Get("bp_cultureprofileregistry_629", "Hire a horse-breaker. (200 denars)"), Flavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_630", "A young rider takes your party's horses and works them in a circle for a morning. \"Now they listen better. Costs a few denars and a hard day.\" Morale rises."), Kind = ServiceKind.VeteranHall, GoldCost = 200, MoraleGain = 3 },
                },
                Rumors = new[] {
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_631", "\"Khuzait nobles sell off their war-horses every spring at Akakalat.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_632", "\"A Battanian rebel pays for trained Khuzait mounts. We sold him five last month.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_633", "\"An imperial general lost his prize stallion to raiders — us.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_634", "\"The khan's youngest brother runs a horse market on the steppe. He's corrupt.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_635", "\"A Vlandian noble wants to ride steppe-style. He'll pay well for a horse and a teacher.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_636", "\"The plain south of the river is empty since the last khanate war.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_637", "\"An old wolf-shaman lives east. He blesses horses for hire. The blessings work.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_638", "\"The khan's tax-collectors don't ride out to our part of the steppe.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_639", "\"A Sturgian mercenary captain is buying mounts in bulk for a campaign.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_640", "\"There's a herd of wild horses descended from the great horde.\""),
                },
                TrustQuestTier1Pool = new[] {
                    new TrustQuest {
                        ItemIds = new[] { "sumpter_horse" }, Counts = new[] { 5 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_641", "\"Five horses. Strong ones, mounts not pack-mules. The Wolves run with horses or not at all.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_642", "He checks each horse's teeth. \"Sound stock. The Wolves know your name.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_643", "5 horses"),
                    },
                    new TrustQuest {
                        ItemIds = new[] { "felt" }, Counts = new[] { 30 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_644", "\"Thirty felt. Yurt-walls, saddle-cloth, men's coats. The Wolves can't camp without it.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_645", "He runs his hand over the bolts. \"Properly pressed. The yurts will hold the autumn winds.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_646", "30 felt"),
                    },
                    new TrustQuest {
                        ItemIds = new[] { "pack_camel" }, Counts = new[] { 3 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_647", "\"Three pack-camels. We range south sometimes, where horses fail. The camels carry water for the long marches.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_648", "He pats the lead camel's flank. \"Strong-back beasts. The deep south opens up to us now.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_649", "3 pack camels"),
                    },
                },
                TrustQuestTier2Pool = new[] {
                    new TrustQuest {
                        ItemIds = new[] { "sumpter_horse" }, Counts = new[] { 25 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_650", "\"Twenty-five horses. A whole pack of fresh mounts. The Wolves multiply when we have horses.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_651", "He surveys the herd, eyes bright. \"This is power. You ride at my right.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_652", "25 horses"),
                    },
                    new TrustQuest {
                        ItemIds = new[] { "sumpter_horse", "pack_camel" }, Counts = new[] { 15, 5 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_653", "\"Fifteen horses and five pack-camels. Mixed string for a long-range raid into the deep south. Bring both.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_654", "He inspects the mixed string. \"This rides as far as the spice country. The Wolves owe you a share.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_655", "15 horses + 5 camels"),
                    },
                    new TrustQuest {
                        ItemIds = new[] { "felt", "sumpter_horse" }, Counts = new[] { 50, 10 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_656", "\"Fifty felt and ten horses. Full re-mount and re-yurt for the cold-camp shift. Bring both.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_657", "He surveys camp shrugging into new felt walls. \"Now the Wolves overwinter strong. Take what you need.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_658", "50 felt + 10 horses"),
                    },
                },
                TrustQuestTier3Pool = new[] {
                    new TrustQuest {
                        ItemIds = new[] { "t2_khuzait_horse", "sumpter_horse" }, Counts = new[] { 5, 30 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_659", "\"Five Khuzait war-mounts and thirty pack-horses. The Wolves go to war this spring, and only blood-kin help us mount the cohort.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_660", "He bows his head, the steppe-warrior's salute. \"You have remounted the Wolves for war. Ride beside me, brother.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_661", "5 war horses + 30 horses"),
                    },
                    new TrustQuest {
                        ItemIds = new[] { "felt", "sumpter_horse", "pack_camel" }, Counts = new[] { 100, 30, 10 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_662", "\"A hundred felt, thirty horses, ten pack-camels. We're moving the whole tribe across the steppe to a new winter range. Heaviest haul a Wolf-friend has ever brought.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_663", "He clasps your shoulder steppe-style. \"The whole tribe survives because of you. The Wolves howl your name.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_664", "100 felt + 30 horses + 10 camels"),
                    },
                },
                // Wave 5 (Chief Recruitment) alliance content
                AllianceCh1TaskBrief = BandItPlus.Localization.Get("bp_cultureprofileregistry_665", "Ride down and break a fleeing kingdom-army column on the open steppe — leave nothing standing."),
                AllianceCh1Pattern = AllianceCh1Pattern.DestroyPartiesOfType,
                AllianceCh1TargetSeedHint = "routed_kingdom_army_party",
                AllianceCh3RitualText = BandItPlus.Localization.Get("bp_cultureprofileregistry_666", "The Khan Borchu accepts your oath; the rite is sealed at dusk in a fire-ring on horseback, three laps shared in silence."),
                AllianceCh3GiftItemId = "steppe_pony_mount",
                AllianceBrokenText = BandItPlus.Localization.Get("bp_cultureprofileregistry_667", "Borchu does not dismount. He looks down at you a long time. \"The steppe is wide. We will ride wider apart from this hour.\""),
            }},
            { "bp_pagan_cult", new CultureProfile {
                ChiefName = BandItPlus.Localization.Get("bp_cultureprofileregistry_668", "Crone Vael, the Bone-Sayer"),
                Signature = new SignatureQuestSpec
                {
                    Title = BandItPlus.Localization.Get("bp_cultureprofileregistry_669", "The Barrow Spoils"),
                    HeraldLine = BandItPlus.Localization.Get("bp_cultureprofileregistry_670", "Vael's been at the bones all night. Lowland diggers cracked the barrow open and carted the old dead off to sell. The chant won't sit right till they're back. She wants you at the black stone."),
                    OfferProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_671", "Sit, traveler. The bones woke me before the runner did. Lowland diggers have opened the barrow under the twin oaks — pried the capstone, lifted out the old dead, packed them in straw like crockery. They cart them south to a collector who would set my grandmothers' fingers behind glass. The dead are owed their sleep. It was paid to them, bone by bone, and now the debt stands open and the whole grove hears it. A nervous little scholar leads the carts, with hired spears about him. Bring the relics back to me — every thread, every knuckle. Keep the wagons, keep the silver. The bones come home."),
                    AcceptProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_672", "The bones turned the moment you spoke. Ride the south road past the twin oaks — the carts are slow, and the dead pull backward on the wheels. Bring every bone. I will be counting."),
                    DeclineNudge = BandItPlus.Localization.Get("bp_cultureprofileregistry_673", "The barrow stands open, traveler. Every night it gapes, the grove sleeps worse and the dead sleep not at all. The bones will ask for you again. They do not tire."),
                    BusyLine = BandItPlus.Localization.Get("bp_cultureprofileregistry_674", "The thread you carry is not yet knotted, traveler. Finish what was asked of you first. The bones do not deal in two debts at once."),
                    TargetPartyName = BandItPlus.Localization.Get("bp_cultureprofileregistry_675", "Barrow-Diggers' Column"),
                    CaptainName = BandItPlus.Localization.Get("bp_cultureprofileregistry_676", "Antiquarian Loman"),
                    JournalObjectiveText = BandItPlus.Localization.Get("bp_cultureprofileregistry_677", "Grave-diggers have looted the pagan cult's barrow and are hauling the bone-relics south to a lowland collector. Intercept the cart column, led by the antiquarian Loman, and recover the relics for Crone Vael."),
                    JournalReturnText = BandItPlus.Localization.Get("bp_cultureprofileregistry_678", "The bone-relics are recovered. Return them to Crone Vael at the cult's camp so the barrow can be resealed."),
                    ConfrontIntro = BandItPlus.Localization.Get("bp_cultureprofileregistry_679", "Stay back — these men are paid and I have papers! A bill of sale, sealed, perfectly lawful — the site was abandoned, nobody — the bones belong to my client now. Please. There is no need for any of this."),
                    Choices = new[]
                    {
                        new SignatureChoice { Label = BandItPlus.Localization.Get("bp_cultureprofileregistry_680", "We come by dark, as the dead come."), Outcome = SignatureOutcome.Battle, ResultProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_681", "They've come for the bones — they've come with the dead! Torches! TORCHES! Spears to the carts, hold the line — oh gods, the dark is moving—") },
                        new SignatureChoice { Label = BandItPlus.Localization.Get("bp_cultureprofileregistry_682", "Daylight and plain steel. Hand over the bones."), Outcome = SignatureOutcome.Battle, ResultProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_683", "Stay back — I have papers, I have a seal! Spears! Spears, earn your coin — keep them off the carts!") },
                    },
                    ClosingProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_684", "Give them to me. Every thread, every knuckle... yes. All here. Tonight we carry them home by torchlight and walk the capstone back before dawn, and the grove will sleep for the first time since the digging. You hear the chant change? Warmer now. That should not comfort you, traveler. It will anyway. Your silver — counted without looking. My eyes are needed elsewhere tonight."),
                    ClosingProseOtherCause = BandItPlus.Localization.Get("bp_cultureprofileregistry_685", "The fen road brought them back before you did — wolves, the runner said, though he would not meet my eye. Scattered and gnawed, gathered out of the mud a knuckle at a time. I read the tooth-marks, traveler. I will not say what they spelled. The barrow is sealed, but the chant has not settled. Half your silver — and a kindness with it: do not travel the fen road by night."),
                    RewardGold = 1500,
                    RewardRelation = 9,
                },
                ChiefTitle = BandItPlus.Localization.Get("bp_cultureprofileregistry_686", "Bone-Sayer"),
                ChiefBackstory = BandItPlus.Localization.Get("bp_cultureprofileregistry_687", "Crone Vael came out of the western hill-country at the head of a procession three years ago and has not stopped speaking since. The cult-priests insist she is three sisters in one body — that the original Vael was a triplet whose two siblings died in childbirth and whose souls anchored themselves in the surviving twin's bones. The lowland scholars insist she is simply one woman with a voice that shifts between three registers when she is reading bones. The cult bows to all three voices regardless. Before the procession she was, by her own account, a midwife in a hill-village destroyed by a Battanian feudal raid — the only survivor of an attack that took her mother, sisters, husband, and two daughters in a single afternoon. She walked out of the burning village with a bag of finger-bones taken from her dead and has been reading them ever since, building a cult of orphans, widows, and runaways from every walk of life. She reads bones for the highborn and the desperate alike, and the price is always the same — a daughter for the temple, or a son for the hill, never returned. The Imperial church has offered fifty thousand denars for her head; she has politely declined to deliver herself."),
                ClanHistory = BandItPlus.Localization.Get("bp_cultureprofileregistry_688", "The Pagan Cult is the youngest bandit band by founding-date and the oldest by claim. The cult-priests insist the rites they perform around the black stone are unchanged since the Calradoian dawn-times — before the Empire's first temple, before any of the four modern kingdoms existed in any form. Crone Vael came out of the western hill-country at the head of a procession three years ago and has not stopped speaking. Hill-villages the temple-roads have not visited in two generations supply most of the cult's numbers — along with disillusioned Battanian druid-apprentices, Sturgian widows whose god-thunderer did not answer, and southern men whose reading had run past what the temple libraries permit. They take from temples and shrines, never from peasant homes; they leave the silver and take only the relics, and the relics are stacked unburned in their camp-circle. The Empire has burned three of their grove-camps and watched the cult re-establish each within a season. The peculiar threat the cult presents is that they keep growing in territories where the official temples have most thinned — and the official temples have been thinning for a decade."),
                ChiefGreeting = BandItPlus.Localization.Get("bp_cultureprofileregistry_689", "The figure in the wolf-skull mask is bent over a circle of bones when you arrive. Slowly — as if the motion itself is part of a longer ritual — he turns. The mask's empty eyes find you before his own do. \"The bones told us you would come, traveler. They did not tell us why. That word is for you to speak. Vael will listen — and the bones will listen with him.\""),
                ChiefGreetingTolerated = BandItPlus.Localization.Get("bp_cultureprofileregistry_690", "Crone Vael — the cult names him so, regardless of his beard — is at his bones again, and again he turns slowly when you arrive. But this time he lifts the wolf-skull mask aside to speak; face seamed, eyes pale, weathered as a riverbed. \"The bones called you a friend on your last passage, traveler. They have not changed their mind. Sit by the circle. Vael will hear what the bones haven't told him yet.\""),
                ChiefLoyaltySpeech = BandItPlus.Localization.Get("bp_cultureprofileregistry_691", "Vael has the name; the bones have it now too. Names are vessel-words, traveler — empty until something is poured into them. The bones ask a thing of you. Bring what they ask, and your name will fill at this fire. Refuse, and it stays the empty word it began."),
                CampIntro = BandItPlus.Localization.Get("bp_cultureprofileregistry_692", "The Pagan Cult's camp encircles a black stone overgrown with moss. Bones hang in the trees on red threads. Three small fires burn in a triangle. The cultists chant low — a single note that never fully stops."),
                HideoutDirections = BandItPlus.Localization.Get("bp_cultureprofileregistry_693", "East of Dunglanys the old road forgets itself in the oak-deep, and that is where you must leave it. Walk until you find the black stone wearing its green coat of moss - the trees lean toward it as if listening. From the stone, count the bones hung on red threads in the high branches; follow where the threads point. The half-buried bronze sickle in the leaf-mould marks the last turning. Our hollow lies past it, at {HIDEOUT_NAME}, where the three small fires burn always in their triangle.\n\nMy watchers are in the trees before you smell the smoke. Pelt-clad, clay-painted, quiet as the moss itself. They will hear the chant before you do and join it, low and unbroken, and that is how I know strangers walk under the oaks. Carry a sprig of rowan in your off-hand as you come; the watchers know the sign and will let your shoulders pass beneath them unpierced. Do not call out. The wood does not love a loud mouth.\n\nCome rowan-handed and the fire is yours, the copper cup is yours, and I will read the small bones for your road ahead. Come without the sign and the bones I read will be your own, traveler. The oaks are old and patient and the red threads always want more."),
                ScoutsLordsProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_694", "The bones speak of iron men in our oaks, traveler. Sit. Watch the smoke. The Battanian highborn ride down from Marunath and Dunglanys with their painted shields, calling our hollow a stain on their forest. Their thanes send hunting-parties dressed as outriders - I read the entrails of one such hunter last moon. He had eaten Vlandian bread before he came north. So the highlands sell us to the western crowns now. The grove remembers.\n\nThere is a lord, a Battanian named Caladog of clan Wolfskin, who has sworn a thread upon my name. Three of his cousins lie under our cairns. He rides with a banner of green and a hatred that smells of old milk. When he comes, the wind brings him first. The Vlandians cross our western ridges chasing tin-roads to the coast - their knights ride heavy and slow under the oak-shadow, blind as cattle. We let some pass. We take their stragglers. The Empire sends tax-clerks no further than the river, for the river drinks them.\n\nIf you carry a banner of any kingdom into this grove, traveler, the trees will read it before my watchers do. Strip your colors at the boundary stones. The bones do not care for crowns. Only for what bleeds, and what is owed, and what is woven. Carry that thread carefully."),
                ScoutsClanProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_695", "The bones speak of many threads in these woods, and I read them by firelight. Granny Hod's forest band shares my oaks - she remembers the old ways, the offerings left at the boundary stones, the names we do not say after dark. Her people leave a hare at my hollow each new moon and I leave the path open for them. We are not kin but we are not strangers. The Reavers of the cold north - Vargolf Iron-eyed - sent a rider three winters back asking for a charm against drowning. I gave him a knot of hair and bone. He has not asked again, which means it worked, or he is dead. The bones have not told me which.\n\nThe Highwaymen vex me. Their Reeve counts coin and laughs at the spirits, and a man who laughs at spirits draws them. I have seen his thread in the weave and it frays. Soon. The Stalkers of the southern fens I respect - they know the marsh-spirits, they leave the proper offerings - but their matriarch and I do not speak. We do not need to.\n\nMy scouts brought back whispers from the Pravend road - the Sky Raiders have been moving south, sniffing at our groves. If they come into my trees the oaks will remember them. The bones say blood by harvest. I have already cut the threads."),
                ScoutsCaravanProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_696", "The threads pull south, traveler. Sit. The bones say a Vlandian wool-train crosses the oak-hollow road from Dunglanys toward Pen Cannoc when the moon is half-eaten - eight guards, two wagons, a sergeant who drinks the cider the village wives leave at the stone cross because he believes it is luck. It is not luck. It is my cider. We pour it. He sleeps in the saddle by the third milestone, and his outriders never look up into the branches. They should look up into the branches.\n\nThe goods are wool and salted pork, but the third wagon, the small one wrapped in oilcloth, carries silver for the Battanian fian-bands the boyars keep on retainer. That wagon is what you want. The escort thins where the road bends past the rowan-stand because the horses will not pass the rowan at speed - the smell of the offerings frightens them - and the column splits in two. Strike the rear half. The front will ride a full mile before they hear the screaming, and by then the bones will have changed their pattern.\n\nThe Frost Reavers tried this road last autumn and Vargolf lost four men to a Battanian patrol because he does not read the omens. You will not lose four men. The crows have been quiet for nine days. That means the patrol is north. Ride now, while the thread is still red."),
                PactTeaseProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_697", "Hssss. You ask the bone-question, traveller. The oaks heard it before you spoke it. The roots are already drinking the weight of what you said. Sit. The fire is low and the grove is listening, and a question shaped like yours is not asked twice in one season without consequence.\n\nBlood is a thread, child. When I bleed for a name, I weave that name into the long braid that hangs in the hollow of the eldest oak - the braid my mother began and her mother before. Three names live on it now. My sister Aeronwen, who pulled me from the stag-pit when I was small. Old Maddoc the Tracker, who fed me through the bone-winter. A Stalker-witch from the high crags, whose threads crossed mine and would not part. You are not yet woven. You are not yet cut.\n\nBring me a deed the bones will speak of - a wolf-pelt taken in MY grove's name, a southern road choked with mist of your making, an enemy's skull set upon the boundary-stones - and the braid grows a fourth thread. Until then, my blood is the grove's and the grove's alone. Come again when the threads have something to read. The oaks are patient. So am I."),
                OathBrotherProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_698", "Then it is whispered, and the grove leans close to hear. Kneel. Open your hand. I take the small bone from my braid - the finger-bone of my own sister who walked into the bog the winter the lowlanders burned our shrine - and I press its end into the soft of your palm until a red bead rises. Mine bleeds too, see, beside the old scar where my mother's blade marked me at twelve. I knot a red thread around both our wrists and breathe on the knot three times. The bones in the bowl rattle without my hand. They have spoken. The braid accepts you. The grove witnesses.\n\nBrother, in our tongue, means hearth-blood. It means my pot is your pot, my dream is your dream, the things I see in the smoke I will tell you and not the others. When the old women sing the kin-names at the dark moon, yours sings now between mine and my dead sister's. You will not eat alone again. You will not die unnamed.\n\nGo back to the firelight, brother. The bog east of Dunglanys knows your name now. The bone-folk of three valleys will hear it by the next new moon. The Battanian lords who hunt us, the priests who curse us - they will learn it last, and they will learn it screaming. The thread is tied. Walk."),
                PactAnswerProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_699", "The bones heard you before I did. They rattled in the bowl this morning, all of them turned the same way, all of them pointing at the door - and then you walked through it with the red still wet on your sleeve. The deed before the word. The grove witnesses that order, traveler. A mouth that promises is just wind through teeth; a hand that has already cut is a thing the threads can be tied to. Sit. Let the braid feel the weight of what you carry.\n\nHear the terms, then, as the bones spell them out. From this moon my cult does not pray for you - we ride for you. When you raise your banner the wood-hidden come down out of the trees, knives wet, and they ride until your enemy is a story told over a fire. Not for coin. Not for grain. For the blood-debt you have entered into, the same debt I swore over my sister's grave when I cut her name into my arm twenty winters past. Your feud is the grove's feud now. In return you ride when WE call - and the call will come, traveler. The lowland priests have long memories.\n\nThe red thread is knotted. Your name lies coiled with mine in the bowl beneath the oldest oak, and the wind that moves through these woods carries both. When steel is drawn anywhere south of Dunglanys, the grove hears it. We are not kin of the hearth, you and I. We are kin of the cut. That bond does not loosen."),
                TroopLoanProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_700", "The bones say yes. I give you ten of my red-thread bearers for seven turnings of the moon - no more, no less, for the threads are knotted that long and no longer. My second is Hesska Twice-Burned, who reads the smoke as I read the bone. She walks at the front of them. She will not speak much to you, traveler, but she will not need to. The wood-hidden know her hand on their shoulder.\n\nHear my terms. If one of mine falls in your work, you bring me his red thread - cut from his wrist, no more is needed - and I will tie it to the rafters where the others can see. If he lives, you send him back with his thread still on him and the smell of your fire in his hair. My pelt-clad do not bleed for trinkets. Seven days. Count them on your knuckles.\n\nThe bones will be told who rode. The bones will be told who came home."),
                NamedTargetAcceptProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_701", "His name is {TARGET}. The grove has whispered it for nine summers, traveler, ever since his riders came through the hollow oaks at {HOME}'s northern edge and cut down my sister Iska where she knelt at the offering stone. They burned her red threads. They scattered the finger-bones I had braided for her wedding-walk. {TARGET} watched from his saddle and laughed, and the bones I cast that night spelled his name three times in the ash.\n\nHe travels the old salt-road every dark moon to count tribute, and his cousin the priest rides at his right hand. The cousin is afraid of crows, traveler - drive a flock at them on the gorge bend past Kalka ford and the column will scatter. {TARGET} keeps a thin guard at the rear. He thinks no one would dare strike a marked man on a holy road.\n\n{REWARD} denars sit in the burial jar beneath my cot, counted out for nine summers. The bones already saw you come. Ride, and the braid will know when his breath stops."),
                NamedTargetReason = BandItPlus.Localization.Get("bp_cultureprofileregistry_702", "{CHIEF} has cast the bones over {TARGET} of {HOME}, and the throw came up red on every side. The witch-mother does not speak the grievance plainly — she circles it in the way of grove-folk, in the way of those who count years by braid-knots and not by harvests. Seven summers past, a daughter of the cult was taken from the alder-grove on a grey dawn and hung from a roadside oak with her sacred braid cut and burnt at the root, and the order came down the line from {TARGET}'s hall. The Bone-Sayer kept the burnt braid in a clay jar; the grove kept the rest. A heavy purse waits, and a red thread already cut to the length of {TARGET}'s throat. The grove is owed a death. The contract is open."),
                NamedTargetComplete = BandItPlus.Localization.Get("bp_cultureprofileregistry_703", "{TARGET} is dead. Crone Vael has been told, and the grove has been told, and the bones in the chief's lap have been told. The red thread that bore the noble's name - knotted nine winters ago for Little Mireh, the apprentice-girl drowned in the stocks at {HOME} - has been cut from the braid and laid in the ash-pit. {REWARD} denars sit at the Bone-Sayer's fire, counted out in coppers and silvers, and a fresh notch has been carved beside the child's old finger-bone. The grove witnessed. The braid is shorter by one name, and Vael says the wind moves cleaner through it tonight."),
                NamedTargetOtherCauseProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_704", "A bone-runner came to the cult-camp at dusk with mud on his shins and the news already half-chewed: {TARGET} had been cut down on a winter road by some rival lord's outriders, robbed and left for the crows before {CHIEF} could ever set her hook. The Bone-Sayer received the word in the smoke of the apprentice-shrine, where Mireh's red-thread braid still hangs above the clay jar of burnt cord. She turned the braid once in her fingers, whispering that the drowning-girl's debt was paid, yes, but not by the hand she had chosen. The grudge is closed; the bond is cooler. She counted out {REDUCED_REWARD} denars of thin quarter-pay into the player's palm and set the tally one small notch firmer, no warmer."),
                RaidVillageAcceptProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_705", "\"The bones name a village. {VILLAGE}, they whisper, on the lowland edge where the Battanian woods thin to tithe-fields. Lord {LORD} holds it, and his hand is the same hand that signed the warrant three summers past - the warrant that loosed the inquisitors of his lowland priests upon Aelwyn's apprentice-grove. They burned the saplings. They burned the girls who tended them. The ash of that grove is still in my hair, child. The bones have not forgotten.\n\n{VILLAGE} tithes oil and grain to those same priests on the dark moon. The wagons are sealed three nights before, and {LORD}'s outriders escort them to the keep on the dark moon itself - so strike between, when the casks sit waiting and the riders are gone. Take the oil. Burn the grain. The smallfolk... let them run. They are not the ones who lit the pyre. The priests are.\n\n{REWARD} denars when the smoke rises and the oil-jars are spilled. The bog drinks the rest. Go now - the bones grow restless.\""),
                RaidVillageReason = BandItPlus.Localization.Get("bp_cultureprofileregistry_706", "{CHIEF} has named {VILLAGE}, the oil-and-grain tributary of Lord {LORD}'s Battanian fief, as the hearth whose ashes will answer for the apprentice-grove of Aelwyn, burned three summers past by lowland priests this fief still tithes and shelters. The Bone-Sayer's bowl has shown the same omen at every cold moon since: charred saplings, a girl's bone-comb buried under hearthstones, smoke that does not rise. The villagers feed the inquisitors who fed the pyre. Their oil greases the censers; their grain feeds the chant. The Crone offers {REWARD} from the grove-hoard and the closing of a debt the roots themselves have whispered. The contract is bone-marked. The grove remembers."),
                RaidVillageComplete = BandItPlus.Localization.Get("bp_cultureprofileregistry_707", "{VILLAGE} smokes black, and {CHIEF} has read the bones of it. The tithe-village of Lord {LORD} - whose lowland priests put the apprentice-grove of Aelwyn to the torch three summers past - lies open-throated under the dawn, its oil-jars cracked, its grain-cribs ash, the chant-wagons that bore tribute to the burning-priests now silent in the cart-ruts. {REWARD} denars sit counted at the bone-altar where the Crone whispers tally to the dead. One debt of Aelwyn has been answered. The smoke goes up to her, and the grove remembers. The bones know one name fewer to weep."),
                RaidVillageOtherCauseProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_708", "Word came whispering down the bone-wind at moonset: {VILLAGE} stood ash and silence, its tithe-barns split, its oil-jars cracked - but the hand that struck was not the wanderer's. A rival lord's column had ridden through on a quarrel of borders, and the priests' own grain had gone up in smoke without the wanderer's torch to light it. {CHIEF} listened with her ear-bones cupped, and the apprentice-grove of Aelwyn stirred no answer in her marrow. The three-summer debt was paid - by another's blade. The smoke rose true, the ash fell right, but the bones had not been thrown by the wanderer's casting. She counted out {REDUCED_REWARD} denars from the rattle-pouch, thin coin for a thin reckoning, and named the bond cold-warm, no closer than a fox at the treeline."),
                // 2026-05-25 rewrite: LITURGICAL / RESPONSORIAL shape. A four-line
                // verse-fragment serves as structural refrain — each line preludes
                // a paragraph of observation, so the chant and the prose interleave
                // antiphonally. Player almost-knows the words; ends with cultists
                // lowering their chant as for a guest. No companion-quote pivot, no
                // "These were not X" template, no "you watched", no "No, not
                // tonight" refusal.
                HideoutCinemaIntro = BandItPlus.Localization.Get("bp_cultureprofileregistry_709", @"    First the fire is named.
    Then the bone is named.
    Then the breath is named.
    The names are not said in daylight.

You hear it from a quarter-mile out — a low single note carried through the wet black trees, held longer than any throat should be able to hold a note, and then taken up unbroken by another throat, and another, so that the sound does not end. A river of voices, all in one place, all on one tone.

    First the fire is named.

You stop your horse. Smoke moves between the trunks — pale, deliberate, climbing.

    Then the bone is named.

Bones hang in the trees on red thread. Small ones — finger-bones, bird-bones, the jawbone of a fox. Where the smoke crosses them they turn, and the turning makes a dry knocking sound, and the knocking is part of the music.

    Then the breath is named.

Your horse will not have its head. You let it stand. There is a clearing ahead through the black trunks where three small fires burn in a triangle, and figures move between them slow, and at the centre stands a black stone furred with moss, and the chant comes from the dark between the fires, never breaking, never quite the same note from one breath to the next but always returning to it.

    The names are not said in daylight.

You did not know the rest of the verse and yet you find that you do know it, the way a person knows the next line of a song heard once in childhood, the way a hand knows the shape of a thing it has never been told. You are leaning forward in the saddle. You did not choose to lean.

The chant takes a long held breath together.

It releases together.

In the silence that follows, an old woman at the nearest fire raises her head and looks straight at you through the trees. She has been waiting for you to arrive at this particular point in the verse. She has been waiting some time.

She lifts one hand. The chant resumes around her, lower now, courteous, the way a room lowers its voices for a guest.

You ride forward."),
                ServiceLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_710", "Consult the Oracle of bones."),
                ServiceFlavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_711", "Crone Vael casts knucklebones onto the black stone. They land in a pattern. She studies them for a long time."),
                Kind = ServiceKind.Oracle,
                BribeAmount = 333,
                WhyNotKingdom = BandItPlus.Localization.Get("bp_cultureprofileregistry_712", "\"A king's god is paper and crowns. Our gods drink blood and grant courage. The bargain is clearer.\""),
                Religion = BandItPlus.Localization.Get("bp_cultureprofileregistry_713", "\"The Old Ones. Names not to be said in daylight. The grove remembers them.\""),
                ThreatResponse = BandItPlus.Localization.Get("bp_cultureprofileregistry_714", "The mask turns toward you. The mask does not blink. \"The bones already showed me how you die. It is not by my hand. But it is soon.\""),
                Pleasantry = BandItPlus.Localization.Get("bp_cultureprofileregistry_715", "Crone Vael's voice does not change. \"The grove is older than you. It will accept your praise or your bones. Either is welcome.\""),
                DrinkFlavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_716", "The cultists pass around a cup of dark wine, thick with herbs. \"Drink. The Old Ones approve of those who drink. The Old Ones forget those who refuse.\""),
                RestFlavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_717", "You sleep at the edge of the grove, the chanting never quite stopping. Strange dreams. Your party wakes uneasy, but rested."),
                ExtraServices = new[] {
                    new CultureSubService { Label = BandItPlus.Localization.Get("bp_cultureprofileregistry_718", "Trade with the bone-carver."), Flavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_719", "A silent man at a stump carves with steady hands — combs, charms, knife-handles, all from old bone. \"Cheap because the dead don't charge. Useful because the dead remember.\""), Kind = ServiceKind.Hunter },
                    new CultureSubService { Label = BandItPlus.Localization.Get("bp_cultureprofileregistry_720", "Receive the grove-healer's blessing. (100 denars)"), Flavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_721", "A young initiate paints a sigil on each soldier's arm with red ochre. The chanting rises to match. \"You walk with the grove for a moon. The grove walks with you.\" Morale rises."), Kind = ServiceKind.VeteranHall, GoldCost = 100, MoraleGain = 5 },
                    new CultureSubService { Label = BandItPlus.Localization.Get("bp_cultureprofileregistry_722", "Take part in the old rite. (50 denars)"), Flavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_723", "A simple ceremony. Crone Vael cuts your palm. A drop of blood on the stone. The chant pauses, then resumes. You feel the grove's regard."), Kind = ServiceKind.Oracle, GoldCost = 50 },
                },
                Rumors = new[] {
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_724", "\"The temple at Marunath is hunting us. Their inquisitors pay informers.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_725", "\"A young noblewoman comes to our grove in secret to leave offerings.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_726", "\"The old gods are returning. The bones say so. We don't argue with the bones.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_727", "\"A heretic priest fled imperial justice and joined our circle.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_728", "\"There's a buried shrine in the forest — older than the empire. We dug it up.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_729", "\"The grove-fires never go out. They've been burning a hundred years.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_730", "\"A relic of the old kings is hidden under the black stone.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_731", "\"Imperial soldiers tried to burn our grove three winters back. Two came out alive. Both stayed.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_732", "\"A rival cult worships the new gods in twisted form.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_733", "\"The bone-sayer dreams the future every full moon.\""),
                },
                OracleLines = new[] {
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_734", "\"You will find what you seek, but the cost will surprise you.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_735", "\"A friend will betray you before the next full moon.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_736", "\"Death stands at your right shoulder. Walk left.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_737", "\"The kingdom you serve will fall.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_738", "\"There is gold in stone in the eastern hills. The stone watches.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_739", "\"A child not yet born will write your name in a song.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_740", "\"The path you walk forks soon. Both ends are the same. The middle is not.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_741", "\"Trust the woman in red. Do not trust the man in green.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_742", "\"A king will die in winter.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_743", "\"The river you crossed yesterday was not a river.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_744", "\"You are owed a debt by someone you have forgotten.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_745", "\"Do not draw your blade in the city of three towers.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_746", "\"A storm is coming. The storm has your name in it.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_747", "\"The horse you ride was never meant for war.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_748", "\"The greatest treasure of your life is a thing you already own.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_749", "\"A wound you took years ago will reopen.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_750", "\"The empire is dying. So is the kingdom.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_751", "\"Beware the merchant who calls you brother on first meeting.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_752", "\"The bones say: bury what you kill.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_753", "\"Three offers of love will come to you. Refuse the first two.\""),
                },
                TrustQuestTier1Pool = new[] {
                    new TrustQuest {
                        ItemIds = new[] { "fish" }, Counts = new[] { 20 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_754", "\"Twenty fish. The old gods feast at our spring rite. Bring it, and the gods will know your name.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_755", "The chief blesses each bundle. \"The old ones are pleased. You have a place at the firepit.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_756", "20 fish"),
                    },
                    new TrustQuest {
                        ItemIds = new[] { "meat" }, Counts = new[] { 15 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_757", "\"Fifteen weight of meat. Blood-rite. The fen-mother takes flesh for spring and gives green growth in return.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_758", "The chief lays the meat on a stone altar. \"The fen-mother smiles tonight. Her children welcome you.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_759", "15 meat"),
                    },
                    new TrustQuest {
                        ItemIds = new[] { "beer" }, Counts = new[] { 20 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_760", "\"Twenty beer for the libation. The thunder-spirit drinks first, then the men. Bring it.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_761", "The chief pours a horn into the fire — flames leap green. \"The spirit drinks. The cult opens to you.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_762", "20 beer"),
                    },
                },
                TrustQuestTier2Pool = new[] {
                    new TrustQuest {
                        ItemIds = new[] { "fish", "wine" }, Counts = new[] { 30, 10 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_763", "\"Thirty fish and ten wine. High feast. The old ones eat and drink — bring both.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_764", "The cult chants as the offering is accepted. \"The gods are pleased. Even the oracle will speak with you.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_765", "30 fish + 10 wine"),
                    },
                    new TrustQuest {
                        ItemIds = new[] { "meat", "beer" }, Counts = new[] { 25, 20 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_766", "\"Twenty-five meat and twenty beer. The midsummer-flesh feast. The fen-mother eats first — bring both.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_767", "Drum-rhythm rises from the inner circle. \"The fen-mother's children embrace you. The cult is yours.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_768", "25 meat + 20 beer"),
                    },
                    new TrustQuest {
                        ItemIds = new[] { "fish", "oil" }, Counts = new[] { 40, 15 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_769", "\"Forty fish and fifteen oil. The lamp-fast night. We burn through dawn for the dark mother — bring both.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_770", "The cult lights the dawn-lamps in long rows. \"The dark mother sees you in firelight. Speak to the oracle.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_771", "40 fish + 15 oil"),
                    },
                },
                TrustQuestTier3Pool = new[] {
                    new TrustQuest {
                        ItemIds = new[] { "fish", "meat", "wine", "velvet" }, Counts = new[] { 50, 30, 20, 10 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_772", "\"Fifty fish, thirty meat, twenty wine, ten silk-cloth for the altar drape. The full rite. Once a generation. Only one who walks with the gods can bring this.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_773", "The chief draws a sigil on your forehead in ash. \"You are kin to the fen-mother now. The cult bleeds for you.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_774", "50 fish + 30 meat + 20 wine + 10 velvet"),
                    },
                    new TrustQuest {
                        ItemIds = new[] { "fish", "wine" }, Counts = new[] { 100, 50 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_775", "\"A hundred fish and fifty wine. The sky-feast. The thunder-one drinks deep before he wakes the storms. Bring both.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_776", "Lightning cracks somewhere distant. The chief smiles. \"He is awake. The cult rides his storm with you.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_777", "100 fish + 50 wine"),
                    },
                },
                // Wave 5 (Chief Recruitment) alliance content
                AllianceCh1TaskBrief = BandItPlus.Localization.Get("bp_cultureprofileregistry_778", "Bring a captured noble of the culture-region to the old stones — they must reach the altar alive and bound."),
                AllianceCh1Pattern = AllianceCh1Pattern.KillNamedLord,
                AllianceCh1TargetSeedHint = "culture_region_minor_noble_random",
                AllianceCh3RitualText = BandItPlus.Localization.Get("bp_cultureprofileregistry_779", "The Crone Vael, the Bone-Sayer accepts your oath; the rite is sealed at the cult altar in cast bones, your fate read in the marrow spilled."),
                AllianceCh3GiftItemId = "reading_bones_set",
                AllianceBrokenText = BandItPlus.Localization.Get("bp_cultureprofileregistry_780", "The Crone does not look at you. She gathers her bones, sweeps them once, lets them fall. \"The pattern is closed. Walk past the stones.\""),
            }},
            { "looters", new CultureProfile {
                ChiefName = BandItPlus.Localization.Get("bp_cultureprofileregistry_781", "Boll the Eldest"),
                Signature = new SignatureQuestSpec
                {
                    Title = BandItPlus.Localization.Get("bp_cultureprofileregistry_782", "The Ditch-Folk's Coin"),
                    HeraldLine = BandItPlus.Localization.Get("bp_cultureprofileregistry_783", "You. Boll wants you. Taxmen went down the ditch-road and shook out the families what feed us. Old man's been sat staring at the fire since. He don't stare like that for nothing. Go on."),
                    OfferProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_784", "Sit, friend. Old Boll will keep this short. There's a wagon on the road — the lord's levy, coin squeezed out of the ditch-families between here and the burnt mill. You know them, maybe. I grew up in those ditches. Those families feed my people scraps when there's scraps, and news when there's not. Now their coin rides south under guard, with a collector on top who yawned while he took it. Take it back, friend. All of it. Don't bargain with the man — Boll has watched collectors his whole life, and they only count. Make the counting stop."),
                    AcceptProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_785", "Good. The wagon's slow — coin is heavy, friend, heavier than grain. The escort will fight for it; they're paid to. Mind yourself. And count it before you leave the road. Collectors skim. It's what they're for."),
                    DeclineNudge = BandItPlus.Localization.Get("bp_cultureprofileregistry_786", "As you like, friend. The road doesn't hurry and neither does old Boll. But the ditch-families gave their last coin, and winter doesn't take promises. Ask me again while the wagon's still close."),
                    BusyLine = BandItPlus.Localization.Get("bp_cultureprofileregistry_787", "The wagon's still rolling, friend. Every mile it makes is a mile of coin the ditches won't see again. Go slow if you must. Just go."),
                    TargetPartyName = BandItPlus.Localization.Get("bp_cultureprofileregistry_788", "Lord's Levy Wagon"),
                    CaptainName = BandItPlus.Localization.Get("bp_cultureprofileregistry_789", "Levy Collector Phanes"),
                    JournalObjectiveText = BandItPlus.Localization.Get("bp_cultureprofileregistry_790", "Find the Lord's Levy Wagon on the roads near Boll's camp, defeat its escort, and recover the coin taken from the roadside families."),
                    JournalReturnText = BandItPlus.Localization.Get("bp_cultureprofileregistry_791", "Return to Boll the Eldest and tell him the levy coin has been taken back."),
                    ConfrontIntro = BandItPlus.Localization.Get("bp_cultureprofileregistry_792", "Off the road. This is his lordship's quarter-levy — counted, sealed, and duller than you can imagine. Nine years I've hauled boxes like this one. Rob us or move, but do decide. I'd like to be bored somewhere warm by dark."),
                    Choices = new[]
                    {
                        new SignatureChoice { Label = BandItPlus.Localization.Get("bp_cultureprofileregistry_793", "Hand the coin back, or bleed for it."), Outcome = SignatureOutcome.Battle, ResultProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_794", "Back? Coin doesn't go back. It goes up — ditch to lord, lord to crown. That's the whole of the world, and you want it reversed on a road. Escort, level. Kill them quickly, I'm losing the light.") },
                    },
                    ClosingProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_795", "The coin went back, friend. I walked it myself, ditch to ditch, and put it in their hands. No speeches. You don't make a speech at people who are hungry — I remember being hungry, and a speech is just a man keeping bread in his mouth longer. They fed us before they had to. Now they eat. Sit. There's stew tonight, with something in it for once. You did that."),
                    ClosingProseOtherCause = BandItPlus.Localization.Get("bp_cultureprofileregistry_796", "Some other band got to the wagon first, friend. Drank half the coin in two nights — I heard it from a tinker who watched them do it. The rest is already trickling into the ditches, the way loose coin does. It finds the poor going down the same as it found the lord going up. So. Half a job done by nobody we know. Half thanks, half pay. Sit anyway. The fire's the same price."),
                    RewardGold = 900,
                    RewardRelation = 10,
                    BattleLootGold = 400,
                },
                ChiefTitle = BandItPlus.Localization.Get("bp_cultureprofileregistry_797", "Outcast-Father"),
                ChiefBackstory = BandItPlus.Localization.Get("bp_cultureprofileregistry_798", "Boll lived in the same Imperial peasant village his whole life — eighty-two years according to the priest's tally, though Boll himself stopped counting at sixty. He raised four sons there, buried two of them at the village shrine, and saw the third leave for the Imperial legions never to return. The village was burned in the autumn of the third year of the imperial succession war — not by enemies but by the local lord's tax-collectors, who decided to make an example of a community that could not pay its levy. Boll was buried under his own collapsed roof when the soldiers came; they assumed he had burned alive and moved on without checking. He dug himself out the next morning with a shovel he had been using for forty years, and walked through the ash looking for survivors. There were none; or rather, there were only the others who had been buried, who came up later from cellars and hayricks. Boll is the oldest peasant left in the region, and the Looters formed around him by accident — fifty starving survivors of fifteen burned villages, each looking for someone who knew where to dig. He leads the Looters because no one younger is left who remembers when there was anything else."),
                ClanHistory = BandItPlus.Localization.Get("bp_cultureprofileregistry_799", "The Starving Outcasts are not a band in the way the others are bands. They have no founding-feast, no oath-fire, no chief-line; Boll holds them together because he is eighty-two and has not yet forgotten what the lords have stopped mentioning. The column began the day Boll's village burned in the second imperial reorganization, when the conscription quotas tripled and the granary-tax was renewed in the same season; the survivors walked east, and walked, and walked, and never quite stopped. They have grown by accretion since — every village burned, every harvest seized, every conscript-train that lost half its men to desertion in the same week added another handful to the wandering column. The Outcasts have no signature raid because they cannot raid: they ambush stragglers, dig in granary-pits at night, gnaw bark in winter, and bury their dead in rows beside whatever road they happened to be on. Every kingdom counts them as bandits and none has taken a serious patrol against them in living memory; the recognition would require an admission about why so many peasant villages have burned in the same generation."),
                ChiefGreeting = BandItPlus.Localization.Get("bp_cultureprofileregistry_800", "A scrawny man peers up at you from beside a thin fire. His hands shake. The knife in them — chipped, half-rusted — shakes too. He stares at your armor a long moment, like a man trying to remember what hope ever felt like. \"You... you look armored, friend. Big armored. Old Boll doesn't want trouble. Just bread, and to be left alive at the end of it. Got any to spare a tired man?\""),
                ChiefGreetingTolerated = BandItPlus.Localization.Get("bp_cultureprofileregistry_801", "Boll's hands shake less when he sees you now. He still doesn't stand, but the chipped knife stays in its sheath, and a place at the thin fire is made without him asking the others. \"You... you came back. Most don't. Old Boll thanks you for the bread last time, traveler. Sit. Not much to give a friend, but what we've got, you've got.\""),
                ChiefLoyaltySpeech = BandItPlus.Localization.Get("bp_cultureprofileregistry_802", "Boll has the name, friend. Name's nothing here — old Boll has heard a thousand and buried more. What we trade in is bread and what's done for it. There's a thing my men want from a strong walker like you. Help us, and I'll know your name's a friend's name. Won't be much trade after — but it'll be honest."),
                CampIntro = BandItPlus.Localization.Get("bp_cultureprofileregistry_803", "Hardly a camp — just a wind-break of branches and a smoldering fire. A handful of skinny men in stolen rags, eyes hollow."),
                HideoutDirections = BandItPlus.Localization.Get("bp_cultureprofileregistry_804", "You want the road to us? There is no road. Walk out past the last village that still has a name, keep walking until the goat-tracks give up and the scrub turns to rubble. When you see a wind-break of branches piled crooked against the stones, and an ash-pit still smoking from last night - you are close. There is a hide stretched to dry on a frame of bent sticks. That is our flag. Our hold lies at {HIDEOUT_NAME}, if you can call it a hold.\n\nMy boys will see you before you see them. They are skinny, they are hungry, they have nothing to lose and they know every gully for a mile. Walk slow. Keep your hands where the light catches them. If you have bread in your saddlebag, hold a piece up high - that is the only sign that has ever meant peace out here. Anything else and they will think you are tax-men or worse.\n\nCome wrong and they will swarm you for your boots and leave the rest for the crows. Come right and we will share what we have, which is not much - a place by the fire that wont catch, a cracked pot of something thin, and the company of men the world forgot. That is all I can offer you, traveler. It is more than anyone else gave us."),
                ScoutsLordsProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_805", "Lords. Lords don't ride out here, friend. Not for us. We're not worth the iron on their boots. The big banners - the Empire, the Sturgians, the Vlandians - they pass each other on the high roads and they don't even look down into the rubble where we sleep. That's the worst of it. To be hated would be something. To be hunted would be something. We are only stepped over.\n\nBut their levies come. Oh, their levies come. When some boyar or some petty count needs to count heads for his muster, he sends his sergeants out to sweep the ditches and the burnt villages, and they take whoever can stand. Two of mine taken last moon by a column out of an Imperial garrison - I don't know which one, they all wear the same purple to my eyes. They were dragged off to die in someone else's war. We did not get them back. We never get them back.\n\nThe tax-riders are the other ones. Vlandian usually, in this stretch. They ride in pairs with crossbows and they shoot at us for sport on their way home from the real villages. I tell my people - hide, do not throw stones, hide. We have no quarrel the lords would honor. We only have hunger, and hunger does not make a feud. It only makes a grave."),
                ScoutsClanProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_806", "Clans. Yes. Clans. We are not a clan. We are what is left when clans are done with you. But I know names. I know who throws scraps and who throws stones. Granny Hod's forest band - the old woman in the green dark - she lets my people pass if we bring her a knife or a tooth or a child that can still work. I send what I can. She has not killed us yet. That is a kindness in this country.\n\nSkarvac's pass-lords up in the rocks, they hunt us for sport when the snow comes. They wear our skins on their saddles. I do not speak that name twice in a night. And the Reavers - Vargolf's Reavers - one of his outriders rode through our camp last spring, took two of my boys for his column, left a copper coin in the ash. A copper coin. Like we were paid. Like we agreed.\n\nThe Stalkers in the fens, the Mireborn ones, they trade with us sometimes. Rot-meat for arrowheads. Fair, by the standards of the road. The Highwaymen will not look at us. We are below their counting. That is fine. Being unseen is being alive. The bandit-tongue says the Sky Raiders have gone quiet in the high country this moon. Quiet is bad. Quiet means someone is sharpening. Watch the ridgelines, friend. Watch them."),
                ScoutsCaravanProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_807", "Caravans. Yes. We watch them. From the rubble. From the ditches. The big ones do not stop here - nothing to stop for, no inn, no well, no walls. That is why they come slow through the scrub. They feel safe. Twelve guards, sometimes fifteen, one wagon of grain and one of cheap wool bound for the empire towns. We do not take them. We cannot. My boys have sticks and hunger, traveler, not swords.\n\nBut. Listen. There is a smaller one. Two wagons. Four guards. A fat merchant from Pravend who cuts across the dead country to skip the toll-road. He comes when the moon is new - dark roads, no witnesses, that is his thinking. Three nights from now, maybe four. He carries salt and iron nails. Not silver. Salt. To us that is silver. The guards drink at the last village before they cross. By the second hill they are slow. By the rubble-field they are blind.\n\nIf you take him, leave us the salt. Take the nails, take the wagon, take the merchant's purse. Just the salt. My children have not tasted salt since the snow broke. The Highwaymen up the Reeve's road would not bother with him - too small, too poor. That is why he lives. That is why he is yours. Ride at dusk. Come from the south. He never looks south because there is nothing south but us, and he does not believe in us."),
                PactTeaseProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_808", "You ask the hunger-question, friend. The road-question. I hear it. I have heard it before, in dry mouths around dry fires, and I know what it costs the asking. Sit. Eat the half I have. We will weigh it together, because a man with nothing weighs careful, or he loses what little is left.\n\nWhat I would give you is not iron and it is not gold. I have neither. What I would give is the last bite, the last watch, the last breath kept back from the cold for your sake. I have given it before. To my woman, who is in the ground. To the boy Anse, who walked out one winter and did not walk back. To old Crook-Mouth, who shared his cloak the night the south burned us out. That is my roll. It is a short roll and a hungry one.\n\nBring me something the road remembers. A wagon turned aside from a village that had nothing left to lose. A pursuer cold in a ditch. A winter survived together. Do that, and the cloak becomes ours. Until then the fire is shared, but the bone is still mine. Ask me again when we have buried someone side by side."),
                OathBrotherProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_809", "Then... then say it slow again so the rocks hear. Brother. Sit. Sit on the rag where I sit. There is no horn here, no mead, no beam to cut your name into - there is a tin cup with rain in it and a knife that has cut more bread than throats, and that is what we have. Drink. Drink it down. Now the knife. My palm already knows this work - see the old white line, that is from a boy who called me father in a ditch outside Pravend and bled out before sunrise - I gave him my cut then and I give you my cut now. Press. Press hard. The dirt drinks it. The dirt remembers what beams forget.\n\nBrother. Brother means you eat before I eat. Brother means the last bite is split, not taken. Brother means when the watch is long and my eyes go, yours stay open, and when yours go, mine stay. We have no cousins, you and I - we have the ones still breathing at this fire, and now they are yours too. The wretches call me Outcast-Father. They will call you Outcast-Son. That is the only roll we keep.\n\nFrom this rubble forward you are my blood. The road knows. The crows over Zeonica know. The lords who hanged my first boy will know when they see your face beside mine. Brother - we have nothing, and now we have nothing together, and that is everything."),
                PactAnswerProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_810", "Then I have heard it. You did not come with a speech. You came with the smell of someone else's blood still on you, and the word after - almost forgot to say it. That is the order an old man trusts. Boll has heard pretty oaths from boys with clean knives. They did not last the winter. Yours came knife-first. Sit. Let the iron in what you did go cold before we speak the rest.\n\nFrom this watch onward, the scraps that answer to me answer to your banner when you raise it. Not as hired hands - we have nothing to be hired for. As blood-allies in the only currency we still hold, which is the next bite and the last watch. My men will share your road. Your enemies become ours, and we have no lords above us to call us back. In return I ask only this - when the levies come for us, as they always come, you raise that banner and you ride. That is the trade. Bread for bread. Wound for wound.\n\nThe wind carries it now. No hall to hear it, no priest to seal it - only the scrub and the rubble, and that is enough for men like us. The road is long. The south is loud. We are bound in the work, traveler, and the work does not forgive turning back. Ride hard."),
                TroopLoanProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_811", "Done. Ten of the wretches - what is left of us that can still lift a blade - for seven days. I will pick them at dusk, the ones whose cough is quiet enough to walk a road. My second is Old Pell, who lost his name in a winter I will not speak of. He is half a man but worth two of the boys. He rides with you, and he counts the days for me.\n\nHear my terms, traveler. If one of the wretches falls in your work, you scrape his bones into the dirt and you SAY HIS NAME aloud before you leave him. That is all I ask. If he lives, you put bread in his mouth before you put bread in your own. My boys do not break shield for coin - we have no coin, we have no shield. They break because I told them to follow. Do not waste them on dogs and tax-men. Seven days. Count them slow.\n\nWhen the seven are spent, send what comes back to the hollow. I will be sitting where I sit. I will know their faces, even the ones the crows have taken."),
                NamedTargetAcceptProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_812", "His name is {TARGET}. He sits warm under {HOME} with his cup full, and seven winters past he hanged my boy Calden from the crossroad oak at Greymire for stealing two loaves and a wheel of cheese. Two loaves. My boy was nine. {TARGET} watched from his horse and would not cut him down for the dogs. I walked the road back to my woman with the rope still around my son's neck because his lords would not let me take it off. She did not speak again. She died in the spring.\n\nHe rides slow. He is fat now, traveler, fat on the bread he hanged my boy for. Four lances at his side and a steward who keeps the ledgers. The steward drinks alone at the Greymire crossing on market days and he owes a Khuzait moneylender more than his life. Press him soft and he will draw you a map. {TARGET} hunts at first light - he rides ahead of his guard when the hounds run. Take him then.\n\n{REWARD} denars when the word comes, traveler. It will not buy back what the rope took, but the road is owed a body, and his is the one we have been waiting for. The snow keeps the rest. Ride."),
                NamedTargetReason = BandItPlus.Localization.Get("bp_cultureprofileregistry_813", "{CHIEF} has named {TARGET} of {HOME} as the lord whose hand signed the grain-tax that emptied his village the winter of the long cold. The grudge is small and exact - a son of nine summers named Tomas, hanged at the crossroad-oak outside Pravend for stealing a half-loaf from a wagon, the rope cut on the second day so the dogs could finish what the lords began. {CHIEF} carries the boy's wooden spoon in a rag at his belt, the only thing the soldiers left. He has begged on seven roads and counted every coin against this one name. The Eldest offers what coppers his band has scraped and the closing of a wound that does not heal. The road is long. The hunger remembers. The contract is open."),
                NamedTargetComplete = BandItPlus.Localization.Get("bp_cultureprofileregistry_814", "{TARGET} is dead, and {CHIEF} has been told. The old one sat a long time before the answer settled in him. Tomas, who was twelve when they hung him at the Karuya crossroad three winters back for stealing a sack of barley, has had a name spoken back into the world for him. {REWARD} denars are counted into the rag at {CHIEF}'s hip, and his hand shakes around them less than it did. The boy is not back. The bread is not back. But the rope has been answered, and the road keeps the rest. The hollow in him is one name quieter."),
                NamedTargetOtherCauseProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_815", "Word reached {CHIEF} by way of a fish-monger off the south track: {TARGET} had been pulled down in a roadside scrap by some lord's outriders, bled out in a ditch before the crows even came. The old man took the news standing, one hand at the rag-wrapped spoon hanging from his belt - the spoon Tomas had carved, the spoon they hanged the boy beside at Karuya crossroad for a half-loaf of bread. He nodded slow. The grudge was closed. The throat was cut, only not by the right hand. He counted out {REDUCED_REWARD} denars - quarter-pay, thin coin for a thin closing - and pushed it across without meeting the eye. The bond sits a notch firmer now, but cooler, the way ash sits firmer than fire."),
                RaidVillageAcceptProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_816", "\"There is a village. {VILLAGE}. Lord {LORD} holds it now, but his father held it the winter my woman walked there with three of my boys, begging a crust. They turned her at the gate. Set the dogs on her. Three sons. Three. The snow took them on the road back, one by one, smallest first. I dug them with my hands. {LORD} was a child in that hall, eating warm bread, watching through the shutter. He saw. He saw and said nothing.\n\nThe barns are full now. They built a wooden palisade this summer, fat with the harvest that should have fed my boys. The lord's riders go to the Empire fair on the new moon, gone four nights. Strike the second night. Burn the granaries first, then the palisade, then the hall. The smallfolk - the ones who set the dogs - leave none. My boys had no mercy in the snow.\n\n{REWARD} denars when the smoke climbs. Keep the grain, keep the cloth, keep the dogs if any still bark. The snow keeps the rest. The snow remembers.\""),
                RaidVillageReason = BandItPlus.Localization.Get("bp_cultureprofileregistry_817", "{CHIEF} speaks the name {VILLAGE} the way a man chews a stone he cannot spit out. In the famine-winter his woman and three of his boys came to that gate begging bread, and the folk there set the dogs on them and shut the door, and the snow took what the dogs did not. {VILLAGE} answers to {LORD} now, and its barns are full, and they have raised a new wooden palisade as if walls could keep the dead out. {CHIEF} has no walls. He has only this contract, and the coin to pay it: {REWARD} when the thatch is ash."),
                RaidVillageComplete = BandItPlus.Localization.Get("bp_cultureprofileregistry_818", "{VILLAGE} burned to the ground, and {CHIEF} stood in the ash with his hollow eyes and counted the timbers of the new palisade as they cracked. The barns went up like dry kindling. The dogs ran, then did not run. He spoke the names of his woman and his three boys aloud, one for each roof that fell, and the snow-winter debt was paid in smoke. {LORD} brought the cut back to the camp. {CHIEF} took the {REWARD} without looking at it, and said only that the village had turned them away once, and would not turn anyone away again."),
                RaidVillageOtherCauseProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_819", "Word crawled into the camp like a sick dog. {VILLAGE} was already ash when {LORD}'s riders got there. Other hands. Other torches. The new wooden palisade the village had been so proud of, the one raised the same season they set the dogs on a starving woman and three small boys, was charcoal sticks in the snow-melt. The full barns were cinders. {CHIEF} listened without moving. Boll the Eldest only said the famine-winter took its own time, and someone else's fire was still fire. He looked through the messenger, not at him, and counted out {REDUCED_REWARD} with hands that did not shake. He said the debt was paid. He did not say by whom."),
                // 2026-05-25 rewrite: FLAT / BANAL shape. Deliberately stripped
                // prose — short declarative sentences, no metaphor, the opposite
                // of cinematic. Opens with a banal date anchor ("It was a Wednesday").
                // Boll isn't introduced with reverence; he's identified after the
                // fact ("It was Boll. There was no way to know that yet."). Ends
                // with "You got off the horse." — undramatic, practical. No
                // companion-quote, no negation list, no "you watched", no "No, not
                // tonight."
                HideoutCinemaIntro = BandItPlus.Localization.Get("bp_cultureprofileregistry_820", @"It was a Wednesday.

It was a Wednesday in autumn, late, and it had rained earlier and stopped, and the road was the kind of road no one bothers to name. There were four of them around the fire. Two were ill. The fire was small. They had no horses. They had no tents. The wind-break was a fallen elm with brush piled against it. There was nothing else.

You stopped your horse about ten paces out. You watched them for a minute. None of them moved.

One of them was eating bread. He stopped when he heard you. He kept the bread.

You said nothing.

After a while a man on the far side of the fire looked up. He did not stand. He said, ""You looking for the road south, it's that way."" He pointed. He went back to staring at the coals.

That was the whole of the welcome.

You sat the horse a little longer. There was nothing here that resembled a camp. There was nothing here that resembled a threat. There was a small wet cough somewhere among the heaped rags by the wind-break. It went on a long time. No one tended it. No one would.

You thought about leaving. You thought, also, that you had ridden two days to find this. Two days of looking, and this was what looking found. Not danger. Not even mystery. Four hungry men by a road, the kind of thing you pass and forget every time you ride any distance in this country.

The man pointing at the road south lowered his hand.

He said, without looking up, ""You can sit by the fire if you want. We don't mind."" He paused. ""We don't have anything to take.""

It was Boll. There was no way to know that yet. He looked like the other three. You found out it was Boll later, when he told you, the way a person introduces himself when he remembers he hasn't.

You got off the horse."),
                ServiceLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_821", "Hear what Boll has heard. (5 denars)"),
                ServiceFlavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_822", "Boll leans close. He smells of smoke and old wounds."),
                Kind = ServiceKind.BeggarEar,
                BribeAmount = 50,
                WhyNotKingdom = BandItPlus.Localization.Get("bp_cultureprofileregistry_823", "Boll laughs without humor. \"A king? We were farmers, lord. The king's tax-men made us this.\""),
                Religion = BandItPlus.Localization.Get("bp_cultureprofileregistry_824", "\"We pray every morning. Same prayer. 'Let us eat today.' Some days it works.\""),
                ThreatResponse = BandItPlus.Localization.Get("bp_cultureprofileregistry_825", "Boll cringes. \"Don't, lord. Please. We got nothing. Take it.\" His men step back without weapons."),
                Pleasantry = BandItPlus.Localization.Get("bp_cultureprofileregistry_826", "His face crumples in something like gratitude. \"Kind of you to say, lord. Kind. We try.\""),
                DrinkFlavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_827", "Boll produces a clay jar of weak ale. He pours into chipped cups. \"Last of it. Hadn't planned to share. But guests is guests.\""),
                RestFlavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_828", "You sleep on cold ground next to their fire. Boll insists his men give up their better blankets for your party. They do, with sad eyes."),
                ExtraServices = new[] {
                    new CultureSubService { Label = BandItPlus.Localization.Get("bp_cultureprofileregistry_829", "Pick through the scrap pile."), Flavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_830", "Boll gestures sadly to a small pile of rusted weapons and patched clothes. \"What we found, what nobody wanted. Cheap. Maybe a coin or two each.\""), Kind = ServiceKind.SlaveMarket },
                    new CultureSubService { Label = BandItPlus.Localization.Get("bp_cultureprofileregistry_831", "Hear stories from the road."), Flavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_832", "An old looter sits up. \"I been everywhere, lord. Walked all my life. Want to hear?\" Costs nothing — they want to talk."), Kind = ServiceKind.Oracle, GoldCost = 0 },
                    new CultureSubService { Label = BandItPlus.Localization.Get("bp_cultureprofileregistry_833", "Pay for a meal. (10 denars)"), Flavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_834", "Boll's wife brings out a thin stew. Your soldiers eat in silence. The looters watch hungrily, hoping for the leftovers. Your party feels heavier afterward — less in body, more in spirit."), Kind = ServiceKind.VeteranHall, GoldCost = 10, MoraleGain = 2 },
                },
                Rumors = new[] {
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_835", "\"Saw a noblewoman riding alone at dawn. Crying, she was.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_836", "\"A merchant dropped a coin-purse on the road yesterday. Some boy got it.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_837", "\"There's a body in the ditch a mile back. Fresh. Got a ring on his hand still.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_838", "\"A garrison captain was kissing a tavern-girl in an alley. Wife don't know.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_839", "\"They're hiring at the silver mine. They don't ask names.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_840", "\"A black wagon went through last night with no lamps.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_841", "\"There's a crack in the town wall at Ortongard, west side.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_842", "\"A monk gave me bread three days ago. Said the world was ending.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_843", "\"Heard two soldiers say they'd rather desert than march again.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_844", "\"There's a treasure buried under a crooked tree.\""),
                },
                TrustQuestTier1Pool = new[] {
                    new TrustQuest {
                        ItemIds = new[] { "grain" }, Counts = new[] { 100 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_845", "\"Grain. A hundred bushels. We're starving — that's why we became this. Feed us, and we'll trade.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_846", "His men cheer when they see the grain. The chief simply nods. \"Tonight we eat. Tomorrow we trade.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_847", "100 grain"),
                    },
                    new TrustQuest {
                        ItemIds = new[] { "hides" }, Counts = new[] { 30 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_848", "\"Thirty hides. Boots, jerkins, anything. The boys go barefoot and that's how men die in winter.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_849", "The chief holds up a hide. \"Real cowhide, not the rotted scraps we've been wearing. The boys live another month.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_850", "30 hides"),
                    },
                    new TrustQuest {
                        ItemIds = new[] { "leather" }, Counts = new[] { 50 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_851", "\"Fifty leather. Belts, slings, foot-rags. The starving lose their kit faster than men who eat. Bring it.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_852", "The chief weighs a strap, slings it over his shoulder. \"Now we look almost like men. Trade with us.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_853", "50 leather"),
                    },
                },
                TrustQuestTier2Pool = new[] {
                    new TrustQuest {
                        ItemIds = new[] { "grain", "leather" }, Counts = new[] { 200, 30 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_854", "\"Two hundred grain. Thirty leather. We can fight if we eat and our boots aren't rotted. Bring both, and we'll fight FOR you.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_855", "His men eat and laugh for the first time in weeks. \"You saved this band. Take any boy who wants to follow you.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_856", "200 grain + 30 leather"),
                    },
                    new TrustQuest {
                        ItemIds = new[] { "grain", "hides" }, Counts = new[] { 150, 50 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_857", "\"A hundred fifty grain and fifty hides. Bread and boots. The band marches in real shoes for once. Bring both.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_858", "The chief watches his band lace boots properly. \"Now we look like soldiers, not the dying. Take recruits.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_859", "150 grain + 50 hides"),
                    },
                    new TrustQuest {
                        ItemIds = new[] { "grain", "leather", "mule" }, Counts = new[] { 100, 20, 5 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_860", "\"A hundred grain, twenty leather, five pack-mules. Re-supply on the move. The empire's coming and the band needs to flee fast and fed.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_861", "The chief slaps the lead mule. \"We outrun the empire because of you. The band owes you blood.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_862", "100 grain + 20 leather + 5 mules"),
                    },
                },
                TrustQuestTier3Pool = new[] {
                    new TrustQuest {
                        ItemIds = new[] { "grain", "leather", "tools" }, Counts = new[] { 300, 50, 20 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_863", "\"Three hundred grain, fifty leather, twenty sets of tools. We're going to stop running — settle a hidden fold and farm it. Help us become more than looters.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_864", "The chief weeps quietly, the first time you've seen it. \"The boys plant fields tomorrow. We are men again, because of you.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_865", "300 grain + 50 leather + 20 tools"),
                    },
                    new TrustQuest {
                        ItemIds = new[] { "grain", "hides" }, Counts = new[] { 500, 100 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_866", "\"Five hundred grain, a hundred hides. The whole band overwinters fed and warm. A debt no man could pay back in a lifetime.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_867", "The chief grasps your hand in both of his. \"You don't know what you've given. The band lives because of you. Forever.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_868", "500 grain + 100 hides"),
                    },
                },
                // Wave 5 (Chief Recruitment) alliance content
                AllianceCh1TaskBrief = BandItPlus.Localization.Get("bp_cultureprofileregistry_869", "Pull off one big heist — escort the stolen-goods cart from a wealthy merchant's caravan back to the looter hideout."),
                AllianceCh1Pattern = AllianceCh1Pattern.EscortToSettlement,
                AllianceCh1TargetSeedHint = "looter_hideout_home",
                AllianceCh3RitualText = BandItPlus.Localization.Get("bp_cultureprofileregistry_870", "The Boll the Eldest accepts your oath; the rite is sealed in shared bread and salt and a chipped cup passed around the campfire."),
                AllianceCh3GiftItemId = "boot_knife_rusty",
                AllianceBrokenText = BandItPlus.Localization.Get("bp_cultureprofileregistry_871", "Boll spits in the fire. \"You was one of us for a hot minute. Now you ain't. Don't take it personal, friend — the road just turned.\""),
            }},
            { "forest_bandits", new CultureProfile {
                ChiefName = BandItPlus.Localization.Get("bp_cultureprofileregistry_872", "Granny Hod"),
                Signature = new SignatureQuestSpec
                {
                    Title = BandItPlus.Localization.Get("bp_cultureprofileregistry_873", "The Widows' Grain"),
                    HeraldLine = BandItPlus.Localization.Get("bp_cultureprofileregistry_874", "Oi. Granny wants you at the fire. Lord's taxmen emptied Alder Croft's grain-store — that's the village what fills our pot. He's gone all quiet about it. Go on. Quiet Hod is worse than shouting Hod."),
                    OfferProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_875", "Sit, child. The pot's thin tonight, and Old Hod will tell you why. The lord's tax-riders came through Alder Croft two days back — the wood-village that fills half the bowls at this fire. They took the winter grain. All of it. Sacks the widows there gleaned with their own cracked hands, weighed against a debt nobody ever signed. The wagons roll south on the low road now, slow with the weight of what they stole. Take it back, child. Not a share — every sack, back to the crofts it came from. And save your breath on bargains. Men who'd starve orphans for a ledger-line don't hear words. They hear spears."),
                    AcceptProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_876", "Good, child. The wagons are slow and grain doesn't bleed — mind that the spears around it do. Bring the sacks back whole. Alder Croft's ovens have been cold two days already."),
                    DeclineNudge = BandItPlus.Localization.Get("bp_cultureprofileregistry_877", "As you like, child. But the grain won't sit on that road forever, and there are little ones at Alder Croft learning what an empty bowl weighs. Old Hod will keep your broth warm a while yet."),
                    BusyLine = BandItPlus.Localization.Get("bp_cultureprofileregistry_878", "The wagons are still on the low road, child. Every day they roll south is a day Alder Croft chews bark-bread. Go on. The fire will keep."),
                    TargetPartyName = BandItPlus.Localization.Get("bp_cultureprofileregistry_879", "Taxman's Grain-Wagons"),
                    CaptainName = BandItPlus.Localization.Get("bp_cultureprofileregistry_880", "His Lordship's Taxman"),
                    JournalObjectiveText = BandItPlus.Localization.Get("bp_cultureprofileregistry_881", "Find the Taxman's Grain-Wagons on the roads south of Granny Hod's forest, defeat the escort, and recover the winter grain taken from the wood-village of Alder Croft."),
                    JournalReturnText = BandItPlus.Localization.Get("bp_cultureprofileregistry_882", "Return to Granny Hod's hideout and tell him the grain is on its way back to Alder Croft."),
                    ConfrontIntro = BandItPlus.Localization.Get("bp_cultureprofileregistry_883", "Move your rabble off the road. These wagons carry his lordship's levy, sealed and ledgered. The crown's business does not halt for forest scum — and my escort has killed better-armed beggars than you."),
                    Choices = new[]
                    {
                        new SignatureChoice { Label = BandItPlus.Localization.Get("bp_cultureprofileregistry_884", "Hand the grain back, or bleed for every sack of it."), Outcome = SignatureOutcome.Battle, ResultProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_885", "Hand it back? It's entered in his lordship's ledger — his property the moment the ink dried. Ledgers outlive widows, road-filth, and this one will outlive you. Escort — spears! Cut them down and keep the wagons rolling.") },
                    },
                    ClosingProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_886", "The carts rolled into Alder Croft this morning, child. Every sack. The widows counted them twice, then stopped counting and started baking. There's a girl there who thought bread was a winter story — she knows better now, and so does the lord's ledger. Sit down. The deep bowl's yours tonight — soup with marrow in it, the good roots, none of the thin stuff. Eat with Old Hod, child. This is what the grain was for."),
                    ClosingProseOtherCause = BandItPlus.Localization.Get("bp_cultureprofileregistry_887", "Somebody else found the wagons first, child. Broke the escort on the low road and left the sacks split in the mud for the crows and the rain. My boys saved what they could — half, maybe less. Alder Croft will eat thin this winter, but it will eat, and Old Hod thanks you for riding at all. Still. Spilled grain is gone grain, and the wood does not get its bread back from a stranger's quarrel. Sit. The broth's thin tonight. Share it anyway."),
                    RewardGold = 800,
                    RewardRelation = 10,
                    RewardFoodVendorTrustBump = true,
                },
                ChiefTitle = BandItPlus.Localization.Get("bp_cultureprofileregistry_888", "Wood-Wife"),
                // 2026-06-03 quest-prose flagship — Granny Hod's distinctive voice overrides
                // the forest_bandits mould at Layer 1 of ResolveProse.
                AllianceCh1AcceptProse =
                    "\"You sit in my hideout uninvited, outsider, but I've heard your name on the trade roads. "
                    + "Hod — they call me Granny Hod, though the years that earned the name were soaked in less mercy than the title suggests.\n\n"
                    + "Twenty-five days. That's all you get to prove you're worth more to me alive than dead. "
                    + "Bring me word of a kill — a party of those who profit from the same imperial coin that called for ours. "
                    + "The hunt-brief comes next; my scouts have marked one.\n\n"
                    + "After that, we'll talk again. Run, and you'll find I keep my hideouts well-watched.\"",
                AllianceCh1HuntBriefProse =
                    "\"My woodcutters brought word at first light. {PARTY_NAME} — {ARTICLE} {CULTURE} {KIND} — turned south at the Hadrian crossings yesterday and now sits near {AREA}.\n\n"
                    + "They think they're hunting deserters in my forest. They aren't. "
                    + "Take them on the road, away from witnesses. Bring me their captain's seal, or a banner, or — if you're sentimental — a name.\n\n"
                    + "The forest watches you both. See that you're the one it remembers.\"",
                AllianceMidQuestUpgradeProse =
                    "\"My runners lost the old mark — moved beyond where my eyes reach, or got luckier than they deserved. "
                    + "Try {PARTY_NAME} instead. {ARTICLE} {CULTURE} {KIND} near {AREA}. They'll do.\"",
                AllianceCh2AdvanceProse =
                    "\"You came back, and you came back lighter than you left. Good. Bones that aren't yours.\n\n"
                    + "Word reached us before you crossed the marsh — a {CULTURE} captain dead, the company scattered. "
                    + "I had a wager on whether you'd take the offer of clean retreat halfway through. One of my younger ones is now out of three weeks of salt because of you.\n\n"
                    + "Come to {HIDEOUT} after dusk. We have things to discuss that the forest doesn't need to overhear.\"",
                ChiefBackstory = BandItPlus.Localization.Get("bp_cultureprofileregistry_889", "Hod was born a free Battanian wood-wife, the kind of woodland-dweller who paid no taxes because the lord's tax-clerks never bothered to ride into the deep oak forests where her people lived. She married a hunter named Tealc when she was nineteen, bore him three sons in a turf-and-timber cottage, and lived for twenty-two years on what the woods provided. The first hanging was Tealc — caught taking a stag the lord had reserved for his own table, and gibbeted the next dawn at the village square as a warning. The second was Tealc's elder brother Brec, who came down out of the wood three months later carrying a bow he should have left at home, and the third was meant to be Tealc's younger brother Anwen who came swearing the same oaths over the same gibbet. Anwen brought the bow but he also brought thirty wood-cousins, and the lord's gibbet-men never arrived at their post that morning. From that day Granny Hod has not poached in the forest she lived in — she owns it. The Forest Bandits are her grandchildren, her brothers-in-law, and the last family of every Battanian who has ever swung from a Vlandian-installed gibbet."),
                ClanHistory = BandItPlus.Localization.Get("bp_cultureprofileregistry_890", "The Forest Bandits have lived under the same big oak for four generations. Hod's great-grandmother built the first lean-to there, and Hod still sleeps under that lean-to's grandchild. Deep-forest Battanian wood-villages the Vlandian tax-clerks could not reach feed most of the band — along with herb-women whose husbands were killed in the lord's last small war, poachers whose lord found out about the poaching, and forest-children who simply walked away from a chore one morning and never came back. They are not great raiders — they take from coach-roads only when the coach-road is foolish enough to run inside the tree-line — but they are extraordinary survivors. Granny Hod knows seventy-one edible roots, twenty-four medicinal barks, and the three trees that should not be cut on the same day. The lords who have tried to push roads through the deep oaks have buried more axemen than they have laid stones. The forest-people themselves regard the band as a seventh-aunt of the wood-villages — the one a family brings the sick child to when the lord's hedge-priest has turned them away. The Battanian crown has not declared a bounty in three reigns."),
                ChiefGreeting = BandItPlus.Localization.Get("bp_cultureprofileregistry_891", "An old man in deer-hide watches you cross the clearing without standing. The fire spits between him and you. He tears jerky with his teeth, studying you like he'd study a wounded deer. \"My boys said you walked in alone. Didn't bolt when they drew steel. That's either bravery or stupidity, traveler — and old Hod's lived too long to tell those apart on first sight. Speak your business. The forest hears everything in here.\""),
                ChiefGreetingTolerated = BandItPlus.Localization.Get("bp_cultureprofileregistry_892", "Granny Hod — the men call him that, and the wood-villages older still — looks up as you duck past his sentries. The wariness from your first visit is gone from his eyes; not warmth, but a kind of tired recognition. \"Back again, traveler. Sit. The fire's yours. Old Hod's boys don't draw steel on you anymore — that's the closest thing to welcome these woods know.\""),
                ChiefLoyaltySpeech = BandItPlus.Localization.Get("bp_cultureprofileregistry_893", "Hod's heard names before, traveler. Heard a hundred this winter alone — half of them lying. Means nothing to me until you've done something. My boys want hides; the forest doesn't give them up easy. Bring what we ask, and old Hod will know your name's worth the breath you spent saying it."),
                CampIntro = BandItPlus.Localization.Get("bp_cultureprofileregistry_894", "The Forest Bandits' camp is hidden under a big oak — lean-tos, drying racks of meat and herbs, a smoke-pit. Dogs slink between the trees."),
                HideoutDirections = BandItPlus.Localization.Get("bp_cultureprofileregistry_895", "Take the Pen Cannoc road south, child, until the cart-ruts grow soft with moss and the alders crowd close enough to brush your stirrups. A day off the road, where the canopy closes so thick the sun comes down green, you'll find an oak older than any king the lowlanders remember - a great hollow at its roots big enough to crawl through. That's the door-stone. Our hold lies at {HIDEOUT_NAME}, past the oak, where the drying-racks hang heavy with venison and the smoke-pit smoulders under its turfed lean-to.\n\nMind the snare-line strung between the hazels - step over it slow, hands open. My girls watch from the high boughs and they've put broadheads through better-armed men than you for moving wrong. Whistle three times like the woodlark when you pass the oak; the dogs will know the sound and the dogs will tell my watchers. Come singing if you can. Quiet men trouble me.\n\nFor those who come kindly, there's broth in the pot and a place by the herb-smoke, and old Granny Hod will read the bones for you if your road ahead is dark. For those who come with steel drawn or coin-thoughts behind their eyes - well. The forest is hungry this season, and my dogs have learned a taste they did not have last spring."),
                ScoutsLordsProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_896", "Sit closer to the fire, child. The oaks have been whispering of horsemen all season. The Battanian lords ride their own country like guests who forgot the way home - the fian-captains out of Pen Cannoc come hunting boar in my groves, and twice now they have hunted my snare-women instead. I sent the second band back with their bowstrings cut and a sprig of yew tied to the captain's saddle. He will know the meaning when his mother sees it.\n\nThe Vlandian lords push east through the lowland passes, hungry for Battanian timber and Battanian girls. There is a baron - calls himself Sir Aedric of some keep I cannot pronounce - who burned a charcoal-camp three valleys west because the burners would not swear to his crown. The trees remember. I remember. His outriders will find my dead-falls before they find his timber.\n\nAnd the Empire sends its tax-riders up the old Calradic road, though the road is half-swallowed by root and moss now. They come in tens, leave in fewer. If you ride my country with a lord's banner over you, child, the oaks will mark it before my watchers do. The deep wood keeps its own counsel about who passes through, and who only thinks they did."),
                ScoutsClanProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_897", "Sit closer, child, the fire's hungry tonight. You ask of my kin in the green and the grey - well, the old roots tangle deep. Crone Vael of the pagan cult keeps her grove three valleys north of mine, and we are two old women who nod across the same moon. She sends me bark-tea in the dark months, I send her snare-rabbits in the lean ones. No blood between us, none owed. That is a rare thing in this trade, child, treasure it where you find it.\n\nThe Reavers - Vargolf's lot in the frost-country - owe me a kindness from the year the white sickness took half my band. He sent furs and salt down the old drovers' path, asked no token in return. A wolf who remembers warmth, that one. But the Highwaymen of the downs, child, them I do not abide. Their Reeve trades captives like sheaves of wheat, and the forest does not forgive that. My scouts marked two of his outriders sniffing the Pen Cannoc road last new moon - if they cross my oak-line, the brambles will have them.\n\nAnd hush now - the Marsh Stalkers have gone quiet, child. Three weeks no chatter from the fen-paths. Quiet is a held breath. Something walks down there, or something has eaten them. Either way, we watch the south road careful."),
                ScoutsCaravanProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_898", "Hush a moment, child, and let an old wife show you where the snares lie. The Pen Cannoc road bends past my oak-stand twice a moon, and the Battanian thanes have grown bold - they send their dye-merchants down to Marunath under a thin guard of six levies and a wagoneer who drinks before the sun is full. Three wagons. The middle one carries the blue-dye the southern lords buy by the thimble, worth more than the cloth it will colour. My snare-boys count their steps on the leaf-mast. Quiet as deer they go.\n\nThe trick, child, is the ford below the third milestone. Wagons must slow, the levies must dismount, and the dye-cart sinks to its axle in the soft mud my girls turned over a week before. That is when we have taken them. Twice in a season, and the thanes still send fresh ones. They think the forest forgets.\n\nIf you ride that road four mornings hence with a dozen good horse, the dye is yours and I will not lift a finger to claim it. Granny's pot is full this moon. But mark me - leave the wagoneer breathing and his tongue loose. He drinks at the Pen Cannoc inn and tells the next caravan-master what he saw, and the next caravan packs heavier guards, and the heavier guards bring heavier purses. The forest feeds those who let the snare reset itself. Remember that, child."),
                PactTeaseProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_899", "Sit, child. Sit on the moss and let Granny look at you proper. That is no fireside-question you have brought me - that is the oak-question, the deep-root question, the one a body only asks when she means to be answered. The wind heard you. The oak heard you. Now Granny hears you, and Granny is the slowest of the three.\n\nChild, the green keeps what is given to it. I have bled for three souls in my long years, and the snare-line remembers each. A coal-burner's girl I pulled from a fever-bed when the lowland leeches would not ride out. A poacher named Aelwyn who shared his last hare in a winter that ate two villages. And my own sister, dust now, who taught me which root mends and which root ends. That is the roll Granny keeps. Short as a finger, deep as a well.\n\nYou are not in it, child. Not yet. Bring Granny a kindness the forest can witness - a stag fed to a starving croft, a tax-man turned back from a holding that fed me when I was thin, a wrong-thing righted in the green's own name. Then we shall sit again, and the oak shall know your scent. Ask me once more when you have walked beneath my trees as one of mine."),
                OathBrotherProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_900", "Then it is spoken, child, and the oak above us heard. Kneel by the moss-stone - no, closer, where the root drinks. I cut a twist of my own white hair, and a twist of yours, and I braid them with the snare-line that has held every rabbit, every fawn, every red-handed lowlander I ever pulled from this wood. There. I bury the braid under the root of the grandmother-oak, and the oak takes it down to where my mother's braid lies, and her mother's, and the chief before that whose name I will not speak by daylight. The wood knows your name now. The wood does not forget what it has swallowed.\n\nBrother in the forest-tongue means hearth-shared, child. It means when you come walking through the alder my snares lift their teeth for you. It means my pot is your pot and the salt-fish my old man left me when the fever took him - that salt-fish is your salt-fish. The Wood-Wife has no sons of her own blood; the fever took those too. So you are the son the oak grew for me late. Do not make me bury a third.\n\nGo now, child of mine, and walk the Pen Cannoc road as kin of the Wood-Wife. The Battanian lords will spit at the name. The under-foresters will keep your back. The oak knows. The snare-line knows. From this root forward you are mine, and what is mine the forest defends."),
                PactAnswerProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_901", "Hush, child. Sit down on the moss, you are still steaming from the ride. I asked you once if you would bleed for me when the time came, and I half-expected a pretty answer with the ink still wet on it. Instead you came back through the brambles with the blood already drying on your sleeve and the word almost forgot in your mouth. The oak knows. The deed first, the word after - that is the order a forest trusts. A speech wilts. A wound keeps.\n\nSo hear what the snare-line says now, and hear it plain. From this moon, my woods-folk are your woods-folk under arms. Not as a debt I can call in at my leisure - as a war-bond, the kind the bramble makes when it grows through two trees and will not let either fall alone. Raise your banner anywhere south of the Pen Cannoc road and my bowmen are in the leaves before your horn finishes. Your feud is the forest's feud. The lords who hunt you will find the trees themselves have grown teeth.\n\nThe wind carries this further than my voice can, child. It will be in the rookeries by dusk and in the snare-lines by dawn - that the Wood-Wife rides at your shoulder, and the old grudges of this country ride with her. Go. The road is loud. We are sworn now in something colder than kinship - sworn in the work, and the work is never finished."),
                TroopLoanProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_902", "Aye, child. Ten of my wood-walkers, seven sunsets - I will choose them myself from the bow-girls and the snare-boys who know the deep paths. My eldest niece Bryn Owl-Eye rides at their head; she has the steady hand and the colder count, and what she says to them is what I would have said. She knows my standards. Trust her quiet more than her speaking.\n\nNow hear my terms, child. My wood-hidden do not break thicket for coin or for grudges that are not theirs. While they walk under your banner, your work is the wood's work - do not spend them on small spite. If one falls, you bring me the bowstring and the name of the place, and I will sing the rest myself. If one lives, you feed them well and send them home with their boots still on.\n\nSeven sunsets, child. I will be counting from the next moonrise. The grove expects them back, and so do I."),
                NamedTargetAcceptProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_903", "His name is {TARGET}, child, and his banner hangs over {HOME} like a crow that forgot how to leave. Sit. The oak knows him. Nine summers back his huntsmen rode the green looking for a white stag and found my daughter's man instead - found Cael at his snare-line with two coneys on his belt, and they hanged him from his own rope for a poacher. He was twenty-two. My Annet went into the moss after that and the moss kept her. {TARGET} signed the warrant himself. I have the parchment still, child. I read it on the nights the wind is loud.\n\nHe rides a chestnut mare and a guard of six, and he hunts the river-road every third week when the woodcock are fat. His master-of-hounds is a Battanian boy who was sold to him as a debt-child and would cut the saddle-girth for a kind word and a coin. Find that boy at the Greenmere ford. {TARGET} is heavy after the kill, child, and the green is heavier on him than he knows.\n\n{REWARD} denars when the oak hears of it, no sooner, no less. The gold is owed but the gold is the smaller half. The green keeps the rest. Ride soft, child, and let the moss hold what falls."),
                NamedTargetReason = BandItPlus.Localization.Get("bp_cultureprofileregistry_904", "{CHIEF} has named {TARGET} of {HOME} as the lord whose blood the oak roots have been thirsting for since the seventh summer past. The wound is a remembered one - a coppicer's daughter named Wenna, taken from a charcoal-burner's camp on the Brackwater bend, hung from a snare-line for the crime of gleaning fallen wood from a noble's wood-pasture. The girl was nine. Granny Hod cut her down herself and carries the frayed cord still, knotted three times for the three days the body swung unclaimed. The green keeps its dead, the old woman says, and the oak knows the name uncrossed. A purse of {REWARD} is offered, and a debt the forest has been counting in rings."),
                NamedTargetComplete = BandItPlus.Localization.Get("bp_cultureprofileregistry_905", "{TARGET} is dead. {CHIEF} has been told, and the old wood-mother only nodded, the way oak nods in a slow wind. The snare-line at the Blackelm hollow has its answer at last - thirty-one summers after little Wren was hung there for a fistful of pignuts, the man who tied the knot lies cold. {REWARD} denars rest in the moss-bowl by the hearth-root, counted by knotted cord. The green keeps what it keeps, and the child it could not keep is finally spoken for. The snare is sprung. The hollow is quiet."),
                NamedTargetOtherCauseProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_906", "Word came up the deer-path at dusk: {TARGET} was already cold, run through in a roadside scuffle by some banner-lord's outriders a fortnight back. {CHIEF} took the news in the smoke of her cookfire, turning the old knotted snare-cord through her fingers - the same cord that hanged little Wren at Blackelm hollow over a handful of pignuts. The grudge was answered, in a fashion. The wrong was closed, the name struck off her tally of debts. Still, she had wanted the hand that did it to be the player's, not a stranger's blade in a ditch she would never walk. She counted out {REDUCED_REWARD} denars - thin coin, quarter-pay - and set the bond a smaller notch firmer than it might have stood."),
                RaidVillageAcceptProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_907", "Sit close, hunter, and hear the wood's complaint. {VILLAGE} is the place, and {LORD} the man who calls himself its keeper. His huntsmen ride into my deep wood with hounds and horns, and they do not hunt for meat - they hunt for sport, leaving the red deer to rot where they fall. His foresters fell my old-grove oaks for charcoal, trees that stood when his grandfather's grandfather was an unweaned babe. And his daughter, that proud thing, wears a comb cut from the heart-oak under which my own mother lies buried. The wood remembers. So do I.\n\nGo at the grey hour before dawn, when the charcoal-burners are still asleep beside their mounds. Burn the kilns first - the smoke will wake the village too late. Take their salted venison and their oat-stores, for those are stolen from my wood already. Spare the bee-hives. Spare the apple trees. Spare any old woman who kneels. The rest is kindling.\n\nFor your trouble I will weigh out {REWARD} from the moss-jar beneath the alder root. Bring me back the comb, hunter. The heart-oak wants its splinter home, and my mother has waited long enough."),
                RaidVillageReason = BandItPlus.Localization.Get("bp_cultureprofileregistry_908", "{CHIEF} speaks the name of {VILLAGE} low, the way one names a sickness in a beloved tree. Its huntsmen, she says, have come three summers running into her deep wood, killing the white-flank deer for sport and leaving the carcasses to rot where the moss grows thickest. Worse still, the village axes have felled six of her old-grove oaks for charcoal, and {LORD}'s own daughter walks abroad with a fine comb cut from the heart-oak under which Granny's mother lies buried. The wood remembers, she murmurs. Now it must answer. She offers the player {REWARD} silver to burn the thatch and break the kilns of {VILLAGE}."),
                RaidVillageComplete = BandItPlus.Localization.Get("bp_cultureprofileregistry_909", "{VILLAGE} burned slow, the way wet thatch will when the wind is patient. The charcoal-pits where {LORD}'s woodsmen had been rendering Granny Hod's old-grove oaks were drowned, the axes broken across the same stumps that fed them. No more deer hung head-down from {LORD}'s rafters; no more sport-kills strung up to rot. The heart-oak comb, the one cut from beneath her mother's grave-tree, was prised from the daughter's hair and laid back among the roots where it belonged.\n\n{CHIEF} counted out {REWARD} without speaking. The wood had been heard, and the wood was quiet again."),
                RaidVillageOtherCauseProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_910", "Word drifts in on the wind that {VILLAGE} is already ash. Some other axe answered the deer-killers and the oak-fellers before yours could. {LORD}'s charcoal-pits are cold, his huntsmen scattered, his hall a smear of cinders, and somewhere in that wreck the comb cut from the heart-oak lies broken or carried off by strangers. Granny Hod listens to the news with her hands folded, lips thin. The wood is quieter now, she allows, and that is something. But the killing was not done by kin of the grove, and the trees did not name the doer. She presses {REDUCED_REWARD} into the runner's palm and turns back to her moss."),
                // 2026-05-25 rewrite: shape diverged from the "These were not X / Not Y / Not heroes /
                // One of your companions said / But you did not answer / You watched" template that all
                // 14 cultures shared. This forest variant opens in DIALOGUE with a sentry-boy who
                // narrates the camp for the player; player is silent, observed rather than observing;
                // ends with permission to descend, not a refusal to strike.
                HideoutCinemaIntro = BandItPlus.Localization.Get("bp_cultureprofileregistry_911", @"""You see them?""

The boy was sixteen at most. He was crouched against a pine three paces from you and you had not heard him arrive. The blade in his hand was not yet for you — he held it loose at his thigh — and he did not look up. He looked past your shoulder and down the slope, the way a son might point his father out to a guest at a feast.

""Don't stare right at the fire,"" he said. ""You'll lose your eyes for the dark after. Look just beside it. That's how Granny taught us, an' she was right.""

You looked just beside it.

There were perhaps thirty of them down in the hollow. A woman pulling flat bread off an iron. Two men arguing over the worth of a deer-hide and laughing in the same breath. Children — three, four of them — chasing a dog that was older than they were and far too patient with the chase. A man on a stump tuning a stringed thing that had survived a hard winter and showed it.

""Most came in the last bad one,"" the boy said quietly. ""Winter took the villages. Granny took everyone after. She don't care what you done before — only what you do here. Says the forest don't ask for papers.""

He glanced up at you for the first time. He had brown eyes and a small, faded scar at his hairline, and he was very young.

""You come to take her?""

You did not answer.

The boy nodded slowly, as though you had.

""Right,"" he said. ""Well. Walk down, then. She'll want to look at your face, an' she likes to do it with the fire on it. Keep your hands easy. The dogs are nervier than the men.""

He sat back against the pine and watched you go."),
                ServiceLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_912", "Buy provisions from Granny Hod."),
                ServiceFlavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_913", "Hod gestures to the drying racks. \"Smoked venison, fresh game, hides, healing herbs.\""),
                Kind = ServiceKind.Hunter,
                BribeAmount = 150,
                WhyNotKingdom = BandItPlus.Localization.Get("bp_cultureprofileregistry_914", "\"A king drew a line on a map and said the trees were his. We chose the trees.\""),
                Religion = BandItPlus.Localization.Get("bp_cultureprofileregistry_915", "\"The forest, child. The deer-mother, the oak-father, the wolf that walks.\""),
                ThreatResponse = BandItPlus.Localization.Get("bp_cultureprofileregistry_916", "Hod doesn't even look up. \"My grandson has an arrow on you, lord. Has had since you walked in.\""),
                Pleasantry = BandItPlus.Localization.Get("bp_cultureprofileregistry_917", "She grins — gap-toothed. \"Forest treats us. Quiet here, mostly.\""),
                DrinkFlavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_918", "Hod brings out a jar of pine-spirit. It smells of resin and burns going down. \"Old recipe. Keeps the wolves friendly. Keeps the men ready.\""),
                RestFlavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_919", "You bunk on pine boughs under the big oak. The dogs sleep nearby. Your party wakes to woodsmoke and the smell of breakfast."),
                ExtraServices = new[] {
                    new CultureSubService { Label = BandItPlus.Localization.Get("bp_cultureprofileregistry_920", "Trade with the hide-tanner."), Flavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_921", "A boy lays out tanned hides — deer, boar, a black bear. \"Better than town leather. We did it ourselves. Hod says you'll like it.\""), Kind = ServiceKind.TrophyRoom },
                    new CultureSubService { Label = BandItPlus.Localization.Get("bp_cultureprofileregistry_922", "Speak with the deep-wood druid. (free)"), Flavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_923", "A robed figure barely visible in the trees gestures you closer. \"The forest tells me much, child. Listen.\" The druid speaks in riddles."), Kind = ServiceKind.Oracle, GoldCost = 0 },
                    new CultureSubService { Label = BandItPlus.Localization.Get("bp_cultureprofileregistry_924", "Hire a wolf-hound trainer. (200 denars)"), Flavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_925", "A young man brings out a half-grown wolf-pup. \"Trained right, it'll hunt with your soldiers. Wrong, it'll eat their boots. I train them right.\" Morale rises."), Kind = ServiceKind.VeteranHall, GoldCost = 200, MoraleGain = 3 },
                },
                Rumors = new[] {
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_926", "\"There's a rich man's hunting cabin three days east. Stocked with fine wine.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_927", "\"A druid in the deep wood pays for rare herbs. He pays in old coins.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_928", "\"The forest's deer have moved south. So have the wolves.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_929", "\"A noble lost his prize hound here last hunt. Whoever finds it earns favor.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_930", "\"There's a shrine in the deep wood with offerings of silver.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_931", "\"Foresters' guild is hiring trackers.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_932", "\"A wandering monk got lost in our woods last month. He's still wandering.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_933", "\"The lord's gamekeeper takes bribes.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_934", "\"There's a bear-cave with a winter's stock of dried fish — a hermit's hoard.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_935", "\"A fugitive paid us to hide him last spring. Then his enemies paid more.\""),
                },
                TrustQuestTier1Pool = new[] {
                    new TrustQuest {
                        ItemIds = new[] { "leather" }, Counts = new[] { 30 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_936", "\"Thirty leather. The forest takes our boots and tunics faster than we can replace them.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_937", "He counts hides quickly. \"Honest stock. The forest knows your face now.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_938", "30 leather"),
                    },
                    new TrustQuest {
                        ItemIds = new[] { "hides" }, Counts = new[] { 25 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_939", "\"Twenty-five hides. Roe-deer, boar, what the forest gives. We tan our own — bring the raw stock.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_940", "He inspects each hide. \"Clean kill, clean cut. The tanner won't curse this batch.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_941", "25 hides"),
                    },
                    new TrustQuest {
                        ItemIds = new[] { "hardwood" }, Counts = new[] { 30 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_942", "\"Thirty hardwood. Bow-staves, lodge-poles, fire-wood. The forest is generous, but we're particular about our wood.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_943", "He bends a stave to test the grain. \"Strong wood. The forest welcomes you.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_944", "30 hardwood"),
                    },
                },
                TrustQuestTier2Pool = new[] {
                    new TrustQuest {
                        ItemIds = new[] { "leather", "hardwood" }, Counts = new[] { 50, 20 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_945", "\"Fifty leather and twenty hardwood. We're rebuilding the deep camp — bows, traps, lodges.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_946", "He works hardwood with a knife as he talks. \"Solid stuff. Take what you need.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_947", "50 leather + 20 hardwood"),
                    },
                    new TrustQuest {
                        ItemIds = new[] { "leather", "fur" }, Counts = new[] { 40, 25 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_948", "\"Forty leather and twenty-five fur. The deep-forest patrols need cold-cloak before the leaves drop. Bring both.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_949", "He drapes a cloak around a young scout. \"He'll keep watch warmer because of you. The patrols salute.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_950", "40 leather + 25 fur"),
                    },
                    new TrustQuest {
                        ItemIds = new[] { "hardwood", "hides" }, Counts = new[] { 60, 30 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_951", "\"Sixty hardwood and thirty hides. New lodge for the western patrol-camp. Heavy haul, forest-walker.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_952", "He tests a roof-beam. \"Lodge will hold a generation. The forest remembers your work.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_953", "60 hardwood + 30 hides"),
                    },
                },
                TrustQuestTier3Pool = new[] {
                    new TrustQuest {
                        ItemIds = new[] { "leather", "hardwood", "ironIngot2" }, Counts = new[] { 100, 40, 10 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_954", "\"A hundred leather, forty hardwood, ten wrought-iron ingots. The whole forest-host re-equips. Only kin help with this.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_955", "He clasps your forearm in the deep-forest greeting. \"You've outfitted the band for a generation. Forest-kin now.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_956", "100 leather + 40 hardwood + 10 wrought iron"),
                    },
                    new TrustQuest {
                        ItemIds = new[] { "fur", "hardwood", "hides" }, Counts = new[] { 80, 50, 30 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_957", "\"Eighty fur, fifty hardwood, thirty hides. The whole-forest gathering — we host every band west of the river. Bring it all.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_958", "He gestures to the gathered bands. \"Every Battanian outlaw west of the river knows your name now. Walk safe.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_959", "80 fur + 50 hardwood + 30 hides"),
                    },
                },
                // Wave 5 (Chief Recruitment) alliance content
                AllianceCh1TaskBrief = BandItPlus.Localization.Get("bp_cultureprofileregistry_960", "Destroy the rival Twin-Oak forest gang — they have been muscling Hod's runners off the east trail."),
                AllianceCh1Pattern = AllianceCh1Pattern.DestroyPartiesOfType,
                AllianceCh1TargetSeedHint = "twin_oak_gang_party",
                AllianceCh3RitualText = BandItPlus.Localization.Get("bp_cultureprofileregistry_961", "The Granny Hod accepts your oath; the rite is sealed with a knot of yew-branch tied around your wrist under the old oak at moonrise."),
                AllianceCh3GiftItemId = "longbow_yew_carved",
                AllianceBrokenText = BandItPlus.Localization.Get("bp_cultureprofileregistry_962", "Hod cuts the yew-knot from your wrist herself. \"The forest never owed you. Walk back to the road and stay on it.\""),
            }},
            { "mountain_bandits", new CultureProfile {
                ChiefName = BandItPlus.Localization.Get("bp_cultureprofileregistry_963", "Skarvac of the High Pass"),
                Signature = new SignatureQuestSpec
                {
                    Title = BandItPlus.Localization.Get("bp_cultureprofileregistry_964", "The Mountain's Toll"),
                    HeraldLine = BandItPlus.Localization.Get("bp_cultureprofileregistry_965", "You. Pass-Lord wants you at his fire. Some fat column ran the road without paying and he's gone all quiet over it. Quiet's worse than shouting, with him. Best climb quick."),
                    OfferProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_966", "A column ran my road four days past. Rich one — wool, dye, southern silver in the strongbox. Their captain bought a paper from some lord's clerk in the lowlands and waved it at my lower watch like it was iron. A clerk's ink does not spend on my road. My toll-tables have not changed in eighteen years, and by those tables that column owes me two thousand four hundred denars. The eagles marked them going down the far side — slow wagons, hired guards, a captain who smiles too much. Go and collect what is owed. How the coin comes out of them I leave to the collector. The ledger only cares that it comes."),
                    AcceptProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_967", "Good. Take enough men that the smile leaves his face before you speak. The pass counts in coin, traveler, not in reasons. Bring me two thousand four hundred and I will not ask which pocket it came out of."),
                    DeclineNudge = BandItPlus.Localization.Get("bp_cultureprofileregistry_968", "As you like. But the ledger stays open, and the column rolls slow under fat wagons. The offer stands until my eagles lose them."),
                    BusyLine = BandItPlus.Localization.Get("bp_cultureprofileregistry_969", "You carry unfinished work already. The pass takes one toll at a time, traveler. Come back with empty hands."),
                    TargetPartyName = BandItPlus.Localization.Get("bp_cultureprofileregistry_970", "Cavren's Paper Column"),
                    CaptainName = BandItPlus.Localization.Get("bp_cultureprofileregistry_971", "Master Cavren"),
                    JournalObjectiveText = BandItPlus.Localization.Get("bp_cultureprofileregistry_972", "Find Cavren's Paper Column on the roads below the High Pass and collect Skarvac's toll of 2400 denars — by demand, bargain, or force."),
                    JournalReturnText = BandItPlus.Localization.Get("bp_cultureprofileregistry_973", "Return to Skarvac of the High Pass with the collected toll."),
                    ConfrontIntro = BandItPlus.Localization.Get("bp_cultureprofileregistry_974", "Ah, more toll-men. You have wasted the climb, friend — I carry a writ of passage from Lord Osrec's own clerk, seal and all. The road is paid for. Now shift your horses before my guards earn their wage."),
                    Choices = new[]
                    {
                        new SignatureChoice { Label = BandItPlus.Localization.Get("bp_cultureprofileregistry_975", "Skarvac's toll. Two thousand four hundred. Count it now."), Requirement = SignatureRequirement.StrengthRatio, RequirementValue = 120, Outcome = SignatureOutcome.ComplyFull, ResultProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_976", "All right — all right. Keep your dogs back. It's here, it's counted. Tell the Pass-Lord his road was never worth half this. But tell him it's paid.") },
                        new SignatureChoice { Label = BandItPlus.Localization.Get("bp_cultureprofileregistry_977", "Half the toll and you roll on. Decide quickly."), Outcome = SignatureOutcome.ComplyHalf, ResultProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_978", "Half? Done — before your master hears you can't count. There's your coin. Even a mountain dog knows a paper's worth something, it seems. Drive on!") },
                        new SignatureChoice { Label = BandItPlus.Localization.Get("bp_cultureprofileregistry_979", "Forget the coin. Steel pays your toll today."), Outcome = SignatureOutcome.Battle, ResultProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_980", "Guards! Earn your silver! I bought this road once — I'll not buy it twice from a dead man.") },
                    },
                    DemandFailProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_981", "That's the collection? That handful? Ha! I've hired more steel than you're showing, friend. Take your toll off me if you can reach it — otherwise, downhill is that way."),
                    ClosingProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_982", "Set it on the stone. I count once — I only count twice when I doubt the collector. Two thousand four hundred, full weight. The ledger closes. You took the whole toll off a man waving a lord's paper, and my road keeps its name. That is proper collector's work, traveler. The pass weighed you on this errand and found the weight honest. Sit at my fire. The mountain remembers who paid — it remembers better who collected."),
                    ClosingProseAlt = BandItPlus.Localization.Get("bp_cultureprofileregistry_983", "Set it down. Hm. I count once... and I count again, because the stack sits low. Twelve hundred. Half. You let the paper-man ride off with the rest of what my tables say he owes. Half a toll keeps a road half-respected, traveler. I take it — coin is coin — but the ledger stays open at his name, and yours sits nearer the margin than it did this morning. Go on. The pass forgets nothing it is still owed."),
                    ClosingProseOtherCause = BandItPlus.Localization.Get("bp_cultureprofileregistry_984", "The eagles brought it down before you did. The column lies scattered on the lowland road — someone else's steel, someone else's quarrel, and my toll burned with the wagons. You climbed, so I will not send you down empty. Half-share, for half-work — the road pays the man who rode it, not the man who finished it. Take the coin and do not thank me. Next time reach the mark before the crows do. The ledger closes crooked, and I hate a crooked line."),
                    RewardGold = 1600,
                    RewardRelation = 8,
                },
                ChiefTitle = BandItPlus.Localization.Get("bp_cultureprofileregistry_985", "Pass-Lord"),
                // 2026-06-03 quest-prose flagship — Skarvac's distinctive voice overrides
                // the mountain_bandits mould at Layer 1. Signature: "the pass and I",
                // eagles as informants, switchbacks weighing every man twice.
                AllianceCh1AcceptProse =
                    "\"You climbed. Not many do. The switchbacks broke better men than you before noon, and yet here you stand in my hall, breathing thin and steady. I am Skarvac of the High Pass. The pass and I are old friends.\n\n"
                    + "Twenty-five days. The eagles measure time the same way I do, by how long a thing lasts before it falls. Bring me a kill. A company that thinks the lowlands end where my road begins. My watchers will mark you one by dawn.\n\n"
                    + "Do not run. The descent is longer than the climb, and I own every stone of it.\"",
                AllianceCh1HuntBriefProse =
                    "\"My eagles circled twice at dawn. That is how I know. {PARTY_NAME}, {ARTICLE} {CULTURE} {KIND}, made camp below the third switchback near {AREA}. They think the altitude favours them. It does not. It favours me.\n\n"
                    + "Take them on the climb, where the air thins and the sword arm grows heavy. Their captain will tire before yours does. That is the pass speaking, not flattery.\n\n"
                    + "Bring me proof. A helm, a tongue, a banner. The wind will carry the rest down to me before you do.\"",
                AllianceMidQuestUpgradeProse =
                    "\"The old mark slipped the descent before my eagles could circle twice. The pass lets some go. Take {PARTY_NAME} instead, {ARTICLE} {CULTURE} {KIND} near {AREA}, and the altitude will do half your work for you.\"",
                AllianceCh2AdvanceProse =
                    "\"You came down lighter. The pass weighs every man twice, once on the climb, once on the descent, and you carried less the second time. That is the only honest report I trust.\n\n"
                    + "The eagles brought the rest before you did. A captain cold on the switchbacks, a company scattered toward the lowlands like loose scree. One of my watchers swore you would turn back at the second bend. He owes me a winter cloak now.\n\n"
                    + "Return to {HIDEOUT} when the sun clears the ridge. The pass will know you are coming. So will I.\"",
                ChiefBackstory = BandItPlus.Localization.Get("bp_cultureprofileregistry_986", "Skarvac was born in a high-pass tollhouse his great-grandfather had built — the kind of stone-and-timber post that collects road-dues for the Sturgian crown in exchange for road-maintenance and traveler-protection. The post had operated under royal charter for ninety years, and Skarvac inherited it from his father at twenty-six like an honest profession. The trouble began the year a young Sturgian magistrate audited the regional tolls and discovered the high-pass charter had quietly lapsed three reigns ago — Skarvac's grandfather had simply kept paying his crown-due each year and the crown had simply kept cashing the cheque without renewing the charter. The magistrate ordered the tollhouse closed and a new royal post built in its place, with new royal toll-takers; Skarvac watched from the cliff above as the work began. He came down the second night with twelve men and burned the new construction to the foundations. He maintained the road, repaired the bridges, and charged the travelers fairly by his own measure for the next twenty-eight years, and the Sturgian crown spent that entire period failing to install anyone capable of replacing him. The crown still insists Skarvac of the High Pass is a bandit; the travelers still insist on paying him."),
                ClanHistory = BandItPlus.Localization.Get("bp_cultureprofileregistry_987", "The Mountain Bandits are the most venerable of the bands organized as bands — older than the Highwaymen, younger than the Sea Raiders. Skarvac's great-grandfather built the original tollhouse the camp now occupies, on a Sturgian crown commission to maintain the high pass and collect road-dues; the commission was renewed for three generations and quietly rescinded in the fourth, when the crown decided the pass no longer mattered. The family kept collecting the dues anyway, and the band crystallized around them. Skarvac has not changed the toll-tables in eighteen years; he has the original commission scroll still pinned to his receiving-tent wall, signed and sealed by a Sturgian boyar two generations dead. Those who find their way to Skarvac's camp tend to share a profile: mountain-village men who no longer believe in the crown, displaced highland families, runaway Vlandian armorer's apprentices who could no longer pay their guild-fees, and the occasional Battanian herder who did not feel like coming down the slopes that year. They run the pass like a road-baron's holding — regular patrols, written passes, posted rates. The Sturgian crown has tried twice to retake the tollhouse and has not tried a third."),
                ChiefGreeting = BandItPlus.Localization.Get("bp_cultureprofileregistry_988", "The Pass-Lord stands by a smoking brazier, warming hands that have killed more men than the brazier has ever burned wood. He watches you finish the climb without offering a single step's worth of help, and only when you reach his fire does he speak — measured, mountain-cold. \"You came up alive. That alone is already a discount on your toll, traveler. Skarvac thanks the mountain for the wages it spared us today. Now — what have you come to spend?\""),
                ChiefGreetingTolerated = BandItPlus.Localization.Get("bp_cultureprofileregistry_989", "Skarvac's brazier is closer to where he stands now — a small mercy you didn't get on your first climb. The Pass-Lord nods once, the way mountain men nod when words would cost more than the gesture. \"You've made the pass three times now, traveler. Skarvac counts that. Warm yourself. The mountain doesn't forget who comes back, and neither does its lord.\""),
                ChiefLoyaltySpeech = BandItPlus.Localization.Get("bp_cultureprofileregistry_990", "The mountain heard the name on your climb up, traveler. The mountain forgets quickly. Skarvac doesn't deal in names — he deals in tolls paid and tolls owed. There's a toll my men need collected. Pay it for us, and your name stops being a stranger's at this fire."),
                CampIntro = BandItPlus.Localization.Get("bp_cultureprofileregistry_991", "The Mountain Bandits' camp is wedged into a cliff cleft — stone walls, iron-banded gate, tower for sentries. Skarvac runs it like a road-baron."),
                HideoutDirections = BandItPlus.Localization.Get("bp_cultureprofileregistry_992", "Take the switchback road above Jaculan and keep climbing past the place where the carters stop to water their mules. The air thins. The pines thin. When the road bends a fifth time and you think it must bend no more, look up and left for a cleft in the cliff face - narrow, dark, easy to miss if a man is watching his horse and not the rock. Above the lintel of the gate hangs an ox-skull on a chain. That is the door. Our hold lies at {HIDEOUT_NAME}, and the gate is iron-banded and the walls beside it are dry-stone fitted by a mason whose name I will not give you.\n\nThe slate-roofed tower above the cleft is manned every hour the sun is up and most of the hours it is not. My watcher sees you long before you see the gate. Ride slow on the last bend. Raise your banner where the road straightens. If your party-pennant is one I know, the chain comes down and the gate opens.\n\nCome the wrong way and the first quarrel takes your standard-bearer off his horse. We do not parley with men who climb our pass uninvited - the road is mine, the toll is mine, and the silence of the rocks afterward is mine also. Come the right way and you eat at my fire, and I will tell you which caravans are worth the riding-down this season."),
                ScoutsLordsProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_993", "The Vlandians own the lowlands. The passes are mine. Their lords forget this every spring, and every spring my watchers remind them. The barons of Jaculan send their outriders up the switchback road to count what crosses - they call it patrol, I call it trespass. The toll on this road is set by the man who holds the high ground, and that man is me. A Vlandian banneret rode up last moon with twelve lances behind him. He came down on foot with eight.\n\nThere is a vassal-clan out of Ocs Hall, Clan Therpentine I think they call themselves, who has a standing grudge with my house. Their old lord lost a son to my father's crossbows in the snow-year, and now the boy's brother rides the high road every season with fresh men, looking for the rock that buried his blood. I let him look. The mountain keeps its own counsel.\n\nThe Empire sends tax-wagons through the southern saddle when the snow thins - Western Empire coin, bound for the garrisons at Lageta. The Battanians come north sometimes in raid-parties but they fear the height; their lords belong in the woods. If you ride with a Vlandian banner over my road, traveler, pay the toll before my Reavers ask twice. The pass remembers every coat-of-arms that climbs it."),
                ScoutsClanProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_994", "The road is mine. That is the first thing any chief in these mountains learns, or he learns it the hard way on my switchbacks. Granny Hod's forest band down in the Battanian woods - she sends a runner every autumn with a sack of cured venison and a token saying her foragers will not cross into my passes. I take the venison. The token I keep in a box. One day she will need the road and I will name the toll.\n\nVargolf and his Frost Reavers - now there is a chief I respect. He bleeds Sturgians, I bleed Vlandians, and our maps do not touch. We have shared a fire twice. He pays his debts in iron, which is the only coin a pass-lord trusts. The Highwaymen of the downs are a different matter - the Reeve thinks every Vlandian road is his counting-house. My switchbacks above Jaculan are NOT his road. Last spring two of his coin-counters tried to set up a toll-post a day's ride below mine. They are buried under the cairn at the third bend now. He has not sent more.\n\nThe Sky Raiders worry me. Aerlin's lot have been seen on the crags this season, hunting in country that is mine by old right. Birds do not pay toll. We will see."),
                ScoutsCaravanProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_995", "The Vlandian wool-trains come up out of Jaculan three times a moon, traveler, and every one of them pays my toll whether the driver knows it or not. Twelve wagons, eight horse, two crossbowmen on the lead - that is what the Boyar Mottimer sends north when his weavers want southern dye. They climb my switchbacks at the second hour past dawn because the merchants fear the wind after noon. By the time they reach the third bend their horses are blowing and the rear-guard is walking. That is where the road belongs to me.\n\nThe captain is a Vlandian named Servan, a fat man who drinks his wine at the lower posthouse and never less than three cups. He will not turn his head once the climb starts. The middle wagon - always the middle - carries pressed Battanian bluestone the dyers cannot make for themselves. Worth four hundred denars the bale, and there are six bales under the oilcloth.\n\nIf you take them, take them at the third bend before the snowmelt-ford, not after. After the ford a Vlandian outrider-patrol rides down from the watchtower at the eleventh hour. Hit them clean, ride east into my passes, and the patrol will find nothing but cart-tracks I have already brushed. The road pays its toll one way or another. Better it pays you and me than the boyar's purse."),
                PactTeaseProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_996", "You ask the toll-question. Few travelers know the road well enough to ask it. Sit. Mind the wind off the rocks - it carries every word said up here, and the pass remembers what the mouth forgets. What you are asking is not paid in coin, and what I give is not handed across a counter.\n\nWhen the time comes, I bleed for the names already cut into the toll-stone above the switchback. That stone is small. My brother Caedric, who held the chain the night the Vlandian column tried to force it. Old Mara of the upper village, who fed my riders three winters before any of us could pay her back. The mule-boy Toren, who took an arrow meant for my throat. You have not yet been cut into that stone. Nor have you been struck from it.\n\nBring me a deed the pass cannot forget - a column turned back at the chain, a tax-wagon taken in MY name, a road kept open when the lowlands tried to choke it. Then the toll-stone learns a new mark. Until that day my chain is mine and my riders are mine, but you have already set foot on my road. Speak again when the rocks know your name."),
                OathBrotherProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_997", "Then the word is laid on the stone and the stone does not forget. Stand on the toll-step beside me. I take the chain from my own neck - the one the lowland sergeant put there in Jaculan before I broke his wrist for it - and I open the link with the cold pliers. Hold out your wrist. The link closes around it. Mine bears the matching kink where it was forced wide once and never sat flush again. Now we wear the same iron. Drink from the pass-horn. The water came down off the snow this morning. It tastes of slate and old smoke and the road we hold.\n\nBrother on my road means this. The toll-stone reads two names from tonight. What climbs the pass climbs past you the same as past me. My switchbacks are your switchbacks. The men who tip their caps at the lower watch will tip them at you - and the ones who try the chain at the upper watch will pay you what they would have paid me, or they will pay in the same coin I take. My feud is your feud. The merchant-prince in Jaculan who put the price on my head - that price sits on yours now too, and I am glad of it.\n\nSkarvac of the High Pass names you kin to the toll-stone, kin to the chain, kin to every switchback between here and the snowline. The Pass-Wardens will know your face by the iron. Jaculan will learn it the slow way. Brother - the road climbs, and we hold the high end of it together."),
                PactAnswerProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_998", "Then I have heard the answer in the only tongue the pass respects - the tongue of work already done. You did not climb up here to swear at me. You climbed up with the deed cooling on your hands and the word as the afterthought, the way a toll-stone is set before the road is named. Good. That is the order I trust. A man who comes with a speech first owes more than he brings. You came with the saddle full. Sit. Let the iron settle.\n\nFrom this dusk on, the chain that lies across my pass lies across yours. When you raise your banner in the low country, my road empties of every other rider and fills with mine, and they come down the switchbacks at your call - not as men I have lent, but as men sworn. Your enemies are toll-evaders to me now. Mine you will ride against without asking the price. We do not pay each other in coin again. We pay in arms, in passage, in the dead we leave on the other man's ground. The toll-stone has both our marks cut into it.\n\nThe wind off the high passes carries names a long way, traveler. It will carry ours together now, lashed the way two horses are lashed across a saddle when one rider has fallen. My road is your road. The chain is the witness. This is not the hearth-bond - this is the colder one. The war-bond. It holds until the last of our enemies has been counted, and the high pass has not finished counting in my lifetime."),
                TroopLoanProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_999", "Done. Ten chain-men for seven days - I pick them off the toll-stone myself, the ones who have stood a full winter at the gate. My second is Brakka Cold-Hand, who keeps the count for me and knows which passes are mine and which are only borrowed. He rides at your stirrup. The other nine answer to him, and he answers to me.\n\nHear my terms, traveler. If a pass-warden of mine falls in your work, you carry his chain back to this stone - not his blade, the chain off his belt. That is how I know the man is done. If he lives, you send him home with the road-dust still on him; I want to see where he has been. My riders do not break shield for petty toll-skips or some lord's grudge. While the chain is on your shoulder, your road is my road - so do not spend them on small coin.\n\nSeven days. The pass counts in sunsets, not in promises. When the eighth dawn breaks I expect Brakka at this gate with nine behind him, or a chain in your hand for every man I am short."),
                NamedTargetAcceptProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_1000", "His name is {TARGET}. His banner flies over {HOME}, and his father's chain still hangs from the toll-stone above the High Pass - the chain my own father was throttled with, nine winters back, when he refused to bend knee and pay tariff on his own road. They left him swinging until the crows had his eyes. {TARGET} was a boy then. He has grown into the same chain, and he rides my road now as if the toll-stone forgot.\n\nHe moves with six lances and a Battanian forester who scouts ahead by half a league. The forester drinks at the waystation below Karakhergit on every third night - a flask of strong spirit loosens his tongue and his loyalty both. {TARGET} rests his column at the old shepherd ruins when the pass is choked with snow. Take him there. He sleeps with his sword across his knees, but he sleeps.\n\n{REWARD} denars when the chain comes back to me with his hand still on it. The road remembers what the boy forgot. The pass remembers. Ride, traveler, and do not look back."),
                NamedTargetReason = BandItPlus.Localization.Get("bp_cultureprofileregistry_1001", "Skarvac of the High Pass has set the toll-stone against {TARGET} of {HOME}, and the chain on the road shall not lift until that name is struck from the pass. The grudge is cut into the lintel of his hold: nine summers past, a caravan of Skarvac's kin came down the switchbacks under safe-passage, eleven souls bound for the salt-fair at Pen Cannoc, and {TARGET}'s outriders cut the lead mule's traces above the Shrike-Drop ravine. Eleven went over. The salt was kept. No iron was paid, no name was spoken in answer. Skarvac offers {REWARD} and the weight of a road-debt finally closed. The pass remembers. The contract is open."),
                NamedTargetComplete = BandItPlus.Localization.Get("bp_cultureprofileregistry_1002", "{TARGET} is dead, and {CHIEF} has been told. The toll-stone at the High Pass switchback bears a fresh notch cut beside the old one - the deeper gouge that has waited eleven winters since Brennic, {CHIEF}'s road-brother, was hauled off the pass in Lord Halric's chain-cart and never seen again past the Gilded Mile. The {REWARD} denars are weighed and pouched at the cairn-fire, and the road-baron's standing with the traveler-killer is set a degree firmer. The chain that took Brennic is answered with a chain of silver. The pass remembers, and the pass is paid."),
                NamedTargetOtherCauseProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_1003", "Word climbed the switchbacks at first thaw - {TARGET} dead in a ditch beside the lowland road, ridden down by some Halric vassal's outriders over a quarrel that was never {CHIEF}'s. The chief took the news on the toll-stone, one thumb tracing the old notch he cut the day Brennic was hauled off the pass in a chain-cart, and said nothing for a long count. The grudge stood answered; the score had not been settled by the hand he sent. {CHIEF} weighed it cold. Quarter-pay was counted out onto the stone - {REDUCED_REWARD} denars, thin coin for a thin closure - and the bond between road-baron and hired blade was set a smaller notch firmer than before, honored but unwarmed, the kill owed but never owed back."),
                RaidVillageAcceptProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_1004", "{VILLAGE} sits in the saddle of the lowland green, and {LORD} keeps it. A Vlandian baron-clan, that one - pretty banner, soft hands, harder pride. Three winters running they have refused my pass-toll. Three winters their wool has crossed the saddle-path at night, smuggled under straw, untaxed and unblessed. Last spring they took Brakka's nephew off the high road and worked him in their quarry until his lungs gave out. Brakka is my chain-warden. Brakka has not slept proper since. So {VILLAGE} owes me, and the boy owes a debt I mean to collect in stone and smoke.\n\nGo down through the cleft after the morning mist lifts, not before - the lowland watch keeps a horn on the chapel roof and the mist hides their eyes, not yours. Burn the wool sheds first. Take the draft horses, the iron, the salt. Leave the chapel; I am not at war with their saints, only with their lord. Any quarry-warden you find, you put him on his knees and you ask him about a boy named Tavik. Then you do what your hand tells you.\n\nFor this work, {REWARD} when you ride back over the pass. {CHIEF} keeps his word. {LORD} does not. That is the whole of the lesson."),
                RaidVillageReason = BandItPlus.Localization.Get("bp_cultureprofileregistry_1005", "{CHIEF} names {VILLAGE} on the lowland side of the saddle-path and spits the name like a stone from his boot. The Vlandian holding of {LORD} has refused the pass-toll three winters running, run wool over Skarvac's road in moonless caravans, and last spring his chain-warden Brakka's sister-son was hooked off that road and worked dead in the village quarry. The boy is buried under their slag. The toll is unpaid. The chief wants the village broken to ash and the lord's wool burned where it lies. He sets the contract at {REWARD} denars, paid on the smoke."),
                RaidVillageComplete = BandItPlus.Localization.Get("bp_cultureprofileregistry_1006", "{VILLAGE} burned to the stone-sills. {CHIEF} stood at the saddle-mouth and watched the smoke roll down the lowland road that had refused his toll three winters running. {LORD}'s wool-bales went up first, then the quarry sheds where Brakka's nephew had been worked under the lash until his back broke. The chain-warden himself walked the ash with a long iron and turned over what was left, looking for the boy's name cut into a beam. He did not find it, but he found enough. The pass-debt was closed. {CHIEF} counted out {REWARD} on a flat rock and pushed it across without a word."),
                RaidVillageOtherCauseProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_1007", "Word reached the High Pass at first light: {VILLAGE} was ash before {CHIEF}'s axes ever crossed the saddle-path. Some other blade had drawn the lord {LORD}'s blood and burned the wool-sheds clean, leaving nothing for the chain-warden Brakka to settle in his nephew's name.\n\n{CHIEF} took the news standing, said little, spat once at the snow. The toll was paid, in a manner of speaking - just not by his hand, and not in the coin his oath required. The quarry that broke Brakka's boy lies cold now, and that was the lion's share of the bargain.\n\nHe counted out {REDUCED_REWARD} on the trestle and pushed it across without meeting the eye. Half-debt for half-work. The road, he muttered, remembers who walked it first."),
                // 2026-05-25 rewrite: shape diverged from the shared 14-culture template. This mountain
                // variant opens in single-word FRAGMENTS, stays in present-tense sensory pressure, has
                // no companion-quote pivot and no negation list; the player is silent throughout and
                // ends as the OBSERVED party — a horn lifting on the tower to summon Skarvac to look
                // at the curiosity that has climbed up his road.
                HideoutCinemaIntro = BandItPlus.Localization.Get("bp_cultureprofileregistry_1008", @"Cold. Real cold, not market-cold — the cold of a place that has no use for you.

Your breath whitens. The horse shifts its weight under you and you feel the slate slip beneath its hoof, hear the small bright clatter of it falling away into nothing, falling further than seems reasonable. You stop counting after the third bounce.

The trail tilts up and does not stop tilting. Loose scree. A switchback so narrow that one rider goes single-file and the other waits.

Look up.

A gate. Iron straps, oak gone grey from the weather, set between two raw walls of stone the mountain itself raised before any hands shaped them. Above the gate, a tower so narrow only one man can stand sentry there.

He is standing there.

He has been standing there since you came around the last bend, perhaps longer. His face is a smudge against the torch behind him. He does not call down. He does not lift the horn at his hip. He watches.

You watched him watching you for two long minutes. Then he turned aside, satisfied with something, and went back to his fire.

Inside the walls: smoke. A horse blanket drying on a line stretched between two boulders. Someone laughs once, low, and is hushed.

No banner flies above this place. No standard. None is needed.

The mountain is the banner.

You sit your horse below that iron gate and feel — for the first time on this errand, perhaps for the first time in a long while — that it may not be you who came here to take a measure.

It may be the other way around.

The horn on the tower lifts, finally. Not loud. Not a war-horn. The note of a man calling his lord to the gate to look at something interesting that has wandered up the road."),
                ServiceLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_1009", "Pay for safe passage in the mountains. (500 denars)"),
                ServiceFlavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_1010", "Skarvac scribes a sigil on a strip of leather. \"Wear this where my men can see.\""),
                Kind = ServiceKind.TollMaster,
                BribeAmount = 200,
                WhyNotKingdom = BandItPlus.Localization.Get("bp_cultureprofileregistry_1011", "\"Our people held this pass before the empire had a name for it. We are older than any king.\""),
                Religion = BandItPlus.Localization.Get("bp_cultureprofileregistry_1012", "\"Mountain-spirits. Avalanche-mother. The cold star.\""),
                ThreatResponse = BandItPlus.Localization.Get("bp_cultureprofileregistry_1013", "Skarvac chuckles. \"This pass has eaten men with bigger swords than yours.\""),
                Pleasantry = BandItPlus.Localization.Get("bp_cultureprofileregistry_1014", "He inclines his head. \"Strong walls. Strong men. Strong tolls.\""),
                DrinkFlavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_1015", "Skarvac pours from an old cask of stolen Sturgian mead. \"Tolls have to go somewhere. This is where most go. Drink, friend.\""),
                RestFlavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_1016", "Your party gets bunks in the tower's lower hall. The walls are stone. The wind doesn't reach in. Your party rises strong."),
                ExtraServices = new[] {
                    new CultureSubService { Label = BandItPlus.Localization.Get("bp_cultureprofileregistry_1017", "Visit the cliff-forge."), Flavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_1018", "A bearded man hammers iron into shape at a forge built into the rock. \"Stolen ore, stolen tools, stolen apprentice. But the iron is good. The price is fair.\""), Kind = ServiceKind.TrophyRoom },
                    new CultureSubService { Label = BandItPlus.Localization.Get("bp_cultureprofileregistry_1019", "Browse the toll records. (100 denars)"), Flavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_1020", "Skarvac flips through a battered ledger. \"We track every party that passes. One of them was another camp. Take it.\""), Kind = ServiceKind.InfoBroker, GoldCost = 100 },
                    new CultureSubService { Label = BandItPlus.Localization.Get("bp_cultureprofileregistry_1021", "Visit the mountain-spirit shrine."), Flavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_1022", "A tiny shrine of stacked stones at the cliff-edge. Old rags tied to it. Skarvac bows quickly. \"We leave a coin. The mountain has been kind.\""), Kind = ServiceKind.Oracle },
                },
                Rumors = new[] {
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_1023", "\"Sturgian merchants started taking the western pass to avoid us.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_1024", "\"A noble's daughter eloped through here last week.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_1025", "\"There's a silver vein in the cliffs above us.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_1026", "\"A Vlandian heir was lost in an avalanche eight years ago.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_1027", "\"The empire's road tax goes through here. The collector pays us off.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_1028", "\"There's a hidden monastery somewhere on this peak.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_1029", "\"A caravan of pilgrims comes through every Saint's Day.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_1030", "\"Mountain Khergit clans are rising again on the eastern slopes.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_1031", "\"A dragon-bone, they call it — found in the highest pass.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_1032", "\"The pass freezes in deep winter. Whatever they were carrying is still up there.\""),
                },
                // Wave 4.7e: Tier 1 random pool — chief picks an errand based on the day.
                TrustQuestTier1Pool = new[] {
                    new TrustQuest {
                        ItemIds = new[] { "iron" },
                        Counts = new[] { 20 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1033", "\"Twenty loads of iron ore. The mountain pays us in stone, but stone breaks. Bring iron and you've shown you understand the trade up here.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1034", "He breaks a chunk of ore in his hand and grunts. \"Pure. Not the rust the southerners pass off. Trade with us, mountain-walker.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_1035", "20 iron ore"),
                    },
                    new TrustQuest {
                        ItemIds = new[] { "hardwood" },
                        Counts = new[] { 30 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1036", "\"Thirty hardwood. The pass-fortifications need shoring up before the snows. Lumber's heavy, but we'll know who's serious.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1037", "He hefts a beam, tests its weight. \"Good wood. Cut clean. The mountain remembers who carried for it.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_1038", "30 hardwood"),
                    },
                    new TrustQuest {
                        ItemIds = new[] { "fur" },
                        Counts = new[] { 25 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1039", "\"Twenty-five pelts. The men who guard the high pass freeze if they don't lay thick under cloak. Bring fur or stay out of the snows.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1040", "He runs a thumb across the fur, grunts approval. \"Heavy coats. The men will hold the high stones tonight.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_1041", "25 fur"),
                    },
                },
                // Wave 4.7e: Tier 2 random pool — visibly harder, multi-item or larger qty.
                TrustQuestTier2Pool = new[] {
                    new TrustQuest {
                        ItemIds = new[] { "iron", "hardwood" },
                        Counts = new[] { 30, 20 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1042", "\"Thirty ore and twenty hardwood. We're forging new pikes for the pass garrison. Bring both and you walk the high places with us.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1043", "He inspects a pike-shaft, nods. \"Good iron. Good wood. The mountain is yours when you come up. Take what you need.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_1044", "30 iron ore + 20 hardwood"),
                    },
                    new TrustQuest {
                        ItemIds = new[] { "iron", "tools" },
                        Counts = new[] { 40, 10 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1045", "\"Forty iron and ten sets of tools. The smithy's running cold and the armorers need both. Heavy haul, mountain-walker — but it's how a man earns the high places.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1046", "He weighs the iron in one hand, tests a hammer-haft with the other. \"Now we forge proper. The high stones know your name.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_1047", "40 iron + 10 tools"),
                    },
                    new TrustQuest {
                        ItemIds = new[] { "mule", "iron" },
                        Counts = new[] { 2, 25 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1048", "\"Two pack-mules and twenty-five iron. We move loads to the high pass that no horse can carry. You bring the beasts and the metal, you're one of us when the mountain calls.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1049", "He pats the lead mule's shoulder. \"Good beasts. Steady. The pass is yours to walk now, like blood-kin.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_1050", "2 mules + 25 iron"),
                    },
                },
                // Wave 4.7e: Tier 3 random pool — final test of trust. Significantly harder.
                // Introduces smithing-system materials (ironIngot2/3) so the player must
                // engage with the smithy economy, not just the trade goods market.
                TrustQuestTier3Pool = new[] {
                    new TrustQuest {
                        ItemIds = new[] { "iron", "ironIngot2" },
                        Counts = new[] { 80, 20 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1051", "\"Eighty iron and twenty wrought-iron ingots. The pass-armory will be the finest east of Pravend. Only a Reaver-friend brings this. Take your time, brother — but bring it all.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1052", "He runs a hand along the rack of finished pikes, then looks at you long. \"You've done what no southerner does. The mountain calls you brother now. The high stones are yours.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_1053", "80 iron + 20 wrought iron"),
                    },
                    new TrustQuest {
                        IsGoldQuest = false,
                        ItemIds = new[] { "ironIngot3", "hardwood", "fur" },
                        Counts = new[] { 15, 50, 30 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1054", "\"Fifteen refined-iron, fifty hardwood, thirty fur. The whole high garrison re-equips in one stroke. A blood-kin's task. You bring this, the mountain knows your name forever.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1055", "He stands silent a long moment, then claps your shoulder hard enough to bruise. \"You re-armed our high pass. The Mountain Bandits will remember your blood and your name.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_1056", "15 refined iron + 50 hardwood + 30 fur"),
                    },
                },
                // Legacy singletons retained as fallback for save compatibility — Pool[] takes precedence.
                TrustQuestTier1 = new TrustQuest {
                    ItemIds = new[] { "iron" },
                    Counts = new[] { 20 },
                    IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1057", "\"Twenty loads of iron ore. The mountain pays us in stone, but stone breaks. Bring iron and you've shown you understand the trade up here.\""),
                    ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1058", "He breaks a chunk of ore in his hand and grunts. \"Pure. Not the rust the southerners pass off. Trade with us, mountain-walker.\""),
                    ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_1059", "20 iron ore"),
                },
                TrustQuestTier2 = new TrustQuest {
                    ItemIds = new[] { "iron", "hardwood" },
                    Counts = new[] { 30, 20 },
                    IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1060", "\"Thirty ore and twenty hardwood. We're forging new pikes for the pass garrison. Bring both and you walk the high places with us.\""),
                    ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1061", "He inspects a pike-shaft, nods. \"Good iron. Good wood. The mountain is yours when you come up. Take what you need.\""),
                    ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_1062", "30 iron ore + 20 hardwood"),
                },
                // Wave 5 (Chief Recruitment) alliance content
                AllianceCh1TaskBrief = BandItPlus.Localization.Get("bp_cultureprofileregistry_1063", "Repel the marked Vlandian probing force that approaches the High Pass within the next day — destroy the party where it climbs."),
                AllianceCh1Pattern = AllianceCh1Pattern.DestroyPartiesOfType,
                AllianceCh1TargetSeedHint = "vlandian_probe_party",
                AllianceCh3RitualText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1064", "The Skarvac of the High Pass accepts your oath; the rite is sealed with a shallow palm-cut on the hereditary boundary stone of the pass."),
                AllianceCh3GiftItemId = "hand_axe_bone_handled",
                AllianceBrokenText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1065", "Skarvac slams the boundary stone with the flat of his hand. \"The pass is closed to you. Find a lower road, friend — this one ends here.\""),
            }},
            { "steppe_bandits", new CultureProfile {
                ChiefName = BandItPlus.Localization.Get("bp_cultureprofileregistry_1066", "Ulan Twice-Banished"),
                Signature = new SignatureQuestSpec
                {
                    Title = BandItPlus.Localization.Get("bp_cultureprofileregistry_1067", "The Third Writ"),
                    HeraldLine = BandItPlus.Localization.Get("bp_cultureprofileregistry_1068", "You. Rider. The chief wants you at his fire. Some khan put his name on paper again — bounty, banishment, the whole song. Third time now. He laughed once when the scout told him. Just once. Go."),
                    OfferProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_1069", "A khan's column crosses my grass this week, traveler. Guard riders, a polished emissary, satchels of sealed paper — tax-rolls, marriage-contracts, and one writ more. Banishment and bounty, renewed, my name under the seal. The third ever written against me. Twice a clan cast me out with words spoken at a fire. Now a khan does it with ink, from a hall I have never stood in. I want that writ. Not burned on the road — carried here, seal unbroken, into my hands. A man should own the paper that hunts him. Take it however the day allows. The wind will tell me how it went, so do not dress the story."),
                    AcceptProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_1070", "Good. Ride wide and read the dust — a column that heavy waters twice a day and hates every stop. Bring the seal unbroken, traveler. It has been years since anyone wrote to me."),
                    DeclineNudge = BandItPlus.Localization.Get("bp_cultureprofileregistry_1071", "As you like. But the writ still rides, and paper outlives riders. Once it reaches a wall-town, every bounty-man on the steppe learns my new price. Think again before the column finds a road."),
                    BusyLine = BandItPlus.Localization.Get("bp_cultureprofileregistry_1072", "The column still rides, traveler. Paper does not tire. Go and fetch my name back before some clerk in a wall-town files me away."),
                    TargetPartyName = BandItPlus.Localization.Get("bp_cultureprofileregistry_1073", "Khan's Emissary Column"),
                    CaptainName = BandItPlus.Localization.Get("bp_cultureprofileregistry_1074", "The Khan's Emissary"),
                    JournalObjectiveText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1075", "Intercept the khan's emissary column on the steppe and secure the sealed writ of banishment and bounty written against Ulan Twice-Banished."),
                    JournalReturnText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1076", "The writ has been taken from the emissary's column. Return to Ulan Twice-Banished at his camp and place the paper in his hands."),
                    ConfrontIntro = BandItPlus.Localization.Get("bp_cultureprofileregistry_1077", "You are addressing an emissary of the khan's household. I do not treat with road-thieves. Whatever you imagine this column carries, it is worth less than what the khan pays for your kind by the head. Move aside."),
                    Choices = new[]
                    {
                        new SignatureChoice { Label = BandItPlus.Localization.Get("bp_cultureprofileregistry_1078", "Count my spears, then hand over the banishment writ."), Requirement = SignatureRequirement.StrengthRatio, RequirementValue = 120, Outcome = SignatureOutcome.ComplyFull, ResultProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_1079", "Counted. Very well — the writ, seal unbroken, as it left the hall. A receipt is customary. I will not be asking for one.") },
                        new SignatureChoice { Label = BandItPlus.Localization.Get("bp_cultureprofileregistry_1080", "Twelve hundred denars says that satchel rides lighter."), Requirement = SignatureRequirement.GoldCost, RequirementValue = 1200, Outcome = SignatureOutcome.ComplyFull, ResultProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_1081", "Documents are lost to weather all the time — the khan's clerks allow for it. Take it and ride. I was watching the horizon. I saw nothing.") },
                        new SignatureChoice { Label = BandItPlus.Localization.Get("bp_cultureprofileregistry_1082", "The paper comes with me. Draw if you disagree."), Outcome = SignatureOutcome.Battle, ResultProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_1083", "Riders — earn your keep! Close the column! The satchels do not fall while one lance stands!") },
                    },
                    DemandFailProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_1084", "The khan's paper does not stop for beggars. Twenty lances ride behind me — petition them, if you must."),
                    ClosingProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_1085", "Give it here. Seal unbroken — you listened. Banishment renewed. Price raised. Good. A man should cost more at my age than he did at nineteen. No, it does not burn. The first two were written about me. This one is mine. It goes in the saddle-chest, with the things I keep."),
                    ClosingProseOtherCause = BandItPlus.Localization.Get("bp_cultureprofileregistry_1086", "Ash and crows two days before you reached it, my scouts say. Rain-soaked, seal crushed, half the ink run grey. Even my banishments reach me secondhand now. I keep it anyway. Half a writ, half a price, traveler — do not argue. I have been undercut before."),
                    RewardGold = 1800,
                    RewardRelation = 8,
                },
                ChiefTitle = BandItPlus.Localization.Get("bp_cultureprofileregistry_1087", "Twice-Banished Khan"),
                // 2026-06-03 quest-prose flagship — Ulan's distinctive voice overrides
                // the steppe_bandits mould at Layer 1. Signature: openly names his two
                // banishments, contrasts himself with khans who still have a fire to ride
                // home to, treats horizon as judgment.
                AllianceCh1AcceptProse =
                    "\"You ride into my camp and call it a meeting. I am Ulan, and you already know the rest of the name, for the steppe sings it cruelly. Twice-Banished. My birth-clan put the mark on me first. The tribe that pitied me put the second mark over the first.\n\n"
                    + "Twenty-five days. Other khans count seasons because they have a fire to ride home to. I count days because days are all an exile is owed.\n\n"
                    + "Bring me a kill, a real one, not a story you carry back lighter than the blood you spilled. After that we will see if your word is worth more than the two clans that broke mine.\"",
                AllianceCh1HuntBriefProse =
                    "\"My riders ate dust for three nights and brought back one name worth chewing. {PARTY_NAME}, {ARTICLE} {CULTURE} {KIND}, watering their horses near {AREA}.\n\n"
                    + "They think the horizon hides them. The horizon hides nothing from a man it has already judged twice. Ride wide, come at them from the sun-side, and do not let any rider break for the high grass — an exile's witness is worse than a killed man.\n\n"
                    + "Bring me proof. A bridle, a brand, a tooth. I do not trust mouths, mine least of all. The steppe will know which of you it kept.\"",
                AllianceMidQuestUpgradeProse =
                    "\"The first mark slipped my noose, rode beyond the horizon's judgment, or bought a season I did not. Take {PARTY_NAME} instead, {ARTICLE} {CULTURE} {KIND} near {AREA}. An exile does not weep over a vanished quarrel. He finds the next one before the dust settles.\"",
                AllianceCh2AdvanceProse =
                    "\"You came back. Few do. Twice-Banished knows the look of a man who has just decided which side of the horizon he belongs on, and you wear it badly.\n\n"
                    + "Word crossed the grass before your shadow did. A {CULTURE} captain unhorsed, the rest scattered like a clan after a bad winter. I had two men wagering you would turn south at the second night. They lost. Good. Loss teaches faster than I do.\n\n"
                    + "Ride to {HIDEOUT} when the sun is low. We will speak where the wind cannot carry it to whichever clan still pretends I am dead to them.\"",
                ChiefBackstory = BandItPlus.Localization.Get("bp_cultureprofileregistry_1088", "Ulan was born to a steppe-clan that had ridden the western grass for nine generations, third son of a chief who had killed his own father to claim the herd-leadership. Ulan grew up in the ger-camps, learned bow and saddle by six, and rode his first cattle-raid at eleven. The first banishment came when he was nineteen — he killed an uncle who had insulted his mother, and his father (who had not loved his brother but loved tradition more) sentenced him to ride west alone. Ulan returned a year later with twenty followers, found his father had been killed by another rival in the meantime, and was promptly banished a second time by the rival who had killed his father — on the grounds that an exiled son should not return to claim a clan that did not exile him. Neither banishment took root. The rival who claimed the clan died in a hunting accident the following spring; Ulan's mother sent word that the herd-elders would accept him back, but by then he had built a band of his own and saw no reason to return. He rides the western steppe along a line that no major faction patrols, because no major faction owns it; his band raids what passes for trade-traffic out there, and he answers to no khan but the open sky."),
                ClanHistory = BandItPlus.Localization.Get("bp_cultureprofileregistry_1089", "The Steppe Bandits are not a clan and never were. They are the people no clan would keep — twice-exiled men, sons whose chiefs sentenced them to the long ride, daughters whose marriages dishonored a herd, oath-breakers whose oaths cost a herd to the wrong neighbor. Ulan was banished twice from his own family before he was thirty, and the band coalesced around his second exile. They keep three yurts and ride between them; they have never built a permanent camp and never will. They take from caravans crossing the steppe, from trade-trains foolish enough to ride without escort, from the rare imperial outpost stupid enough to be built where the grass grows tall. The signature of a Steppe Bandit raid is that there is no signature: they come, they take, the camp moves a week's ride before the news of the raid catches up. The Khanate has placed three separate bounties on Ulan and pulled all three back when the bounty-hunters returned with shaved heads and no horses. The eastern clans regard the Bandits as a dirty necessity — every chief who has ever needed a deniable rider on a deniable errand has known where the three yurts were that month."),
                ChiefGreeting = BandItPlus.Localization.Get("bp_cultureprofileregistry_1090", "The small, leathery rider dismounts without ceremony — a habit, perhaps, of a man banished from too many courts to bother with their forms. He leads his horse to meet you the way a host welcomes a traveler at the door of a gēr. His eyes do not match the welcome. \"A guest. The gods send guests, even to Ulan Twice-Banished. You will eat with us, traveler. You will trade with us. Then you will leave alive — if the gods still send guests when we have spoken.\""),
                ChiefGreetingTolerated = BandItPlus.Localization.Get("bp_cultureprofileregistry_1091", "Ulan doesn't lead his horse out to meet you anymore — the courtesy is reserved for strangers. He stays at the gēr-flap, raises a cup, and waits for you to come in. \"A guest twice over is no longer a guest, traveler. Eat. Drink. Trade. The gods who sent you the first time send you again, and Ulan listens this time without his hand on a knife.\""),
                ChiefLoyaltySpeech = BandItPlus.Localization.Get("bp_cultureprofileregistry_1092", "A guest's name is wind under the gēr, traveler. The gods send guests; only deeds tell us which guests the gods meant. Ulan has a thing his men need done. Do it, and you become a guest the gods sent for a reason — not just one passing by."),
                CampIntro = BandItPlus.Localization.Get("bp_cultureprofileregistry_1093", "The Steppe Bandits' camp is a tight cluster of three yurts, horses picketed in a ring around them. They keep moving — the camp will be gone in a week."),
                HideoutDirections = BandItPlus.Localization.Get("bp_cultureprofileregistry_1094", "Ride west from the last watering-stand, two days hard across the open grass. You will find no road, no marker stone, no priest's cairn to count from - only the wind in the grass and the sun walking the sky. On the second evening look for three yurts pulled tight together like horses against a wolf, and a fire-pit dug shallow so the smoke does not climb. The felt door of the middle yurt is painted with a single sun. That is {HIDEOUT_NAME}, and that is my fire.\n\nMy riders watch the four horizons before you see the yurts. They will count your horses from a ridge you cannot find, and read your saddle-cloth before you read the grass. Come in slow and come in open-handed - reins loose, weapons sheathed, your banner showing high enough that the steppe knows your face. A rider will cross your path and turn his horse beside yours. That is the welcome. Follow him in.\n\nCome fast, come hidden, come with an unmarked spear, and the first you will know of us is the arrow already in your throat. The steppe keeps no graves, traveler - the crows do that work. But ride to my fire the right way and you drink mare's milk under my roof, and what is mine is yours for the night. We will be gone from this ground in a week. The grass forgets us. Ride while the wind still knows the way."),
                ScoutsLordsProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_1095", "The Khuzait khans send their riders into my watering-country like I am a stranger on my own grass. Twice now this season a noyan of the khan's household has crossed the salt-flats with his lancers, hunting me as a wolf hunts a lame mare. I know his banner. I rode under it once, before the council struck my name from the long-rolls and called me bandit. He drinks from cups my father gave him. Now he hunts me with them at his belt.\n\nThe Empire sends tax-wagons up the old caravan-road from the southern cities, and their cataphracts ride heavy enough that the steppe-grass remembers their weight for a week. I do not touch them often. Their commanders write down the names of every man they kill, and a written name is a curse that follows a clan three generations. The Aserai send no levies this far north, but their coin-traders ride with paid Vlandian sellswords - mercenaries, not vassals, and they ask no questions when a column goes missing.\n\nThe khan himself, the great khan, he has not spoken my name in seven winters. That is the deepest wound. If you ride khan's-country with his banner on your lance, traveler, my watchers will read you from three ridges away. Ride with no banner, or ride with one he hates. The steppe has long sight and a longer memory."),
                ScoutsClanProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_1096", "Borchu of the Wolf-Khans is a name I do not say twice. We grew up drinking the same milk, raided the same Khuzait outriders as boys, and when my own people cast me out he was the one who turned his horse and rode the other way. I owe him no blood. I owe him no fire. If our grass touches I ride wide, and he rides wider. That is the peace between Wolf-Khan and Twice-Banished, and it is colder than the deep winter.\n\nGranny Hod's forest band sent a runner to my watering-stand last moon. She wants steppe-horses, fast ones, and she pays in Battanian silver that still has the boyar's mark on it. I will trade. She keeps her woods, I keep my open sky. Skarvac's pass-lords up in the mountains are another matter - they robbed two of my outriders on the Pravend road and left them for the crows. I have not forgotten. When the snow comes I will ride a hundred men up that pass and we will see how high his rocks make him.\n\nThe Slavers under Khalid have gone quiet. Three seasons no caravan, no chain-song on the dune road. That silence is not peace. That is a man counting his teeth before he bites."),
                ScoutsCaravanProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_1097", "A Khuzait silk-train rolls west from Makeb every ten days - eight wagons, twenty horse-guard, a captain called Tsegen who drinks airag from sundown to moonrise and trusts his outriders to do his looking. They water at the third stand past the broken kurgan, the one with the leaning stone where my grandfather pastured before the khan put a price on his shadow. The escort spreads thin at the watering because the horses must be unsaddled in turn. That is the hour. Three breaths of charge, no more, and the silk is yours.\n\nThe wagons carry Khuzait silk going to Vlandian factors at Pravend, and on the return-leg they carry silver going back to the khan's tax-riders. Either direction pays. The silver is heavier and slower-tracked - the khan does not count what bandits take, only what officials lose, and Tsegen will swear it was steppe-wolves to save his own neck.\n\nIf you ride, ride at second-watering, not first. Twenty horse will do it. Take the silk, leave the wagons burning, scatter the remounts toward Borchu's range so the trackers chase the Wolf-Khan's hoofprints and not yours. I take my own moon next quarter. There is steppe enough for two hunts. Do not be on this road when mine comes - I have been twice-banished and I do not share waterholes."),
                PactTeaseProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_1098", "You ask the long-rolls question, rider, and you ask it on open ground where no walls can hide the answer. Sit. The wind is the only listener I trust, and it has heard worse from me. A khan who has been struck twice from the rolls does not give his name away again without weighing the giver to the half-ounce.\n\nWhen I bled, I bled for a banner that is no longer flown. For the brother-khan who held my left when the rolls were first sealed against me. For the watering-stand widow who fed my horses the season after my own people spat my name into the dust. Twice my name was struck. Twice. And still I keep an oath-list of my own making, short as a winter shadow, and I add to it the way other men add a wife - rarely, and never twice the same way.\n\nRide with me where the grass goes thin. Cut a road open when the south thinks it closed. Stand beside a banner that no rolls will ever bless - mine, raised on steppe I claim by hoof and not by writ - and the long-rolls of my own keeping will learn another name. Ask again, traveler, when the wind knows you by something other than your face."),
                OathBrotherProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_1099", "Then it is spoken, and the steppe hears it. Stand by the watering-stand. Drink from my horn first - I drink second tonight, as is right when a brother is made. Take my knife - the one I carried when they struck me from the rolls, when the khanate spat my name into the long grass. Open your palm where mine still bears the old white seam. Press them together. The blood runs into the earth and the earth remembers. The horses smell it. The wind carries it east to the camps that exiled me and west to the camps that never will. There. It is done. The mare-milk is poured. Your name is in my mouth now and it tastes like my own.\n\nBrother in the steppe tongue is not a soft word. It means my saddle is your saddle. My yurt-pole holds your felt. The arrows in my quiver answer to your hand. When I was twice-banished I had no kin to ride for me - now I have you, and you have a khan who was a khan before they tore the title from him and is a khan again because he says so. Your mother is my mother. Your hunger is my hunger. My own banner, the one they tried to burn, flies for you now.\n\nThe open country knows your name. The watering-stand knows it. The lords who banished me twice will hear it on the wind and they will know a brother of Ulan rides the long grass. You are kin-by-blood to the Twice-Banished. Ride."),
                PactAnswerProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_1100", "Then it is answered. I asked once if you would bleed for me, and you did not stand here and swear it with a smooth tongue - you went out and opened a vein in the world and brought me back the proof, dripping. The deed first, the word after. That is steppe-order. A lesser man would have galloped in with a speech long as a winter and a saddle light as a fledgling. You came in heavy and spoke last. Good. The Khan I was before they struck me from the rolls would have known you on sight.\n\nHear, then, the shape of what we are now. Not brothers - that is a hearth-word, and this is a saddle-word. From this hour my riders are your riders when the horn calls, and your feud is the feud of every man who eats from my pot. When the lowland lords ride to break you, they will find steppe-bows at their flanks and no clean road home. In return I take your sword-arm in mine when MY banner - my own banner, the one they tried to burn - rises against the kingdom that twice-banished me. Blood for blood. Saddle for saddle. Called once, answered always.\n\nThe wind carries this further than any herald. It will reach the watering-stands by dawn, the long-rolls by the next moon, and the men who exiled me before the snow is off the grass. Ride hard, ally. The steel is drawn. The bond is iron."),
                TroopLoanProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_1101", "Done. Ten of my riders for seven days - I will cut them from the herd myself before the long-rolls are sung again. My second is Bayartu Iron-Stirrup, struck from the rolls beside me at Khuzait court and twice as patient with fools. He rides at your right hand. The banished know how to hold a line that is not their own. Seven days. I count them in moons, not coins.\n\nHear my terms, traveler. If a saddle-mate of mine falls under your banner, you bring me his bowstring and the name of the man who took him - I will ride out for that name myself when the loan is done. If he lives, you send him back with his horse and his honor in the same shape you found them. My riders do not draw bow for cattle-thieves or village quarrels. While they wear your dust, your war is mine - so spend them on work worth a Khan's sons.\n\nThe banished will know who borrowed them. See they have a story worth telling when the seven moons close."),
                NamedTargetAcceptProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_1102", "His name is {TARGET}, and his banner hangs over {HOME} like it has a right to the sky. It does not. Nine summers ago his riders crossed the Bokai grass while my father was at the long-rolls naming the new foals, and they took my sister Altani off the colt-line for the bride-price of a Khuzait under-lord. She hanged herself in his hall before the second moon. The under-lord paid {TARGET} in salt and silver. {TARGET} kept both. I was struck from the rolls for failing to ride after her - my own banner burned by my uncles - and {TARGET} has slept easy under nine winters of stars that owed me her name.\n\nHe rides with twelve lances and a Khuzait herald who whispers his routes to anyone with a coin and a soft word. The herald waters his horse at the well outside {HOME} every third dawn. {TARGET} hunts cranes in the marsh-flats when the wind turns south - he goes light, four guards, no scout. Take him on the marsh road. He cannot run in mud.\n\n{REWARD} denars when the herald brings me his ring, traveler. The silver is owed. The salt is owed. Altani is owed more than either, but the steppe keeps what coin cannot pay. Ride, and let the wind tell me when it is done."),
                NamedTargetReason = BandItPlus.Localization.Get("bp_cultureprofileregistry_1103", "{CHIEF} has named {TARGET} of {HOME} as the lord whose hide must answer for a banner cut down twice. The wound is old and exact - a winter raid on the Twice-Banished khan's own ger-camp on the Bokai flats, a wife and two sons dragged off in the dust, and {TARGET}'s outriders riding home with Ulan's own horsetail standard tied to a saddle-strap as trophy. The long-rolls of his fathers were struck through by men who served {TARGET}, and Ulan rides now with no clan-name behind his own. The Twice-Banished offers {REWARD} in caravan-silver for the deed. The steppe is wide. A banner waits to be answered. The contract is open."),
                NamedTargetComplete = BandItPlus.Localization.Get("bp_cultureprofileregistry_1104", "{TARGET} is dead, and {CHIEF} has been told. The long-roll has been read aloud at the felt-wall, and the name that was scratched twice with a knife-tip - the name of the lord who set Ulan's banner in the dirt at Burkhan-Tal and laughed while the heralds struck him from the clan-rolls - is read no more. {REWARD} denars sit weighed at the chief's saddle, and the debt between khan-without-a-tent and the rider who answered for him is stamped a degree closer. Ulan rides under his own banner tonight. The two banishments are answered. The steppe keeps the rest, as the steppe keeps everything."),
                NamedTargetOtherCauseProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_1105", "Word reached the ger-camp at dusk: {TARGET} was dead, run through by a rival lord's outriders on a frost-rutted road three valleys east. {CHIEF} heard it out twice, then went quiet. The long-rolls came down from the saddle-chest, and the knife-tip that had twice scratched the names of his wife and two sons - the ones dragged screaming from this very camp at Burkhan-Tal - now drew a thin third line beside them. The grudge stood answered. The killing had not been earned, though, and that mattered to a man whose pride had been banished twice already. The thin coin was counted out without ceremony: {REDUCED_REWARD} denars, quarter-pay for a quarter-debt. The bond sits a smaller notch firmer, no warmer."),
                RaidVillageAcceptProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_1106", "{VILLAGE}. Say the name again so the wind hears it. That dung-heap pays its tribute in horses and felt to {LORD}, and {LORD} sat at the council fire two winters past and watched the elders strike my name from the long-rolls. Twice they have done this to me. Twice. Once when I was a boy of nineteen and my father's herds were still warm in the grass, and again when I came back grown and asked only for a tent and a name. They voted. They drank kumis while they voted. {LORD}'s own uncle raised the cup.\n\nRide at dawn when the felt-makers are at the racks and the horse-lines are loose. Take the herds first - every mare, every gelding, every yearling foal. Burn the felt only after you have driven the horses two valleys clear. Leave the old women. Leave the shrine-pole. I want {LORD} to find his village standing and empty, his wealth on four legs running east, and his name spoken in laughter from here to the Khuzait border.\n\nWhen you bring me proof, {REWARD} is yours, weighed out in good silver and not the clipped coin the council uses. Ulan keeps his word. The council forgot that. {LORD} will remember."),
                RaidVillageReason = BandItPlus.Localization.Get("bp_cultureprofileregistry_1107", "{CHIEF} speaks the name {VILLAGE} as though spitting a stone from his teeth. It is a tributary of the Khuzait clan whose elders, sitting twice in council, voted to strike his name from the long-rolls - first when he was a boy, again when he was a man grown.\n\nTheir khan still drinks mare's milk paid in horses and felt sent up from {VILLAGE} each summer. {CHIEF} would see those tributes burned in the dust, the herds scattered, and a message carried back to that council: a name cut from the rolls is not a name silenced.\n\nHe offers {REWARD} for the village put to torch, and the silver-tongued {LORD} shamed before his elders."),
                RaidVillageComplete = BandItPlus.Localization.Get("bp_cultureprofileregistry_1108", "{VILLAGE} burned through the night, and {CHIEF} watched the felt-roofs collapse without dismounting. The horse-tribute would not reach the council that struck his name twice from the long-rolls; the felt would not warm the elders who voted him gone. {LORD}'s house had paid in horses and felt for years, and now they paid in ash. {CHIEF} took the {REWARD} from a saddlebag of a rider sent to find him, weighed the coin once, and spat into the embers. Twice-banished, he said, and twice-remembered. Let the council count their losses in the morning."),
                RaidVillageOtherCauseProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_1109", "Word reached {CHIEF} on the cold wind that {VILLAGE} was already smoke. Other riders, faster knives, had cut the throat of {LORD}'s tributary before his own hooves could mark the snow.\n\nHe sat long over the news, working a horse-hair plait between his fingers. The council that struck his name from the long-rolls a second time would hear of it by morning, and they would think their khan's felt and horse-tribute saved by some kinder hand. They would not know he had ridden against them at all.\n\n\"The mare is dead,\" he said at last, flat as old iron. \"Another wolf ate her. The meat is gone.\" He counted out {REDUCED_REWARD} without looking up, and waved the matter from his tent."),
                // 2026-05-25 rewrite: CATALOGUE-OF-MIRAGES shape. The steppe and the
                // eye are the characters; the camp is the one mirage that doesn't
                // dissolve. Lists "unbelieved" things (lake, tree, fire) in series,
                // then a single mirage that holds — that's the camp. Distinct from
                // steppe_wolves (horse-POV) which opens INSIDE the horse's senses.
                // No companion-quote, no "These were not X", no "you watched", no
                // "No, not tonight".
                HideoutCinemaIntro = BandItPlus.Localization.Get("bp_cultureprofileregistry_1110", @"The eye, out here, is a thing you stop trusting first.

By noon today you have unbelieved a lake — a real one, blue and calm, all the way to where the road met its shore and the shore became dust under your hooves. You have unbelieved a tree, twice; both trees were standing horsemen the wind had not yet reached. You have unbelieved a fire, which was nothing, a trick of sun on dry grass. The flat country owes you nothing and shows you everything, and the showing is mostly a lie.

So you do not, at first, believe the smoke.

It lifts off the rim of the world at the wrong hour for any honest fire, in the wrong colour for any kind of cookfire you have ridden up on, and you are tired enough that the eye has done worse to you before sundown. You ride toward it the way you have ridden toward every false promise the day has offered — without hope, only forward, because forward is the only direction the steppe gives you.

A mile.

Two.

The smoke holds.

A mile after that there are shapes under it. The shapes do not dissolve as you close on them. You have ridden close enough now that they should — the heat-haze should pull them apart into nothing, the way it has pulled every other dishonest shape apart today — and they do not. Three felt tents in a tight cluster. A picket-line of horses, some still saddled. Smoke that smells like real wood, not like the eye's idea of wood.

You sit your horse on the rise and you understand that the steppe has stopped lying for a moment, has held something up and let it stay solid in the heat, and that this is a courtesy the steppe pays only to the very few who live light enough to be allowed.

Below, an old man checks each picket-knot by feel. A woman packs a cook-pot away though the night is only half gone. A small girl sleeps in a saddle, certain it will carry her somewhere safer by morning.

Ulan Twice-Banished looks up from his picket-line and lifts a hand without surprise. He has been expecting somebody. He did not know it would be you.

You ride down before the steppe changes its mind."),
                ServiceLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_1111", "Buy a steppe pony."),
                ServiceFlavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_1112", "Ulan whistles. A boy brings forward three ponies. \"Cheap because we steal them. Hardy because we ride them.\""),
                Kind = ServiceKind.SteppeTrader,
                BribeAmount = 150,
                WhyNotKingdom = BandItPlus.Localization.Get("bp_cultureprofileregistry_1113", "\"Twice banished, twice free. The great khan called us small.\""),
                Religion = BandItPlus.Localization.Get("bp_cultureprofileregistry_1114", "\"Sky. Wind. Wolf.\""),
                ThreatResponse = BandItPlus.Localization.Get("bp_cultureprofileregistry_1115", "Ulan whistles. Three riders appear over the ridge with bows drawn. \"You are loud. Loud is bad here.\""),
                Pleasantry = BandItPlus.Localization.Get("bp_cultureprofileregistry_1116", "He gestures to a horse, almost smiling. \"The horse is a friend. The friend is good.\""),
                DrinkFlavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_1117", "The riders pass a skin of fermented mare's milk. Ulan drinks first. \"Old way. Honors the guest. Refuse, you insult. Accept, you're brother for the night.\""),
                RestFlavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_1118", "You sleep in the central yurt. The fire never goes out. Your party rises with the steppe-wind in their hair."),
                ExtraServices = new[] {
                    new CultureSubService { Label = BandItPlus.Localization.Get("bp_cultureprofileregistry_1119", "Trade with the yurt-maker."), Flavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_1120", "A woman lays out felt panels, leather harness, simple tools. \"Steppe goods. Light, strong, packs small. Travel-ready.\""), Kind = ServiceKind.Hunter },
                    new CultureSubService { Label = BandItPlus.Localization.Get("bp_cultureprofileregistry_1121", "Hear the old khan's wisdom."), Flavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_1122", "An ancient man, white-bearded, sits by the fire. He speaks slowly. \"Listen. Once a khan thought he was the steppe. The steppe disagreed. Same steppe, no khan.\""), Kind = ServiceKind.Oracle },
                    new CultureSubService { Label = BandItPlus.Localization.Get("bp_cultureprofileregistry_1123", "Hire a pony-breaker. (200 denars)"), Flavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_1124", "A grim-faced rider takes your horses and runs them through the steppe paces. \"Now they ride sharper. Worth the coin.\" Morale rises."), Kind = ServiceKind.VeteranHall, GoldCost = 200, MoraleGain = 3 },
                },
                Rumors = new[] {
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_1125", "\"A khan's brother was assassinated last month.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_1126", "\"The great khanate is moving its herds west again.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_1127", "\"A Khuzait trader at Akakalat fences anything for half-price.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_1128", "\"A Vlandian noble pays in gold for steppe ponies.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_1129", "\"There's a buried camp on the steppe — Khuzait dead from a winter siege long ago.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_1130", "\"A wandering shaman lives north of here. He cures horse-sickness.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_1131", "\"The grass burns hot every year now.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_1132", "\"An imperial cartographer was captured by us last year.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_1133", "\"Someone in the great clans pays for stolen horses, no questions.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_1134", "\"There's a rumored treasure-mound from the old khanate.\""),
                },
                TrustQuestTier1Pool = new[] {
                    new TrustQuest {
                        ItemIds = new[] { "sumpter_horse" }, Counts = new[] { 10 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1135", "\"Ten horses. Sound legs, sound wind. We are nothing without mounts.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1136", "He claps a hand on the lead horse. \"You ride well. The steppe knows you.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_1137", "10 horses"),
                    },
                    new TrustQuest {
                        ItemIds = new[] { "felt" }, Counts = new[] { 30 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1138", "\"Thirty felt. Yurt-cloth, saddle-padding, men's coats. We can't camp without it.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1139", "He runs his hand over the bolts. \"Properly pressed. The yurts will hold. Trade with us.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_1140", "30 felt"),
                    },
                    new TrustQuest {
                        ItemIds = new[] { "pack_camel" }, Counts = new[] { 5 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1141", "\"Five pack-camels. We range south sometimes — camels carry water where horses fail.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1142", "He pats the lead camel. \"Strong-back beasts. The deep south is reachable now.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_1143", "5 pack camels"),
                    },
                },
                TrustQuestTier2Pool = new[] {
                    new TrustQuest {
                        ItemIds = new[] { "sumpter_horse" }, Counts = new[] { 25 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1144", "\"Twenty-five horses. A whole new herd. Bring them, and the open country is yours to ride.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1145", "He runs his hand through the lead mare's mane. \"Magnificent stock. The steppe rides with you.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_1146", "25 horses"),
                    },
                    new TrustQuest {
                        ItemIds = new[] { "sumpter_horse", "pack_camel" }, Counts = new[] { 15, 5 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1147", "\"Fifteen horses and five camels. Mixed string for the long-range raid into the deep south.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1148", "He inspects the mixed string. \"This rides as far as the spice country. Take what you need.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_1149", "15 horses + 5 camels"),
                    },
                    new TrustQuest {
                        ItemIds = new[] { "felt", "sumpter_horse" }, Counts = new[] { 50, 10 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1150", "\"Fifty felt and ten horses. Full re-mount and re-yurt for the cold-camp shift.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1151", "He surveys the camp shrugging into new walls. \"Now we overwinter strong. Take what you need.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_1152", "50 felt + 10 horses"),
                    },
                },
                TrustQuestTier3Pool = new[] {
                    new TrustQuest {
                        ItemIds = new[] { "t2_khuzait_horse", "sumpter_horse" }, Counts = new[] { 5, 30 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1153", "\"Five Khuzait war-mounts and thirty pack-horses. The clan goes to war this spring. Only blood-kin help us mount the cohort.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1154", "He bows his head, the steppe-warrior's salute. \"You have remounted us for war. Ride beside me, brother.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_1155", "5 war horses + 30 horses"),
                    },
                    new TrustQuest {
                        ItemIds = new[] { "felt", "sumpter_horse", "pack_camel" }, Counts = new[] { 100, 30, 10 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1156", "\"A hundred felt, thirty horses, ten camels. We're moving the whole clan across the steppe to a new winter range.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1157", "He clasps your shoulder steppe-style. \"The whole clan survives because of you. The steppe sings your name.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_1158", "100 felt + 30 horses + 10 camels"),
                    },
                },
                // Wave 5 (Chief Recruitment) alliance content
                AllianceCh1TaskBrief = BandItPlus.Localization.Get("bp_cultureprofileregistry_1159", "Burn the standing-stone marker of the clan that exiled Ulan — destroy the small honor-guard patrolling the site."),
                AllianceCh1Pattern = AllianceCh1Pattern.DestroyPartiesOfType,
                AllianceCh1TargetSeedHint = "ulan_exile_marker_honorguard",
                AllianceCh3RitualText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1160", "The Ulan Twice-Banished accepts your oath; the rite is sealed solo, three arrows shot into the exile-marker on horseback alone, then once around the stone."),
                AllianceCh3GiftItemId = "compound_bow_steppe",
                AllianceBrokenText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1161", "Ulan looses one arrow at the dust beside your foot. \"The marker is yours and mine no longer. Ride. The next arrow finds higher.\""),
