            { "sea_raiders", new CultureProfile {
                ChiefName = BandItPlus.Localization.Get("bp_cultureprofileregistry_1162", "Bjornulf Salt-Tongue"),
                Signature = new SignatureQuestSpec
                {
                    Title = BandItPlus.Localization.Get("bp_cultureprofileregistry_1163", "The Shore-Price"),
                    HeraldLine = BandItPlus.Localization.Get("bp_cultureprofileregistry_1164", "Oi — you the captain's landwalker? Good. He's in a black mood. Some harbor-rat impounded a beached keel and sold the crew's shares at auction. The silver's rolling inland on a wagon right now. Go hear him before he bites somebody."),
                    OfferProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_1165", "You know what a share is, landwalker? It is not coin. It is the oath made countable. The Herring-Bane crew — nine oars, good men — beached on a storm-tide and walked to harbor for timber. The harbormaster impounded their keel and auctioned their shares off the quay like salvage. Like they were drowned already. Now a pay-wagon hauls that silver inland under guard, his factor at the head of it, counting what is not his. Bring the crew's silver home — every clipped coin. I keep maybe half my oaths, traveler. Ask anyone. But I swore on the salt that nine men get their cut, and this is the half I keep."),
                    AcceptProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_1166", "Good. The wagon rolls slow — silver is heavy and so is guilt. His factor holds the key and thinks paper is armor. Bring me the box whole. I weigh the shares out myself, on sail-cloth, the old way."),
                    DeclineNudge = BandItPlus.Localization.Get("bp_cultureprofileregistry_1167", "No? Then drink slower and think on it, traveler. A share stolen from one crew is stolen from every crew that ever pulled an oar for me. The wagon rolls while you chew."),
                    BusyLine = BandItPlus.Localization.Get("bp_cultureprofileregistry_1168", "One tide at a time, landwalker. You carry my errand already — finish it, then we talk shares."),
                    TargetPartyName = BandItPlus.Localization.Get("bp_cultureprofileregistry_1169", "Harbormaster's Pay-Wagon"),
                    CaptainName = BandItPlus.Localization.Get("bp_cultureprofileregistry_1170", "Harbormaster's Factor"),
                    JournalObjectiveText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1171", "Intercept the harbormaster's pay-wagon on the inland road and recover the strongbox of auctioned crew shares. The column is led by the harbormaster's factor."),
                    JournalReturnText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1172", "The strongbox is recovered. Return the silver to Bjornulf Salt-Tongue so the shares can be paid out to the beached crew."),
                    ConfrontIntro = BandItPlus.Localization.Get("bp_cultureprofileregistry_1173", "This consignment travels under the harbor seal — lawful salvage, assessed and auctioned. If you have a grievance, the office hears petitions on quarter-days. Stand away from the wagon."),
                    Choices = new[]
                    {
                        new SignatureChoice { Label = BandItPlus.Localization.Get("bp_cultureprofileregistry_1174", "That silver is crew shares. Hand down the box and keep breathing."), Requirement = SignatureRequirement.StrengthRatio, RequirementValue = 120, Outcome = SignatureOutcome.ComplyFull, ResultProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_1175", "I — yes. Under protest — recorded protest. Guards, ground your spears. The key is — here, the key, take it. I will enter it in the ledger as seized by force of arms. Which it is. Which it plainly is.") },
                        new SignatureChoice { Label = BandItPlus.Localization.Get("bp_cultureprofileregistry_1176", "The salt does not file petitions. Draw."), Outcome = SignatureOutcome.Battle, ResultProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_1177", "Guards! Guards, to the wagon — spears, form on the — kill them, kill them now!") },
                    },
                    DemandFailProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_1178", "No. No, I think not. I have counted your riders and I have counted my escort, and mine is the longer column. The consignment proceeds. Go back to your beach."),
                    ClosingProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_1179", "Sail-cloth on the shingle, landwalker — nine piles, weighed twice against the mast-tally. Watch my hands, all of you. Watch that nothing sticks. A share is the oath made countable. The salt heard me swear it; now it hears it paid. Your cut pours last and pours full. Drink with us — the Herring-Bane crew owes you a song, and I intend to make them sing it badly and long."),
                    ClosingProseOtherCause = BandItPlus.Localization.Get("bp_cultureprofileregistry_1180", "An inland crew broke the box before you reached it, landwalker — what washed back is half, gathered coin by coin out of ditches and taverns. Nine thin piles tonight, weighed the same as fat ones. The sea robs clean. Only a landsman robs a robbed man twice. Half shares for you as well — the salt keeps its arithmetic even when thieves don't."),
                    RewardGold = 1200,
                    RewardRelation = 8,
                    BattleLootGold = 1200,
                },
                ChiefTitle = BandItPlus.Localization.Get("bp_cultureprofileregistry_1181", "Salt-Tongue Captain"),
                // 2026-06-03 quest-prose flagship — Bjornulf's distinctive voice overrides
                // the sea_raiders mould at Layer 1. Signature: openly admits the lies his
                // epithet implies, names specific lost crews (Gull-Throat, Sea-Wolf), treats
                // the alliance as another oath he might break, talks about words vs silence.
                AllianceCh1AcceptProse =
                    "\"Sit, then. You crossed my pickets without a blade between your ribs, which means someone in my crew lied for you, or I did, and Bjornulf Salt-Tongue does not always remember which.\n\n"
                    + "Twenty-five days. That is the rope I am paying out. In that span you bring me a kill, a worthy one — the kind a captain admits to over ale and lies about over salt. Refuse, and I will swear you safe passage with my warmest grin. Ask the Sea-Wolf crew how that oath aged.\n\n"
                    + "Words are wind. Today, mine bind. Tomorrow we shall see.\"",
                AllianceCh1HuntBriefProse =
                    "\"My oar-runners came in wet and grinning at the third tide. {PARTY_NAME}, {ARTICLE} {CULTURE} {KIND}, has fouled itself on the shingle near {AREA}, drunk on its own swagger.\n\n"
                    + "I lost the Gull-Throat to that stretch of coast two winters back — thirty good men and a boy who could not yet grow a beard. So I have a personal interest in who walks home from it now. You will see they do not.\n\n"
                    + "Do not parley. Do not let them speak. A man like me knows what tongues are for, and theirs are for silence.\"",
                AllianceMidQuestUpgradeProse =
                    "\"The old mark slipped my net — the sea took them, or a better liar than me did. No matter. Take {PARTY_NAME} instead, {ARTICLE} {CULTURE} {KIND} loitering near {AREA}. I owe them a silence too.\"",
                AllianceCh2AdvanceProse =
                    "\"You came back. I half-expected a gull bearing your tongue in its beak, and instead here you stand, dripping somebody else's blood. A pleasant surprise, and I do not get many.\n\n"
                    + "The news outran your horse. A {CULTURE} captain face-down in the surf, his crew scattered like spilled herring. I told my second you would turn coward at the half-mark. He has my belt-knife now, and I have a fresh lesson in the cost of underestimating quiet men.\n\n"
                    + "Come to {HIDEOUT} after the watch-fires bank. There are oaths to swear, and you should hear how I swear them before you trust the next one.\"",
                ChiefBackstory = BandItPlus.Localization.Get("bp_cultureprofileregistry_1182", "Bjornulf was a fjord-fisherman's son in a Sturgian coastal village so small the imperial maps did not record its name. He went to sea at eight as a netting-boy on his father's two-thwart skiff, and by fifteen he was crewing a longship out of a different fjord, having sworn off his father's business after his father drowned drunkenly in three feet of harbour-water. His first raid was with a Sturgian crown-licensed corsair against an imperial salt-shipment; his second was the same corsair, against the same crown, after the corsair stopped paying his shares. Bjornulf took the longship in the harbour with five other crewmen, sailed it south, and has been raiding ever since under no flag he did not paint himself. He speaks five languages badly and signs three of them properly; the sea is his only good language, and his crews speak it fluently regardless of where they were born. His longships have raided the imperial coast for so long the Sturgian crown stopped acknowledging he ever existed — easier than admitting they cannot catch him. The Empire makes no such pretense; they have placed a bounty of fifteen thousand denars on his head, twelve thousand on his Salt-Tongue cousin, and eight thousand on the longship that was once theirs."),
                ClanHistory = BandItPlus.Localization.Get("bp_cultureprofileregistry_1183", "The Sea Raiders are the oldest organized bandit-line in the modern kingdoms — a thread of fjord-raiders whose family-rolls run unbroken through six imperial reigns, four Sturgian crown-changes, and one full inter-kingdom war. Bjornulf's great-great-grandfather rowed the same coast Bjornulf rows now, and the longboat-keels he hauls onto the beach are built from the same stand of pine his ancestors timber-stamped a century and a half ago. Coastal fjord-villages supply the core of the band — second sons of fishing families with no boat to inherit, displaced shore-men whose harbors were taxed past sustainability, and the occasional Battanian fisher who could not abide a Vlandian harbor-master. They strike inland from the coast — never far, but far enough that the inland lords cannot quite credit what is happening. They do not raid villages they have raided in the same year; the Salt-Tongue Code, which Bjornulf inherited and his great-great-grandfather wrote, forbids it. The Sturgian crown has used them as auxiliaries in two coastal wars and disowned them in three. Among the coastal villages they are half-feared, half-counted-on — the way every coastal village half-counts on the sea itself."),
                ChiefGreeting = BandItPlus.Localization.Get("bp_cultureprofileregistry_1184", "The longhall falls silent when you push past the door-leather. The huge man at the high seat — beard bleached to driftwood-grey by salt and seasons — looks up from a horn of mead. His grin comes slow, the grin of a man amused that another fool has wandered into his hall. \"A landwalker! And alive, even! Bjornulf has not seen one walk in unblooded since the snows came. Speak quick, traveler — my mead grows cold, and so does my mood.\""),
                ChiefGreetingTolerated = BandItPlus.Localization.Get("bp_cultureprofileregistry_1185", "The longhall does not fall silent for you anymore. Mead-horns tilt in your direction, a few crewmen call out names you haven't yet learned. Bjornulf himself rises this time, salt-bleached beard split by a grin that has actual amusement in it. \"The landwalker returns! Twice past my door is a season's worth of luck, traveler. Sit, sit — Bjornulf pours for those his hall counts as half-friend now.\""),
                ChiefLoyaltySpeech = BandItPlus.Localization.Get("bp_cultureprofileregistry_1186", "Bjornulf hears names every tide-fall, landwalker. Names wash up and wash out with the wrack. Crew-names — those carve into the longhall posts and stay. Earn yours. There's an errand my crew would have you run. Do it, and your name goes on Bjornulf's posts; not before."),
                CampIntro = BandItPlus.Localization.Get("bp_cultureprofileregistry_1187", "The Sea Raiders' camp is on the beach — longboats hauled up on rollers, tents made of sail-cloth. The smell is fish, tar, and seaweed."),
                HideoutDirections = BandItPlus.Localization.Get("bp_cultureprofileregistry_1188", "Follow the coast road north out of Varcheg until the shingle turns black under your boots and the gulls get loud enough to drown your own thinking. Half a tide on you'll smell us before you see us - fish-rack drying split cod on the wind, tar-smoke off the keels, the iron pot we keep wedged in the beach-stones never quite off the boil. Our hold lies at {HIDEOUT_NAME}, tucked behind a fold of cliff that the tide-charts pretend isn't there. Walk past the sail-cloth tents above the high-water line and you've already walked in.\n\nMy boys watch from the headland with the longboats hauled up on rollers behind them. They'll have your shape against the surf-line a good mile before you've smelled the cod. Come down the shingle slow, hands where a bowman can count your fingers, and shout my name into the wind - Bjornulf, loud, like you mean it. The gulls will carry it before you do.\n\nCome creeping along the cliff-tops instead and the sea gets your bones before my lads do - we shove the wrong sort off the rocks and let the tide do the bookkeeping. Come the right way and there's a seat by the pot, salt-fish in your hand, and a story owed both directions. Sit. Drink. We'll talk."),
                ScoutsLordsProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_1189", "Hah! The Sturgian boyars send their levy-boys down the coast road each spring, all wool cloaks and frozen toes, and we pluck them like cod from a weir. Prince Raganvad's vassals hold Varcheg above us - one of his housecarls, a thick-necked oaf calling himself Lord Stanimir, has sworn three times this year to burn my cove. Three times he marched. Three times he found nothing but gull-shit and a cold fire-pit. My boys row out the back channel before his boots crunch the shingle. The storm hides what the cliffs don't.\n\nThe Vlandians come too, by sea, the fool bastards. Some count's outriders sailing up from Ocs Hall thinking the northern fjords are open trade - we sank a cog of theirs last moon and her belly was full of southern wine. Drank it dry around this very fire. The Empire's tax-galleys stay south where the water is warm; they know better than to point a prow at our weather.\n\nIf you ride under a Sturgian banner, friend, the boyars will know your face from the ledgers before they know your name. Stanimir keeps a long memory and a longer rope. Sail under no banner at all and the coast is yours - the cod don't care whose coin you carry, and neither do I."),
                ScoutsClanProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_1190", "Hah! Sit closer, the wind off the cove will steal half my words and the cod-gulls the rest. You ask who I respect? Few. Vargolf Iron-eyed of the Frost Reavers - him I respect. He sent word last moon that my warbands crossed the Pravend road one too many times, and he is right, the bastard. I owe him a longboat of mead and a quiet talk before the thaw, or he rides north to my cove and we settle it in the old way, axe and oar. I would rather drink with him than bleed with him. Both end the same.\n\nThe Sky Raiders up in the crags - Aerlin's lot - they hunt the same Sturgian caravans I do, and that grates. We have not bled yet, but a season more of empty nets and we will. Granny Hod's forest band keeps to the deep timber west of here and stays clear of salt water, which is the only thing that keeps her old bones whole. The Highwaymen of the downs? I do not know their Reeve and I do not want to. Land-rats counting coppers.\n\nWhat my scouts brought back is this - the Marsh Stalkers have gone quiet down south, and quiet Stalkers means a knife is being sharpened somewhere. Mark it."),
                ScoutsCaravanProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_1191", "Listen close, landsman, and hear how the cod swims. Every third week a Sturgian fur-train rolls down the coast road from Revyl bound for Varcheg - eight wagons heavy with sable and walrus-tusk, sixteen boyar-spears wrapped in wolf-cloak, and a captain who drinks more mead than a wedding-priest. They camp at the salt-marsh ford because the boyar-fool thinks the bog at his back is a wall. It is not a wall. It is my front door, and my boys swim it like otters in milk.\n\nThe trick, friend, is the dusk-hour. Their outriders ride wide at noon, tight at dawn, but at dusk they bunch by the fires because Sturgians fear the dark like children fear the cellar. Hit them then with thirty horse coming down the dune-spine and they break before the second wagon catches fire. The sable goes for a king's ransom in Pravend - Vlandian merchants pay double because they cannot trap the beasts themselves.\n\nThere is also a Khuzait silk-runner who threads the Varcheg quay every new moon, paying off the harbour-master in Aserai gold. Him you can BUY, not bleed. Slip him forty dinars and he tells you which hold carries the silk and which carries the salt-pork. Take the silk, leave the pork, and the longboats never even wet their oars. That is how cod swims, traveler. Mouth-first."),
                PactTeaseProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_1192", "Ha! There it is - the oath-question, dropped at my fire like a stone in a still bay. You think I have not heard it before? I have. From men who choked on the asking and men who sang it drunk. The salt knows which is which, and the salt remembers longer than any of us. Sit. Drink. Let me weigh you the way the long-keel weighs a wave.\n\nWhen Bjornulf bleeds, he bleeds for names cut into the mast of the Salt-Sister - my first keel, gone now to a southern reef. Eirik Broken-Tooth, my shield-brother since we were boys hauling nets at Varcheg. Old Hilde who pulled my mother screaming from the ice the winter I was born. Two oar-mates from the Pravend run who took spears that should have been mine. That is the oath-cup, friend. It is small. It is full. It does not pour easy.\n\nYou are not yet a name on my mast. But the timber has room. Bring me a deed the cove will sing about - a galley taken, a southern lord's gold pried loose, a wreckers' beacon doused before it killed kin of mine - and we will share mead-share proper. Until then, the long-keel runs and you run beside it. Ask me again when the salt has tasted your work."),
                OathBrotherProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_1193", "Then by the salt and the storm, it is done. Stand up off that wet stone, brother, and drink - the oath-cup is full and the mead is mine and what is mine is yours from the keel up. Here - take my knife. Open your palm where mine bears the old grin from the night we burned the Varcheg pier and I swore on a dead man's mast I would never sail alone again. Press the cuts. Let the blood drip into the cup. Now we both drink - you first, then me - and the salt knows, brother, the salt knows. The long-keel under our feet just learned your name and the gulls overhead are already screaming it.\n\nShield-brother means this: my mead is your mead, my crew is your crew, my feud is your feud. When the Sturgian boyars send their riders south I row with you. When the lowland lords come hunting your hide the Salt-Tongue's oar-bench rows for you. We share the cup, we share the storm, we share the gallows if it comes to that - and laugh on the way up.\n\nFrom this tide forward you are blood of Bjornulf, kin of the hidden cove, hearth-mate of every man on this long-keel. Varcheg will hear it. The boyar of Revyl will hear it and his bowels will turn. The salt knows, the storm knows, the dead at the pier know. Brother - drink deep. The sea has two of us now."),
                PactAnswerProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_1194", "Hah! You answered with the deed first and the words after, the way a long-keel answers a storm - prow into the wave, mouth shut till the spray clears. I asked once if you would bleed for me, and you went off and bled before I had finished pouring the cup. The salt knows that order. The salt remembers when Old Hrothgar, my shield-brother, gave me a split lip and a longboat the same afternoon - deed first, jest after. You stand in his shadow now, and he was no small man.\n\nSo hear MY answer, loud, the way the cove hears the surf. From this tide forward, when you raise your banner, my long-keels put to oar. Not for coin. Not for a share of the hold. As blood-allies - your feud is my feud, your hunters are my hunters, and any lord who carves your name onto his blade carves mine beside it. You give me passage when the Sturgian shore turns cold against me, and a share of the salt when the season is fat. That is the bond. Mead-share, steel-share, grave-share if it comes to it.\n\nThe wind carries this oath now, shield-brother - down the coast, past Varcheg, into every cove that knows my flag. When steel is drawn, the storm-mouths will sing your name beside mine. Ride loud. The salt has heard us."),
                TroopLoanProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_1195", "Aye, done and salted! Ten of my oar-men for seven tides of the sun - I will cull them off the strand myself before the gulls roost. My second is Hrolfi Brine-Beard, a shield-brother who has chewed more salt than you have drunk ale. He rides at your shoulder and speaks my mouth. If a cove-boy of mine drops in the muck of your fight, you bring his axe back wet or dry, I do not care which. If he lives, you bring him back hoarse and stinking of someone else's mead.\n\nHear me plain, traveler - my shield-brothers do not break the wall for coin or for whim. They break it because Salt-Tongue set them to it, and while they answer your horn your work is the cove's work. Do not piss them away on roadside scuffles and stray dogs. Seven days. I count tides, not promises.\n\nThe whole strand will know ten of mine rode out under your banner. The whole strand will be watching the horizon for their return."),
                NamedTargetAcceptProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_1196", "Hark and drink slow, stranger, for the name is heavy. {TARGET}. He keeps his rotted banner over {HOME}, the same shore my long-keel beached at nine summers gone with my shield-brother Hrolf laid across the oar-bench, gut-split. {TARGET}'s coast-watchers met us in the surf with fire-arrows and a priest who blessed the burning. Hrolf and I had shared the oath-cup since we were boys cutting our first salt-teeth. That whoreson watched my brother cook in the wrack and laughed from his cliff. I have drunk to that laugh every winter since, and the mead has gone sour in my mouth.\n\nHe rides the coast road twice a moon to count his fishing rents, four lances and a turncoat Nord called Asbjorn who owes my cousin a debt the cousin will forgive for the right cup. Buy Asbjorn three horns of mead at the Tyal crossing and he will piss out his master's bed-hour. {TARGET} sleeps fat after the rent-counting. Take him then, before the cock sings.\n\n{REWARD} denars when his head salts in my cellar, shield-brother. The mead-share waits, and so does Hrolf's shade. Ride hard, and the long-keel keeps the rest."),
                NamedTargetReason = BandItPlus.Localization.Get("bp_cultureprofileregistry_1197", "{CHIEF} has named {TARGET} of {HOME} as the man whose throat the long-keel was launched for. The grudge is salt-deep and specific - a shield-brother named Hrothgar drowned in a weighted net off the Skerry of Broken Oars, sunk on {TARGET}'s order after a tally-dispute over plundered grain that was never plunder at all but honest oath-coin. {CHIEF} swore at the oath-cup that day, mead spilled on the strake, that the man who weighted that net would be hauled up by his own ribs. The Storm-Mouth offers a heavy purse of {REWARD} and the closing of a debt the sea itself has been holding. The keel is wet. The oars are counted. The contract is open."),
                NamedTargetComplete = BandItPlus.Localization.Get("bp_cultureprofileregistry_1198", "{TARGET} is dead, and {CHIEF} has heard it spoken across the oath-cup. The long-keel Saelvarg, burned to her waterline off the Pelegir skerries seven winters past, has been answered for - and Halvard Storm-foot, shield-brother dragged under by the chain-net that bloody dawn, can rest now that the noble who ordered the trap is meat for the gulls. {REWARD} denars sit heavy at the mead-share, counted twice by salt-stained fingers. The bond between Salt-Tongue and the traveler-killer is stamped a fathom deeper. The long-keel's name is sung whole again, and the tide takes the rest."),
                NamedTargetOtherCauseProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_1199", "Word reached the salt-camp on a gull-bitten morning that {TARGET} was already cold meat - waylaid on some inland road by a rival lord's outriders, throat opened in a ditch far from any tide. {CHIEF} heard it out, then spat into the surf and stood a long while staring at the burnt ribs of the Saelvarg where she still lay rotting on the strand. Halvard Storm-foot was no closer to peace under the waves for a kill done by other hands. The grudge is technically answered - the bastard breathes no more - but the chief wanted the chain-net repaid by the one he'd sworn the iron to, not gifted by some stranger's blade. He counted out {REDUCED_REWARD} denars in thin coin, quarter-pay for a quarter-done thing, and clapped a shoulder without warmth. The bond stands a notch firmer, but cooler - salt without the fire."),
                RaidVillageAcceptProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_1200", "By the brine in my beard and the salt in my teeth, you came at the right tide! {VILLAGE} - that's the grain-fat little hovel under {LORD}, a Sturgian fence-clan that twice now refused to launder my plundered cargo. Two seasons running, you hear? Two! And the second time, the swine tipped off a boyar's outriders who chased my long-keels halfway down the coast. I lost three good rowers and a chest of Aserai silks to those inland rats. They thought the sea wouldn't reach them. The sea reaches everywhere.\n\nHere's the cut of it: ride at midnight, the village sits soft a half-day inland with no palisade worth the name and no watch worth the wages. Take the granary, take the smoked fish, take the iron tools. Leave the women and the wells - I'm a raider, not a butcher, and I want them rebuilding so I can come back and gut them again next harvest. Fire the headman's hall on your way out, that's the message.\n\nDo this clean and {REWARD} denars sloshes into your purse, by the foam and the foul wind I swear it. Bring me ash on your boots and the smell of burning thatch in your cloak, and I'll pour the first horn myself. Now go, before the tide turns soft on us!"),
                RaidVillageReason = BandItPlus.Localization.Get("bp_cultureprofileregistry_1201", "{CHIEF} spat the name {VILLAGE} across the longhouse board like a mouthful of bilge-water. Two seasons running, he roared, the fence-merchants of that inland Sturgian rat-warren had turned up their noses at honest plundered cargo, and worse, two seasons running they had whispered to a boyar's outriders the moment his keels touched silt. The grain-village under {LORD} sat soft and undefended a half-day inland, fat at midnight, and Bjornulf Salt-Tongue meant to see its thatch burn before the next tide.\n\nHe wanted a blade he had not already bought. {REWARD} in good silver if the torches went up before dawn."),
                RaidVillageComplete = BandItPlus.Localization.Get("bp_cultureprofileregistry_1202", "{VILLAGE} burns behind the raiders, its grain-sheds gutted, its fences kindling, its midnight quiet broken into a long red howl that {CHIEF} drinks like ale. Two seasons of fence-merchants laughing at honest plunder, two seasons of {LORD}'s boyar-bought outriders sniffing the coast - the salt has its answer now, and the answer is ash. The Sea Raider spits over the smoking thatch, hauls the cargo none of those inland weasels would launder, and counts {REWARD} into the player's palm with a storm-mouthed laugh. Debt closed. Tongue salted. Tide paid."),
                RaidVillageOtherCauseProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_1203", "Word washes up the coast that {VILLAGE} is a black smear in the dirt, torched by some other crew before {CHIEF} could put a keel to the river. Bjornulf Salt-Tongue spits, laughs the short laugh, and pours a horn anyway. Two seasons those inland weasels turned his cargo away at the fence-stalls and whispered the boyar's outriders onto his trail - now the gulls pick at their grain-pits and it was not his blade that did it. Cold comfort, he says, is still comfort. {LORD} is told the storm came without him; the purse is lighter for it.\n\n{CHIEF} pays {REDUCED_REWARD} - a finder's cut for pointing the wind, not a raider's share."),
                // 2026-05-25 rewrite: TIDAL / CYCLIC shape. The sea breathes in /
                // Hold / The sea breathes out is the structuring refrain — each
                // beat reveals a piece of the camp. The sea owns the prose cadence
                // itself; the player breathes on its count by the third stanza.
                // The chief nods on an exhale; the player descends on an in-breath.
                // No companion-quote, no "These were not X" template, no "you
                // watched", no "No, not tonight" refusal.
                HideoutCinemaIntro = BandItPlus.Localization.Get("bp_cultureprofileregistry_1204", @"The sea breathes in.

You hear it from the headland — the long whole rattle of stones turning over stones as the water draws back down the shingle, every pebble taking its small place in the count, the noise so old it has worn its own meaning out of the words men use for it. The sea breathes in. You stop your horse to let it.

Hold.

The sea breathes out. The swell rises and lays itself down on the strand and the same stones knock the other way. Salt mist comes off the break and rides up the headland and beads grey on your horse's mane. You take a breath without thinking. You take it on the sea's count.

The sea breathes in.

Out along the strand below — visible only because the moon has cleared a cloud, and only for as long as it stays cleared — a longship sits canted on the shingle, dragon-head black against the paler dark, strakes still wet from the work it was at an hour ago. A working ship. A ship come home tonight with the salt fresh on it. A cloud takes the moon back. The ship is dark again.

Hold.

The sea breathes out. The cloud thins. Now there are fires on the strand, low driftwood-fires sheltered in the lee of the hulls, and figures moving slow between them, and the smell of tar and brine and burning oak comes up the headland on the same breath. The sea will show you the camp at its own pace. It will not be hurried.

The sea breathes in.

You are breathing on the sea's count. You did not choose to. You realize, dimly, that you have been breathing on the sea's count since you stopped your horse. This is what the coast does to a man who does not belong to it. The coast does not ask you to belong. It only asks you to keep time.

Hold.

The sea breathes out. An old raider on the strand looks up from the fish-bone he is carving and meets your eye across the long fall of dune. He does not stand. He nods once. The nod is part of the breath — it falls on the exhale, the way the tide falls. He waits for the next in-breath to see what you will do.

The sea breathes in.

You go down to him."),
                ServiceLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_1205", "Buy or sell with the smuggler."),
                ServiceFlavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_1206", "Bjornulf claps a small ship-chest open. \"What we don't want, we trade. What you don't want, we'll buy.\""),
                Kind = ServiceKind.CoastalSmuggler,
                BribeAmount = 200,
                WhyNotKingdom = BandItPlus.Localization.Get("bp_cultureprofileregistry_1207", "\"A king's law ends at the shore. Past the shore is our law.\""),
                Religion = BandItPlus.Localization.Get("bp_cultureprofileregistry_1208", "\"Sea-fathers and storm-mothers. Old gods of the cold water.\""),
                ThreatResponse = BandItPlus.Localization.Get("bp_cultureprofileregistry_1209", "Bjornulf laughs, big enough to scare gulls. \"My grandfather killed a kraken with a knife! And you threaten ME?\""),
                Pleasantry = BandItPlus.Localization.Get("bp_cultureprofileregistry_1210", "He spreads his arms. \"It is good, yes? Sea, sand, sail.\""),
                DrinkFlavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_1211", "Bjornulf cracks open a barrel of mead with his fist. \"From the southern jarls' own brewery. We took the whole shipment. Drink, landwalker, drink!\""),
                RestFlavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_1212", "You sleep under sail-cloth, the surf hissing nearby. Your party wakes salt-touched and hungry for breakfast."),
                ExtraServices = new[] {
                    new CultureSubService { Label = BandItPlus.Localization.Get("bp_cultureprofileregistry_1213", "Listen to the storm-caller."), Flavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_1214", "An old man with a beard like white kelp gestures you closer. \"Storms speak. Most don't listen. I listen. The sea has news.\""), Kind = ServiceKind.Oracle },
                    new CultureSubService { Label = BandItPlus.Localization.Get("bp_cultureprofileregistry_1215", "Trade with the sail-maker."), Flavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_1216", "A woman with stained hands sews sail-cloth. \"Sail, rope, hooks, salted fish. Sea goods. Cheap because we make our own.\""), Kind = ServiceKind.Hunter },
                    new CultureSubService { Label = BandItPlus.Localization.Get("bp_cultureprofileregistry_1217", "Drink with the longboat crew. (100 denars)"), Flavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_1218", "The whole crew gathers around the fire. They sing the old songs — long, off-key, joyful. Your party joins in. They never sing the same song twice. Morale climbs."), Kind = ServiceKind.VeteranHall, GoldCost = 100, MoraleGain = 5 },
                },
                Rumors = new[] {
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_1219", "\"A Sturgian galley sank in the bay last month. Most cargo is still on the bottom.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_1220", "\"The imperial navy patrol changes every fortnight.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_1221", "\"A merchant prince in Quyaz wants ten chests of northern amber.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_1222", "\"A Battanian noble was lost overboard near here last winter.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_1223", "\"There's a smuggler's cave a day's sail north — used for two centuries.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_1224", "\"A Vlandian count's daughter was secretly shipped to Aserai.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_1225", "\"The old gods of the sea still take offerings.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_1226", "\"An imperial fleet captain is corrupt. We supply him.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_1227", "\"A drowned village lies a mile out — Sturgian, lost to a storm.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_1228", "\"The southern desert sultan has banned northern goods.\""),
                },
                TrustQuestTier1Pool = new[] {
                    new TrustQuest {
                        ItemIds = new[] { "fish" }, Counts = new[] { 30 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1229", "\"Thirty fish. The sea provides, but our cellars run low between raids.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1230", "He sniffs a barrel. \"Salt-cured well. You learned from real fishermen. Trade with us.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_1231", "30 fish"),
                    },
                    new TrustQuest {
                        ItemIds = new[] { "walrus_tusk" }, Counts = new[] { 20 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1232", "\"Twenty walrus-tusk. The carvers in the north pay handsomely, and we trade north as well as raid south.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1233", "He weighs a tusk. \"Heavy ivory. The carvers will sing your praises. Trade.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_1234", "20 walrus tusks"),
                    },
                    new TrustQuest {
                        ItemIds = new[] { "whale_oil" }, Counts = new[] { 25 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1235", "\"Twenty-five whale-oil. The longships need it for caulking, the lamps need it for the dark months. Bring it.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1236", "He uncorks a flask, smells it. \"Pure rendering. The hulls will hold another season.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_1237", "25 whale oil"),
                    },
                },
                TrustQuestTier2Pool = new[] {
                    new TrustQuest {
                        ItemIds = new[] { "fish", "hardwood" }, Counts = new[] { 100, 30 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1238", "\"A hundred fish and thirty hardwood. Fish for the winter store, wood for hull-patches.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1239", "He claps a fresh plank. \"Boatbuilders' wood. Salt-fish for the dark months. You're a son of the cold sea.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_1240", "100 fish + 30 hardwood"),
                    },
                    new TrustQuest {
                        ItemIds = new[] { "walrus_tusk", "fish" }, Counts = new[] { 50, 30 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1241", "\"Fifty walrus-tusk and thirty fish. The northern trade-run leaves on the new moon. Bring both for the run.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1242", "He nods at the loaded longship. \"The northern carvers feast tonight. The cold-sea is open to you.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_1243", "50 tusks + 30 fish"),
                    },
                    new TrustQuest {
                        ItemIds = new[] { "fish", "whale_oil" }, Counts = new[] { 80, 20 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1244", "\"Eighty fish and twenty whale-oil. We re-stock the cold-house and re-caulk the fleet before the autumn raid south. Bring both.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1245", "He surveys the fleet readying. \"Sea-worthy. We raid south better-fed and tighter-hulled because of you.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_1246", "80 fish + 20 whale oil"),
                    },
                },
                TrustQuestTier3Pool = new[] {
                    new TrustQuest {
                        ItemIds = new[] { "fish", "hardwood", "walrus_tusk" }, Counts = new[] { 200, 50, 30 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1247", "\"Two hundred fish, fifty hardwood, thirty walrus-tusk. The full longship-fleet readies for the great raid down the imperial coast. Outfit us.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1248", "He stands at the prow of the lead-ship. \"You launched the fleet that broke the empire's coast. The north sings your name.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_1249", "200 fish + 50 hardwood + 30 tusks"),
                    },
                    new TrustQuest {
                        ItemIds = new[] { "walrus_tusk", "whale_oil", "salt" }, Counts = new[] { 100, 50, 30 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1250", "\"A hundred walrus-tusk, fifty whale-oil, thirty salt. The greatest northern trade-load this fjord has ever sent. Bring it all.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1251", "He claps your shoulder, an old sea-captain's blessing. \"The cold-northern halls open to you. You walk in firelight wherever Sturgian iron rings.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_1252", "100 tusks + 50 whale oil + 30 salt"),
                    },
                },
                // Wave 5 (Chief Recruitment) alliance content
                AllianceCh1TaskBrief = BandItPlus.Localization.Get("bp_cultureprofileregistry_1253", "Raid the marked coastal village's tribute caravan — take the salt and silver before the tide turns."),
                AllianceCh1Pattern = AllianceCh1Pattern.RaidVillagesOfClan,
                AllianceCh1TargetSeedHint = "sea_raider_coastal_village_marked",
                AllianceCh3RitualText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1254", "The Bjornulf Salt-Tongue accepts your oath; the rite is sealed in salt — a lick on the tongue, a swallow of cold seawater from the sealskin cup."),
                AllianceCh3GiftItemId = "axe_salt_iron_1h",
                AllianceBrokenText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1255", "Bjornulf spits salt into the surf. \"The sea drinks oath-breakers same as it drinks all the rest. Ride inland.\""),
            }},
            { "desert_bandits", new CultureProfile {
                ChiefName = BandItPlus.Localization.Get("bp_cultureprofileregistry_1256", "Hakkun the Sand-Reader"),
                Signature = new SignatureQuestSpec
                {
                    Title = BandItPlus.Localization.Get("bp_cultureprofileregistry_1257", "The Well-Killers"),
                    HeraldLine = BandItPlus.Localization.Get("bp_cultureprofileregistry_1258", "Dune-walker! The chief wants you. He's been crouched over his ash-bowl since first light, muttering about the deep wells. When the sand talks to him that long, somebody's about to bleed. Go on, move."),
                    OfferProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_1259", "This morning I read the ash, and the ash was white as bone. Now I know why. A lord has cut himself a new trade road, and my people sit too near it, so he sends wagons south — quicklime, traveler. Lime for the deep wells. One sack and a well is dead for a generation. Ten wagons and the sand-clans die of thirst without a blade drawn. An engineer leads them, a man of measures and schedules, with outriders paid to keep the curious away. Stop the column. Turn it or break it — the wells do not care which. The sand has already shown me the wagons standing still. Go and make my reading true."),
                    AcceptProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_1260", "Good. The wind turned east last night — it knew your answer before your mouth did. Ride the new road south; the wagons raise white dust, not brown. Water is life, traveler. Bring mine home."),
                    DeclineNudge = BandItPlus.Localization.Get("bp_cultureprofileregistry_1261", "The sand shows me two readings, traveler. In one you ride, and the wells stay sweet. In the other, my people drink dust. Which one do you mean to make true?"),
                    BusyLine = BandItPlus.Localization.Get("bp_cultureprofileregistry_1262", "The wagons still roll. Every sunrise I read the ash, and the ash is still white. Do not make me read it a third time."),
                    TargetPartyName = BandItPlus.Localization.Get("bp_cultureprofileregistry_1263", "Quicklime Column"),
                    CaptainName = BandItPlus.Localization.Get("bp_cultureprofileregistry_1264", "Engineer Fazil"),
                    JournalObjectiveText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1265", "Hakkun the Sand-Reader has asked you to stop a lord's column carrying quicklime meant to foul the deep desert wells. Intercept the Quicklime Column and its engineer before the wells are poisoned."),
                    JournalReturnText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1266", "The quicklime will not reach the wells. Return to Hakkun the Sand-Reader at his hideout to collect your reward."),
                    ConfrontIntro = BandItPlus.Localization.Get("bp_cultureprofileregistry_1267", "You are standing on a surveyed road. I have eleven wagons, outriders, and a lord's seal that says this cargo moves. State your business quickly — I am due at the first well by dusk."),
                    Choices = new[]
                    {
                        new SignatureChoice { Label = BandItPlus.Localization.Get("bp_cultureprofileregistry_1268", "Ask your outriders my name — then turn these wagons around."), Requirement = SignatureRequirement.Renown, RequirementValue = 180, Outcome = SignatureOutcome.ComplyFull, ResultProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_1269", "That name I have heard — from men who were still frightened when they said it. I build roads; I do not die on them. Turn the wagons! We go back. No blood over another man's road.") },
                        new SignatureChoice { Label = BandItPlus.Localization.Get("bp_cultureprofileregistry_1270", "The wells stay sweet. Steel settles the rest."), Outcome = SignatureOutcome.Battle, ResultProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_1271", "Outriders — to me. Kill this one, and mind the barrels. Wages as agreed; double for whoever brings me the head.") },
                    },
                    DemandFailProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_1272", "Never heard of you. I have heard of my schedule — I keep it. Wagons, move on! If the name is worth anything, friend, now would be the time to show me."),
                    ClosingProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_1273", "Come to the well, traveler. Draw. Drink — cold and sweet, from the deep stone. I read the sand this morning. It showed me children at this well thirty years from now. You are in that reading, though they will never know your name. Here is your silver, counted slowly. Everything worth doing is done slowly. The dune holds its peace tonight, and so do I."),
                    ClosingProseOtherCause = BandItPlus.Localization.Get("bp_cultureprofileregistry_1274", "The wind did not wait for you, traveler. A khamsin came down on the column and buried half of it standing — the lime ruined, and the proof with it, under a dune that was not there at dawn. I read it, but I read it late. The wells are safe; the desert took the doing for itself. Half the silver. Not insult — arithmetic. The sand keeps its own ledger."),
                    RewardGold = 1700,
                    RewardRelation = 9,
                },
                ChiefTitle = BandItPlus.Localization.Get("bp_cultureprofileregistry_1275", "Sand-Reader"),
                // 2026-06-03 quest-prose flagship — Hakkun's distinctive voice overrides
                // the desert_bandits mould at Layer 1. Signature: explicitly READS something
                // at the start of every entry (sand, ash, ripples), the desert as a sentient
                // force, predictions framed as already-seen.
                AllianceCh1AcceptProse =
                    "\"The sand told me you would come three sunrises ago. I am Hakkun, the Sand-Reader, and the dunes outside this place have been drawing your shape since the last khamsin.\n\n"
                    + "Twenty-five days. The desert has already chosen them; I only count what it has shown me. Bring me a kill — a band that drinks from the same poisoned well as the merchants who chained my sister. My next reading will name them, and the sand never wastes a name.\n\n"
                    + "Refuse, and the dunes will swallow your footprints before sundown. They have done it before. I have watched.\"",
                AllianceCh1HuntBriefProse =
                    "\"At dawn I knelt with the cooled ash and watched the wind write a name in it. {PARTY_NAME}, {ARTICLE} {CULTURE} {KIND}, riding the salt-flat road near {AREA}. The grains had already settled around their captain before my scouts confirmed it at noon.\n\n"
                    + "The stars marked this one a season ago. I saw the throat opened before the throat was grown. Go and finish what the desert has long since witnessed.\n\n"
                    + "Bring me a token — a buckle, a blade, a tongue. The sand will know which to keep and which to bury.\"",
                AllianceMidQuestUpgradeProse =
                    "\"The wind has scoured the old name from my reading-bowl — that quarry rides where my sight does not reach. The dunes have offered another in its place: {PARTY_NAME}, {ARTICLE} {CULTURE} {KIND} near {AREA}. The sand has already shown me their ending.\"",
                AllianceCh2AdvanceProse =
                    "\"You return, and the sand spoke of it before your shadow crossed my threshold. I read your coming in the ripples three nights past — the wind blowing east instead of its proper west.\n\n"
                    + "A captain dead, a company scattered to feed the jackals. The desert is not surprised; the desert remembered it forward, the way it remembers all the bones it will one day hold. I only watched. The stars charged me nothing for the watching.\n\n"
                    + "Come to {HIDEOUT} when the moon is thin. There are readings the open sky should not hear spoken aloud.\"",
                ChiefBackstory = BandItPlus.Localization.Get("bp_cultureprofileregistry_1276", "Hakkun was born into a desert-survey caste — a small Aserai sub-people whose ancestors served the early sultans as cartographers and well-finders, paid in silver and protected by royal warrant. The caste was disbanded a century ago when the sultanate reformed its tax-survey system; Hakkun's grandfather inherited the books, his father inherited the books, and Hakkun inherited a library of dune-charts more accurate than anything the current sultan possesses. He worked as a caravan-guide for fifteen years, the most expensive in the southern trade, and was never short of clients despite charging triple the going rate. The trouble began the year a corrupt sultanate official accused him of selling well-locations to bandits — a charge that was technically true insofar as the official had failed to pay him for the previous season's services and Hakkun had recovered his fee from a desert raid. The Sultan has tried three times to hire him as a guide and three times to hang him as a brigand; he has accepted neither offer with finality. The Desert Bandits are now a confederation of the dispossessed survey-caste families and a few hundred true desert-walkers who follow Hakkun for the same reason caravans used to: he knows where every well runs dry and which lord owns the men guarding it."),
                ClanHistory = BandItPlus.Localization.Get("bp_cultureprofileregistry_1277", "The Desert Bandits are the oldest survival of an Aserai survey-caste — a small sub-people whose ancestors served the early sultans as cartographers and well-finders, paid in royal silver and protected by royal warrant. The caste was disbanded six generations ago when the imperial-leaning sultans of the third Aserai dynasty replaced it with a court bureau of foreign mapmakers. The disbanded surveyors took their charts, their well-rods, and their sand-reading knowledge into the deep dunes and have lived there since. Hakkun is the eleventh chief by direct succession from the last royal-warrant survey-master. Admission is tightly controlled — descendants of the original caste, desert-village families with documented survey-bloodlines, and the rare outsider an elder vouches for after a year of testing. They take from caravans that cross the deep dunes without paying the customary water-tribute — a tribute the band considers payment for use of wells the caste's ancestors found. The Aserai sultanate has tried four times in three generations to extract a peace-deal that would re-recognize the caste in exchange for surrender of arms; Hakkun has refused all four because none of the offers came with a return of the original royal silver-stamp."),
                ChiefGreeting = BandItPlus.Localization.Get("bp_cultureprofileregistry_1278", "The Sand-Reader steps out of the shadow between two tents — robed, face-cloth wrapped against the wind, only the eyes visible. Those eyes find you and read you the way Hakkun reads dunes: slowly, patiently, complete. \"You come to the dunes, traveler. The dunes know you now. They have already told Hakkun what manner of wanderer you are. Speak — and let us see whether your tongue agrees with the sand.\""),
                ChiefGreetingTolerated = BandItPlus.Localization.Get("bp_cultureprofileregistry_1279", "The Sand-Reader steps out without his face-cloth this time — eyes still the same, but a face beneath, weather-burned and patient. The dunes have decided about you, and so has Hakkun. \"You return. The sand has spoken your name three days running, and Hakkun listens to the sand. Sit. The shade is yours, and the wind doesn't bite the dunes' familiars.\""),
                ChiefLoyaltySpeech = BandItPlus.Localization.Get("bp_cultureprofileregistry_1280", "The sand has the name now, traveler. The sand takes a long time to decide what to make of one. Hakkun listens to the sand, and the sand asks for proof. There's a thing my men require of those who would walk the dunes as kin. Bring it. Then the sand and Hakkun will speak the same word over you."),
                CampIntro = BandItPlus.Localization.Get("bp_cultureprofileregistry_1281", "The Desert Bandits' camp is hidden in a wadi between dunes — striped tents, camels at the picket, a single deep well. The sun pounds."),
                HideoutDirections = BandItPlus.Localization.Get("bp_cultureprofileregistry_1282", "Ride south from Sargot, traveler, and let the sun be your only companion for a day and a night. When the green dies behind you and the dunes rise like sleeping beasts on every side, watch for a cattle-skull bleached white as bone, set upright in the sand at the mouth of a low wadi. That skull is my hand pointing inward. Follow the wadi between the two tall dunes - the wind has cut them like the prow of a ship - and you will smell the well-water before you see the tents. Our hold lies at {HIDEOUT_NAME}, in the shade the sun forgives only at noon.\n\nMy watchers sit higher than you will think to look. They read a rider's shoulders the way I read the dunes - by the lean of him, by the dust he kicks, by whether his hand rests on rein or hilt. Ride slow when the wadi narrows. Keep your palm open at your side. If you carry a token I have given, hold it up to the ridge; my boys have eyes that count grains of sand.\n\nCome the right way and the striped tents open to you - dates, sour milk, the shade of canvas and the slow talk of men who have nowhere to hurry. Come the wrong way, with a closed fist or a hidden blade, and the sand will drink you before my camels lift their heads. The desert keeps its own ledger, friend. I only read it aloud."),
                ScoutsLordsProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_1283", "The Aserai sultans send their riders south from Sargot when the wells run thin and the tax-rolls run thinner. The sand tells me before they crest the dune - hoofprints sit different when a horse carries silver. Emir Unqid's vassal-clans have ridden my wadi three times this season. Two columns I let pass because the wind said they carried only their own water. The third I read coin in their saddlebags, and that one did not ride back. The sand drank what the Emir would have spent.\n\nThe Vlandian mercenaries come down the coast road every other moon, hired by some merchant-prince in Quyaz who thinks gold buys him passage through my country. Their captain calls himself Sir Renald of the Burning Sun - a name a Vlandian gave himself to sound like one of us. The dune does not mistake him. We have a quarrel, he and I, since he burned a waterhole my grandfather dug.\n\nThe Empire sends its tax-wagons north from the coast, the Khuzait outriders push west when their grazing fails, and the Battanian sellswords ride for whoever pays in silver and not in promises. They all cross my sand. The sand remembers each of them. If you ride my country with a banner, traveler, let the wind read it first. The dune is patient. The dune keeps every name."),
                ScoutsClanProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_1284", "The sand keeps its own ledger, and the wind reads me the names. Khalid of the Slaver caravans crossed my wadi twice this moon - he brought salt, he brought silver, he asked for water and a guide to the deep crossings. I gave him both. The Slavers and my dune-band have an old understanding: their chains do not touch Aserai blood, and my scouts do not mark their routes for the lords of Sargot. It is not love. It is the way two scorpions share a stone.\n\nThe Fallen Legionaries trouble me. Aurelius marches his iron men south through the broken passes, looking for the old forts the Empire forgot, and his outriders have been seen drinking at a well I claim. I have not yet sent a token. I am still reading the sand. If he digs in at the dry-ruin three days east, blood will follow, and the dunes will keep it. To the far north Granny Hod's forest band sent a runner this spring asking after caravan glass - I told him my routes, he told me his. We trade words, not steel.\n\nBoll's outcasts I do not respect. They scratch the edges of every chief's ground and call themselves free. The desert does not feed the rootless for long. The wind tells me Boll will be bones before the next dry season, and I will not mourn him."),
                ScoutsCaravanProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_1285", "The sand tells me when a caravan is coming three days before the dust rises, traveler. The Aserai spice-trains move out of Sargot every new moon, bound for the markets at Quyaz - eight wagons, twenty guards, two outriders who circle wide because the captain fears ambush from the dunes. He is right to fear it. He is wrong about which dune. They take the southern track past the dry wadi because the well there still gives water, and a thirsty escort stops drinking sharp.\n\nThe fourth wagon carries cardamom and saffron the Vlandian factors at Pravend pay in weighed silver, no questions asked. The captain is a man called Iqbal - sober, watchful, but his second is a drunk who rides rearguard and sleeps in the saddle by the second watch. Hit them when the column splits to water the camels. The guards bunch at the well and the wagons sit naked on the track for a quarter-hour. We have taken three caravans this way in two seasons.\n\nIf you ride with thirty horse and come down from the eastern ridge at dusk, the wagons are yours. I want no share - the dune gives me what I need. Take the saffron north and sell it to the same Vlandians who bought it the first time. The desert keeps its silences. The merchants never ask where their spices walked between selling and buying. That is how the sand eats and never shows the bones."),
                PactTeaseProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_1286", "You have come to the well with the deep question, traveler. The wind reads it before I do. Sit. Drink the bitter water. A question of this weight is not asked twice in the same season, and the dune beneath us has already taken note of where your shadow falls.\n\nIn my country, blood is not the binding. Salt is. I have shared salt with three men still walking, and the bones of two more who walk no longer. My uncle Ifris, who taught me to read the ripple-lines before a sand-storm. The well-keeper of the southern wadi, who hid my mother when the empire's riders came counting heads. A Khuzait scout I did not kill in the year of the white sun, who later did not kill me. That is the salt-bond. That is what an oath from a Sand-Reader weighs. You have eaten at my fire, but we have not yet shared the salt.\n\nBring me a deed the dune will remember without my telling it. Open a well that was closed. Close a road that should not have stayed open. Carry my name into a place I cannot walk. Then the wind will read you to me, and I will not need to ask. Until that day, drink. Speak again when the sand has heard you."),
                OathBrotherProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_1287", "Then the dune has heard it, and the dune does not unhear. Sit. Drink. This is the bitter water from the deep well south of Sargot - the water my mother drank when she named me, the water I drank when I read my first storm in the sand. I take the salt from the leather pouch at my belt - the same salt I shared with my first rider when we were boys with nothing but thirst between us - and I press a pinch to your tongue and a pinch to mine. Now I cut a strand of your hair and twist it into the cord at my wrist where my brother-strands already lie. The wind has taken your scent. The dune has taken your name. It is done.\n\nHear me, salt-brother. Among my people, blood is cheap - any wound spills it. Salt is what we bond by, because salt is what the desert costs us. You are no longer a man I ride beside. You are kin of the deep wells. My tent is your tent. My water-skin is your water-skin. When I am thirsty in the open sand, you will feel the dryness in your own throat.\n\nThe dune-country south of Sargot learns your name tonight. The chiefs of the seven wells learn it by sunrise. The Aserai lords who put a price on my head will read the salt on your lips and know - they have not one Sand-Reader to hunt now, but two. The wind reads brother across your shadow, salt-brother. Walk under it."),
                PactAnswerProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_1288", "Then the dune has read your answer before your tongue could shape it. You did not come back with a speech polished smooth by the long ride. You came back with the deed already drying on your hands, and the words trailing it like dust behind a horse. That is the order the sand trusts. A man who speaks first and bleeds later is a man the wind forgets. You bled first. Sit. Let the heat of what you have done settle into the cool of evening.\n\nFrom this hour, the salt-bond between us thickens. My riders are yours when you raise your banner - not as guests at your fire, not as a debt I can call back when the wells run shallow. As blood-allies, sworn to the same feud. The caravans that hunt you will find dune-shadows at their flank before the noon prayer. Your enemies drink from my cup of grudges now. In return, when I send the salt-token south, you ride. No question. That is the shape of it. Brothers share a hearth; we share a war.\n\nThe wind will carry this oath where no scroll can follow. It will read it to the dunes from Sargot to the deep south, and the dunes will remember, as they remembered my first wound and the kin who paid for it. Ride hard, salt-brother. The sand is patient. Our enemies are not."),
                TroopLoanProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_1289", "It is done, traveler. Ten of my sons of the wadi will ride at your stirrup before the next dawn breaks white over the dunes. I send Yusuf al-Mihrab with them - he reads sand as I read it, and the wind-readers under his hand will not stray. Seven days. The dune counts in suns, and I have counted seven.\n\nHear my terms, for the salt-bond is not free. If a dune-rider of mine falls in your work, you bring me his sash and the name of the place he fell - the wadi remembers its dead, and so must I. If he lives, you return him with his thirst quenched and his blade still keen. My wind-readers do not break shield for trinkets. While they ride beneath your shadow, your road is the dune's road - do not squander them on cattle-thieves and drunkards.\n\nSeven suns, traveler. The dune will tell me when they are due. See that the dune does not have to ask twice."),
                NamedTargetAcceptProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_1290", "His name is {TARGET}. His banner snaps over {HOME}, and the wells between his holdings are the same wells my sister Anaya was sold beside in the summer of the red dust - nine years gone, traveler. {TARGET}'s tax-riders found our caravan dry on the seventh dune, took the water, took the women, took the boy who carried my brother's name. They left us the salt. The dune remembers what the courts forget, and I have been reading that dune for nine summers waiting for a man with your stride to walk into my shade.\n\nHe rides with twelve spears and a captive Aserai scout who would slit his throat for a waterskin and a fair word. {TARGET} stops at the old caravan well three days east of {HOME} every new moon - he believes the stars hide him there. They do not. He drinks deep, and his guards drink with him. Take him in the hour before dawn, when the wind walks alone.\n\n{REWARD} denars when the salt-bond is paid, traveler. The gold is owed, but the gold is not the debt. The wind reads the rest. Ride before the sand forgets your weight."),
                NamedTargetReason = BandItPlus.Localization.Get("bp_cultureprofileregistry_1291", "{CHIEF} has read {TARGET} of {HOME} in the dunes for nine summers, and the wind has named the man each season the same. The grudge is salt-bound and specific - a wellhead at Bir al-Saqf poisoned with bloated camel-carcass on the noble's order, a caravan of forty souls walked dry into the white pan east of the oasis, and a boy named Yusuf, who was {CHIEF}'s sister-son, found three days later with his lips cracked black and his waterskin slit clean. The Sand-Reader keeps a row of small white stones beside his sleeping mat, one for each thirsted soul, and only {TARGET}'s stone has not yet been buried. A heavy purse is offered, and the dune-debt at last comes due."),
                NamedTargetComplete = BandItPlus.Localization.Get("bp_cultureprofileregistry_1292", "{TARGET} is dead, and the wind has carried word back across the salt-flats to {CHIEF}. The dune has read the name and given its slow answer. Forty-two summers ago, in the salt-year, {TARGET}'s house broke the bond at the Well of Sahla and left Hakkun's brother Yusef-of-the-Long-Stride to die thirsty among poisoned stones; that thirst is finally watered. {REWARD} denars rest in a clay jar beside the chief's mat, counted twice and bound in salt. Between bandit-king and traveler the bond now sits a measure heavier. The dune remembers, and the dune is content. The wind reads no further."),
                NamedTargetOtherCauseProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_1293", "Word came on a salt-trader's tongue: {TARGET} had been cut down at a dry wadi by a rival lord's outriders, three days east, far from any blade the player had drawn. {CHIEF} heard the news beside the row of small white stones laid out next to his sleeping mat, the ones he counted each dusk for Yusef-of-the-Long-Stride who had thirsted at the Well of Sahla in the salt-year. He sat a long while with the stones, then said the dune does not always care whose foot wakes it, only that the sand moves. The grudge was answered, he allowed, but answered by a wind not the player's hand. He counted out {REDUCED_REWARD} denars - thin coin, quarter-pay - and set the bond a small notch firmer, no warmer."),
                RaidVillageAcceptProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_1294", "{VILLAGE}. Say the name slowly, as the dunes say it when the wind is patient. {LORD} signs the tax-rolls there now, and {LORD}'s riders drink from a sweet well that was bought with poison. In the salt-year they dropped a bloated camel into the Well of Sahla, and my brother Yusef drank from it before he knew, and the caravan he guarded died one by one across three days of sand. {LORD}'s oasis still pours clean water. That arithmetic offends me.\n\nGo at the third hour past dusk, when their watchmen face the road and not the dunes. Burn the granary first - they keep tax-grain for {LORD}'s riders there, and grain that fed murderers should feed nothing again. Take the salt, take the copper, take any horse marked with the running-hare brand because that brand belonged to Yusef's caravan and {LORD} has no right to it. Leave the children and the old women. The dunes already know their names.\n\n{REWARD} silver waits for you when the smoke is seen from the ridge. I read the sand each morning, friend, and the sand has spoken your face for some weeks now. Go. Make {LORD} taste his own well."),
                RaidVillageReason = BandItPlus.Localization.Get("bp_cultureprofileregistry_1295", "{CHIEF} traces a slow circle in the sand and names {VILLAGE}, the oasis-hamlet whose Aserai masters drink from a clean well while his people taste salt and ash. In the salt-year, he murmurs, their tax-riders dropped a bloated camel-carcass into the Well of Sahla, and the caravan that drank it died choking on its own breath - and among that caravan rode his brother Yusef.\n\nThe dunes remember names the wind cannot scour. He asks {LORD} to ride against the village, to burn its granaries and scatter its herds until the new well runs as foul as the old. For this reading of the sand, {REWARD} is offered."),
                RaidVillageComplete = BandItPlus.Localization.Get("bp_cultureprofileregistry_1296", "The smoke from {VILLAGE} rose thin and slow, the way old grief leaves a man, and {CHIEF} read the column the way he once read dunes. The oasis-folk had drunk from a different well after the salt-year, after the bloated camel-carcass fouled Sahla and took Yusef with the caravan, and now they would drink from no well at all. {LORD}'s tax-riders lay where they had fallen. The Sand-Reader counted out {REWARD} into the wanderer's palm, slow as sand through fingers, and spoke the closing-words for his brother at last."),
                RaidVillageOtherCauseProse = BandItPlus.Localization.Get("bp_cultureprofileregistry_1297", "Word drifted across the dunes like ash on a dry wind: {VILLAGE} was burning before {CHIEF} ever read the sand for its smoke. Other hands had done the work. Other knives had opened the throats of the men who drank from the second well, the well that was not Sahla, the well that was not poisoned in the salt-year when Yusef's caravan lay swelling beside a bloated camel.\n\n{CHIEF} traced a slow circle in the dust when {LORD} brought the news, and the circle closed without joy. The Aserai tax-riders were dead. So was the satisfaction of having killed them. He counted out {REDUCED_REWARD} in cool silence, for a debt half-paid is still a debt half-owed."),
                // 2026-05-25 rewrite: SUN-AS-CHARACTER / SUN-HAS-AGENCY shape. The
                // sun is a continuous character with intent — "studies", "decides",
                // "concedes", "watches", "judges". Player NEGOTIATES with the sun
                // through the day; the camp is "the sun's first concession". Ends
                // with the sun watching the player accept the gift of shade. No
                // companion-quote, no "These were not X" template, no "you watched"
                // reveal, no "No, not tonight" refusal.
                HideoutCinemaIntro = BandItPlus.Localization.Get("bp_cultureprofileregistry_1298", @"The sun has been with you all day. It has not, exactly, been kind.

It came up at your back at the false dawn and walked round to your face by noon, and it has been studying you since — patient, white, indifferent, the way a thing studies a thing it has not yet decided about. The shadow of your horse has been your only company, and the sun has been moving that, too, shortening it through the morning and stretching it through the afternoon as a way of telling you the time.

The sun is not in a hurry. The sun knows that the people who hurry, out here, are the people who go bad-eyed and pitch sideways out of their saddles to be found, in time, by the next set of riders, or by no one. The sun has watched many such people. The sun does not care which kind you are.

You ration your water. The sun rations its mercy.

By the long afternoon you have made a kind of bargain with it, the way travelers in the deep desert come to make bargains with the only force out here large enough to be worth bargaining with. You will not waste it. You will not curse it. You will sit straight in the saddle and you will not let the horse drift. In return the sun, perhaps, will let you reach a wadi before sundown. Perhaps. The sun does not promise.

You crest the dune and there, below you, the sun makes its first concession of the day.

A long fold of shadow between two great drifts, deep enough to hold a coolness the sun cannot yet reach into. Striped tents the colour of the sand that hides them. A string of camels couched in the lee. A single well. The shadow is real. The shadow is wide. The shadow has been waiting for some hours, the way shadows wait, growing slowly out from the dune as the sun turns west.

The sun has shown you this. The sun did not have to.

Hakkun the Sand-Reader steps out of one of the striped tents and looks up at you on the dune-rim. He shades his eyes — not against the sky, but against the angle of late light off the sand — and waits. By desert law a well is shared. By desert law you have already been granted what you came for: the shade.

You ride down into it slowly, because the sun is watching, and the sun will judge how you take the gift."),
                ServiceLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_1299", "Have the sand-reader trace nearby camps."),
                ServiceFlavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_1300", "Hakkun smooths a patch of sand. He draws lines, then more lines. \"I read tracks others miss.\""),
                Kind = ServiceKind.SandScout,
                BribeAmount = 175,
                WhyNotKingdom = BandItPlus.Localization.Get("bp_cultureprofileregistry_1301", "\"The sultan's tax-men rode out one summer and never came back. The next summer no men rode out.\""),
                Religion = BandItPlus.Localization.Get("bp_cultureprofileregistry_1302", "\"The desert. The sun-father. The night-mother.\""),
                ThreatResponse = BandItPlus.Localization.Get("bp_cultureprofileregistry_1303", "Hakkun's voice doesn't change. \"Hospitality is sacred. Your threat broke that. The sand will eat your bones.\""),
                Pleasantry = BandItPlus.Localization.Get("bp_cultureprofileregistry_1304", "He inclines his head. \"You honor my tent. Sit. Drink.\""),
                DrinkFlavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_1305", "Hakkun pours a fragrant tea — desert mint, honey, cardamom. The cup is small but the warmth lasts. Your party feels eased."),
                RestFlavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_1306", "You sleep in a striped tent, cool against the sand. The night-wind sings. Your party rises strong, well-watered, well-fed."),
                ExtraServices = new[] {
                    new CultureSubService { Label = BandItPlus.Localization.Get("bp_cultureprofileregistry_1307", "Trade with the camel-master."), Flavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_1308", "A wiry man stands among five camels. \"Hardy. Drink rare. Walk far. Trade fair, take a beast home.\""), Kind = ServiceKind.HorseMaster },
                    new CultureSubService { Label = BandItPlus.Localization.Get("bp_cultureprofileregistry_1309", "Listen to the star-reader. (50 denars)"), Flavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_1310", "An old woman wrapped in indigo cloth squints up at the daytime sky. \"Stars speak in daylight too, if you know how to look. Listen.\""), Kind = ServiceKind.Oracle, GoldCost = 50 },
                    new CultureSubService { Label = BandItPlus.Localization.Get("bp_cultureprofileregistry_1311", "Take tea in Hakkun's tent. (50 denars)"), Flavor = BandItPlus.Localization.Get("bp_cultureprofileregistry_1312", "Hakkun pours a second tea. He tells you old desert stories. Your soldiers drink quietly, watching. The desert feels less hostile for an evening. Morale rises."), Kind = ServiceKind.VeteranHall, GoldCost = 50, MoraleGain = 4 },
                },
                Rumors = new[] {
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_1313", "\"The sultan's tax-caravan crosses the dunes at the new moon.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_1314", "\"A merchant prince in Husn Fulq pays for desert-blooded horses.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_1315", "\"There's a buried city under the eastern sands — old as anything.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_1316", "\"A noble's youngest son ran away to be a desert mystic.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_1317", "\"A Vlandian knight tried to cross our dunes without a guide last spring.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_1318", "\"The southern oases are paying for water. Drought year.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_1319", "\"A perfumer in Quyaz buys desert flowers.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_1320", "\"Aserai sultan's caravan-master is corrupt.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_1321", "\"There's a tomb under the great red dune.\""),
                    BandItPlus.Localization.Get("bp_cultureprofileregistry_1322", "\"A foreign sorcerer hired us to fetch desert-glass for him last year.\""),
                },
                TrustQuestTier1Pool = new[] {
                    new TrustQuest {
                        ItemIds = new[] { "date_fruit" }, Counts = new[] { 20 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1323", "\"Twenty baskets of dates. The dunes give us little besides patience and thirst — sweet food keeps men's spirits.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1324", "He pops one in his mouth, chews thoughtfully. \"Sweet. Fresh. Trade with us, dune-walker.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_1325", "20 dates"),
                    },
                    new TrustQuest {
                        ItemIds = new[] { "salt" }, Counts = new[] { 15 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1326", "\"Fifteen salt. We cure the camel-meat for the long crossings — without salt, the dunes eat what we kill before we eat it.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1327", "He takes a pinch, tastes. \"Pure salt. The crossings open up to us. Trade.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_1328", "15 salt"),
                    },
                    new TrustQuest {
                        ItemIds = new[] { "oil" }, Counts = new[] { 25 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1329", "\"Twenty-five oil. Lamps for the sand-night. The desert dark is darker than men remember. Bring it.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1330", "He tests the oil. \"Pure. The lamps will hold all night. The dunes welcome you.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_1331", "25 oil"),
                    },
                },
                TrustQuestTier2Pool = new[] {
                    new TrustQuest {
                        ItemIds = new[] { "velvet", "date_fruit" }, Counts = new[] { 30, 30 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1332", "\"Thirty silk and thirty dates. Silk for the sun-tents, dates for the long marches. Bring both.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1333", "He drapes silk over the saddlebow. \"You move through sand like a serpent. The dunes are open to you.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_1334", "30 velvet + 30 dates"),
                    },
                    new TrustQuest {
                        ItemIds = new[] { "date_fruit", "oil" }, Counts = new[] { 40, 20 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1335", "\"Forty dates and twenty oil. The deep-desert sortie leaves on the new moon. Bring both for the long crossing.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1336", "He surveys the loaded camels. \"You provisioned a deep-desert raid. The Sultan's caravans aren't safe from us this season.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_1337", "40 dates + 20 oil"),
                    },
                    new TrustQuest {
                        ItemIds = new[] { "salt", "velvet" }, Counts = new[] { 50, 20 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1338", "\"Fifty salt and twenty silk. Salt for the meat-store, silk for the trade-tents. Bring both, and you walk among us as caravan-master.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1339", "He nods, the sand-rider's salute. \"You provision the trade and feed the riders. Take what you need.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_1340", "50 salt + 20 velvet"),
                    },
                },
                TrustQuestTier3Pool = new[] {
                    new TrustQuest {
                        ItemIds = new[] { "velvet", "date_fruit", "spice" }, Counts = new[] { 50, 50, 30 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1341", "\"Fifty silk, fifty dates, thirty spice. The sultan's-caravan-cut. We strip a sultan's caravan and replace it with our own. Outfit us.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1342", "He laughs, sand-eyes bright. \"You've turned us into a sultan's-caravan ourselves. The dunes belong to whoever rides with you.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_1343", "50 velvet + 50 dates + 30 spice"),
                    },
                    new TrustQuest {
                        ItemIds = new[] { "date_fruit", "oil", "salt" }, Counts = new[] { 100, 50, 30 },
                        IntroText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1344", "\"A hundred dates, fifty oil, thirty salt. The greatest crossing this band has ever attempted — three weeks through the deep dunes. Provision the whole expedition.\""),
                        ThanksText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1345", "He clasps your forearm in the dune-rider's greeting. \"The deep-desert opens to us. You walk in cool wells wherever sand blows.\""),
                        ShortLabel = BandItPlus.Localization.Get("bp_cultureprofileregistry_1346", "100 dates + 50 oil + 30 salt"),
                    },
                },
                // Wave 5 (Chief Recruitment) alliance content
                AllianceCh1TaskBrief = BandItPlus.Localization.Get("bp_cultureprofileregistry_1347", "Escort a contraband caravan from Hakkun's hideout to the resolved Aserai desert village before the next full moon."),
                AllianceCh1Pattern = AllianceCh1Pattern.EscortToSettlement,
                AllianceCh1TargetSeedHint = "aserai_village_random",
                AllianceCh3RitualText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1348", "The Hakkun the Sand-Reader accepts your oath; the rite is sealed at sundown with sand poured over your hands, shadows long across the dunes."),
                AllianceCh3GiftItemId = "scimitar_sand_honed_1h",
                AllianceBrokenText = BandItPlus.Localization.Get("bp_cultureprofileregistry_1349", "Hakkun reads the sand at your feet without looking up. \"The dunes have changed your name. I no longer know it. Go.\""),
